\begin{lemma} \label{lemma:energy1}
Let ${\vec w}$ be the solution to (\ref{eqn:wprob}). Then, by  assuming that (\ref{eqn:oldcond}) holds,  there exists a constant $C$ such that
\begin{subequations}
\begin{align}
\left \| \nabla \times \left ( {\vec E}_\alpha - {\vec E}_0 - {\vec w}   \right) \right \|_{L^2(B_\alpha)} \le & C \alpha^{7/2}
 \mu_{r,*} ( | \mu_{r,s}^{-1} - \mu_{r,*}^{-1} | +\nu)    \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)}, \label{oldlemma_engy1} \\
 \left \| {\vec E}_\alpha - {\vec E}_0 - {\vec w} - \left ( \frac{\sigma_*- \sigma_s}{\sigma_*} \right )  \nabla \phi_0 \right \|_{L^2(B_\alpha)} \le & C
  \alpha^{9/2}
 \mu_{r,*} (  | \mu_{r,s}^{-1} - \mu_{r,*} ^{-1} | +\nu)  \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)}  \label{oldlemma_engy2}.
 \end{align}
 \end{subequations}
\end{lemma}
\begin{proof}
First we construct
\begin{align}
( & \mu_0^{-1} \nabla \times ( {\vec E}_\alpha - {\vec E}_0 -{\vec w}),  \nabla \times {\vec v} )_{\Omega_{fs} }+
(  \mu_0^{-1} \mu_{r,s}^{-1} \nabla \times ( {\vec E}_\alpha - {\vec E}_0 - {\vec w}) , \nabla \times {\vec v} )_{\Omega_{s}\setminus \overline{B_\alpha} }\nonumber\\
&+
(  \mu_0^{-1} \mu_{r,*}^{-1} \nabla \times ( {\vec E}_\alpha - {\vec E}_0-{\vec w}) ,  \nabla \times {\vec v})_{B_\alpha } 
- \im \omega \left  (  \sigma_s  \left ( {\vec E}_\alpha - {\vec E}_0-{\vec w}  \right ) , {\vec v} \right )_{\Omega_s \setminus \overline{B_\alpha} }\nonumber\\
&- \im \omega \left (  \sigma_*  \left  ( {\vec E}_\alpha - {\vec E}_0 -{\vec w} -  \left ( \frac{\sigma_* - \sigma_s}{\sigma_*} \right ) \nabla \phi_0 \right ), {\vec v}\right  )_{  {B_\alpha} } \nonumber \\
& = \mu_0^{-1} \left ( (\mu_{r,s}^{-1} - \mu_{r,*}^{-1})  \nabla \times ( {\vec E}_0 - {\vec F}) ,  \nabla \times {\vec v} \right )_{B_\alpha}
-\im \omega ( (\sigma_s-\sigma_*) ( {\vec E}_0 - {\vec F}+ \nabla \phi_0 )  , {\vec v} )_{  {B_\alpha} } , \nonumber
\end{align}
then we choose ${\vec v} = \left \{ \begin{array}{ll} {\vec E}_\alpha - {\vec E}_0 - {\vec w} -  \left ( \frac{\sigma_* - \sigma_s}{\sigma_*} \right ) \nabla \phi_0  & \text{in $B_\alpha$} \\ {\vec E}_\alpha - {\vec E}_0 - {\vec w}  & \text{in ${\mathbb R}^3 \setminus \overline{B_\alpha}$} \end{array} \right .$ and multiply by $\mu_0$ so that
\begin{align}
&  \| \nabla \times ( {\vec E}_\alpha - {\vec E}_0 -{\vec w}) \|^2_{L^2( \Omega_{fs} ) } +  \mu_{r,s}^{-1} \| \nabla \times ( {\vec E}_\alpha - {\vec E}_0 -{\vec w}) \|^2_{L^2( \Omega_{s}\setminus\overline{B_\alpha}  ) } \nonumber\\
& +  \mu_{r,*}^{-1}  \| \nabla \times ( {\vec E}_\alpha - {\vec E}_0 -{\vec w}) \|^2_{L^2( B_\alpha  ) }
- \im \omega \mu_0  \sigma_s  \left  \|    {\vec E}_\alpha - {\vec E}_0-{\vec w}  \right \|^2 _{L^2(\Omega_s \setminus \overline{B_\alpha}) }\nonumber\\
& - \im \omega\mu_0  \sigma_*  \left \|    {\vec E}_\alpha - {\vec E}_0 -{\vec w} -  \left ( \frac{\sigma_* - \sigma_s}{\sigma_*} \right ) \nabla \phi_0 \right \|^2_{  L^2({B_\alpha}) } \nonumber\\
& =  (\mu_{r,s}^{-1} - \mu_{r,*}^{-1}) \left  ( \nabla \times ( {\vec E}_0 - {\vec F}) ,  \nabla \times {\vec v} \right )_{B_\alpha}
-\im \omega \mu_0  ( (\sigma_s-\sigma_*) ( {\vec E}_0 - {\vec F}+ \nabla \phi_0)  , {\vec v} )_{  {B_\alpha} } , \nonumber
\end{align}
and  by the Cauchy-Schwartz inequality
\begin{align}
  \mu_{r,*}^{-1}& \left  \| \nabla \times \left ( {\vec E}_\alpha - {\vec E}_0 -{\vec w} - \left ( \frac{\sigma_* - \sigma_s}{\sigma_*} \right ) \nabla \phi_0  \right ) \right \|^2_{L^2( B_\alpha  ) } = \mu_{r,*}^{-1}  \| \nabla \times ( {\vec E}_\alpha - {\vec E}_0 -{\vec w}) \|^2_{L^2( B_\alpha  ) } \nonumber \\
  & \le \left | \left  ( (\mu_{r,s}^{-1} - \mu_{r,*}^{-1}) \nabla \times ( {\vec E}_0 - {\vec F}) ,  \nabla \times {\vec v} \right )_{B_\alpha} \right |
+ \omega \mu_0 \left |  ( (\sigma_s-\sigma_*) ( {\vec E}_0 - {\vec F}+ \nabla \phi_0 )  , {\vec v} )_{  {B_\alpha} }  \right |. \nonumber
\end{align}
Now
\begin{align}
\left |  (\mu_{r,s}^{-1} - \mu_{r,*}^{-1})\left ( \nabla \times ( {\vec E}_0 - {\vec F}) ,  \nabla \times {\vec v} \right )_{B_\alpha} \right | & \le  | \mu_{r,s}^{-1} - \mu_{r,*}^{-1} | \| \nabla \times ( {\vec E}_0 - {\vec F})\|_{L^2(B_\alpha)} 
\|\nabla \times {\vec v} \|_{L^2(B_\alpha)}  \nonumber \\
& \le C | \mu_{r,s}^{-1} - \mu_{r,*}^{-1} |\alpha^{3/2} \alpha^2 \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)} \|\nabla \times {\vec v} \|_{L^2(B_\alpha)}  \nonumber \\
& \le C | \mu_{r,s}^{-1} - \mu_{r,*}^{-1} |\alpha^{7/2} \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)} \|\nabla \times {\vec v} \|_{L^2(B_\alpha)},  \nonumber 
\end{align}
and
\begin{align}
\omega \mu_0 \left |  ( (\sigma_s-\sigma_*) ( {\vec E}_0 - {\vec F}+ \nabla \phi_0 )  , {\vec v} )_{  {B_\alpha} }  \right | \le & \omega \mu_0 | \sigma_s-\sigma_*|  \| {\vec E}_0 - {\vec F}+ \nabla \phi_0 \|_{L^2(B_\alpha)} \| {\vec v} \|_{L^2(B_\alpha)} \nonumber\\
\le & C \omega \mu_0 | \sigma_s-\sigma_*|   \alpha \| \nabla \times ({\vec E}_0 - {\vec F} ) \|_{L^2(B_\alpha)} \alpha  \| \nabla \times {\vec v} \|_{L^2(B_\alpha)}  \nonumber\\
\le & C\alpha^2  \omega \mu_0 | \sigma_s-\sigma_*|   \alpha^{3/2} \alpha^2  \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)}   \| \nabla \times {\vec v} \|_{L^2(B_\alpha)}  \nonumber\\
\le & C\alpha^{11/2}  \omega \mu_0 | \sigma_s-\sigma_*|  \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)}  \| \nabla \times {\vec v} \|_{L^2(B_\alpha)}  \nonumber\\
\le & C\alpha^{7/2} \nu    \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)}    \| \nabla \times {\vec v} \|_{L^2(B_\alpha)},  \nonumber
\end{align}
which follows from (\ref{eqn:e0mfmphi}),
\begin{align} 
  \| \nabla \times ({\vec E}_0 - {\vec F} ) \|_{L^2(B_\alpha)} \le C \alpha^{3/2}  \alpha^3 \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)},\label{eqn:e0minFminphi}
 \end{align}
 and $ \| {\vec v} \|_{L^2(B_\alpha)} \le C  \alpha  \| \nabla \times {\vec v} \|_{L^2(B_\alpha)} $ and $\alpha^2 \omega \mu_0 | \sigma_s-\sigma_*| \le \nu $.
Thus,
\begin{align}
  & \left  \| \nabla \times \left ( {\vec E}_\alpha - {\vec E}_0 -{\vec w} - \left ( \frac{\sigma_* - \sigma_s}{\sigma_*} \right ) \nabla \phi_0  \right ) \right \|^2_{L^2( B_\alpha  ) }\le
 C \mu_{r,*} \alpha^{7/2} (   | \mu_{r,s}^{-1} - \mu_{r,*}^{-1} | + \nu )\nonumber \\
& \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad \qquad     \| \nabla \times {\vec E}_0 \|_{W^{2,\infty}(B_\alpha)}  \| \nabla \times {\vec v} \|_{L^2(B_\alpha)},
\end{align} 
which leads to (\ref{oldlemma_engy1}). Using (\ref{eqn:ealphame0mwmphi})  gives (\ref{oldlemma_engy2}).
\end{proof}

