\nabla_\xi \times \mu_{r,s}^{-1} \nabla_\xi \times {\vec w}_{0,fs} - \im \omega \mu_0 \alpha^2  \sigma_* {\vec w}_{0,fs}  = & \im \omega \mu_0 \alpha^2 \sigma_* [ \alpha^{-1} {\vec F}( {\vec z} + \alpha {\vec \xi})] && \text{in $B$ } ,\\
\nabla_\xi \times \nabla_\xi \times {\vec w}_{0,fs}  =& {\vec 0} && \text{in $B^c$},\\
