[{\vec n} \times {\vec w}_{0,fs} ]_\Gamma ={\vec 0}, [ {\vec n} \times \mu_r^{-1} \nabla \times {\vec w}_{0,fs} ]_\Gamma= &-\im \omega \mu_0 \mu_{r,s} ( 1- \mu_r^{-1}) {\vec n} \times ( {\vec H}_0 ({\vec z}) + \alpha {\vec D} {\vec H}_0 ( {\vec z}) {\vec \xi}) && \text{on $\Gamma:= \partial B$}, \\
{\vec w}_{0,fs} ({\vec \xi}) = & O(|{\vec \xi}|^{-1}) && \text{as $|{\vec \xi}| \to \infty$},
\end{align}
\end{subequations}
and ${\vec \xi}$ has an origin in $B$.  It then follows from Lemma~\ref{lemma:diffw} that

