\subsection{\label{subsec:auxiliarly_field_method} Auxiliary-field eigenvalue technique}

The non-linear nature of the eigenvalue problem in Eq.~\eqref{eqn:classicalQNM_transformed} for dispersive materials renders its numerical solution difficult. The introduction of auxiliary fields in accordance with Yan {\it et al.}~\cite{yan2018rigorous} aims to linearize the eigenvalue problem so that more conventional and efficient solvers can be leveraged. The permittivity distribution $\varepsilon(\bm{r},\omega)$ is described using a position-dependent $N$-pole Drude-Lorentz model,
\begin{equation*}\label{eqn:Drude_Lorentz}
    \varepsilon(\bm{r},\omega) = \varepsilon_\infty(\bm{r}) -\varepsilon_\infty(\bm{r})\sum_{l=1}^N \frac{\omega_{\text{p},l}^2(\bm{r})}{\omega^2-\omega_{0,l}^2(\bm{r})+ \mathrm{i} \gamma_l(\bm{r}) \omega} ,
\end{equation*}
in which $\gamma_l(\bm{r})$, $\omega_{\text{p},l}(\bm{r})$ and $\omega_{0,l}(\bm{r})$ are damping rates, plasma and resonance frequencies pertaining to the $l$th pole, respectively. Dispersive PMLs like the one defined in Eq.~\eqref{Eq:PML_Absorption} destroy the form of the Drude-Lorentz permittivity in $\Omega_\mathrm{PML}$ and it is therefore common to use non-dispersive PMLs, in which the $\omega$-dependence is replaced by a constant frequency $\omega_\mathrm{PML}$ located within the frequency range of interest. These non-dispersive PMLs have the disadvantage that modes with lower frequency are less rapidly attenuated, thereby compromising the accuracy of the simulation. However, alternative auxiliary field methods can also be derived for arbitrary, rational dispersive permittivities (including dispersive PMLs), and studies with dispersive PMLs have been performed~\cite{lalanne2019quasinormal,demesy2023dispersive}. 
For the non-dispersive PMLs, only $\varepsilon_\infty(\bm{r})$ in Eq.~\eqref{eqn:Drude_Lorentz} needs to be transformed to $\tilde{\varepsilon}_\infty(\bm{r})$, and auxiliary polarizations $\tilde{\bm{P}}_l$ and current densities $\tilde{\bm{J}}_l$ are defined for each pole, via
\begin{align}
    \tilde{\bm{P}}_l=&-\frac{\varepsilon_0\tilde{\varepsilon}_\infty(\bm{r})\omega_{\text{p},l}^2(\bm{r})}{\omega^2-\omega_{0,l}^2(\bm{r})+ \mathrm{i} \omega\gamma_l(\bm{r})}\tilde{\bm{E}},
    \quad\tilde{\bm{J}}_l= - \mathrm{i} \omega\tilde{\bm{P}}_l\, .
    \label{Eq:Auxiliary}
\end{align}
Treating the simple case of a single Drude-Lorentz pole $(N = 1)$, we use these auxiliary fields to reformulate Eq.~\eqref{eqn:classicalQNM_transformed} as a linear eigenvalue problem, $\hat{\mathcal{H}}\tilde{\bm{\psi}}_n={\tilde \omega}_{n}\tilde{\bm{\psi}}_n$, for an augmented eigenvector $\tilde{\bm{\psi}}_n=[\tilde{\bm{H}}_n,\tilde{\bm{E}}_n,\tilde{\bm{P}}_n,\tilde{\bm{J}}_n]^\text{T}$,
in which
\begin{equation}
    \hat{\mathcal{H}}=\begin{bmatrix}
    0 & - \mathrm{i} (\mu_0\tilde{\mu})^{-1}\nabla\times & 0 & 0 \\
    \mathrm{i} (\varepsilon_0\tilde{\varepsilon}_\infty^{-1})\nabla\times & 0 & 0 & - \mathrm{i} (\varepsilon_0\tilde{\varepsilon}_\infty)^{-1} \\
    0 & 0 & 0 & \mathrm{i} \\
    0 & \mathrm{i} \varepsilon_0\tilde{\varepsilon}_\infty\omega_{\text{p}}^2 & - \mathrm{i} \omega_{0}^2 & - \mathrm{i} \gamma
    \end{bmatrix} \, .
    \label{classicalQNM_fourVec}
\end{equation}
%in the case of a single Drude-Lorentz pole $(N = 1)$, whereby
The generalization to an arbitrary number $N$ of poles is straightforward.

From the unconjugated form of the Lorentz reciprocity theorem, applied to the augmented system in Eq.~\eqref{classicalQNM_fourVec}, an orthogonality relation for the modes can be derived: 
\begin{align}\label{eqn:QNM_orthogonality}
    &\int_{\Omega}\mathrm{d}^3r\, \bigg(\varepsilon_0\tilde{\varepsilon}_\infty(\bm{r})\tilde{\bm{\bm{E}}}_n\cdot\tilde{\bm{E}}_{n'}- \mu_0\tilde{\mu}(\bm{r})\tilde{\bm{H}}_{n}\cdot\tilde{\bm{H}}_{n'}\\&+\frac{\omega_{0}^2(\bm{r})}{\varepsilon_0\tilde{\varepsilon}_\infty\omega_{\text{p}}^2(\bm{r})}\tilde{\bm{P}}_n\cdot\tilde{\bm{P}}_{n'}-\frac{1}{\varepsilon_0\tilde{\varepsilon}_\infty(\bm{r})\omega_{\text{p}}^2(\bm{r})}\tilde{\bm{J}}_n\cdot\tilde{\bm{J}}_{n'}\bigg)=\delta_{n n'} \, , \notag
\end{align}
and their normalization condition can be readily written as
\begin{align}
    \int_{\Omega}\mathrm{d}^3 r\, \left[\partial_\omega[ \omega \varepsilon_0\tilde{\varepsilon}(\bm{r},\omega)]_{\omega=\tilde{\omega}_n}\tilde{\bm{E}}_n\cdot\tilde{\bm{E}}_{n}-\mu_0\tilde{\mu}(\bm{r})\tilde{\bm{H}}_n\cdot\tilde{\bm{H}}_{n}\right] \notag \\
    = 1 \, .
\end{align}
It should be emphasized that the volume integration in these relations is performed over the entire computational domain $\Omega$, including the PML regions $\Omega_{\mathrm{PML}}$, yet the normalization of the QNMs does not depend on the PML parameters~\cite{sauvan2022norm}. Although the orthogonality relation in this form can only be derived within the auxiliary-field eigenvalue approach, the normalization can also be used for materials with arbitrary dispersion and permeability, for which we would have to replace $\tilde{\mu} \rightarrow \partial_\omega[ \omega \tilde{\mu}(\bm{r},\omega)]$.

By defining the matrix
\begin{equation}
    \hat{\mathcal{D}}=\mathrm{diag}\left[-\mu_0\tilde{\mu},\varepsilon_0\tilde{\varepsilon}_\infty,\frac{\omega_{0}^2}{\varepsilon_0\tilde{\varepsilon}_\infty\omega_{\mathrm{p}}^2},\frac{-1}{\varepsilon_0\tilde{\varepsilon}_\infty\omega_{\mathrm{p}}^2}\right]
    \label{D_Matrix} \, ,
\end{equation}
corresponding to the orthogonality relation in Eq.~\eqref{eqn:QNM_orthogonality}, the completeness relation can be written as
\begin{equation}
    \sum_n \tilde{\bm{\psi}}_n(\bm{r}') \otimes \tilde{\bm{\psi}}_n^{\mathrm{T}}(\bm{r}) \hat{\mathcal{D}}(\bm{r}) = \hat{\bm{I}} \delta(\bm{r} - \bm{r}') \, ,
\end{equation}
in which $\tilde{\bm{\psi}}_n^{\mathrm{T}}(\bm{r}) \hat{\mathcal{D}}$ are the left eigenvectors of $\hat{\mathcal{H}}$~\cite{yan2018rigorous}.
Invoking the orthogonality and completeness properties, as well as the scattered-field formulation, we can derive analytic expressions for the modal excitation coefficients in Eq.~\eqref{eqn:QNM_expansion_PML}:
\begin{align}
    \alpha_n(\omega) = \frac{\tilde{\omega}_n}{\tilde{\omega}_n - \omega} \varepsilon_0&\langle \tilde{\bm{E}}^*_n | \Delta\varepsilon(\bm{r},\tilde{\omega}_n) | \bm{E}_\mathrm{b} \rangle_{L^2(\Omega_\mathrm{res})} \notag \\
    + \varepsilon_0&\langle  \tilde{\bm{E}}^*_n | \varepsilon_\mathrm{b}(\bm{r},\omega) - \varepsilon_\infty(\bm{r)} | \bm{E}_\mathrm{b} \rangle_{L^2(\Omega_\mathrm{res})} \notag \\
    -\frac{\tilde{\omega}_n}{\tilde{\omega}_n - \omega} \mu_0&\langle \tilde{\bm{H}}^*_n | \Delta\mu(\bm{r}) | \bm{H}_\mathrm{b} \rangle_{L^2(\Omega_\mathrm{res})} \, ,
\end{align}
in which $\langle \cdot | \cdot \rangle_{L^2(\Omega_\mathrm{res})}$ is the standard complex $L^2$-inner product over $\Omega_\mathrm{res}$. With these formulae, we can calculate the excitation coefficients in the frequency domain for arbitrary incident fields $\bm{E}_\mathrm{b}(\bm{r},\omega)$ through simple overlap integrals. A modal expansion as in Eq.~\eqref{eqn:QNM_expansion_PML} is also possible in the time domain with coefficients $\xi_n(t)$ related to $\alpha_n(\omega)$ via a Fourier transform and satisfying the equation
\begin{align}
    \frac{\mathrm{d}\xi_n}{\mathrm{d}t}= &-\mathrm{i}\tilde{\omega}_n \xi_n(t) + \mathrm{i}\tilde{\omega}_n \varepsilon_0\langle \tilde{\bm{E}}_n^* | \varepsilon(\tilde{\omega}_n) - \varepsilon_\mathrm{b} | \bm{E}_\mathrm{b}(t) \rangle \notag \\
    &\hspace{-0.5cm}- \varepsilon_0\langle \tilde{\bm{E}}_n^* | \varepsilon_\mathrm{b} - \varepsilon_\infty | \frac{\mathrm{d}}{\mathrm{d}t}\bm{E}_\mathrm{b}(t) \rangle - \mathrm{i}\tilde{\omega}_n \mu_0\langle \tilde{\bm{H}}_n^* | \Delta \mu | \bm{H}_\mathrm{b}(t) \rangle \notag \\
    =  &-\mathrm{i}\tilde{\omega}_n \xi_n(t) + D_n(t) \ . \label{eqn:QNM_coeffs_time_domain}
\end{align}

It is worth noting that although this auxiliary-field eigenvalue approach was originally introduced for systems with non-dispersive magnetic permeabilities $\mu(\bm{r})$, its generalization for media with strongly frequency-dependent permeabilities (as relevant for magnonic cQED) may be feasible via the introduction of suitable auxiliary fields for the magnetic response. In the following, we assume that such a complete set of suitably regularized and normalized modes can be ascertained, and explore their quantization for arbitrary, linear, 3D, magnetodielectric systems.

\section{\label{Sec:Quantum_QNMs} Quantization of the regularized quasinormal modes}

We now introduce a quantization scheme for the regularized QNMs of arbitrary, 3D, linear, dissipative (with possible gain components) and dispersive nanoresonators, as defined in \S~\ref{Sec:Classic_QNMs}. In our approach, we will quantize the eigenmodes of the PML-truncated domain in Eqs.~\eqref{eqn:classicalQNM_transformed} and \eqref{eqn:QNM_expansion_PML}. As already mentioned, this set of eigenmodes includes QNM-like and PML modes, which following our earlier remarks, shall simply be referred to as modes without further differentiation.
%For the sake of simplicity, we will simply refer to them as modes from now on, as they are treated equally.

Similar to previous work~\cite{franke2019quantization, franke2020nonlinear, franke2022coupled}, our approach is predicated on the formalism of mQED, which offers a phenomenological Green's function quantization scheme for electromagnetic fields in the presence of spatially inhomogeneous, lossy and dispersive media~\cite{gruner1996mqed,dung1998mqed,scheel1998qed,dung2000mqed, raabe2007unified}, later generalized for systems with gain~\cite{matloob1997electromagnetic,raabe2008qed}. However, in order to facilitate a rigorous application of the theory, a brief discussion concerning some important prerequisites is warranted. The complex permittivity $\varepsilon(\bm{r},\omega) = \varepsilon_\mathrm{r}(\bm{r},\omega) + \mathrm{i} \varepsilon_\mathrm{i}(\bm{r},\omega)$ and inverse permeability $\mu^{-1}(\bm{r}, \omega) = \kappa(\bm{r},\omega) = \kappa_\mathrm{r}(\bm{r},\omega) + \mathrm{i} \kappa_\mathrm{i}(\bm{r},\omega)$ are required to satisfy the Kramers-Kronig relations (\textit{i.e.}, they are analytic in the closed, upper-half, complex $\omega$ plane and 
$\zeta(\bm{r},\omega) \rightarrow 1$ for $|\omega| \rightarrow\infty$ ($\zeta \in \{\varepsilon,\kappa \}$). This is not really a requirement of the quantum theory, but arises from the physical necessity of causality. Furthermore, they should be reciprocal, $\zeta(\bm{r},\omega) = \zeta^\mathrm{T}(\bm{r},\omega)$, and satisfy the reflection symmetry condition $\zeta_{i j}(\bm{r},-\omega^*) = \zeta^*_{i j}(\bm{r}, \omega)$, which guarantees their reality in the time domain. These properties ensure that the fundamental QED commutation relations between the electric and magnetic field operators are maintained. If the material parameters $\zeta(\bm{r},\omega)$ of the system are reciprocal, it readily follows from Eq.~\eqref{eqn:PML_parameter_transformation} that the PML-transformed parameters $\tilde{\zeta}(\bm{r},\omega)$ are as well. It should be noted that there have been generalizations of mQED for the cases of non-reciprocal materials and materials with magnetoelectric crossing effects~\cite{buhmann2012macroscopic}, which is, however, beyond the scope of this work. 


When incorporating dispersive or non-dispersive PMLs in the quantization, two problems arise. For dispersive PMLs, it is easy to show from Eq.~\eqref{eqn:PML_parameter_transformation} and the Jacobian in Eq.~\eqref{Eq:PML_Jacobian} that the PML-transformed parameters $\tilde{\zeta}(\bm{r},\omega)$ satisfy reflection symmetry, which preserves the important property that modes with $\Re(\tilde{\omega}_n) \neq 0$ always appear in pairs $(\tilde{\bm{E}}_\mu,\tilde{\omega}_\mu)$, $(\tilde{\bm{E}}^*_n,-\tilde{\omega}^*_n)$ and that all the modes have a non-positive imaginary part $\Im(\tilde{\omega}_n) \leq 0$. Due to the $\omega$-dependence of the coordinate transformation, the material parameters have a pole at $\omega = 0$ and consequently do not satisfy the Kramers-Kronig relations, (\textit{i.e.}, they do not correspond to a causal medium). To resolve this issue, we could construct causal PMLs~\cite{kuzuoglu2002frequency} by making the replacement $\omega \rightarrow \omega + \mathrm{i} \eta$ in Eq.~\eqref{Eq:PML_Absorption} with a small $\eta > 0$, thereby shifting the pole into the lower, complex $\omega$ half-plane. Note that these causal PMLs also work, in principle, in the static case $\omega = 0$, due to the finite values of the transformed material parameters at this point~\cite{kuzuoglu2002frequency}, whereas the usual PMLs fail and cannot be used to reproduce static modes~\cite{besbes2022role}. However, we are only interested in the fields in the inner, unmapped domain $\Omega \setminus \Omega_\mathrm{PML}$, and by using the properties of the Green's function we will show that the correct commutator is maintained within this region even if it is not in the PML region $\Omega_\mathrm{PML}$, so we expect that the use of PMLs as defined in Eq.~\eqref{Eq:PML_Absorption} should suffice in most cases where static modes can be neglected. When using non-dispersive PMLs, the PML-transformed parameters no longer satisfy reflection symmetry, and since they do not afford the damping of waves with non-positive frequencies, the QNMs with $\Re(\tilde{\omega}_n) \leq 0$ are not correctly recovered and PML modes with $\Im(\tilde{\omega}_n) > 0$ occur, which would grow exponentially in time~\cite{sauvan2022norm}. In practice, one is often interested in the spectral response of a system only within a finite frequency interval $\Delta \omega$,
%\in \mathbb{R}_+$.
in which case non-dispersive PMLs could be used provided that the contributions of the modes with $\Re(\tilde{\omega}_n) \leq 0$ are negligible in $\Delta \omega$. With the same argument, one can also justify the use of material parameters $\zeta(\bm{r},\omega)$ or PMLs that do not satisfy the Kramers-Kronig relations (\textit{e.g.}, non-dispersive and complex), provided that the true, physical parameters are sufficiently well approximated within $\Delta\omega$. 
%\textcolor{red}{Cite Franke thesis?} 

The formalism of mQED is based on the dyadic Green's function of the system, defined by 
\begin{align}\label{eqn:Greens_function}
    \nabla \times \tilde{\kappa} \nabla \times G(\bm{r},\bm{r}',\omega) - \frac{\omega^2}{c^2} \tilde{\varepsilon} G(\bm{r},\bm{r}',\omega) = \bm{I} \delta(\bm{r}-\bm{r}') \, .
\end{align}
If the system exhibits loss only, then the Green's function is analytic in the upper $\omega$ half-plane and has a set of discrete poles (corresponding to the QNMs), as well as possible branch cuts in the lower half-plane in the case of non-trivial background geometries. The introduction of gain components in the system shifts up the poles in the complex $\omega$ plane and a prerequisite to apply the theory for such active systems is that all the poles remain located in the lower half-plane. Again, this is not so much a fundamental limitation of the quantum theory but is, rather, a constraint on its range of validity for systems with linear amplification~\cite{raabe2008qed}. The Green's function thus also satisfies the Kramers-Kronig relations, and besides that, reflection symmetry and the reciprocity $G(\bm{r},\bm{r}',\omega) = G^\mathrm{T}(\bm{r}',\bm{r},\omega)$.  


From Eq.~\eqref{eqn:Greens_function}, one can derive the useful relation
\begin{align}\label{eqn:Im_Greens}
    &\Im(G(\bm{r},\bm{r}',\omega)) =  \frac{\omega^2}{c^2} \int_\Omega \mathrm{d}^3 s\, G^\dagger(\bm{s},\bm{r},\omega) \tilde{\varepsilon}_\mathrm{i}(\bm{s},\omega) G(\bm{s},\bm{r}',\omega)  \notag\\
    &- \int_\Omega \mathrm{d}^3 s\, \left( \nabla \times G(\bm{s},\bm{r},\omega)\right)^\dagger\tilde{\kappa}_\mathrm{i}(\bm{s},\omega) \left( \nabla \times G(\bm{s},\bm{r}',\omega)\right) \, , 
\end{align}
in which the curl operator has to be applied column-wise, and the real and imaginary parts of tensorial fields are defined as their hermitian and anti-hermitian parts, respectively, which reduce to the component-wise real and imaginary parts due to reciprocity. Note that although the integrals on the right-hand side have to be taken over the whole space, including the PML domain $\Omega_\mathrm{PML}$, the left-hand side does not depend on the PML parameters as long as $\bm{r}, \bm{r}' \in \Omega \setminus\Omega_\mathrm{PML}$, given that the PMLs (ideally) do not affect the Green's function in the unmapped domain. 

The second ingredient that we need to formulate the modal quantum theory is an expansion of the Green's function in terms of the modes in Eq.~\eqref{eqn:classicalQNM_transformed}. By using a residue-decomposition approach, one can derive the expansion
\begin{align}\label{eqn:Greens_function_expansion}
    G(\bm{r},\bm{r}',\omega) = \sum_n A_n(\omega) \tilde{\bm{E}}_n(\bm{r}) \otimes \tilde{\bm{E}}_n(\bm{r}) \ , 
\end{align}
with $A_n = \varepsilon_0 c^2 / \omega(\tilde{\omega}_n-\omega)$ or $A_n = \varepsilon_0 c^2 / \tilde{\omega}_n(\tilde{\omega}_n-\omega)$, where the non-uniqueness of the expansion stems from the overcompleteness of the set of modes~\cite{lalanne2018light}. 

In mQED, the frequency components of the quantized electric field operator $\hat{\bm{E}}(\bm{r},\omega)$ satisfy the equation
\begin{align}
    \nabla \times \tilde{\kappa}\nabla \times \hat{\bm{E}}(\bm{r},\omega) - \frac{\omega^2}{c^2} \tilde{\varepsilon}\hat{\bm{E}}(\bm{r},\omega) = i \omega \mu_0 \hat{\bm{j}}_\mathrm{F}(\bm{r},\omega) \, . 
\end{align}
In the case of magnetodielectric materials with loss only, the noise/fluctuation current density $\hat{\bm{j}}_\mathrm{F}(\bm{r},\omega)$ introduced on the right-hand side, in accordance with the fluctuation-dissipation theorem, can be written as
\begin{align}\label{eqn:noise_current_loss}
    \hat{\bm{j}}_\mathrm{F}(\bm{r},\omega) = &\omega \sqrt{\frac{\hbar \varepsilon_0}{\pi} \tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)} \hat{f}_{\mathrm{e},j}(\bm{r},\omega) \bm{e}_j  \\
    &+ \nabla \times \bigg( \sqrt{-\frac{\hbar}{\pi\mu_0} \tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)} \hat{f}_{\mathrm{m},j}(\bm{r},\omega) \bm{e}_j   \bigg) \, , \notag
\end{align}
in which we have used the Einstein summation convention and $\hat{f}_{\lambda, j}(\bm{r},\omega)$ ($\hat{f}^\dagger_{\lambda, j}(\bm{r},\omega)$) are bosonic annihilation (creation) operators of the joint (polaritonic) excitations of the field-dressed medium. The latter satisfy the commutation relation\cite{dung1998mqed}
\begin{equation}
    \left[\hat{f}_{\lambda, i}(\bm{r},\omega), \hat{f}^\dagger_{\lambda', j}(\bm{r}',\omega') \right]= \delta_{\lambda \lambda'}\delta_{ij}\delta(\bm{r}-\bm{r}')\delta(\omega-\omega') \, ,
    \label{Eq:Bosonic_Commutation}
\end{equation}
and diagonalize the material-field Hamiltonian:
\begin{align}\label{eqn:mQED_Hamitonian}
    \hat{H}_\mathrm{EM} = \int_\Omega \mathrm{d}^3r \int_0^\infty\mathrm{d}\omega\, \hbar \omega \bigg( &\hat{f}^\dagger_{\mathrm{e}, j}(\bm{r},\omega)\hat{f}_{\mathrm{e}, j}(\bm{r},\omega) \\
    &+ \hat{f}^\dagger_{\mathrm{m}, j}(\bm{r},\omega)\hat{f}_{\mathrm{m}, j}(\bm{r},\omega)\bigg) \, . \notag
\end{align}
Note that in Eq.~\eqref{eqn:noise_current_loss}, we have assumed scalar material parameters $\zeta(\bm{r},\omega)$ and Cartesian PMLs, for which the PML-transformed parameters are diagonal with $\tilde{\zeta}_{\mathrm{i}, j j} = \tilde{\zeta}_{\mathrm{i},j}$. However, the analysis can easily be generalized for the non-diagonal case by replacing $\sqrt{\tilde{\zeta}_{\mathrm{i}, j}(\bm{r},\omega)}$ and the standard basis vectors $\bm{e}_j$ by the eigenvalues and eigenvectors of the matrices $\Im(\zeta(\bm{r},\omega))^{\frac{1}{2}}$, respectively (\textit{i.e.}, by transforming to a system of principal axes).
Explicitly, this would mean replacing Eq.~\eqref{eqn:noise_current_loss} by
\begin{align}
    &\hat{\bm{j}}_\mathrm{F}(\bm{r},\omega) = \omega\sqrt{\frac{\hbar\varepsilon_0}{\pi}} (\Im(\tilde{\varepsilon}(\bm{r},\omega))^\frac{1}{2} \cdot \hat{\bm{f}}_\mathrm{e}(\bm{r},\omega) \notag \\
    &= \omega\sqrt{\frac{\hbar\varepsilon_0}{\pi}}(\Im(\tilde{\varepsilon}(\bm{r},\omega))^\frac{1}{2}_i \bm{e}_i(\bm{r},\omega)\left(\bm{e}^*_i(\bm{r},\omega) \cdot \hat{\bm{f}}_\mathrm{e}(\bm{r},\omega)\right) \notag \\
    &= \omega\sqrt{\frac{\hbar\varepsilon_0}{\pi}}(\Im(\tilde{\varepsilon}(\bm{r},\omega))^\frac{1}{2}_i \bm{e}_i(\bm{r},\omega) \hat{\tilde{f}}_\mathrm{e}(\bm{r},\omega) \notag \ , 
\end{align}
in which $(\Im(\tilde{\varepsilon}(\bm{r},\omega))^\frac{1}{2}_i$ are the eigenvalues of the matrix $\Im(\tilde{\varepsilon}(\bm{r},\omega)^\frac{1}{2}$ and $\bm{e}_i(\bm{r},\omega)$ its eigenvectors, which are complete and orthonormal since $\Im(\tilde{\varepsilon}(\bm{r},\omega))^\frac{1}{2}$ is a hermitian matrix. Note that the eigenvectors are the same as those of the matrix $\Im(\tilde{\varepsilon}(\bm{r},\omega))$. The transformation would work in the same manner for the magnetic part, although the eigenvectors could be different. The Hamiltonian in Eq.~\eqref{eqn:mQED_Hamitonian} would have the same form in the transformed bosonic operators $\hat{\tilde{f}}_\mathrm{e/m}(\bm{r},\omega)$, as the scalar products are invariant under a change of basis.

The noise current defined in Eq.~\eqref{eqn:noise_current_loss} stands in accordance with the fluctuation-dissipation theorem and ensures preservation of the fundamental commutation relations of the electric and magnetic fields. These formulae can also be derived from the canonical quantization of a microscopic model in which the electric and magnetic material responses are described using separate oscillator fields~\cite{philbin2010canonical}. From this perspective, it is clear that the Fock space corresponding to these bosonic variables describes not only the electromagnetic degrees of freedom, but also those of the material excitations. 

In the case of materials exhibiting gain, the creation and annihilation operators interchange roles in the respective (finite) spatial and spectral regions. Eq.~\eqref{eqn:noise_current_loss} must then be replaced by
\begin{align}\label{eqn:noise_current_gain}
    \hat{\bm{j}}_\mathrm{F}(\bm{r},\omega) = \omega \sqrt{\frac{\hbar\varepsilon_0}{\pi}|\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j \bigg[ \Theta(\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \hat{f}_{\mathrm{e},j}(\bm{r},\omega) \notag \\ 
      + \Theta(-\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \hat{f}^\dagger_{\mathrm{e},j}(\bm{r},\omega) \bigg] \notag \\
      +\nabla \times \bigg( \sqrt{\frac{\hbar}{\pi\mu_0} | \tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)|} \bm{e}_j \bigg[\Theta(-\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \hat{f}_{\mathrm{m},j}(\bm{r},\omega) \notag \\
      + \Theta(\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \hat{f}^\dagger_{\mathrm{m},j}(\bm{r},\omega) \bigg]   \bigg) \, ,
\end{align}
and the (normal-ordered) Hamiltonian in Eq.~\eqref{eqn:mQED_Hamitonian} by
\begin{align}\label{eqn:mQED_Hamiltonian_gain}
    \hat{H}_\mathrm{EM} = \int_\Omega \mathrm{d}^3r &\int_0^\infty\mathrm{d}\omega\, \hbar \omega  \\
    \cdot\bigg(&\mathrm{sgn}( \tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \hat{f}_{\mathrm{e},j}^\dagger(\bm{r},\omega)\hat{f}_{\mathrm{e},j}(\bm{r},\omega) \notag \\
    + &\mathrm{sgn}(-\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \hat{f}_{\mathrm{m},j}^\dagger(\bm{r},\omega)\hat{f}_{\mathrm{m},j}(\bm{r},\omega) \bigg) \, . \notag
\end{align}
Note that excitations in the gain regions have a negative-energy contribution to the Hamiltonian. These expressions can again be derived from a microscopic model using inverted oscillator fields in the gain regions~\cite{amooghorban2011casimir}. However, it is worth underlining that the expressions in Eqs.~\eqref{eqn:noise_current_loss} and \eqref{eqn:noise_current_gain} cannot be derived from a generalized phenomenological quantization scheme that allows for general non-local material responses described by a conductivity tensor, whenever the permittivity and permeability are spatially inhomogeneous~\cite{raabe2008qed, raabe2007unified}. Since these expressions can be motivated from a microscopic model and provide analytic results for arbitrary magnetodielectric media, we will make use of them in this paper. 

By using the definition of the Green's function in Eq.~\eqref{eqn:Greens_function}, the total electric field operator in the Schr{\"o}dinger picture can now be written as
\begin{align}
    \hat{\bm{E}}(\bm{r},\omega) &= i \mu_0\int_0^\infty\mathrm{d}\omega\, \omega\int_\Omega \mathrm{d}^3 s\, G(\bm{r},\bm{s},\omega) \bm{j}_\mathrm{F}(\bm{s},\omega) + \mathrm{h.c.} \notag \\
    &= \hat{\bm{E}}^{(+)}(\bm{r}) + \hat{\bm{E}}^{(-)}(\bm{r}) \ ,
\end{align}
where $\hat{\bm{E}}^{(\pm)}(\bm{r})$ are the positive/negative frequency parts. By using Eq.~\eqref{eqn:noise_current_gain} and the identity in Eq.~\eqref{eqn:Im_Greens}, we can ascertain the commutator of the electric field operator:
\begin{align}\label{eqn:E_field_commutator}
  &\left[ \hat{E}^{(+)}_i(\bm{r}), \hat{E}^{(-)}_j(\bm{r}') \right] \notag \\
  &= \frac{\hbar \mu_0}{\pi} \int_0^\infty \mathrm{d}\omega\, \omega^2 \int\mathrm{d}^3s\notag \\
  &\hspace{1cm}\cdot\bigg[ \frac{\omega^2}{c^2} G^\dagger_{i m}(\bm{s},\bm{r},\omega) \tilde{\varepsilon}_{\mathrm{i},m}(\bm{s},\omega) G_{m j}(\bm{s},\bm{r}',\omega) \notag \\
  &- (\nabla \times G(\bm{s},\bm{r},\omega))^\dagger_{i m} \tilde{\kappa}_{\mathrm{i},m}(\bm{s},\omega)(\nabla \times G(\bm{s},\bm{r'},\omega))_{m j}   \bigg]   \notag \\
  &= \frac{\hbar \mu_0}{\pi} \int_0^\infty \mathrm{d}\omega\, \omega^2 \Im(G(\bm{r},\bm{r}',\omega))_{i j}  \, ,
\end{align}
where the latter equation shows that the commutator is not affected by the PMLs for $\bm{r},\bm{r}' \in \Omega\setminus\Omega_{\mathrm{PML}}$. By invoking the first equality and the Green's function expansion in Eq.~\eqref{eqn:Greens_function_expansion}, we can expand the commutator in terms of the modes:
\begin{align}\label{eqn:E_field_commutator_QNM}
    \left[ \hat{E}^{(+)}_i(\bm{r}), \hat{E}^{(-)}_j(\bm{r}') \right] = \sum_{n,n'} P_{n n'} \tilde{E}_{n,i}(\bm{r}) \tilde{E}^*_{n',j}(\bm{r}') \, ,
\end{align}
with 
\begin{align}
    P_{n n'} = \frac{\hbar \mu_0}{\pi} &\int_0^\infty \mathrm{d}\omega\, \omega^2\int\mathrm{d}^3 s\, A_n(\omega) A_{n'}^*(\omega)  \\ 
    \cdot\bigg[ &\frac{\omega^2}{c^2} \tilde{\bm{E}}_n(\bm{s}) \tilde{\varepsilon_{\mathrm{i}}}(\bm{s},\omega)\tilde{\bm{E}}^*_{n'}(\bm{s})  \notag\\
    &-(\nabla \times\tilde{\bm{E}}_n(\bm{s})) \tilde{\kappa}_{\mathrm{i}}(\bm{s},\omega)(\nabla \times\tilde{\bm{E}}^*_{n'}(\bm{s})) \bigg] \, . \notag
\end{align}
These integrals describe the losses of the modes. Ultimately, our aim is to develop a suitable modal expansion of the electric field operator. As we consider general, anisotropic, magnetodielectric systems which could exhibit electric and magnetic losses in distinct spatial/frequency regions, we start by decomposing the QNM operators in electric/magnetic and loss/gain components; we thus introduce the four operators $(\hat{\xi}_{n,\mathrm{e},\mathrm{L}}, \hat{\xi}_{n,\mathrm{e},\mathrm{G}}, \hat{\xi}_{n,\mathrm{m},\mathrm{L}}, \hat{\xi}_{n,\mathrm{m},\mathrm{G}})$ for each mode and expand the electric field operator in the form 
\begin{align}
    \hat{\bm{E}}(\bm{r}) &= \sum_n \tilde{E}_{n}(\bm{r}) (\hat{\xi}_{n,\mathrm{e},\mathrm{L}} + \hat{\xi}^\dagger_{n,\mathrm{e},\mathrm{G}} + \hat{\xi}_{n,\mathrm{m},\mathrm{L}} + \hat{\xi}_{n,\mathrm{m},\mathrm{G}}^\dagger) \notag \\
    &\hspace{6cm}+ \mathrm{h.c.} \notag \\
    &= \hat{\bm{E}}^{(+)}(\bm{r}) + \hat{\bm{E}}^{(-)}(\bm{r}) \, ,
\end{align}
in which the modal operators can be expressed through the continuous bosonic variables:
\begin{align}\label{eqn:QNM_operataors_unsymmetrized_e}
    \hat{\xi}^{(\dagger)}_{n,\mathrm{e},\mathrm{L/G}} = \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n(\omega)\int\mathrm{d}^3 r\, \theta(\pm\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ \sqrt{\frac{\hbar\varepsilon_0}{\pi}|\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot \tilde{\bm{E}}_n(\bm{r}) \hat{f}_{\mathrm{e},j}^{(\dagger)}(\bm{r},\omega) \, , \\
    \hat{\xi}^{(\dagger)}_{n,\mathrm{m},\mathrm{L/G}} = \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega A_n(\omega)\int\mathrm{d}^3 r\, \theta(\mp\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ \sqrt{\frac{\hbar}{\pi \mu_0}|\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot (\nabla\times\tilde{\bm{E}}_n(\bm{r})) \hat{f}_{\mathrm{m},j}^{(\dagger)}(\bm{r},\omega) \, . \label{eqn:QNM_operataors_unsymmetrized_m}
\end{align}
Note that the hermitian conjugates of the gain operators $\hat{\xi}_{n,\mathrm{e/m},\mathrm{G}}$ have to be used in the expansion of the positive-frequency part of the electric field, in order to reproduce the correct commutation relation as given in Eq.~\eqref{eqn:E_field_commutator_QNM}. Although they are hermitian conjugates of modal operators, they still behave like superpositions of positive-frequency excitations ($\propto \mathrm{e}^{-\mathrm{i}\omega t}$), as can be seen from Eqs.~\eqref{eqn:QNM_operataors_unsymmetrized_e} and \eqref{eqn:QNM_operataors_unsymmetrized_m}, and the Heisenberg equations for the continuous variables $\hat{f}_{\mathrm{e/m},j}(\bm{r},\omega)$ in the gain regions with the Hamiltonian of Eq.~\eqref{eqn:mQED_Hamiltonian_gain}. This is analogous to the approach in Ref.~\cite{franke2022coupled}. In our case, however, we have included the PMLs into the quantization, which always exhibit gain. In the presence of gain materials, the vacuum correlation function of the electric field would be given by
\begin{align}\label{eqn:vacuum_correlation_PMLs}
    &\langle \hat{E}_i(\bm{r}) \hat{E}_j(\bm{r}') \rangle \\
    &= \frac{\hbar \mu_0}{\pi} \int_0^\infty \mathrm{d}\omega\, \omega^2 \int\mathrm{d}^3 s\notag \\
    &\hspace{1cm}\cdot \bigg[ \frac{\omega^2}{c^2} G^\dagger_{i m}(\bm{s},\bm{r},\omega) |\tilde{\varepsilon}_{\mathrm{i},m}(\bm{s},\omega)| G_{m j}(\bm{s},\bm{r}',\omega) \notag \\
  &- (\nabla \times G(\bm{s},\bm{r},\omega))^\dagger_{i m} |\tilde{\kappa}_{\mathrm{i},m}(\bm{s},\omega)|(\nabla \times G(\bm{s},\bm{r'},\omega))_{m j}   \bigg] \notag\ .  
\end{align}
Due to the moduli of the material parameters in this formula, the identity in Eq.~\eqref{eqn:Im_Greens} cannot be used to express the correlation function in terms of the imaginary part of the Green's function, which must be taken into account when, for example, calculating QE decay rates~\cite{franke2021fermi} or Casimir(-Polder) forces~\cite{sambale2010casimir}. In our approach, this implies that the presence of gain components in the PMLs would affect the correlation function due to induced fluctuations and thus the quantum dynamics, as they would, for example, affect the spontaneous decay of a QE. This means that in order to obtain the correct correlation function of the real system without contributions from the PMLs, we have to eliminate these fluctuations attributable to the gain components of the PMLs from our modal theory. To achieve this, we redefine the gain and loss operators in Eqs.~\eqref{eqn:QNM_operataors_unsymmetrized_e} and \eqref{eqn:QNM_operataors_unsymmetrized_m} by including the gain components of the PML region $\Omega_\mathrm{PML}$ in the loss operators:
\begin{align}\label{eqn:QNM_operators_unsymmetrized_e_L_2}
    \hat{\xi}_{n,\mathrm{e},\mathrm{L}} = + \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n(\omega)\int_\Omega\mathrm{d}^3 r\, \bigg[\theta(\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ 
    \ \ \ \ \sqrt{\frac{\hbar\varepsilon_0}{\pi}|\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot \tilde{\bm{E}}_n(\bm{r}) \hat{f}_{\mathrm{e},j}(\bm{r},\omega) \bigg]\notag \\
    + \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n(\omega)\int_{\Omega_\mathrm{PML}}\mathrm{d}^3 r\, \bigg[ \theta(-\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ 
    \sqrt{\frac{\hbar\varepsilon_0}{\pi}|\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot \tilde{\bm{E}}_n(\bm{r}) \hat{f}_{\mathrm{e},j}^{\dagger}(\bm{r},\omega) \bigg] \notag \\
    = \hat{\tilde{\xi}}_{n,\mathrm{e},\mathrm{L}} + \hat{\tilde{\xi}}^\dagger_{n,\mathrm{e},\mathrm{PML}} \ , 
\end{align}
\begin{align}\label{eqn:QNM_operators_unsymmetrized_e_G_2}
    \hat{\xi}^\dagger_{n,\mathrm{e},\mathrm{G}} =  \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n(\omega)\int_{\Omega\setminus\Omega_\mathrm{PML}}\mathrm{d}^3 r\, \bigg[\theta(-\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ 
    \sqrt{\frac{\hbar\varepsilon_0}{\pi}|\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot \tilde{\bm{E}}_n(\bm{r}) \hat{f}_{\mathrm{e},j}^{\dagger}(\bm{r},\omega) \bigg] \ , 
\end{align}
\begin{align}\label{eqn:QNM_operators_unsymmetrized_m_L_2}
    \hat{\xi}_{n,\mathrm{m},\mathrm{L}} = + \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega A_n(\omega)\int_\Omega\mathrm{d}^3 r\, \bigg[\theta(-\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ 
    \sqrt{\frac{\hbar}{\pi \mu_0}|\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot (\nabla\times\tilde{\bm{E}}_n(\bm{r})) \hat{f}_{\mathrm{m},j}(\bm{r},\omega) \bigg] \notag \\
    + \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega A_n(\omega)\int_{\Omega_\mathrm{PML}}\mathrm{d}^3 r\, \bigg[\theta(\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ 
    \sqrt{\frac{\hbar}{\pi \mu_0}|\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot (\nabla\times\tilde{\bm{E}}_n(\bm{r})) \hat{f}_{\mathrm{m},j}^{\dagger}(\bm{r},\omega) \bigg] \notag \\
    = \hat{\tilde{\xi}}_{n,\mathrm{m},\mathrm{L}} + \hat{\tilde{\xi}}^\dagger_{n,\mathrm{m},\mathrm{PML}} \ , 
\end{align}
\begin{align}\label{eqn:QNM_operators_unsymmetrized_m_G_2}
    \hat{\xi}^\dagger_{n,\mathrm{m},\mathrm{G}} = + \mathrm{i} \mu_0 \int_0^\infty\mathrm{d}\omega\, \omega A_n(\omega)\int_{\Omega \setminus\Omega_\mathrm{PML}}\mathrm{d}^3 r\, \bigg[\theta(\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) \notag\\ 
    \sqrt{\frac{\hbar}{\pi \mu_0}|\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega) |} \bm{e}_j\cdot (\nabla\times\tilde{\bm{E}}_n(\bm{r})) \hat{f}_{\mathrm{m},j}^{\dagger}(\bm{r},\omega) \bigg] \ .
\end{align}
These loss operators thus satisfy the commutation relations
\begin{align}\label{eqn:P_e_L}
    \left[ \hat{\xi}_{n,\mathrm{e},\mathrm{L}}, \hat{\xi}^\dagger_{n',\mathrm{e},\mathrm{L}} \right]  = \frac{\hbar \mu_0}{\pi} \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n(\omega) A^*_{n'}(\omega) \notag \\
    \bigg[+ \int_\Omega\mathrm{d}^3 r\, 
     \theta(\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) 
    \frac{\omega^2}{c^2} |\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)| E_{n,j}(\bm{r})E_{n', j}^*(\bm{r}) \notag \\
    - \int_{\Omega_\mathrm{PML}} \mathrm{d}^3 r\, 
     \theta(-\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) 
    \frac{\omega^2}{c^2} |\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)| E_{n,j}(\bm{r})E_{n', j}^*(\bm{r})\bigg]  \notag \\
     = \tilde{P}^{\mathrm{e},\mathrm{L}}_{n n'} - \tilde{P}^{\mathrm{e},\mathrm{PML}}_{n' n}= P^{\mathrm{e},\mathrm{L}}_{n n'}  \ , 
\end{align}
\begin{align}\label{eqn:P_m_L}
    \left[ \hat{\xi}_{n,\mathrm{m},\mathrm{L}}, \hat{\xi}^\dagger_{n',\mathrm{m},\mathrm{L}} \right] = P^{\mathrm{m},\mathrm{L}}_{n n'} = \frac{\hbar \mu_0}{\pi} \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n(\omega) A^*_{n'}(\omega) \notag \\
    \bigg[+\int_\Omega\mathrm{d}^3 r\, 
     \theta(-\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) 
     |\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)| \notag\\(\nabla\times\bm{E}_n(\bm{r}))_j (\nabla \times\bm{E}_{n'}^*(\bm{r}) )_j \notag \\
     -\int_{\Omega_\mathrm{PML}}\mathrm{d}^3 r\, 
     \theta(\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) 
     |\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)| \notag \\(\nabla\times\bm{E}_n(\bm{r}))_j (\nabla \times\bm{E}_{n'}^*(\bm{r}) )_j \bigg] \notag \\ 
     = \tilde{P}^{\mathrm{m},\mathrm{L}}_{n n'} - \tilde{P}^{\mathrm{m},\mathrm{PML}}_{n' n}= P^{\mathrm{e},\mathrm{L}}_{n n'}  \ , 
\end{align}
and the gain operators satisfy
\begin{align}
    \left[ \hat{\xi}_{n,\mathrm{e},\mathrm{G}}, \hat{\xi}^\dagger_{n',\mathrm{e},\mathrm{G}} \right] = P^{\mathrm{e},\mathrm{G}}_{n n'} = \frac{\hbar \mu_0}{\pi} \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n^*(\omega) A_{n'}(\omega) \notag \\
    \int_{\Omega\setminus\Omega_\mathrm{PML}} \mathrm{d}^3 r\, \theta(-\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)) 
    \frac{\omega^2}{c^2} |\tilde{\varepsilon}_{\mathrm{i},j}(\bm{r},\omega)| E^*_{n,j}(\bm{r})E_{n', j}(\bm{r})
\end{align}
\begin{align}
    \left[ \hat{\xi}_{n,\mathrm{m},\mathrm{G}}, \hat{\xi}^\dagger_{n',\mathrm{m},\mathrm{G}} \right] = P^{\mathrm{m},\mathrm{G}}_{n n'} =  \frac{\hbar \mu_0}{\pi} \int_0^\infty\mathrm{d}\omega\, \omega^2 A_n^*(\omega) A_{n'}(\omega) \notag \\
    \int_{\Omega\setminus\Omega_\mathrm{PML}}\mathrm{d}^3 r\, 
     \theta(\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)) 
     |\tilde{\kappa}_{\mathrm{i},j}(\bm{r},\omega)| \notag \\
     (\nabla\times\bm{E}^*_n(\bm{r}))_j (\nabla \times\bm{E}_{n'}(\bm{r}) )_j 
\end{align}

