    In this paper, for the aforementioned reasons, we derive a new model, which generalizes the two-phase flow model derived in \cite{Giorgini2023} to the framework of an evolving domain with a free boundary. 
    Here, a key assumption is that the evolution of our domain is driven by the velocity field of the mixture contained in the domain. This means that the normal velocity of the free boundary is equal to the normal component of the velocity field at the boundary. 

    \subsection{Formulation of our model}

	To formulate our system of equations, we consider an evolving domain $\{\Omega(t)\}_{t\in[0,T]}$ in $\R^d$ (with $d\in \N$, $T>0$). We set $\Gamma(t)\coloneqq\partial\Omega(t)$ for all $t\in[0,T]$. This means that $\{\Gamma(t)\}_{t\in[0,T]}$ is a closed, oriented evolving hypersurface in $\R^d$. For brevity, we use the notation
	\begin{equation*}
		\QT \coloneqq \bigcup_{0 < t <T} \{t\} \times \Om 
		\quad\text{and}\quad 
		S_T \coloneqq \bigcup_{0 < t <T} \{t\} \times \Ga 
	\end{equation*}
	We further assume that the evolving domain $\QT$ is transported by a vector field $\u\in C^2(\overline{\QT})$, which is supposed to be the \textit{volume-averaged velocity field} of the two materials that are contained inside the domain.
	This entails that $S_T$ is transported by the trace vector field $\u\vert_{S_T}\in C^2(S_T)$. Since $S_T$ is orientable, there exists an evolving unit normal vector field $\n\in C^2(S_T)$ and the normal velocity $\cV$ of $S_T$ is thus given by
	\begin{align*}
		\u \cdot \n = \cV \quad\text{on $S_T$}.
	\end{align*}
    For a mathematically precise formulation of the notion of evolving domains and surfaces that are transported by a velocity field, we refer to \cite{BDGP-book,BGN-book}.

    \pagebreak[4]

	In order to describe the time evolution of the velocity field $\u$, we derive the following thermodynamically consistent model:%
    \begin{subequations}
		\label{eqs:NSCH}
		% \begin{empheq}[left={\empheqlbrace}]{alignat=3}
        \begin{alignat}{3}
			\label{eqs:NSCH:1}
			& \delt \big(\rho(\phi) \u\big) 
			+ \Div \big( \u \otimes (\rho(\phi)\u + \J) \big) 
			= \Div(\T),
			\quad \Div \u = 0
			&& \tin \QT, 
			\\
			\label{eqs:NSCH:2}
			& \deltb \phi 
			= \Div (m_\Omega(\phi) \Grad \mu)
			&& \tin \QT,
			\\
			\label{eqs:NSCH:3}
			&\mu 
			= - \varepsilon \Lap \phi + \varepsilon^{-1} F'(\phi)  && \tin \QT,
			\\
			\label{eqs:NSCH:4}
			& \deltc \psi  
			= \Divg (m_\Gamma(\psi) \Gradg \theta) - \beta m_\Omega(\phi) \deln \mu  && \ton S_T,
			\\
			\label{eqs:NSCH:5}
			& \theta 
			= - \delta \Lapg \psi + \delta^{-1} G'(\psi)
			+ \alpha \varepsilon \deln \phi  && \ton S_T, 
			\\
			\label{eqs:NSCH:6}
			&K \varepsilon \deln \phi
			= \alpha \psi - \phi, 
			\quad 
			L m_\Omega(\phi) \deln \mu
			= \beta \theta - \mu, 
			\quad K,L \in [0,\infty], 
			&& \ton S_T, 
			\\
			\label{eqs:NSCH:7}
			& \big[\T\n  + \Gradg q  + \gamma_\tau  \u \big]_\tau
			= \Big[ 
                \onehalf \, (\J\cdot\n) \, \u
                - \delta\, \Divg(\Gradg\psi \otimes \Gradg\psi)
            \Big]_\tau
			&& \ton S_T, 
			\\
			\label{eqs:NSCH:8}
			& \T\n\cdot\n + \gamma_\n \cV %(\u \cdot \n)
			= \onehalf \, (\J\cdot\n) \cV %(\u \cdot \n)
                - q H 
			&& \ton S_T, \\
			\label{eqs:NSCH:9}
			&  \Divg \u = 0,  
            \quad \u \cdot \n = \cV
			&& \ton S_T.
		% \end{empheq}
        \end{alignat}
	\end{subequations}
	This system can be understood as a generalized version of the model introduced in \cite{Giorgini2023}, adapted to the situation of an evolving domain with free boundary. 
    An equivalent reformulation of this model will be discussed in Subsection~\ref{SUBSEC:ALTFOR}.

    In the above equations and throughout this paper, $\Grad$ denotes the gradient, $\Gradg$ denotes the tangential gradient on the surface, $\Div$ denotes the divergence, and $\Divg$ denotes the surface divergence. For (sufficently regular) functions $\mathbf{w}:\QT\to \R^d$ and $\mathbf{M}:\QT\to \R^{d\times d}$, we use the conventions
    \begin{equation*}
        [\Grad\mathbf{w}]_{ij} = \partial_j \mathbf{w}_i
        \quad\text{and}\quad
        [\Div \mathbf{M}]_i = \sum_{k=1}^d \partial_k \mathbf{M}_{ik}
    \end{equation*}
    for all $i,j\in\{1,...,d\}$. This means that for any vector-valued function, $\Grad$ provides its Jacobian matrix.
    For functions on the surface $S_T$, an analogous convention is employed.
    Moreover, for any (column) vectors $\mathbf{v}, \mathbf{w}\in\R^d$, their tensor product is given by $\mathbf{v} \otimes \mathbf{w} = \mathbf{v}\mathbf{w}^T$.

	In system \eqref{eqs:NSCH}, the volume-averaged velocity field of the two fluids is represented by the vector-valued function $\u:\QT\to\R^d$. The scalar functions $\phi:\QT\to\R$, $\mu:\QT\to\R$, $\psi:S_T\to\R$ and $\theta:S_T\to\R$ denote the \textit{bulk phase-field}, the \textit{bulk chemical potential}, the \textit{surface phase-field}, and the  \textit{surface chemical potential}, respectively. 
	It is a key feature of the model \eqref{eqs:NSCH} that the evolving domain $\QT$ is transported by the velocity field $\u$. This is reflected in the boundary condition $\eqref{eqs:NSCH:9}_2$ and, therefore, system \eqref{eqs:NSCH} is a \textit{free boundary problem}.

	The time evolution of $\u$ is described by the \textit{incompressible Navier--Stokes equations} \eqref{eqs:NSCH:1}. Here, $\rho(\phi)$ stands for the phase-field dependent \textit{density}, $\J$ represents the \textit{mass flux} related to interfacial motion, and $\T$ is the \textit{stress tensor}. They are given by the formulas
	\begin{align}
		\label{eq:rho}
		\rho(\phi) &\coloneqq \onehalf \trho_2 (1+\phi) + \onehalf \trho_1 (1-\phi),
		\\
		\label{eq:J}
		\J &\coloneqq - \onehalf (\trho_2 - \trho_1) \mom(\phi) \Grad\mu,
		\\
		\label{eq:T}
		\T &\coloneqq  \bS - p\I - \eps \Grad\phi \otimes \Grad\phi
		\quad\text{with}\quad
		\bS \coloneqq 2\nu(\phi) \, \D\u,
	\end{align}
	where the constants $\trho_1,\trho_2>0$ are the individual densities of the fluids, $\nu(\phi)$ is the phase-field dependent \textit{viscosity}, and
	$$\D\u \coloneqq \onehalf \big( (\Grad \u) + (\Grad \u)^T \big)$$
	denotes the \textit{symmetric gradient} of $\u$. 
    The matrix $\bS$ is referred to as the \textit{viscous stress tensor}.

	The evolution of the phase-fields $\phi$ and $\psi$ is described by the \textit{bulk-surface convective Cahn--Hilliard system} \eqref{eqs:NSCH:2}--\eqref{eqs:NSCH:6}. 
	Here, the \textit{bulk Cahn--Hilliard equation} \eqref{eqs:NSCH:2}--\eqref{eqs:NSCH:3} is coupled to the \textit{surface Cahn--Hilliard equation} \eqref{eqs:NSCH:4}--\eqref{eqs:NSCH:5}, which can be interpreted as a dynamic boundary condition. To state the Cahn--Hilliard equations, we are using the following notation. For scalar functions $f:\QT\to\R$ and $g:S_T\to\R$, we write
	\begin{equation}
		\label{DEF:MATDER}
		\deltb f \coloneqq \delt f + \u\cdot \nabla f,
		\qquad 
		\deltc g  
        \coloneqq \delt \tilde g + \u \cdot \Grad \tilde g
        = \delt \tilde g + \u_\tau \cdot \Gradg \tilde g + \cV \n\cdot \Grad \tilde g
	\end{equation}
	to denote the \textit{material derivatives} of $f$ and $g$, respectively. Here, $\tilde g$ denotes an arbitrary (sufficiently regular) extension of $g$ onto a neighborhood of $S_T$. In fact, the expression $\deltc g$ does actually not depend on the choice of this extension (see, e.g., \cite[Remark~2.7.2]{BDGP-book}).
    The phase-field dependent functions $m_\Omega(\phi)$ and $m_\Gamma(\psi)$ represent the \textit{mobilities} of the bulk- and the surface materials, respectively. Moreover, $F'$ and $G'$ are the derivatives of \textit{double-well potentials} $F$ and $G$, respectively.
	The bulk and surface quantities of the Cahn--Hilliard equations are further coupled through the boundary conditions in \eqref{eqs:NSCH:6}, which are to be understood as follows:%
	\begin{subequations}
		\label{CH:CPL}
		\begin{alignat}{2}
			\label{CH:CPL:1}
			&\begin{cases}
				\phi = \alpha \psi  &\text{if $K=0$},\\
				K \varepsilon \deln \phi = \alpha \psi - \phi &\text{if $K\in (0,\infty)$},\\
				\deln \phi = 0 &\text{if $K=\infty$}
			\end{cases}
			&&\quad \ton S_T, 
			\\[1ex]
			\label{CH:CPL:2}
			&\begin{cases}
				\mu = \beta \theta  &\text{if $L=0$},\\
				L m_\Omega(\phi) \deln \mu = \beta \theta - \mu &\text{if $L\in (0,\infty)$},\\
				m_\Omega(\phi) \deln \mu = 0 &\text{if $L=\infty$}
			\end{cases}
			&&\quad \ton S_T.
		\end{alignat}
	\end{subequations}
	Here, $\alpha,\beta\in\R$ are prescribed parameters. 
	The parameters $K,L\in [0,\infty]$ are used to distinguish different cases, each resulting in a certain solution behaviour related to a corresponding physical phenomenon (see Subsection~\ref{SUBSEC:DYN} for more details). 
    If $K=0$, we additionally assume that $\alpha\neq 0$.

    Furthermore, on the surface $S_T$, the tangential component of the velocity field is governed by the \textit{generalized Navier slip boundary condition} \eqref{eqs:NSCH:7} with a slip parameter $\gamma_\tau$ that may depend on the materials involved (i.e., the phase-fields).
	Here, for any vector field $\mathbf{w}$, the notation $\mathbf{w}_\tau$ indicates that only the tangential component of $\mathbf{w}$ is considered.
	The normal component of $\u$ is determined by the relation \eqref{eqs:NSCH:8}, which involves 
    the \textit{mean curvature} $H = - \frac{1}{d}\Divg\n$.
	Moreover, $\gamma_\n$ is a prescribed scalar function that may depend on the phase-fields. 

    The energy functional associated with system \eqref{eqs:NSCH} is given by
    \begin{equation}
        \label{DEF:E}
        \begin{aligned}
            \cE(\u,\phi,\psi) & \coloneqq 
            \intO \frac{\rho(\phi)}{2} \abs{\u}^2 \dx
            + \intO \Big(
            \frac{\varepsilon}{2} \abs{\Grad \phi}^2 
            + \frac{1}{\varepsilon} F(\phi)
            \Big) \dx \\
            & \qquad + \intG \Big(
            \frac{\delta}{2} \abs{\Gradg \psi}^2 
            + \frac{1}{\delta} G(\psi)
            + \frac{1}{2}\mathds{h}(K) \abs{\alpha \psi - \phi}^2
            \Big) \dHH{d-1},
        \end{aligned}
    \end{equation}
    where the function 
    \begin{equation}
        \label{DEF:H}
        \mathds{h}:[0,\infty] \to \R, \quad
        \mathds{h}(r) \coloneqq
        \begin{cases}
            r^{-1} &\text{if $r\in(0,\infty)$},\\
            0 &\text{if $r\in\{0,\infty\}$}
        \end{cases}
    \end{equation}
    is used to account for the different choices of the parameter $K$. In \eqref{DEF:E}, the first summand on the right-hand side represents the \textit{kinetic energy}. The second summand is the \textit{bulk free energy} and the third summand is the \textit{surface free energy}. They are both of \textit{Ginzburg--Landau type} and the free energy densities crucially depend on the potentials $F$ and $G$, respectively, which are assumed to be double-well shaped. This means that they are coercive with two local minimum points close to $-1$ and $1$ (as these values represent the pure phases of the materials) and a local maximum point in between (usually at zero).
    A typical choice for $F$ and $G$ is the so-called \textit{Flory--Huggins potential}
    \begin{align}\label{DEF:W:LOG}
        W_{\textup{log}}(s) \coloneqq \frac{\Theta}{2}\big[(1+s)\ln(1+s) + (1-s)\ln(1-s)\big] -\frac{\Theta_c}{2}s^2, \quad s\in(-1,1)
    \end{align}
    for $0 < \Theta < \Theta_c$, which can be derived from Boltzmann kinetics. It is sometimes simply referred to as the \textit{logarithmic potential}. 
    Since $W_{\textup{log}}'(s) \to \pm\infty$ as $s\to\pm\infty$, the potential $W_{\textup{log}}$ is a so-called \textit{singular potential}. This property ensures that for any solution of system~\eqref{eqs:NSCH} with $F=G=W_{\textup{log}}$, the phase-fields $\phi$ and $\psi$ attain their values within the physically relevant range $[-1,1]$. An important consequence is that due to $\abs{\phi}\le 1$, we have
    \begin{equation*}
        0 < \min\{\trho_1,\trho_2\} \leq \rho(\phi) \leq \max\{\trho_1,\trho_2\} < \infty, 
    \end{equation*}
    which means that the density $\rho(\phi)$ remains uniformly positive and finite.
    Furthermore, our model has the following physically relevant properties:
	%%%
	\begin{itemize}[leftmargin=*, topsep=0em, partopsep=0em, parsep=1ex, itemsep=0ex]
		\item \textbf{Energy dissipation.}
		Sufficiently regular solutions of system \eqref{eqs:NSCH} satisfy the \textit{energy-dissipation law}
		\begin{equation}
			\label{diss}
			\begin{aligned}
				& \ddt \cE(\u,\phi,\psi)
				+ \intO 2 \nu(\phi) \abs{\D \u}^2 \dx
				+ \intG \gamma_{\tau} \abs{\u_{\tau}}^2 \dHH{d-1} 
				\\&\quad 
				+ \intG \gamma_{\n} \abs{\u \cdot \n}^2 \dHH{d-1} 
				+ \intO m_{\Omega}(\phi) \abs{\Grad \mu}^2 \dx
				\\&\quad 
				+ \intG m_{\Gamma}(\psi) \abs{\Gradg \theta}^2 \dHH{d-1}
				+ \intG \mathds{h}(L) \abs{\beta \theta - \mu}^2 \dHH{d-1}
				= 0
			\end{aligned}
		\end{equation}
		for all $t\in [0,T]$. In this sense, our model can be considered \textit{thermodynamically consistent}.
		%%%
		\item \textbf{Conservation of mass.}
		Sufficiently regular solutions of system \eqref{eqs:NSCH} fulfill the \textit{mass conservation law} 
		\begin{align}
			\label{mass}
			&\beta \intO \phi(t) \dx + \intG \psi(t) \dHH{d-1}
			= \beta \int_{\Omega(0)} \phi(0) \dx + \int_{\Gamma(0)} \psi(0) \dHH{d-1}
		\end{align}
		for all $t\in [0,T]$. In the case $L=\infty$, it even holds
		\begin{align}
			\label{mass:inf}
			\intO \phi(t) \dx 
			= \int_{\Omega(0)} \phi(0) \dx
			\quad\text{and}\quad
			\intG \psi(t) \dHH{d-1} 
			= \int_{\Gamma(0)} \psi(0) \dHH{d-1}
		\end{align}
		for all $t\in [0,T]$, so the bulk mass and the surface mass are conserved separately.
		%%%
		\item \textbf{Conservation of bulk volume and surface area.}
		For any sufficiently regular solution of system \eqref{eqs:NSCH}, the volume of the evolving domain $\Omega(\cdot)$ and the area of the evolving boundary $\Gamma(\cdot)$ are preserved over the course of time.
		Namely, as the bulk fluid is assumed to be incompressible (i.e., $\Div\u = 0$ in $\QT$) and there is no extra source, it follows that
		\begin{align}
			\label{vol}
			\ddt \mathrm{Vol}_{d}\big(\Omega(t)\big)
			= \ddt \intO 1 \dx 
			= \intO \Div(\u) \dx 
			= 0 
			\quad\text{for all $t\in[0,T]$}
		\end{align}
		by means of the Reynolds transport theorem (see, e.g., \cite[Theorem~2.11.1]{BDGP-book}).
		Similarly, as we also demand $\Divg\u = 0$ on $\ST$, the transport theorem for evolving hypersurfaces (see, e.g., \cite[Theorem~2.10.1]{BDGP-book}) yields
		\begin{align}
			\label{area}
			\ddt \mathrm{Vol}_{d-1}\big(\Gamma(t)\big)
			= \ddt \intG 1 \dHH{d-1} 
			= \intG \Divg(\u) \dHH{d-1} 
			= 0 
			\quad\text{for all $t\in[0,T]$.}
		\end{align}
	\end{itemize}

    \subsection{Further related literature}

    In contrast to our model, where the free boundary is the boundary of the evolving domain, there are also models for two-phase flows, where a free boundary contained in the interior of a static (i.e., time-independent) domain is considered.
    We refer, for example, to \cite{Garcke2014,Barrett2017}. 
    A related sharp interface model with moving contact lines on inextensible elastic sheets was derived in \cite{YZR2023SharpInterface}.
    For the investigation of Cahn--Hilliard type models on evolving surfaces without any bulk contribution, we refer to \cite{Abels2025,Bachini2023,Bachini2023a,Caetano2021,Caetano2023,Elliott2024} as well as the references therein.

    \subsection{The outline of this paper}

	The plan of this paper is as follows.
    In Section~\ref{SECT:VAR}, we present an equivalent reformulation of system \eqref{eqs:NSCH}. Moreover, we compare two simplified variants of our model, one without dynamic boundary conditions and one in a domain with static boundary, with previous models proposed in the literature. We further discuss the benefits of dynamic boundary conditions in our model as well as in Cahn--Hilliard type models in general.
	Section~\ref{SECT:MODEL} is then devoted to the derivation of the Navier--Stokes--Cahn--Hilliard model~\eqref{eqs:NSCH}. We start from scratch by considering local mass balance laws as well as local energy dissipation laws. Eventually, our model derivation is completed via the Langrange multiplier approach.

    \section{Important features and variants of our model}\label{SECT:VAR} 

	\subsection{An alternative reformulation}\label{SUBSEC:ALTFOR} 
    Instead of $p$ and $q$, we can alternatively use the pressures
    \begin{alignat*}{2}
        \ov p &:= p + f
        &&\quad\text{with}\quad
        f \coloneqq 
        \Big( \frac \eps2 \abs{\Grad\phi}^2 +\frac 1\eps F(\phi) \Big),
        \\
        \ov q &:= q + g
        &&\quad\text{with}\quad
        g \coloneqq 
        \Big( \frac \delta 2 \abs{\Gradg\psi}^2 
            + \frac 1\delta G(\psi) 
            + \frac 12 \h(K) (\alpha\psi-\phi)^2 \Big),
    \end{alignat*}
    which involve the free energy densities $f$ and $g$.
    It is straightforward to check that
    \begin{align*}
        &- \Grad p - \eps\, \Div\big(\Grad\phi \otimes \Grad\phi \big)
        \\
        &\quad= \mu \Grad\phi 
            - \Grad p 
            - \Grad \Big( \frac \eps2 \abs{\Grad\phi}^2 +\frac 1\eps F(\phi) \Big) 
        % \\
        % &\quad
        = \mu \Grad\phi 
            - \Grad \ov p
    \end{align*}
    in $\QT$, and
    \begin{align*}
        &\eps\,(\Grad\phi \otimes \Grad\phi)\n  
            - \Gradg q 
            - \delta\, \Divg\big(\Gradg\psi \otimes \Gradg\psi \big)
        \\
        &\quad= - \Gradg q 
            - \Gradg \Big( \frac \delta2 \abs{\Gradg\psi}^2 
                +\frac 1\delta G(\phi)
                + \frac 12\h(K) (\alpha\psi-\phi)^2
            \Big)
        \\
        &\quad\qquad + \theta \Gradg \psi 
            - \eps \deln\phi (\alpha\Gradg \psi - \Grad\phi)   
            + \h(K) (\alpha\psi-\phi) (\alpha\Gradg \psi - \Gradg\phi) 
        \\[1ex]
        &\quad= \theta \Gradg\psi 
            - \Gradg \ov q
            - \eps \deln\phi (\alpha\Gradg \psi - \Grad\phi)   
            + \h(K) (\alpha\psi-\phi) (\alpha\Gradg \psi - \Gradg\phi)
    \end{align*}
    on $\ST$.
    By the definition of $\h(K)$ and boundary condition \eqref{eqs:NSCH:6}, this implies that
    \begin{align*}
        &\Big[\eps\,(\Grad\phi \otimes \Grad\phi)\n  
            - \Gradg q 
            - \delta\, \Divg\big(\Gradg\psi \otimes \Gradg\psi \big) \Big]_\tau
        \\
        &\quad= \theta \Gradg\psi 
            - \Gradg \ov q
            - \big[ \eps \deln\phi - \h(K) (\alpha\psi-\phi) \big]
                (\alpha\Gradg \psi - \Gradg\phi)  
        \\
        &\quad= \theta \Gradg\psi 
            - \Gradg \ov q.
    \end{align*}
    on $\ST$.
    Recalling the definitions of the stress tensor $\T$ and the viscous stress tensor $\bS$ (see~\eqref{eq:T}), system~\eqref{eqs:NSCH} can thus be reformulated as  
    \begin{subequations}
		\label{eqs:NSCH:ALT}
		% \begin{empheq}[left={\empheqlbrace}]{alignat=3}
        \begin{alignat}{3}
			\label{eqs:NSCH:ALT:1}
			& \delt \big(\rho(\phi) \u\big) 
			+ \Div \big( \u \otimes (\rho(\phi)\u + \J) \big) 
            - \Div(\bS) + \Grad \ov p
			= \mu \Grad\phi,
			\quad \Div \u = 0
			&& \tin \QT, 
			\\
			\label{eqs:NSCH:ALT:2}
			& \deltb \phi 
			= \Div (m_\Omega(\phi) \Grad \mu),
			&& \tin \QT,
			\\
			\label{eqs:NSCH:ALT:3}
			&\mu 
			= - \varepsilon \Lap \phi + \varepsilon^{-1} F'(\phi)  && \tin \QT,
			\\
			\label{eqs:NSCH:ALT:4}
			& \deltc \psi  
			= \Divg (m_\Gamma(\psi) \Gradg \theta) - \beta m_\Omega(\phi) \deln \mu  && \ton S_T,
			\\
			\label{eqs:NSCH:ALT:5}
			& \theta 
			= - \delta \Lapg \psi + \delta^{-1} G'(\psi)
			+ \alpha \varepsilon \deln \phi  && \ton S_T, 
			\\
			\label{eqs:NSCH:ALT:6}
			&K \varepsilon \deln \phi
			= \alpha \psi - \phi, 
			\quad 
			L m_\Omega(\phi) \deln \mu
			= \beta \theta - \mu, 
			\quad K,L \in [0,\infty], 
			&& \ton S_T, 
			\\
			\label{eqs:NSCH:ALT:7}
			& \big[\bS\n  + \Gradg \ov q  + \gamma_\tau  \u \big]_\tau
			= \Big[ 
                \onehalf \, (\J\cdot\n) \, \u
                + \theta \Gradg\psi
            \Big]_\tau
			&& \ton S_T, 
			\\
			\label{eqs:NSCH:ALT:8}
			& \bS\n\cdot\n 
                - \ov p
                - \eps (\deln\phi)^2
                + \gamma_\n \cV %(\u \cdot \n)
			= \onehalf \, (\J\cdot\n) \cV %(\u \cdot \n)
                - \ov q H + gH - f
			&& \ton S_T, \\
			\label{eqs:NSCH:ALT:9}
			&  \Divg \u = 0,  
            \quad \u \cdot \n = \cV
			&& \ton S_T.
		% \end{empheq}
        \end{alignat}
	\end{subequations}
    This formulation might be more convenient for future mathematical analysis of this model.

	\subsection{Variants of our model without dynamic boundary conditions}\label{SUBSEC:FBAGG}

	The standard choice of boundary conditions for the classical Cahn--Hilliard equation, where no surface quantities are considered, are homogeneous Neumann boundary conditions on both $\phi$ and $\mu$. This situation is also included in our model as a special case. 
	By assuming $\psi\equiv -1$ or $\psi\equiv 1$ and choosing $K=L=\infty$, we obtain $\theta\equiv 0$ and therefore, system \eqref{eqs:NSCH} reduces to%
	\begin{subequations}
		\label{eqs:AGGQ}
		% \begin{empheq}[left={\empheqlbrace}]{alignat=3}
        \begin{alignat}{3}
			\label{eqs:AGGQ:1}
			& \delt \big(\rho(\phi) \u\big) 
			+ \Div \big( \u \otimes (\rho(\phi)\u + \J) \big) 
			= \Div(\T),
			\quad \Div \u = 0
			&& \tin \QT, 
			\\
			\label{eqs:AGGQ:2}
			& \deltb \phi
			= \Div (m_\Omega(\phi) \Grad \mu)
			&& \tin \QT,
			\\
			\label{eqs:AGGQ:3}
			&\mu 
			= - \varepsilon \Lap \phi + \varepsilon^{-1} F'(\phi)  && \tin \QT,
			\\
			\label{eqs:AGGQ:6}
			&\deln \phi = 0, 
			\quad 
			\deln \mu = 0 
			&& \ton S_T, 
			\\
			\label{eqs:AGGQ:7}
			& \big[\bS\n  + \Gradg q  + \gamma_\tau  \u \big]_\tau
			= \Big[ \onehalf \, (\J\cdot\n) \, \u\Big]_\tau
			&& \ton S_T, 
			\\
			\label{eqs:AGGQ:8}
			& \T\n\cdot\n + \gamma_\n  \cV %(\u\cdot\n)
			= \onehalf \, (\J\cdot\n) \, \cV %(\u\cdot\n) 
            - qH
			&& \ton S_T, \\
			\label{eqs:AGGQ:9}
			&  \Divg\u = 0 , \quad \u \cdot \n = \cV
			&& \ton S_T,
		% \end{empheq}
        \end{alignat}
	\end{subequations} 
	where $\rho(\phi)$, $\J$ and $\T$ are given by \eqref{eq:rho}--\eqref{eq:T}.

	As a further simplification, it is possible to neglect the condition $\Divg\u = 0$ on $\ST$, which also allows us also to omit the surface pressure $q$ as it acts as a Lagrange multiplier for this condition (cf.~Subsection~\ref{SUBSEC:LAG}). 
    This simplification was also employed in \cite{Giorgini2023}, where a variant of our model with a static boundary was derived. There, neither the condition $\Divg\u = 0$ nor any surface pressure were included in the model. In this way, the system \eqref{eqs:AGGQ} further simplifies to
	\begin{subequations}
		\label{eqs:AGG}
		% \begin{empheq}[left={\empheqlbrace}]{alignat=3}
        \begin{alignat}{3}
			\label{eqs:AGG:1}
			& \delt \big(\rho(\phi) \u\big) 
			+ \Div \big( \u \otimes (\rho(\phi)\u + \J) \big) 
			= \Div(\T),
			\quad \Div \u = 0
			&& \tin \QT, 
			\\
			\label{eqs:AGG:2}
			& \deltb \phi
			= \Div (m_\Omega(\phi) \Grad \mu)
			&& \tin \QT,
			\\
			\label{eqs:AGG:3}
			&\mu 
			= - \varepsilon \Lap \phi + \varepsilon^{-1} F'(\phi)  && \tin \QT,
			\\
			\label{eqs:AGG:6}
			&\deln \phi = 0, 
			\quad 
			\deln \mu = 0
			&& \ton S_T, 
			\\
			\label{eqs:AGG:7}
			& \big[\bS\n + \gamma_\tau  \u \big]_\tau
			= \Big[ \onehalf \, (\J\cdot\n) \, \u\Big]_\tau
			&& \ton S_T, 
			\\
			\label{eqs:AGG:8}
			& \T\n\cdot\n + \gamma_\n  \cV %(\u\cdot\n)
			= \onehalf \, (\J\cdot\n) \, \cV %(\u\cdot\n) 
			&& \ton S_T, 
            \\
			\label{eqs:AGG:9}
			&\u \cdot \n = \cV
			&& \ton S_T.
		% \end{empheq}
        \end{alignat}
	\end{subequations} 
	This version can be regarded as a variant of the Abels--Garcke--Grün model (cf.~\cite{Abels2012}) in an evolving domain with free boundary.

    \subsection{The role of dynamic boundary conditions in our model}\label{SUBSEC:DYN}

	As already discussed in the literature (see, e.g., \cite{Giorgini2023}), the homogeneous Neumann boundary conditions in \eqref{eqs:AGG:6} are quite restrictive. On the one hand, the condition $\deln \phi = 0$ on $S_T$ means that the contact angle between the diffuse interface separating the fluids and the boundary $\Gamma(\cdot)$ is always exactly ninety degrees. Of course, this is unrealistic in many applications, where the contact angle is expected to change dynamically over the course of time. On the other hand, the condition $\deln \mu = 0$ on $S_T$ implies that no transfer of material between bulk and surface can occur (cf.~\eqref{mass:inf}). Therefore, absorption or adsorption processes cannot be described. 

	These issues are overcome in model \eqref{eqs:NSCH} by means of the bulk-surface convective Cahn--Hilliard subsystem \eqref{eqs:NSCH:2}--\eqref{eqs:NSCH:6}. 
	At least for the non-convective bulk-surface Cahn--Hilliard system (i.e., $\u\equiv 0$), it has been observed in several numerical simulations that a transfer of material between bulk and surface occurs if $L\in [0,\infty)$ and that the contact angle between the diffuse interface and the boundary changes dynamically over the course of time (see, e.g., \cite{Knopf2021a,Bao2021a,Metzger2023,Bullerjahn2024,Bullerjahn2025}). 
	Unfortunately, the sharp-interface limit of such bulk-surface Cahn--Hilliard models, which would provide an explicit law for the behavior of the contact angle, is still not very well understood. 

	In a fixed domain, the bulk-surface Cahn--Hilliard system subject to the coupling conditions \eqref{CH:CPL} with $K,L\in[0,\infty]$ has already been studied extensively in the literature. In particular, the coupling conditions \eqref{CH:CPL} with $K,L\in[0,\infty]$ were introduced and investigated in the following papers:
	%%%
	\begin{itemize}[leftmargin=*, topsep=0em, partopsep=0em, parsep=1ex, itemsep=0ex]
		\item For $K=L=0$, the non-convective bulk-surface Cahn--Hilliard equation was proposed in \cite{Gal2006,Goldstein2011}. Since $L=0$, the chemical potentials are assumed to always remain in a chemical equilibrium, and a rapid transfer of material between bulk and surface is expected to occur.
		%%%
		\item For $K=0$ and $L=\infty$, the non-convective bulk-surface Cahn--Hilliard equation was derived in \cite{Liu2019} by an energetic variational approach. In this case, the mass flux between bulk and surface is zero. Consequently, no transfer of material between bulk and surface will occur. 
		%%%
		\item The case $K\in (0,\infty)$ and $L=\infty$ was first proposed an analyzed in \cite{Knopf2020}. It was shown that solutions of this model converge to solutions of the system with $K=0$ and $L=\infty$ as the parameter $K$ is sent to zero.
        %%%
		\item For $K=0$ and $L\in (0,\infty)$, the non-convective bulk-surface Cahn--Hilliard equation was proposed in \cite{Knopf2021a} to interpolate between the models associated with $K=0$, $L=0$ and ${K=0}$, ${L=\infty}$. In this case, a transfer of material between bulk and surface will occur, and the number $L^{-1}$ is related to the rate of absorption (or adsorption) of bulk material by the boundary (cf.~\cite{Knopf2021a}).
		%%%
		\item In \cite{Knopf2024,Knopf2024a,Giorgini2025}, the convective bulk-surface Cahn--Hilliard equation with a given velocity field was studied for all cases $K,L\in[0,\infty]$ in a unified framework. 
		Of course, these results also include the non-convective case by simply choosing $\u\equiv 0$ for the prescribed velocity field. 
	\end{itemize}
	%%%

	\subsection{Variants of our model with a static boundary}

	It is also possible to consider a static boundary, which is not allowed to move along with the velocity field. To implement this, we assume $\Omega(\cdot)\equiv \Omega$, $\Gamma(\cdot)\equiv\Gamma$ and $\cV = \u\cdot\n = 0$ on $\ST$. Then, the simplified model can be expressed as
	\begin{subequations}
		\label{eqs:GKQ}
		% \begin{empheq}[left={\empheqlbrace}]{alignat=3}
        \begin{alignat}{3}
			\label{eqs:GKQ:1}
			& \delt \big(\rho(\phi) \u\big) 
			+ \Div \big( \u \otimes (\rho(\phi)\u + \J) \big) 
			= \Div(\T),
			\quad \Div \u = 0,
			&& \tin \QT, 
			\\
			\label{eqs:GKQ:2}
			& \delt \phi + \Div(\phi\u)
			= \Div (m_\Omega(\phi) \Grad \mu),
			&& \tin \QT,
			\\
			\label{eqs:GKQ:3}
			&\mu 
			= - \varepsilon \Lap \phi + \varepsilon^{-1} F'(\phi),  && \tin \QT,
			\\
			\label{eqs:GKQ:4}
			& \delt \psi + \Divg(\psi \u_\tau) 
			= \Divg (m_\Gamma(\psi) \Gradg \theta) - \beta m_\Omega(\phi) \deln \mu,  && \ton S_T,
			\\
			\label{eqs:GKQ:5}
			& \theta 
			= - \delta \Lapg \psi + \delta^{-1} G'(\psi)
			%+ \varepsilon (\nu \cdot \nabla \phi)
			+ \alpha \varepsilon \deln \phi , && \ton S_T, 
			\\
			\label{eqs:GKQ:6}
			&K \varepsilon \deln \phi
			= \alpha \psi - \phi, 
			\quad 
			L m_\Omega(\phi) \deln \mu
			= \beta \theta - \mu, 
			\quad K,L \in [0,\infty], 
			&& \ton S_T, 
			\\
			\label{eqs:GKQ:7}
			& \big[\bS\n  + \Gradg q  + \gamma_\tau  \u \big]_\tau
			= \Big[ \theta \Gradg \psi + \onehalf \, (\J\cdot\n) \, \u\Big]_\tau,
			&& \ton S_T, 
			\\
			\label{eqs:GKQ:9}
			&  \Divg\u = 0, \quad \u\cdot\n = 0, 
			&& \ton S_T,
		% \end{empheq}
        \end{alignat}
	\end{subequations} 
	where $\QT$ and $\ST$ are to be interpreted as $\QT = \Omega\times (0,T)$ and $\ST = \Gamma\times (0,T)$, respectively. This model can be understood as a variant of the Navier--Stokes--Cahn--Hilliard model derived in \cite{Giorgini2023}, which further includes the condition $\Divg\u = 0$ on $\ST$ along with the surface pressure $q$ acting as a Lagrange multiplier for this condition. We point out that it becomes clear by the model derivation (see Section~\ref{SECT:MODEL}) that the boundary condition \eqref{eqs:NSCH:7} drops out when the condition $\u\cdot\n = 0$ on $\ST$ is demanded. 

	If we further neglect the relation $\Divg\u = 0$ on $\ST$ and set $q\equiv 0$, we arrive exactly at the model that was derived in \cite{Giorgini2023}.
	A Cahn--Hilliard--Brinkman variant of this model, in which the Navier--Stokes equation is replaced by a Brinkman equation to describe flows through porous media, was investigated in \cite{Colli2024}.



	\section{Model derivation}\label{SECT:MODEL}

	In this section we will derive the Navier--Stokes--Cahn--Hilliard system with dynamic boundary conditions \eqref{eqs:NSCH}.

	We consider an evolving domain $\{\Omega(t)\}_{t\in[0,T]}$ in $\R^d$ of class $C^2$. For every $t\in [0,T]$, let $\Gamma(t)\coloneqq\partial\Omega(t)$. This means that $\{\Gamma(t)\}_{t\in[0,T]}$ is a closed, oriented evolving hypersurface in $\R^d$ of class $C^2$. For brevity, we use the notation
	\begin{equation*}
		\QT \coloneqq \bigcup_{0 < t <T} \{t\} \times \Om 
		\quad\text{and}\quad 
		\ST \coloneqq \bigcup_{0 < t <T} \{t\} \times \Ga .
	\end{equation*}
    % In the following, we identify $\{\Omega(t)\}_{t\in[0,T]}$ with $\QT$ and $\{\Gamma(t)\}_{t\in[0,T]}$ with $\ST$.
	We further assume that the evolving domain $\QT$ is transported by a vector field $\u\in C^2(\overline{\QT})$, which is supposed to be the \textit{volume-averaged velocity field} of the two fluids that are considered.
	Therefore, $S_T$ is transported by the vector field $\u\vert_{S_T}\in C^2(S_T)$. 
    This means that 
    \begin{align*}
        \Omega(s) = \eta_s\big(t,\Omega(t)\big)
        \quad\text{and}\quad
        \Gamma(s) = \eta_s\big(t,\Gamma(t)\big)
        \quad\text{for all $s,t\in [0,T]$,}
    \end{align*}
    where for any $(t,\x) \in \overline{\QT}$, the flow map $[0,T] \ni s \mapsto \eta_s(t,\x) \in \overline{\Omega(s)}$ is the unique solution of the 
    ordinary differential equation
    \begin{align*}
        \frac{\mathrm{d}}{\mathrm{d} s} \eta_s(t,\x) = \u\big(s,\eta_s(t,\x)\big), \quad s\in [0,T],
    \end{align*}
    which satisfies the initial condition 
    $\eta_s(t,\x)|_{s = t} = \x$.    
    %
    Since $S_T$ is orientable, there exists an evolving unit normal vector field $\n\in C(S_T)$ and the normal velocity $\cV$ of $S_T$ is given by
	\begin{align}
		\label{BC:NORVEL}
		\u \cdot \n = \cV \quad\text{on $S_T$}.
	\end{align}
    For more details about the theory of evolving domains and hypersurfaces as well as corresponding calculus and transport theorems, we refer to \cite{BDGP-book,BGN-book}.

	In the following, we write $\u_\tau$ and $\u_\n$ to denote the tangential component and the normal component of $\u$, respectively.
	We further assume that each bulk material has a constant individual density $\trho_i$, $i=1,2$
	and each boundary material has a constant individual density $\tsigma_i$, $i=1,2$.

	\subsection{Considerations based on local mass balance laws}

	The mass densities $\rho_i:\QT\to\R$, $i=1,2$, of the two fluids in the bulk are supposed to satisfy the following mass balance law:
	\begin{align}
		\label{BL:MASS:B}
		\delt \rho_i + \Div \, \widehat\J_i = 0,
		\quad i=1,2,
		\quad\text{in $\QT$.}
	\end{align}
	Here, $\widehat\J_i$ are the mass fluxes corresponding to the motion of the two materials in the bulk. 
	In our model, we also want to account for a transfer of material between bulk and surface. This is, for instance, needed in order to describe absorption processes. 
	Therefore, we also consider functions $\sigma_i:\ST\to\R$, $i=1,2$, which represent the mass densities of the substrates on the free boundary. In general, the materials on the surface might differ from those in the bulk. This is the case, for example, if the materials are transformed by chemical reactions occurring at the boundary. Therefore, we interpret the densities $\sigma_i$ as independent functions that are not necessarily the traces of the densities $\rho_i$, respectively.
	%
	We assume that the the following mass balance law holds on the free boundary:
	\begin{align}
		\label{BL:MASS:S}
		\deltn \sigma_i + \Divg \, \widehat\K_i = \widehat\J_{\Gamma,i} \cdot \n,
		\quad i=1,2,
		\quad\text{on $\ST$.}
	\end{align}
	In this relation, $\widehat\K_i$ are (not necessarily tangential) vector fields representing the mass fluxes on the boundary. 
	Moreover, $\widehat\J_{\Gamma,i}$ are (not necessarily tangential) vector fields describing the transfer of material between bulk and boundary. 
	Here and in what follows, the expression 
	\begin{align}
		\label{DEF:NTD}
		\deltn h 
		= \deltc h - \u_\tau \cdot \Gradg h
        = \delt \tilde h + \cV\n \cdot \Grad \tilde h
	\end{align}
	denotes the \textit{normal time derivative} of any (sufficiently regular) function $h:\ST\to\R$. 
    Here, $\tilde h$ denotes an arbitrary (sufficiently regular) extension of $h$ onto a neighborhood of $S_T$.
	In \eqref{BL:MASS:S}, the normal time derivative needs to be used instead of $\delt\sigma_i$ to account for the normal velocity of the evolving hypersurface $\ST$. 
	%
	In order to ensure the local preservation of surface area (cf.~\eqref{PDE:DIVV:S} below), we additionally postulate that
	\begin{align}
		\label{CONS:VOL}
		\frac{\widehat\J_{\Gamma,1}}{\tsigma_1}\cdot \n + \frac{\widehat\J_{\Gamma,2}}{\tsigma_2}\cdot \n = 0
		\quad\text{on $\ST$}.
	\end{align}	
	We next assume that the motion of our materials is described by the individual velocity fields $\u_i:\QT\cup\ST\to\R^d$, $i=1,2$.  
	In view of the mass fluxes and the mass densities, we have the following relations:
	\begin{align*}
		\u_i = \frac{\widehat\J_i}{\rho_i} \quad\text{in $\QT$},
		\qquad
		\u_i = \frac{\widehat \K_i}{\sigma_i} \quad\text{on $\ST$},
		\qquad
		i=1,2.
	\end{align*}
	Consequently, the mass balances \eqref{BL:MASS:B} and \eqref{BL:MASS:S} can be rewritten as
	\begin{alignat}{2}
		\label{BL:MASS:B'}
		\delt \rho_i + \Div(\rho_i\u_i) &= 0,
		&&\quad i=1,2,
		\quad\text{in $\QT$,}
		\\
		\label{BL:MASS:S'}
		\deltn \sigma_i  + \Divg(\sigma_i\u_{i}) &= \widehat\J_{\Gamma,i} \cdot \n,
		&&\quad i=1,2,
		\quad\text{on $\ST$.}
	\end{alignat}
	We now introduce $\phi_i:\QT\to\R$ and $\psi_i:\ST\to\R$, $i=1,2$, to denote the volume fractions of the two fluids in the bulk and the two substrates on the boundary, respectively. 
	Recalling that each component has a constant density $\trho_i$, $\tilde{\sigma}$, $i=1,2$, the volume fractions can be identified as
	\begin{align}
		\label{DEF:PHIPSI*}
		\phi_i = \frac{\rho_i}{\trho_i} \quad\text{in $\QT$,}
		\qquad
		\psi_i = \frac{\sigma_i}{\tilde{\sigma}_i} \quad\text{on $\ST$,}
		\qquad
		i=1,2.
	\end{align}
	Under the assumption that the excess volume is zero, we have
	\begin{align}
		\label{CONS:PHIPSI}
		\phi_1 + \phi_2 = 1 \quad\text{in $\QT$,}
		\qquad
		\psi_1 + \psi_2 = 1 \quad\text{on $\ST$.}
	\end{align}
	We further define the order parameters
	\begin{align}
		\label{DEF:PHIPSI}
		\phi = \phi_2 - \phi_1 \quad\text{in $\QT$,}
		\qquad
		\psi = \psi_2 - \psi_1 \quad\text{on $\ST$,}
	\end{align}
	which are referred to as the \textit{phase-fields}.
	Using the phase-fields $\phi$ and $\psi$, the velocity field $\u$ can be decomposed as
	\begin{alignat}{2}
		\label{DEF:VAVG:B}
		\u &= \phi_1 \u_1 + \phi_2 \u_2
		\quad\text{in $\QT$,}
		\\
		\label{DEF:VAVG:S}
		\u &= \psi_1 \u_{1} + \psi_2 \u_{2}
		\quad\text{on $\ST$.}
	\end{alignat}
	We now introduce 
	\begin{alignat}{2}
		\label{Ji}
		\J_i &= \widehat\J_i - \rho_i \u,
		&&\quad i=1,2,
		\quad\text{in $\QT$,}
		\\
		\label{Ki}
		\K_i &= \widehat\K_i - \sigma_i \u,
		&&\quad i=1,2,
		\quad\text{on $\ST$,}
	\end{alignat}
	which represent the mass fluxes relative to the volume averaged velocity field. The mass balance equations \eqref{BL:MASS:B'} and \eqref{BL:MASS:S'} can thus be rewritten as
	\begin{alignat}{2}
		\label{BL:MASS:B*}
		\delt \rho_i + \Div(\rho_i\u) + \Div \, \J_i &= 0,
		&&\quad i=1,2,
		\quad\text{in $\QT$,}
		\\
		\label{BL:MASS:S*}
		\deltn \sigma_i + \Divg(\sigma_i\u) + \Divg \, \K_i  &= \widehat \J_{\Gamma,i} \cdot \n,
		&&\quad i=1,2,
		\quad\text{on $\ST$.}
	\end{alignat}
	In this context, $\J_i$ and $\K_i$, $i=1,2$, can be regarded as diffusive flow rates. We now define the total mass densities as
	\begin{alignat}{2}
		\label{DEF:RHO}
		\rho &= \rho_1 + \rho_2
		\quad\text{in $\QT$,}\\
		\label{DEF:SIGMA}
		\sigma &= \sigma_1 + \sigma_2
		\quad\text{in $\ST$.}
	\end{alignat}
	This leads to the relations
	\begin{alignat}{2}
		\label{BL:MASS:B**}
		\delt \rho + \Div(\rho\u) + \Div(\J_1+\J_2)&= 0
		&&\quad\text{in $\QT$,}
		\\
		\label{BL:MASS:S**}
		\deltc \sigma + \sigma \Divg\u  + \Divg(\K_1+\K_2) &= (\widehat \J_{\Gamma,1}  + \widehat \J_{\Gamma,2} ) \cdot \n
		&&\quad\text{on $\ST$.}
	\end{alignat}
	Moreover, in view of the balance of linear momentum with respect to the velocity field $\u$, we have
	\begin{align}
		\label{BL:CLM}
		\delt (\rho\u) + \Div(\rho\u\otimes\u) = \Div \, \tT 
		\quad\text{in $\QT$.}
	\end{align}
	Here, $\tT$ denotes the stress tensor, which needs to be specified by constitutive assumptions. In the following, we write 
	\begin{align}
		\label{DEF:JK}
		\J = \J_1 + \J_2 \quad\text{in $\QT$,}
		\qquad
		\K = \K_1 + \K_2 \quad\text{on $\ST$.}
	\end{align}
	Using \eqref{BL:MASS:B**} to reformulate \eqref{BL:CLM}, we obtain 
	\begin{align}
		\label{BL:CLM*}
		\begin{aligned}
			\rho(\delt\u + \u\cdot\Grad\u) 
			&= \Div \, \tT + ( \Div \, \J )\u
			% \\&
			= \Div(\tT + \u\otimes \J) - \Grad\u \; \J 
			\quad\text{in $\QT$.}
		\end{aligned}
	\end{align}
	We now define the objective stress tensor
	\begin{align}
		\label{DEF:TT}
		\T = \tT + \u \otimes \J
		\quad\text{in $\QT$,}
	\end{align}
	which is frame indifferent. Hence, \eqref{BL:CLM*} can be rewritten as
	\begin{align}
		\label{BL:CLM**}
		\rho \delt\u + \Grad\u \; (\rho\u + \J) 
		= \Div\, \T 
		\quad\text{in $\QT$.}
	\end{align}
	We now multiply the equations \eqref{BL:MASS:B'} each by ${1}/{\trho_i}$, $i=1,2$, and we add the resulting equations. Recalling \eqref{DEF:PHIPSI*},\eqref{CONS:PHIPSI} and \eqref{DEF:VAVG:B}, we deduce 
	\begin{align}
		\label{PDE:DIVV}
		\begin{aligned}
			\Div \u = \Div \left(\frac{\rho_1}{\trho_1}\u_1 + \frac{\rho_2}{\trho_2}\u_2 \right) = - \delt \left(\frac{\rho_1}{\trho_1} + \frac{\rho_2}{\trho_2}\right)
			= -\delt 1 = 0
			&&\quad\text{in $\QT$,}
		\end{aligned}
	\end{align}
	which means that the volume averaged velocity field is divergence-free. 
	Similarly, multiplying \eqref{BL:MASS:S'} by ${1}/{\tsigma_i}$, $i=1,2$, adding the resulting equations, and recalling \eqref{CONS:VOL}, \eqref{DEF:PHIPSI*}, \eqref{CONS:PHIPSI} and \eqref{DEF:VAVG:S}, we infer 
	\begin{align}
		\label{PDE:DIVV:S}
		\begin{aligned}
			& \Divg \, \u 
			= \Divg \left(\frac{\sigma_1}{\tsigma_1}\u_1 + \frac{\sigma_2}{\tsigma_2}\u_2 \right)
			\\
			&\quad   
			= - \deltc \left(\frac{\sigma_1}{\tsigma_1} + \frac{\sigma_2}{\tsigma_2}\right) 
			+ \u_\tau \cdot \Gradg \left(\frac{\sigma_1}{\tsigma_1} + \frac{\sigma_2}{\tsigma_2}\right)
			+ \left(\frac{\widehat\J_{\Gamma,1}}{\tsigma_1} + \frac{\widehat\J_{\Gamma,2}}{\tsigma_2}\right)\cdot\n
			\\
			&\quad  
			= \left(\frac{\widehat\J_{\Gamma,1}}{\tsigma_1} + \frac{\widehat\J_{\Gamma,2}}{\tsigma_2}\right)\cdot\n 
			= 0 
			&&\quad\text{on $\ST$.}
		\end{aligned}
	\end{align}
	We now define 
	\begin{alignat}{4}
		\label{DEF:TJ}
		\tJ_i &= \frac{\J_i}{\trho_i}, 
		&&\quad i=1,2,
		&\qquad \J_\phi &= \tJ_2-\tJ_1
		&&\quad\text{in $\QT$,}
		\\[1ex]
		\label{DEF:TJG}
		\tJ_{\Gamma,i} &= \frac{\tJ_{\Gamma,i}}{\tsigma_i}, 
		&&\quad i=1,2,
		&\qquad \J_\psi &= \tJ_{\Gamma,2}-\tJ_{\Gamma,1}
		&&\quad\text{on $\ST$,}
		\\[1ex]
		\label{DEF:TK}
		\tK_i &= \frac{\K_i}{\tilde{\sigma}_i},
		&&\quad i=1,2,
		&\qquad \K_\psi &= \tK_2-\tK_1
		&&\quad\text{on $\ST$.}
	\end{alignat}
	Multiplying the equations \eqref{BL:MASS:B*} each by ${1}/{\trho_i}$, $i=1,2$, and subtracting the resulting equations, we deduce that
	\begin{align}
		\label{EQ:PHI}
		\delt \phi + \Div(\phi\u) + \Div \, \J_\phi = 0
		\quad\text{in $\QT$.}
	\end{align}
	Moreover, multiplying the equations \eqref{BL:MASS:B*} each by ${1}/{\trho_i}$, adding the resulting equations, and recalling \eqref{CONS:PHIPSI} and \eqref{PDE:DIVV}, we conclude that
	\begin{align}
		\label{ID:DIVJ}
		\Div(\tJ_1 + \tJ_2) 
		= - \delt(\phi_1+\phi_2) - \Div\big((\phi_1+\phi_2)\u \big) 
		= 0
		\quad\text{in $\QT$.}
	\end{align}
	Proceeding similarly with \eqref{BL:MASS:S*}, and recalling \eqref{CONS:PHIPSI} and \eqref{PDE:DIVV:S}, we obtain
	\begin{align}
		\label{EQ:PSI}
		\deltc \psi + \Divg \, \K_\psi
		= \deltn \psi  + \Divg(\psi\u) + \Divg \, \K_\psi 
		= \J_\psi \cdot\n
		\quad\text{on $\ST$,}
	\end{align}
	and
	\begin{align}
		\label{ID:DIVK}
		\Divg(\tK_1 + \tK_2) 
		&= - \deltc (\psi_1+\psi_2) - \Divg\big((\psi_1+\psi_2)\u_\tau \big) 
		+ \big(\tJ_{\Gamma,1} + \tJ_{\Gamma,2} \big)\cdot\n 
		= 0
	\end{align}
	on $\ST$.
	Using \eqref{DEF:TJ} and \eqref{ID:DIVJ}, which entails $\Div(\tJ_1)=-\Div(\tJ_2)$, we infer that
	\begin{align}
		\label{ID:DIVJ**}
		\begin{aligned}
			\Div \, \J 
			&= \frac 12 \bigg[ \trho_2 \Div \, \tJ_2 
			+ \trho_1 \Div \, \tJ_1 \bigg]
			+ \frac 12\bigg[ \trho_2 \Div \, \tJ_2 
			+ \trho_1 \Div \, \tJ_1 \bigg]
			\\[1ex]
			&= \frac{\trho_2-\trho_1}{2} \Div \, \tJ_2
			- \frac{\trho_2-\trho_1}{2} \Div \, \tJ_1
			= \frac{\trho_2-\trho_1}{2} \Div \, \J_\phi
			&&\quad\text{in $\QT$.}
		\end{aligned}
	\end{align}
	This means that the fluxes $\J$ and $\onehalf (\trho_2-\trho_1) \J_\phi $ can merely differ by an additive divergence-free function. As in \cite{Abels2012,Giorgini2023}, we thus assume that 
	\begin{align}
		\label{ID:J}
		\J = \frac{\trho_2-\trho_1}{2} \J_\phi 
		\quad\text{in $\QT$.}
	\end{align}
	In the same way, we derive the identity
	\begin{align}
		\Divg \, \K = \frac{\tilde{\sigma}_2-\tilde{\sigma}_1}{2} \Divg \, \K_\psi
		\quad\text{on $\ST$.}
	\end{align}
	Assuming that $\phi$ and $\psi$ only attain values in the interval $[-1,1]$, we use \eqref{CONS:PHIPSI}, \eqref{DEF:PHIPSI} and \eqref{DEF:RHO} to conclude that the density $\rho = \rho(\phi)$ is given by
	\begin{align}
		\label{DEF:RHO*}
		\rho(\phi) = \frac{\trho_2-\trho_1}{2} \phi + \frac{\trho_2+\trho_1}{2}
		\quad\text{in $\QT$.}
	\end{align}

	\subsection{Local energy dissipation laws}

	As in \cite{Abels2012} and \cite{Giorgini2023}, we consider the following energy density in the bulk: 
	\begin{align}
		\label{DEF:END:B}
		e_{\Omega}(\u,\phi,\Grad\phi) 
		= \frac{\rho(\phi)}{2}\abs{\u}^2
		+ f(\phi,\Grad\phi)
		\quad\text{in $\QT$.}
	\end{align}
	Here, the first summand on the right-hand side represents the kinetic energy density. The second summand denotes the free energy density in the bulk. It is assumed to be of Ginzburg--Landau type, that is
	\begin{align}
		\label{DEF:GL:B}
		f(\phi,\Grad\phi)
		= \frac{\eps}{2}\abs{\Grad\phi}^2 + \frac 1\eps F(\phi)
		\quad\text{in $\QT$.}
	\end{align}
	As in \cite{Giorgini2023}, we additionally introduce the surface energy density
	\begin{align}
		\label{DEF:END:S}
		e_{\Gamma}(\phi,\psi,\Gradg\psi) 
		= g(\phi,\psi,\Gradg\psi)
		\quad\text{on $\ST$.}
	\end{align}
	Here, $g$ stands for the free energy density on the surface. It is also assumed to be of Ginzburg--Landau type with an additional term accounting for the relation between $\phi$ and $\psi$, namely
	\begin{align}
		\label{DEF:GL:S}
		g(\phi,\psi,\Gradg \psi) = \frac{\delta}{2}\abs{\Gradg\psi}^2
		+ \frac 1\delta G(\psi)
		+ \h(K) (\alpha\psi-\phi)^2,
		\quad\text{$K\in[0,\infty]$}
	\end{align}
	on $\ST$, where $\h$ is the function introduced in \eqref{DEF:H}.
	Here, $\delta>0$ is related to the thickness of the diffuse interface on the boundary, 
	% $\kappa\ge 0$ acts as a weight for surface diffusion effects, 
	and $G$ is a potential that usually exhibits a double-well structure.

	To derive local energy dissipation laws, we now consider an arbitrary (sufficiently smooth) test volume $V(t)\subset \Om$,
	$t\in[0,T]$, that is transported by the velocity field $\u$. 
	In an isothermal situation, the second law of thermodynamics leads to the dissipation inequality
	\begin{align}
		\label{IEQ:DISS}
		\begin{aligned}
			0 &\ge \ddt \left[ \int_{V(t)} e_{\Omega}(\u,\phi,\Grad\phi) \dx
			+ \int_{\del V(t)\cap \Ga} e_{\Gamma}(\phi,\psi,\Gradg\psi) \dHH{d-1} \right]
			\\
			&\qquad + \int_{\del V(t)\cap \Om} \J_e \cdot \n_{\del V(t)} \dHH{d-1}
			+ \int_{\del (\del V(t)\cap \Ga)} \K_e \cdot \n_{\del (\del V(t)\cap \Ga)} \dHH{d-2}.
		\end{aligned}
	\end{align}
	In this inequality, the vector fields $\J_e$ and $\K_e$ are energy fluxes that will be specified later, $\n_{\del V(t)}$ is the outer unit normal vector field on $\del V(t)$, and $\n_{\del (\del V(t)\cap \Ga)}$ is the unit conormal vector field on the relative boundary $\del \big(\del V(t)\cap \Ga\big)$ within the submanifold $\Ga$. As we consider a thermodynamically closed system, there is no exchange of energy over the boundary $\Ga$ and thus, the domain of the first integral in the second line is just $\del V(t)\cap \Om$ instead of $\del V(t)$. Applying Gau\ss's divergence theorem for not necessarily tangential vector fields (see, e.g., \cite[Proposition~2.5.1]{BDGP-book}) on both integrals in the second line, we reformulate \eqref{IEQ:DISS} as
	\begin{align}
		\label{IEQ:DISS*}
		\begin{aligned}
			0 &\ge \ddt \left[ \int_{V(t)} e_{\Omega}(\u,\phi,\Grad\phi) \dx
			+ \int_{\del V(t)\cap \Ga} e_{\Gamma}(\phi,\psi,\Gradg\psi) \dHH{d-1} \right]
			\\
			&\qquad + \int_{V(t)} \Div \, \J_e \dx
			+ \int_{\del V(t)\cap \Ga} \Divg \, \K_e 
			+ H \K_e \cdot \n
			- \J_e \cdot \n 
			\dHH{d-1}\,.
		\end{aligned}
	\end{align}
	Here, $H = -\frac{1}{d}\Divg\n$ is the mean curvature of $\Gamma(t)$, and we point out that $\n_{\del V(t)} = \n(t)$ on $\Gamma(t)$.
	Applying the Reynolds transport theorem for evolving domains (see, e.g., \cite[Theorem~2.11.1]{BDGP-book}), we deduce the identity
	\begin{align}
		\label{TRANSP:B}
		\ddt \int_{V(t)} e_{\Omega}(\u,\phi,\Grad\phi) \dx
		= \int_{V(t)} \delt e_{\Omega}(\u,\phi,\Grad\phi) 
		+ \Div\big(e_{\Omega}(\u,\phi,\Grad\phi) \u \big) \dx.
	\end{align}
	Similarly, recalling that $\Divg\u=0$ (see~\eqref{PDE:DIVV:S}), we use the transport theorem for orientable evolving hypersurfaces (see, e.g., \cite[Theorem~2.10.1]{BDGP-book}) to obtain
	\begin{align}
		\label{TRANSP:S}
		\begin{split}
			&\ddt \int_{\del V(t)\cap \Ga} e_{\Gamma}(\phi,\psi,\Gradg\psi) \dHH{d-1} 
			% \\
			% &\quad
			= \int_{\del V(t)\cap \Ga} \deltc e_{\Gamma}(\phi,\psi,\Gradg\psi) 
			% + e_{\Gamma}(\phi,\psi,\Gradg\psi)\, \Divg\u 
			\dHH{d-1}.
		\end{split}
	\end{align}
	Now, by means of \eqref{TRANSP:B} and \eqref{TRANSP:S}, \eqref{IEQ:DISS*} can be reformulated as
	\begin{align}
		\label{IEQ:DISS**}
		\begin{aligned}
			0 &\ge \int_{V(t)} 
			\delt e_{\Omega}(\u,\phi,\Grad\phi) 
			+ \Div\big(e_{\Omega}(\u,\phi,\Grad\phi) \u \big)
			+ \Div \, \J_e \dx
			\\
			&\quad 
			+ \int_{\del V(t)\cap \Ga} 
			\deltc e_{\Gamma}(\phi,\psi,\Gradg\psi) 
			\dHH{d-1}
			\\
			&\quad
			+ \int_{\del V(t)\cap \Ga} 
			\Divg \, \K_e 
			+ H \K_e \cdot \n 
			- \J_e\cdot\n 
			\dHH{d-1}.
		\end{aligned}
	\end{align}
	As \eqref{IEQ:DISS**} holds in particular for all test volumes $V(t)\subset \Om$ with $\del V(t) \cap \Ga = \emptyset$, we infer the following local energy dissipation law in the bulk:
	\begin{align}
		\label{IEQ:DISS:LOC:B}
		0 \ge -\mathcal D_{\Omega} 
		\coloneqq \delt e_{\Omega}(\u,\phi,\Grad\phi) 
		+ \Div\big(e_{\Omega}(\u,\phi,\Grad\phi) \u \big)
		+ \Div \, \J_e 
        \quad\text{in $\QT$.}
	\end{align}
	Let now $c>0$ be arbitrary and let us consider a generic test volume $V(t)\subset \Om$ with $\abs{V(t)}$ being sufficiently small such that 
	\begin{align*}
		\int_{V(t)} \mathcal D_{\Omega} \dx < c.
	\end{align*}
	Invoking \eqref{IEQ:DISS:LOC:B}, we infer from \eqref{IEQ:DISS**} that
	\begin{align*}
		\int_{\del V(t)\cap \Ga} 
		\deltc e_{\Gamma}(\phi,\psi,\Gradg\psi) 
		+ \Divg \, \K_e 
		+ H \K_e \cdot \n 
		- \J_e\cdot\n \dHH{d-1}
		<c.
	\end{align*}
	As $c>0$ and the test volume $V(t)$ were arbitrary (except for the above smallness assumption), we conclude the following local energy dissipation law on the boundary:
	\begin{align}
		\label{IEQ:DISS:LOC:S}
		0 \ge -\mathcal D_{\Gamma}
		\coloneqq \deltc e_{\Gamma}(\phi,\psi,\Gradg\psi) 
		+ \Divg \, \K_e 
		+ H \K_e \cdot \n 
		- \J_e\cdot\n
        \quad\text{on $\ST$.}
	\end{align}

	\subsection{Completion of the model derivation by the Lagrange multiplier approach}\label{SUBSEC:LAG}

	To complete the model derivation, we employ the \textit{Lagrange multiplier approach} (see~\cite{Liu2002}). Therefore, we introduce the Lagrange multipliers  $\mu$, $\theta$ and $q$  that need to be appropriately adjusted in the following approach. 
	In the final model, $\mu$ will represent the \textit{bulk chemical potential}, $\theta$ will represent the \textit{surface chemical potential} and $q$ will represent the \textit{surface pressure}.
	Invoking the identities \eqref{EQ:PHI} and \eqref{EQ:PSI}, the local energy dissipation laws \eqref{IEQ:DISS:LOC:B} and \eqref{IEQ:DISS:LOC:S} can be expressed as
	\begin{alignat}{2}
		\label{IEQ:DISS:B:0}
		0 \ge -\mathcal D_{\Omega} 
		&= \delt e_{\Omega}(\u,\phi,\Grad\phi) 
		+ \Div\big(e_{\Omega}(\u,\phi,\Grad\phi) \u \big)
		+ \Div \, \J_e 
		\notag\\
		&\quad - \mu \big( 
		\delt \phi 
		+ \Div(\phi\u) 
		+ \Div \, \J_\phi \big)
        - p \, \Div\u
		&&\quad\text{in $\QT$,}
		\\[1ex]
		\label{IEQ:DISS:S:0}
		0 \ge - \mathcal D_{\Gamma}
		&= \deltc e_{\Gamma}(\phi,\psi,\Gradg\psi) 
		+ \Divg \, \K_e 
		+ H \K_e \cdot \n 
		- \J_e\cdot\n
		\notag\\
		&\quad
		- \theta \big( 
		\deltc \psi 
		+ \Divg \, \K_\psi 
		- \J_\psi\cdot\n 
		\big)
		- q \, \Divg\u
		&&\quad\text{on $\ST$.}
	\end{alignat}
	% Here, the usage of $q-g$ instead of $q$ is more convenient as it will lead to a more concise formulation of the final model.
	In the following, we will simply write $\rho$, $f$ and $g$ instead of $\rho(\phi)$, $f(\phi,\Grad\phi)$ and $g(\phi,\psi,\Gradg\psi)$ to provide a cleaner presentation.
	By the definition of the energy densities $e_{\Omega}$ and $e_{\Gamma}$ (see \eqref{DEF:END:B} and \eqref{DEF:END:S}), we reformulate \eqref{IEQ:DISS:B:0} and \eqref{IEQ:DISS:S:0} as
	\begin{alignat}{2}
		\label{IEQ:DISS:B:1}
		0 \ge -\mathcal D_{\Omega} 
		& = \delt \big(\tfrac12 \rho \abs{\u}^2 \big)
		+ \Div\big(\tfrac12\rho \abs{\u}^2 \u \big)
		+ \delt f + \Div(f\u)
		+ \Div \, \J_e
		\notag\\
		&\quad - \mu \big( 
		\delt \phi 
		+ \Div(\phi\u) 
		+ \Div \, \J_\phi \big)
        + p \, \Div\u
		&&\quad\text{in $\QT$,}
		\\[1ex]
		\label{EST:DISS:S:1}
		0 \ge - \mathcal D_{\Gamma}
		& = \deltc g 
		+ \Divg \, \K_e 
		+ H \K_e \cdot \n 
		- \J_e \cdot \n
		\notag\\
		&\quad- \theta \big( 
		\deltc \psi 
		+ \Divg \, \K_\psi 
		- \J_\psi\cdot\n 
		\big)
		+ q \, \Divg\u
		&&\quad\text{on $\ST$.}
	\end{alignat}
	We now assume that $\psi$ is suitably extended onto a neighborhood of $\ST$.
	By means of the chain rule, the derivatives 
	$\delt f$ and $\deltc g$ 
	can be expressed as
	\begin{alignat}{2}
		\label{ID:DDTF}
		\delt f
		&= \delph f \, \delt \phi + \delgph f\, \delt \Grad\phi
		&&\quad\text{in $\QT$,}
		\\
		\label{ID:DDTGC}
		\deltc g
		&= \delph g \, \deltc \phi
		+ \delps g \, \deltc \psi 
		+ \delgps g\cdot \deltc \Gradg\psi
		&&\quad\text{on $\ST$.}
	\end{alignat}

	\subsubsection{Computations in the bulk}

	In the bulk, we proceed exactly as in \cite{Abels2012} and \cite{Giorgini2023} to reformulate inequality \eqref{IEQ:DISS:B:1} as
	\begin{align} 
		\label{EST:DISS:B:2}
		\begin{aligned}
			0 & \ge \Div\big[\J_e 
			- \tfrac 12 \abs{\u}^2 \J 
			+ \T^T\u 
			- \mu \J_\phi
			+ \delgph f \deltb \phi
			\big]
			\\
			& \quad + \big[ \delph f 
			- \Div(\delgph f) 
			- \mu 
			\big]
			\deltb \phi  
            + \Grad\mu \cdot \J_\phi
			\\
			& \quad - \big[ \T + p\I
			+ \Grad\phi \otimes \delgph f 
			\big] : \Grad\u
			&&\quad\text{in $\QT$.}
		\end{aligned}
	\end{align}
	To ensure \eqref{EST:DISS:B:2}, we now choose the chemical potential $\mu$ and the energy flux $\J_e$ as
	\begin{alignat}{2}
		\label{DEF:MU*}
		\mu &= \delph f 
		- \Div\big( \delgph f \big)
		&&\quad\text{in $\QT$,}
		\\
		\label{DEF:JE}
		\J_e &= \onehalf \abs{\u}^2 \J 
		- \T^T\u 
		+ \mu \J_\phi
		- \delgph f \deltb \phi
		&&\quad\text{in $\QT$.}
	\end{alignat}
	Due to these choices, the first two lines of the right-hand side of \eqref{EST:DISS:B:2} vanish.
	We further assume the mass flux $\J_\phi$ to follow Fick's law. This means that
	\begin{align}
		\label{DEF:JPHI}
		\J_\phi = -\mom(\phi) \Grad\mu \quad\text{in $\QT$,}
	\end{align}
	where $\mom = \mom(\phi)$ is a nonnegative function representing the mobility in the bulk.
	Hence, \eqref{EST:DISS:B:2} reduces to
	\begin{align}
		\label{EST:DISS:B:3}
		0  \ge  - \big[ \T + p\I
		+ \Grad\phi \otimes \delgph f 
		\big] : \Grad\u
		- \mom(\phi) \abs{\Grad\mu}^2
		\quad\text{in $\QT$.}
	\end{align}
	We next assume that the stress tensor $\T$ can be expressed as
	\begin{align*}
		\T
        = \bS - p \I - \Grad\phi \otimes \delgph f 
		\quad\text{in $\QT$,}
	\end{align*}
	where the scalar variable $p$ denotes the pressure, $\I$ stands for the identity matrix, and $\mathbf S$ is the \textit{viscous stress tensor} that corresponds to irreversible changes of the energy due to friction. The term $\Grad\phi \otimes \delgph f$ can be interpreted as a Korteweg force. For Newtonian fluids, $\mathbf S$ is usually assumed to be given by
	\begin{align}
        \label{DEF:S}
		\mathbf S = 2 \nu(\phi) \D\u,
	\end{align}
	where the nonnegative function $\nu=\nu(\phi)$ represents the viscosity of the fluids, and $\D\u$ denotes the symmetric gradient of $\u$. This choice along with \eqref{DEF:MU*}, \eqref{DEF:JE} and the identity $p\I:\Grad \u = p\, \Div \, \u  = 0$ in $\QT$ ensures that \eqref{EST:DISS:B:2} is fulfilled as it reduces to
	\begin{align}
		\label{EST:DISS:B:4}
		0  \ge  - \nu(\phi) \abs{\D\u}^2
		- \mom(\phi) \abs{\Grad\mu}^2
		\quad\text{in $\QT$.}
	\end{align}
	In particular, recalling \eqref{DEF:GL:B}, the chemical potential $\mu$ given by \eqref{DEF:MU*} can be expressed as
	\begin{align}
		\label{PDE:MU}
		\mu =  - \eps \Lap\phi + \frac 1\eps F'(\phi)
		\quad\text{in $\QT$.}
	\end{align}
	Moreover, the total stress tensor $\T$ is given by
	\begin{align}
		\label{DEF:T}
		\begin{aligned}
			\T 
			&= \bS 
			- p \I 
			- \eps \Grad\phi \otimes \Grad\phi
            \\
            &= 2 \nu(\phi) \D\u 
			- p \I 
			- \eps \Grad\phi \otimes \Grad\phi
			\quad\text{in $\QT$.}
		\end{aligned}
	\end{align}
	Plugging \eqref{DEF:JPHI} into \eqref{EQ:PHI}, we further obtain the equation
	\begin{align}
		\label{PDE:PHI}
		\delt\phi + \Div(\phi\u) = \Div\big( \mom(\phi) \Grad\mu \big)
		\quad\text{in $\QT$.}
	\end{align}
	Eventually, recalling \eqref{DEF:TT} and \eqref{DEF:T}, we use \eqref{BL:CLM} to derive the equation
	\begin{align}
		\label{PDE:NS}
		\delt (\rho\u) 
		+ \Div\big(\u\otimes(\rho(\phi)\u + \J )\big) 
		- \Div\big(2\nu(\phi)\D\u\big)
		+ \Grad p
		= - \eps\Div(\Grad\phi\otimes\Grad\phi)
		\quad\text{in $\QT$,}
	\end{align}
	where, according to \eqref{ID:J} and \eqref{DEF:JPHI}, we have
	\begin{align}
		\label{PDE:J}
		\J = - \frac{\trho_2-\trho_1}{2} \mom(\phi) \Grad\mu 
		\quad\text{in $\QT$.}
	\end{align}

	\subsubsection{Computations on the boundary}

	We now consider the local energy dissipation law \eqref{EST:DISS:S:1} on the surface.
	Recalling the formulas for $f$ (see~\eqref{DEF:GL:B}) and $\J_e$ (see~\eqref{DEF:JE}), we deduce from \eqref{EST:DISS:S:1} that
	\begin{align} \label{EST:DISS:S:2*}
		\begin{aligned}
			0 & \ge \delph g \, \deltc \phi
			+ \delps g \, \deltc \psi 
			+ \delgps g\cdot \deltc \Gradg\psi  
			+ \Divg \, \K_e
			+ H \K_e \cdot \n
			\\
			&\quad    
			- \tfrac 12 (\J\cdot\n)\u\cdot\u 
			- \T\n \cdot \u
			- \mu \J_\phi\cdot \n
			+ \eps\, \deln\phi \, \deltc \phi    
			\\
			&\quad 
			- \theta \deltc \psi 
			- \Divg(\K_\psi \theta)
			+ \Gradg \theta\, \K_\psi 
			+ \theta \J_\psi\cdot \n
			\\
			&\quad 
			- \Divg(q \u) + \Gradg q \cdot \u 
		\end{aligned}
	\end{align}
	on $\ST$. 
    Now, the most technical step is to reformulate the term $\delgps g\cdot \deltc \Gradg\psi$. 
    According to \cite[Lemma~38]{BGN-book}, we have
    \begin{align} 
        \begin{split}
        \deltc \Gradg \psi - \Gradg \deltc \psi   
        &= \Gradg \u \Gradg \psi - \mathbf{P}_\Gamma \big[ \Gradg \u + (\Gradg \u)^T \big] \mathbf{P}_\Gamma  \Gradg \psi
        \\
        &= \Gradg \u  \Gradg \psi - \mathbf{P}_\Gamma \big[ \Gradg \u + (\Gradg \u)^T \big] \Gradg \psi
        \end{split}
    \end{align} 
    on $\ST$. Here, the symmetric matrix $\mathbf{P}_\Gamma$ represents the orthogonal projection onto the tangent space of $\Gamma=\Gamma(t)$.
    Invoking the definition of $g$ (see~\eqref{DEF:GL:S}), we further deduce
	\begin{align}
        \begin{aligned}
			&\delgps g \cdot \Big\{ \Gradg \u  \Gradg \psi - \mathbf{P}_\Gamma \big[ \Gradg \u + (\Gradg \u)^T \big] \Gradg \psi \Big\}
            \\
            &\quad = -\delta \Gradg\psi \cdot (\Gradg \u)^T \Gradg \psi 
            = - \delta \big( \Gradg\psi \otimes \Gradg\psi \big) : \Gradg \u
		\end{aligned}
	\end{align}
    on $\ST$. From these two identities, we thus infer
    \begin{align}
        \begin{aligned}
			&\delgps g\cdot \deltc \Gradg\psi
            \\
            &\quad = \delgps g\, \Gradg \deltc \psi
                + \delgps g \cdot \Big\{ \Gradg \u  \Gradg \psi - \mathbf{P}_\Gamma \big[ \Gradg \u + (\Gradg \u)^T \big] \Gradg \psi \Big\}
			\\
			&\quad = \delgps g\, \Gradg \deltc \psi
                - \delta \big( \Gradg\psi \otimes \Gradg\psi \big) : \Gradg \u 
            \\[1ex]
            &\quad = \Divg\big[ \delgps g \deltc \psi - \delta (\Gradg\psi \otimes \Gradg\psi) \u \big] 
                - \Divg\big( \delgps g \big) \deltc \psi 
                + \delta\, \Divg(\Gradg\psi \otimes \Gradg\psi) \u
		\end{aligned}
	\end{align}
	on $\ST$. We further notice that
    \begin{align}
        \delta (\Gradg\psi \otimes \Gradg\psi) \u \cdot \n
        = \Gradg\Big( \frac{\delta}{2} \abs{\Gradg\psi}^2 \Big)\cdot \n
            + \Lapg \psi \Gradg\psi\cdot \n 
        = 0
    \end{align}
    on $\ST$.
	Using these equations, inequality \eqref{EST:DISS:S:2*} can alternatively be expressed as
	\begin{align} \label{EST:DISS:S:2}
		\begin{aligned}
			0 & \ge \Divg\big[ \K_e
			- \theta \K_\psi 
            + \delgps g\, \deltc \psi 
            - \delta(\Gradg\psi \otimes \Gradg\psi) \u
			- q \u 
            %\ros - g\n (\u\cdot \n) \blu
			\big]
			\\
			&\quad 
			+ \big[
			\delph g + \eps \Grad\phi\cdot \n
			\big] \deltc \phi
			+ \big[
			\delps g 
			- \Divg\big(\delgps g\big) 
			- \theta
			\big] \deltc \psi
            \\
			&\quad + \big[
			\T\n
			+ \Gradg q 
			- \tfrac 12 (\J\cdot\n)\u 
            + \delta\, \Divg(\Gradg \psi \otimes \Gradg\psi) 
			\big]_\tau \cdot \u_\tau
			\\
			&\quad 
			+ \big[
			\T\n\cdot\n 
			- \tfrac 12 (\J\cdot\n) (\u\cdot\n) 
			\big] (\u\cdot\n)
			\\
			&\quad
			+ H \K_e \cdot \n
			+ \Gradg \theta\, \K_\psi 
			+ \theta  \J_\psi \cdot \n - \mu \J_\phi\cdot \n
		\end{aligned}
	\end{align}
    on $\ST$.
	In order to ensure that the inequality \eqref{EST:DISS:S:2} is fulfilled, we choose the  mass flux $\K_\psi$, and the energy flux $\K_e$ as follows:
	\begin{alignat}{2}
		\label{DEF:KPSI}
		\K_\psi &= - \mga(\psi) \Gradg \theta
		&&\quad\text{on $\ST$,}
		\\
		\label{DEF:KE}
		\K_e &= \theta \K_\psi
        - \delgps g \, \deltc \psi
        + \delta(\Gradg\psi \otimes \Gradg\psi) \u 
		+ q \u
		&&\quad\text{on $\ST$.}
	\end{alignat}
	In \eqref{DEF:KPSI}, $\mga=\mga(\psi)$ is a nonnegative function representing the mobility of the materials on the surface.
	The choice of $\K_e$ entails that the first line of the right-hand side in \eqref{EST:DISS:S:2} vanishes. Except for $q\u$, all terms on the right-hand side of \eqref{DEF:KE} are tangential vector fields. We thus have
	\begin{align}
		\label{EQ:KE}
        H\K_e \cdot \n 
        = Hq (\u\cdot\n)
         \quad\text{on $\ST$.}   
	\end{align}
	Due to \eqref{DEF:KPSI}--\eqref{EQ:KE}, inequality \eqref{EST:DISS:S:2} now reduces to
	\begin{align} \label{EST:DISS:S:3*}
        \begin{aligned}
			0 & \ge  \big[
			    \delph g + \eps \Grad\phi\cdot \n
			\big] \deltc \phi
			+ \big[
    			\delps g 
    			- \Divg\big(\delgps g\big) 
    			- \theta
			\big] \deltc \psi
            \\
			&\quad + \big[
    			\T\n
    			+ \Gradg q 
    			- \tfrac 12 (\J\cdot\n)\u 
                + \delta\, \Divg(\Gradg \psi \otimes \Gradg\psi) 
			\big]_\tau \cdot \u_\tau
			\\
			&\quad 
			+ \big[
    			\T\n\cdot\n 
    			- \tfrac 12 (\J\cdot\n) (\u\cdot\n) 
    			%+ \delta\, \Divg(\Gradg\psi \otimes \Gradg\psi) \cdot \n 
                + Hq
			\big] (\u\cdot\n)
			\\
			&\quad
			- \mga(\psi)\abs{\Gradg\theta}^2 
			+ \theta  \J_\psi \cdot \n - \mu \J_\phi\cdot \n
		\end{aligned}
	\end{align}
	on $\ST$. We now assume that the flux terms $\J_\phi$ and $\J_\psi$ are directly proportional. This means that there exists $\beta\in\R$ such that
	\begin{equation}
        \label{ASS:FLUX}
		\J_\psi \cdot \n = \beta \J_\phi \cdot \n = - \beta \, m_\Omega(\phi) \Grad\mu \quad \ton \ST.
	\end{equation}
	Here, the second equality follows from \eqref{DEF:JPHI}.
	We further make the constitutive assumptions
	\begin{alignat}{2}
		\label{BC:NAV}
		\big[
		      \T\n
			+ \Gradg q 
			- \tfrac 12 (\J\cdot\n)\u 
            + \delta\, \Divg(\Gradg \psi \otimes \Gradg\psi) 
		\big]_\tau 
		&=
		-\gamma_\tau\u_\tau
		&&\ton \ST,
		\\
		\label{BC:NOR}
		      \T\n\cdot\n 
            - \tfrac 12 (\J\cdot\n) (\u\cdot\n) 
            + Hq
		&=
		-\gamma_\n (\u\cdot\n)
		&&\ton \ST,
	\end{alignat}
	where $\gamma_\tau$ and $\gamma_\n$ are nonnegative functions, which may depend on the phase fields. Equation \eqref{BC:NAV} can be interpreted as a \textit{generalized Navier slip boundary condition} with $\gamma_\tau$ being the slip parameter. We point out that an analogous boundary condition appeared in \cite{Giorgini2023}.
	By means of \eqref{ASS:FLUX}--\eqref{BC:NOR}, inequality
	\eqref{EST:DISS:S:3*} further reduces to 
	\begin{align} \label{EST:DISS:S:3}
		\begin{aligned}
			0 &\ge 
			\big[
			\delph g + \eps \Grad\phi\cdot \n
			\big] \deltc \phi
			+ \big[
			\delps g 
			- \Divg\big(\delgps g\big) 
			- \theta
			\big] \deltc\psi
			\\
			&\quad
			- \gamma_\tau\abs{\u_\tau}^2 
			- \gamma_\n (\u\cdot\n)^2
			- \mga(\psi) \abs{\Gradg \theta}^2
			\\
			&\quad
			- (\beta\theta - \mu)\,  \mom(\phi) \Grad\mu \cdot \n
		\end{aligned}
	\end{align}
	on $\ST$.
	The terms in the second line are clearly nonpositive. In order to ensure that the third line is also nonpositive, we assume that one of the following boundary conditions holds:
	\begin{subequations} 
		\label{BC:MUTHETA}
		\begin{alignat}{2}
			\beta\theta - \mu &= 0
			&&\quad\text{on $\ST$,}
			\\
			\mom(\phi) \Grad\mu \cdot \n &= \tfrac 1L (\beta\theta - \mu)
			&&\quad\text{on $\ST$ for a constant $L\in(0,\infty)$,}
			\\
			\mom(\phi) \Grad\mu \cdot \n &= 0
			&&\quad\text{on $\ST$.}
		\end{alignat}
	\end{subequations}
	It thus remains to ensure that the first line in \eqref{BC:MUTHETA} is nonpositive. 
    The approach depends on the parameter $K$ that appears in the energy density $g$ (see \eqref{DEF:GL:S})
    and we need to handle the cases $K=0$ and $K\in(0,\infty]$ separately.
    %
    \begin{subequations}
    \begin{itemize}[leftmargin=*]
    	\item\textit{The case $K=0$.}
    	In this case, we assume that $\phi$ and $\psi$ are directly proportional on $\ST$. More precisely, we assume that
        \label{BC:PHIPSI}
        \begin{align}
            \label{BC:PHIPSI:1}
            \alpha\psi-\phi = 0 \quad\ton\ST 
        \end{align}
        with a prescribed parameter $\alpha\in\R\setminus\{0\}$.
        In the definition of $g$, we have $\h(K) = \h(0) = 0$ and thus $\delph g = 0$ on $\ST$. Moreover, due to \eqref{BC:PHIPSI:1}, $\alpha^{-1}\phi$ can be interpreted as an extension of $\psi$ in some neighborhood of $\ST$. This entails $\alpha\Grad\psi = \Grad\phi$ on $\ST$ and we thus have
        \begin{equation*}
            \deltc\phi = \alpha\deltc\psi
            \quad\text{on $\ST$.}
        \end{equation*}
        Consequently, the first line of \eqref{EST:DISS:S:3} can be rewritten as
        \begin{align*}
            \big[
            \delps g 
            - \Divg\big(\delgps g\big) 
            - \theta
            + \alpha\eps \Grad\phi\cdot \n
            \big] \deltc\psi
            \quad\ton\ST.
        \end{align*}
        Choosing 
        \begin{align*}
            \theta 
            &= - \Divg\big(\delgps g\big)
            + \delps g 
            + \alpha\eps \Grad\phi\cdot \n,
        \end{align*}
        we thus ensure that the first line of \eqref{EST:DISS:S:3} vanishes, which shows that the inequality \eqref{EST:DISS:S:3} is fulfilled.

        \item \textit{The case $K\in(0,\infty]$.}
        In this case, we assume that $\phi$ and $\psi$ are coupled by the boundary condition
        \begin{alignat}{2}
            \label{BC:PHIPSI:2}
            K\eps \deln\phi &= \alpha\psi-\phi
            &&\quad\ton\ST \text{ if $K\in (0,\infty)$},
            \\
            \label{BC:PHIPSI:3}
            \deln\phi &= 0
            &&\quad\ton\ST \text{ if $K=\infty$},
        \end{alignat}
        where $\alpha\in\R$ is a prescribed parameter.
    	In view of the definition of $g$ (see \eqref{DEF:GL:S}), this ensures that 
    	\begin{alignat*}{2}
    		\delph g  
    		&= - \h(K) (\alpha\psi - \phi)  
    		= - \eps \Grad\phi\cdot\n 
    		&&\ton\ST,
    		\\
    		\delps g  
    		&= \delta^{-1} G'(\psi) + \alpha \h(K) (\alpha\psi - \phi)  
    		=  \delta^{-1} G'(\psi) + \alpha \eps \Grad\phi\cdot\n 
    		&&\ton\ST.
    	\end{alignat*}
    	Consequently, the first line of \eqref{EST:DISS:S:3} can be rewritten as
    	\begin{align*}
    		\big[
    		\delps g 
    		- \Divg\big(\delgps g\big) 
    		- \theta
    		\big] \deltc\psi
    		\quad\ton\ST.
    	\end{align*}
    	Choosing 
    	\begin{align*}
    		\theta 
    		&= - \Divg\big(\delgps g\big)
    		+ \delps g ,
    	\end{align*}
    	we thus ensure that the first line of \eqref{EST:DISS:S:3} vanishes, which shows that the inequality \eqref{EST:DISS:S:3} is fulfilled.
	\end{itemize}
    \end{subequations}
    %
	By the definition of $g$ (see \eqref{DEF:GL:S}), we conclude in all cases $K\in[0,\infty]$ that $\theta$ is given by
	\begin{align}
		\label{PDE:THETA}
		\theta = - \delta \Lapg\psi + \frac 1\delta G'(\psi) + \alpha \eps \Grad\phi\cdot\n 
		\ton\ST.
	\end{align}
	Eventually, by substituting \eqref{DEF:JPHI} and \eqref{DEF:KPSI} into \eqref{EQ:PSI}, we obtain
	\begin{align}
		\label{PDE:PSI}
		\deltc \psi + \Divg(\psi\u_\tau) = \Divg(\mga(\psi) \Gradg \theta) - \beta \mom(\phi) \Grad\mu\cdot\n
		\quad\text{on $\ST$.}
	\end{align}

    In summary, we have thus derived system \eqref{eqs:NSCH} along with formulas \eqref{eq:rho}-\eqref{eq:T} with the following correspondences:
    %
    \begin{center}
    \makeatletter \setlength{\tabcolsep}{2pt} \makeatother
    \begin{tabular}{rclcrclcrcl}
        \eqref{eqs:NSCH:1} 
        &$\widehat{=}$ 
        &\eqref{PDE:NS}, \eqref{PDE:DIVV}, 
        &$\phantom{xx}$ 
        &\eqref{eqs:NSCH:2} 
        &$\widehat{=}$ 
        &\eqref{PDE:PHI}, 
        &$\phantom{xx}$ 
        &\eqref{eqs:NSCH:3} 
        &$\widehat{=}$ 
        &\eqref{PDE:MU}, 
        \\
        \eqref{eqs:NSCH:4} 
        &$\widehat{=}$ 
        &\eqref{PDE:PSI},
        &$\phantom{xx}$ 
        &\eqref{eqs:NSCH:5} 
        &$\widehat{=}$ 
        &\eqref{PDE:THETA},
        &$\phantom{xx}$ 
        &\eqref{eqs:NSCH:6} 
        &$\widehat{=}$ 
        &\eqref{BC:PHIPSI}, \eqref{BC:MUTHETA}, 
        \\
        \eqref{eqs:NSCH:7} 
        &$\widehat{=}$ 
        &\eqref{BC:NAV}, 
        &$\phantom{xx}$ 
        &\eqref{eqs:NSCH:8} 
        &$\widehat{=}$ 
        &\eqref{BC:NOR},
        &$\phantom{xx}$ 
        &\eqref{eqs:NSCH:9} 
        &$\widehat{=}$ 
        &\eqref{PDE:DIVV:S}, \eqref{BC:NORVEL},
        \\
        \eqref{eq:rho} 
