\section{Environment construction and AFM embedding}\label{appendix:sec_3}
This section elaborates on the amino-acid centric environment construction algorithm discussed in Section \ref{sec:sec_env}.
\begin{algorithm}[h!]
\caption{Amino-Acid Centric Environment Extraction}
\label{alg:env_extract}
\begin{algorithmic}[1]
\Require Protein dataset $\mathcal{D}$, radius $r_{\text{max}} = 5$\AA
\State $\mathcal{E} \gets \emptyset$
\ForAll{structure $\mathcal{X} \in \mathcal{D}$} \Comment{$\mathcal{X} \in \mathbb{R}^{N_{\text{atoms}} \times 3}$}
    \ForAll{amino acid $a \in \mathcal{X}$}
        \ForAll{atom $\mathbf{x}_{i} \in a$}
        \Comment{$\mathbf{x}_{i} \in \mathbb{R}^{3}$}
            \State $\mathcal{X}_{a} \gets \{a\}$
            \ForAll{amino acid $a' \in \mathcal{X}$}
                \If{$\exists\, \mathbf{x}_{j} \in a'$ s.t. $\left\|\mathbf{x}_{i} - \mathbf{x}_{j}\right\| \leq r_{\text{max}}$}
                    \State $\mathcal{X}_{a} \gets \mathcal{X}_{a} \cup \{a'\}$ \Comment{All atoms in $a'$}
                \EndIf
            \EndFor
            \State $\mathcal{E} \gets \mathcal{E} \cup \mathcal{X}_{a}$
        \EndFor
    \EndFor
\EndFor
\State \Return $\mathcal{E}$
\end{algorithmic}
\end{algorithm}

\section{Predicting amino acid, secondary structure, and pK\textsubscript{a}}\label{appendix:sec_4}
In what follows, we provide additional details for experiments and results described in Section \ref{sec:chemistry}.

\subsection{Secondary Structure and Amino Acid Prediction}\label{subsec:amino_ss_appendix}
\paragraph{Target variables.} In these tasks, the target space of the target $\mathrm{y}$ is categorical variable.
\begin{itemize}
    \item In \textbf{amino acid prediction}, the target variable $\mathrm{y}$ holds one of the  following categories: $\{A, C, D, E, F, G, H, I, K, L, M, N, P, Q, R, S, T, V, W, Y\}$, each representing a standard twenty amino acids (cf. \cite{kawashima2000aaindex} for further explanation).
    \item In \textbf{secondary structure prediction}, the target variable $\mathbf{y} $ can assume one of the following categories: $\{H, E, O \}$, where $H$ denotes an $\alpha$-helix, $E$ denotes a $\beta$-strand, and $O$ corresponds to all other secondary structure types (see  Table \ref{tab:ss_codes}). Although more secondary structure types exist, we are primarily interested in $\alpha$-helices and $\beta$-strands due to their structural prominence.
\end{itemize}
\paragraph{Loss function.} To train models for these tasks, we employ a \textit{cross entropy loss} written as
\begin{equation}\label{eq:cross_entropy}
    \mathcal{L} (\hat{\mathrm{y}}_{i}, \mathrm{y}_{i}) = - \sum_{c=1}^{\mathrm{|y|}} y_{ic} \log \left(\dfrac{\exp(\hat{y}_{ic})}{\sum_{j=1}^{\mathbf{|y|}} \exp(\hat{y}_{ij})} \right),
\end{equation}
where $\hat{\mathrm{y}}_{i}$ is the \textit{predicted logit} for each class and $\mathrm{y}_{i}$ is the \textit{one-hot encoding} of the true class label for sample $i$.
\paragraph{Evaluation metrics.} To evaluate the model's performance, we use the following metrics.
\begin{itemize}
    \item \emph{Precision}: For a given class $i$, precision is defined as
    \begin{equation*}
        \text{Precision}_{i} = \dfrac{\text{True Positive}_{i}}{\text{True Positive}_{i} + \text{False Positive}_{i}}
    \end{equation*}
    \item \emph{Recall}: For a given class $i$, recall is defined as
    \begin{equation*}
        \text{Recall}_{i} = \dfrac{\text{True Positive}_{i}}{\text{True Positive}_{i} + \text{False Negative}_{i}}
    \end{equation*}
    \item \emph{F1 score}: For a given class $i$, the F1 score is the harmonic mean of its Precision and Recall:
    \begin{equation*}
        \text{F1}_{i} = 2 \cdot \dfrac{\text{Precision}_{i} \cdot \text{Recall}_{i}}{\text{Precision}_{i} + \text{Recall}_{i}}
    \end{equation*}
\end{itemize}
For secondary structure prediction we report the precision, recall, and F1 score for each class in $\mathrm{y}$. In addition, we report an unweighted average and a weighted average (mean weighted by number of instances in each class) for the respective tasks.

\paragraph{Ablation study.} We conduct an ablation study on the set of atoms $\mathcal{A}_{a}$ to evaluate the effect of including descriptors from multiple atoms within amino acid $a$ on secondary structure and amino acid prediction performance. Specifically, two configurations are compared: one where $\mathcal{A}_{a} = \{\text{C, CA, CB, N, H, HA}\}$, and a reduced version $\mathcal{A}_{a} = \{\text{CA}\}$. For this ablation, identical models are trained using Egret descriptors, varying only the atom set. Egret descriptors are used because as shown in Tables \ref{tab:ss_results} and \ref{tab:name_results}, they consistently outperform other atom-level descriptor types. The ablation results for secondary structure prediction are presented in Table \ref{tab:ss_ablation} and for amino acid prediction in Table \ref{tab:aa_ablation}. Clearly, incorporating a larger set of atoms in $\mathcal{A}_a$ leads to a substantial improvement in prediction accuracy.

\subsection{Acid dissociation constant (pK\textsubscript{a}) prediction}\label{subsec:app_pka}
\paragraph{Loss function.} We treat $pK_\text{a}$ prediction as a regression problem.  To train pKa regressors, we train a graph neural network to minimize the mean absolute error (MAE) as follows,
\begin{equation}
    \mathcal{L}_{1} = \dfrac{1}{N} \sum_{i=1}^{N} |y_{i} - \hat{y}_{i}|,
\end{equation}
where $N$ is the number of samples in the dataset, $y^*_i$ is the \textit{groundtruth} pK\textsubscript{a} value of a protonated site in a protein obtained by solving the Poisson-Boltzmann equation from \cite{reis2020pypka}, and $\hat{y}_i$ is the \textit{predicted }pK\textsubscript{a}. 

\paragraph{Evaluation metrics.} To quantitatively evaluate the accuracy of the model, we report the mean absolute error measured on the test set. 
