\subsection{Algorithm Core Components} 
\subsubsection{\textbf{LLM-DE}}
\begin{algorithm}[t]
    \begin{algorithmic}[1]
        \STATE \textbf{Input:}
        \STATE \quad Combinatorial action set: 
        $\mathcal{CA} = \{a_1, \ldots, a_8\}$ 
        \STATE \quad Total number of FEs: $MFEs$
         \STATE \quad Number of current FEs: $FEs$
        \STATE \quad 
         Average score of each action: $S(t)$
        \STATE \quad 
          Selected frequency of each action: $V(t)$
        \STATE \quad Number of iteration: $t$ 
        \STATE  Set $\mathcal{A}^{*} \gets \emptyset$ 

        \STATE  $(\mathcal{A}, \mathcal{L}) \gets \textbf{LLM}(\mathcal{CA}, S(t), V(t), MFEs, FEs, t)$

        \STATE  \textbf{for} $i\leftarrow 1$ \textbf{to} $|\mathcal{A}|$ \textbf{do}
        \STATE \quad \textbf{if} $\mathcal{L}\{i\} = \text{certain}$ \textbf{then}
        \STATE \quad \quad \textbf{if} $\mathcal{A}\{i\} \notin \mathcal{A}^{*}$ \textbf{then}
        \STATE  \quad \quad \quad $\mathcal{A}^{*} \leftarrow \mathcal{A}^{*} \cup \mathcal{A}\{i\}$
        \STATE \quad \quad \textbf{end if}
        \STATE  \quad \textbf{else}
        % \STATE  \quad \quad $\mathcal{CA}' \leftarrow \mathcal{CA}' \cup \mathcal{A}\{i\}$
        \STATE \quad \quad $P(t)\gets \text{Softmax}(S(t))$
        \STATE  \quad \quad  $a_r \gets \text{Roulette-wheel}(P(t))$ 

        \STATE  \quad \quad \textbf{if} $a_r \notin \mathcal{A}^{*}$ \textbf{then} 
        \STATE  \quad \quad \quad $\mathcal{A}^{*} \leftarrow \mathcal{A}^{*} \cup a_r$
        \STATE \quad \quad \textbf{end if}

        \STATE \quad \textbf{end if}
        \STATE  \textbf{end for}

        \STATE \textbf{Output:} Selected action set $\mathcal{A}^{*}$

    \end{algorithmic}

    \caption{\textbf{LLM-DE}($\mathcal{CA}$, $MFEs$, $FEs$, $S(t)$,$V(t)$, $t$)}
    \label{alg:LLM-DE}
\end{algorithm}

The task of \textbf{LLM-DE} is to leverage the LLM as a decision expert for selecting actions. The corresponding pseudocode is provided in Algorithm~\ref{alg:LLM-DE}. Specifically, \textbf{LLM-DE} first observes the contextual information of the time slot and all actions in $\mathcal{CA}$, then outputs a selected set of actions $\mathcal{A}$ along with a corresponding 
set of confidence labels $\mathcal{L}$ for each selected action~(line 9). It should be noted that these confidence labels are generated via a self-reflection mechanism, wherein the LLM introspects and assesses the reliability of its own outputs. If the LLM is confident in its selected action, it is assigned the label 'certain'; otherwise, it receives the label 'uncertain'. The specific prompt for \textbf{LLM-DE} is shown in Fig. \ref{fig: Prompt}. Furthermore, if an action is labeled as 'certain', it is added to the set $\mathcal{A}^{*}$ (lines 11-14). Otherwise, the probabilities for each action are calculated using a softmax function based on their average scores (line 16), as described below: 
\begin{equation}
P_{a_i}(t) = \frac{\exp(S_{a_i}(t))}{\sum_{j=1}^{|\mathcal{CA}|} \exp(S_{a_j}(t))}, \quad i = 1, \ldots, |\mathcal{CA}|.
\end{equation}
Finally, the roulette wheel selection strategy is used to determine the final action $a_r$ according to the computed probabilities (line 17) , which is then added to $\mathcal{A}^{*}$ (lines 18-20).
