\paragraph{Tree Coarsening Procedure}

In \cref{alg:binary-coarnse-tree}, we provide the full procedure of constructing the (binary) coarse-grained trees augmented with unresolved merger nodes for classification.

\begin{algorithm}[ht!]
\caption{Merger Tree Coarsening}
\label{alg:binary-coarnse-tree}
\small
\begin{algorithmic}[1]
\Require Tree $\mathcal{T}_0 = ([n_0], E_0, X_0)$ defined over full time steps $\{1, 2, \ldots, T\}$.


\State \textbf{Pre-Binarization:} For each node with more than two pre-merger nodes in $\mathcal{T}_0$, retain only the two most massive nodes to obtain a binary tree $\mathcal{T}_{\text{bin}}$. Let $M_0$ be the set of merger nodes in $T_{\text{bin}}$.

\State \textbf{Coarsening:} 

\State \hspace{1.3em} Remove all nodes from even time steps $\{ 2,4,\ldots, T-1\}$ in $\mathcal{T}_{\text{bin}}$ (retrain the root at time $T$). 

\State \hspace{1.3em} Denote the set of kept nodes $[n']$ and features as $X'$.

\State \hspace{1.3em} Create a dictionary $D \gets \{\text{parent}(m) : m \mid m \text{ is a removed  node} \land m \in M_0 \}$

\State \hspace{1.3em} \textbf{For each} $c \in [n']$, walk up to first kept parent node $p$ and add an edge $(c \to p)$ if not already visited.

\State \hspace{1.3em} Let the resulting tree be $\mathcal{T}_{\text{coarse}} = ([n'], E', X')$

\State \textbf{Post-Binarization:} Apply binarization (see line 1) to $\mathcal{T}_{\text{coarse}}$ to obtain binary-coarsened tree $\mathcal{T} = (V, E, X)$

%\State \textbf{Merge Node Identification} Let $M \subset [n]$ be the set of merger nodes in $\mathcal{T}$

\State \textbf{Virtual Node Augmentation:} Maintain the virtual node set $\tilde{V}$, virtual edges $\tilde{E}$, and labels $\mathbf{y}$.
\For{each $n$ in the set of merger nodes in $\mathcal{T}$}
    \State Add virtual node $v(n)$ to $\tilde{V}$ (i.e., the unresolved merger nodes for classification)
    \State Add three virtual edges to $\tilde{E}$: $(n \to v(n)), (\text{child1}(n) \to v(n)), (\text{child2}(n) \to v(n)).  $
    \If{$n \in \text{keys}(D)$}
        \State Label $\mathbf{y}_{v(n)} \gets 1$
    \Else
        \State Label $\mathbf{y}_{v(n)} \gets 0$
    \EndIf
\EndFor

\State \textbf{Return:}  Binarized, coarsened tree $\mathcal{T}_c = (V+\tilde{V}, E+\tilde{E}, X\cup \mathbf{0}, \mathbf{0}\cup \mathbf{y})$ with virtual nodes and labels.

\end{algorithmic}
\end{algorithm}



