\begin{center}
\begin{minipage}{0.6\textwidth} 
\begin{algorithm}[H]
\caption{MLMC gradient adjustment}
\label{alg:grad_adjust}
\begin{algorithmic}[1]
\State \textbf{Input} $\nabla h_0(\phi), \{\nabla\bar{f}_{\phi}^{l, +}, \nabla \bar{f}_{\phi}^{l-1, -}\}_{l=1}^L$
\For{$l = 1$ to $L$}
    \State $\nabla \bar{f}_{\phi}^{l-1, -}$ $\leftarrow \frac{||\nabla\bar{f}_{\phi}^{l, +}||_2}{||\nabla\bar{f}_{\phi}^{l-1, -}||_2 + \epsilon} \nabla \bar{f}_{\phi}^{l-1, -} $
\EndFor
\State $\nabla h_c(\phi) \leftarrow \sum_{l=1}^L( \nabla\bar{f}_{\phi}^{l, +} + \nabla \bar{f}_{\phi}^{l-1, -})$
\If{$\nabla h_0(\phi) \cdot \nabla h_c(\phi) < 0$}
\State $\tilde\nabla h_0(\phi) \leftarrow \nabla h_0 (\phi) - \frac{\nabla h_0(\phi) \cdot\nabla h_c(\phi)}{||\nabla h_c(\phi)||_2^2} \nabla h_c(\phi)$
\State $\tilde\nabla h_c (\phi) \leftarrow \nabla h_c(\phi) - \frac{\nabla h_0 (\phi)\cdot \nabla h_c(\phi)}{||\nabla h_0(\phi)||_2^2} \nabla h_0(\phi)$
\Else{$\tilde\nabla h_0(\phi) \leftarrow \nabla h_0(\phi) , \tilde\nabla h_1 (\phi)\leftarrow\nabla h_1(\phi)$}
\EndIf
\State \textbf{Output} $\tilde\nabla \ell_\text{MLMC}(\phi) \leftarrow \tilde\nabla h_0 (\phi) + \tilde\nabla h_c (\phi)$
\end{algorithmic}
\end{algorithm}
\end{minipage}
\end{center}



\section{Proof of theoretical results}
\label{app:proofs}

\subsection{Proof of \Cref{thm:main_result}}
\label{appendix:proof_main_result}

\begin{proof}
Note that here, and throughout the rest of this proof, we will simplify the notation.
We will drop the subscript for variances and expectations, and these should all be understood as being $u_{1:m} \sim \mathbb{U}^m$ and $\theta \sim \pi$. We will also use the variable $\z$ to denote a vector containing $u_{1:m}$ and $\theta$, so that $\z \in \mathbb{R}^{md_{\mathcal{U}}+d_{\Theta}}$ and $\z_i$ represents a vector containing $u_{1:m, i}$ and $\theta_i$. Finally, we will write $L^4$ and $W^{1,4}$ to denote the weighted norms $L^4(\pi \times \mathbb{U}^m)$ and $W^{1,4}(\pi \times \mathbb{U}^m)$.

The proof will be structured as follows. We will express the variance of each term using the variance of individual samples. We will then use a Poincar\'e-type inequality to bound the variance of the objective in terms of the expected squared norm of its gradient, then we will upper bound the norm using only terms which depend on constants and terms expressing how well $G^{l-1}$ approximates $G^{l}$. Note that we will first prove the result for NLE, and will comment on the NPE case at the bottom of the proof.

Since each term in the MLMC expansion are MC estimators (and therefore based on independent samples), we can express the variances of each term as follows: 
\begin{align}\label{eq:Var_MCterms1}
\text{Var}\left[h_0(\phi)\right] & = \text{Var}\left[\frac{1}{n_0} \sum_{i=1}^{n_0} f^0_\phi \left(\z_i \right)\right] \nonumber \\
& = \frac{1}{n_0^2} \sum_{i=1}^{n_0} \text{Var}\left[ f^0_\phi \left(\z_i\right)\right] = \frac{1}{n_0} \text{Var}\left[f_{\phi}^0 \left(\z\right) \right], 
\end{align}
where we use the fact that the variance of a sum of independent random variables is the sum of variances. Similarly for the other levels, 
\begin{align} \label{eq:Var_MCterms2}
\text{Var}\left[h_l(\phi)\right] & = \frac{1}{n_l} \text{Var}\left[f_{\phi}^l \left(\z \right) - f_{\phi}^{l-1}\left(\z\right)\right]\quad \text{for } l \in \{1,\ldots,L\}.
\end{align}




For the first step, we use a version of a Poincar\'e-type inequality for log-concave measures due to \citep{Bobkov1999} (note that a simpler statement and additional discussion is provided in Proposition 10.1 (b) of \citet{Saumard2014} for the case of strongly log-concave measures). This result shows that for any log-concave measure $\mu$, there exists $K_\text{Poin}>0$ such that for any sufficiently regular integrand $f:\mathcal{Z} \rightarrow \mathbb{R}$ where $\mathcal{Z} \subseteq \mathbb{R}^{d_\mathcal{Z}}$, $\text{Var}[f(z)] \leq K_\text{Poin} \mathbb{E}_{z \sim \mu}\left[\|\nabla f(z) \|_2^2 \right]$. Applying this Poincar\'e inequality to each term of the learning objective (i.e. to the terms in \Cref{eq:Var_MCterms1} and \Cref{eq:Var_MCterms2}), we get
\begin{align}\label{eq:Poincare0}
     \text{Var}\big[f_{\phi}^0(\z) \big] & \leq  K_\text{Poin} \; \mathbb{E}\left[\left\|\nabla_{\z} f_{\phi}^0(\z) \right\|^2_2 \right]\\\label{eq:Poincare}
    \text{Var}\big[f_{\phi}^l(\z) - f_{\phi}^{l-1}(\z)\big] & \leq  K_\text{Poin} \; \mathbb{E}\left[\left\|\nabla_{\z} f_{\phi}^l(\z) - \nabla_{z} f_{\phi}^{l-1}(\z) \right\|^2_2 \right]
\end{align}
for $l \in \{1,\ldots,L\}$. Here, we emphasise again that the expectation is over $z$, which encompasses both $\theta$ and $u_{1:m}$. This result requires the joint distribution of the prior $\pi$ and $m$ times the base measure $\mathbb{U}$ to be  log-concave, which holds since the product of log-concave densities is also log-concave (since the sum of convex functions is convex) and we have assumed that the prior and base measures are independent and separately log-concave through Assumption \hyperref[A1]{(A1)}. 

To simplify notation, we now introduce the vector-valued function $g^l(\z) = g^l(\theta,u_{1:m}) = (G^l_\theta(u_1)^\top,\ldots,G^l_\theta(u_m)^\top,\theta)^\top$ so that $q_\phi^{\text{NLE}}(G^l_\theta(u) \given \theta)=q_\phi^{\text{NLE}}(g^l(\theta,u)) = q_\phi^{\text{NLE}}(g^l(\z)) $. We will now derive our first bound, which looks at the first term in the MLMC expansion. To do so, we simplify \Cref{eq:Poincare0} as follows
\begin{align}
    \mathbb{E}\left[\left\| \nabla_{z} f_{\phi}^0(\z) \right\|^2_2\right]
   & = \mathbb{E} \left[\left\| \nabla_{\z}  \log q^{\text{NLE}}_{\phi}\left(g^0(\z)\right)\right\|^2_2 \right] \nonumber \\
   &
   = \mathbb{E}\left[\left\|  \nabla_{\z} g^0(\z) \nabla \log q^{\text{NLE}}_{\phi}\left(g^0(\z)\right) \right\|^2_2\right] \label{eq:term0_1}\\
&
   \leq \mathbb{E}\left[\left\|  \nabla_{\z} g^0(\z) \right\|^2_2 \left\| \nabla \log q^{\text{NLE}}_{\phi}\left(g^0(\z)\right) \right\|^2_2\right] \label{eq:term0_2} \\
   &
   \leq \mathbb{E}\left[\left\|  \nabla_{\z} g^0(\z)\right\|^4_2\right]^\frac{1}{2} \mathbb{E}\left[\left\| \nabla \log q^{\text{NLE}}_{\phi}\left(g^0(\z)\right) \right\|^4_2\right]^\frac{1}{2} \label{eq:term0_3}
\end{align}
Here, we have that \Cref{eq:term0_1} follows due to the chain rule, \Cref{eq:term0_2} follows due to the Cauchy-Schwarz inequality of the 2-norm, \Cref{eq:term0_3} follows due to the Cauchy-Schwarz inequality of expectations.

We now bound each term in \Cref{eq:term0_3} separately. For the first term, we get
\begin{align}
  \mathbb{E}\left[\left\|  \nabla_{\z} g^0(\z)\right\|^4_2\right]  & = 2 \mathbb{E}\left[\|\nabla_{\z} G^0(\z)\|^4_2\right]+ 2 \mathbb{E}\left[\| \nabla_z \theta\|_2^4\right]\label{gradg_min1}\\
    & \leq 
     2 \mathbb{E}\left[\left\|  \nabla_{\z} G^0(\z)\right\|^4_{F} \right] +2 \mathbb{E}\left[\| \nabla_z \theta\|_F^4 \right]\label{gradg_0}\\
   & = 2 \mathbb{E}\left[\left(\sum_{|\alpha| = 1} \left(\sum_{j=1}^d \left( D^\alpha (G^0(\z))_j\right)^2\right)\right)^2\right] +2d_{\Theta}^2  \label{gradg_1}\\
   & \leq 2 (d_{\Theta}+m d_{\mathcal{U}}) \sum_{|\alpha| = 1} \mathbb{E}\left[\left( \sum_{j=1}^d  \left( D^\alpha (G^0(\z))_j\right)^2 \right)^2\right] +2 d_{\Theta}^2  \label{gradg_2} \\
   & \leq 2 (d_{\Theta}+m d_{\mathcal{U}}) \sum_{|\alpha| = 1} \mathbb{E}\left[\|D^\alpha G^{0}(\z)\|_2^4 \right]+2 d_{\Theta}^2  \label{gradg_21} \\
    &  \leq 2 (d_{\Theta}+m d_{\mathcal{U}}) \sum_{|\alpha|= 1} \left\|D^\alpha G^0 \right\|^4_{L^{4}} +2 d_{\Theta}^2 \label{gradg_30} \\
    &  \leq 2(d_{\Theta}+m d_{\mathcal{U}}) \left\|G^0 \right\|^4_{W^{1,4}}+2 d_{\Theta}^2, \\
    & \leq K_{\text{grad}} \left(\left\|G^0 \right\|^4_{W^{1,4}} +1\right)\label{gradg_3} 
\end{align}
where \Cref{gradg_min1} follows from the fact that $(a+b)^{2} \leq 2 a^2 +2b^2$, \Cref{gradg_0} follows from the fact that the  Frobenius norm $\|\cdot\|_{F}$ is an upper-bound on the matrix 2-norm, \Cref{gradg_1} follows from the definition of the Frobenius norm and from the fact that $\mathbb{E}[\|\nabla_z \theta \|_F^4] =  d_{\Theta}^2$, \Cref{gradg_2} follows from the fact that $(\sum_{i=1}^n a_i)^2 \leq n \sum_{i=1}^n a_i^2 $, and \Cref{gradg_21}, \Cref{gradg_30} and \Cref{gradg_3} follow from the definitions of the 2-norm, the  $L^4$-norm and the $W^{1,4}$-norm respectively.



We now move on to bounding the second term in \Cref{eq:term0_3}. 
Since we assumed in Assumption \hyperref[A3]{(A3)} that $\nabla \log q^{\text{NLE}}_{\phi}$ satisfies a linear growth condition, 
we must have that 
\begin{align}
    \mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_{\phi}\left(g^0(\z)\right) \right\|^4_2\right] 
    & = \mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_{\phi}\left(G_\theta^0(u) \given \theta\right) \right\|^4_2\right] \\
    & \leq  K^4_{\text{grow}}(\phi) \mathbb{E}\left[\left(\left\|G^0(\z)\right\|_2+\|\theta\|_2+1 \right)^4\right] \label{eq:scoreterm1}\\
     & \leq 27 K^4_{\text{grow}}(\phi) \left( \mathbb{E}\left[\left\|G^0(\z)\right\|_2^4\right] + \mathbb{E}\left[ \|\theta\|_2^4\right]+1\right) \label{eq:scoreterm2} \\ 
     & \leq 27 K^4_{\text{grow}}(\phi) \left( \left\|G^0 \right\|_{W^{1,4}}^4 + \mathbb{E}\left[ \|\theta\|_2^4\right]+1\right) \nonumber\\
     & \leq K_{\text{score}}(\phi) \left( \left\|G^0 \right\|_{W^{1,4}}^4 +1\right)\label{eq:scoreterm3}
\end{align}
Here, \Cref{eq:scoreterm1} uses the growth condition, \Cref{eq:scoreterm2} holds due since $(a+b+c)^4 \leq 27(a^4+b^4+c^4)$, and \Cref{eq:scoreterm3} uses the definition of Sobolev norm and the fact that $\mathbb{E}\left[ \|\theta\|_2^4\right]$ is upper bounded by a constant since the expectation is against $\pi$, which a log-concave distribution and hence all its moments are finite (see Section 5.1. of \cite{Saumard2014}). Combining \Cref{eq:Var_MCterms1}, \Cref{eq:Poincare0}, \Cref{eq:term0_3}, \Cref{gradg_3}, and \Cref{eq:scoreterm3} therefore gives:
\begin{align}
    \text{Var}\left[h_0(\phi)\right] 
    & \leq \frac{1}{n_0} K_{\text{Poin}} K_{
    \text{grad}}^{\frac{1}{2}}
     \left( \left\|G^0 \right\|^4_{W^{1,4}} +1\right)^{\frac{1}{2}} K_{
    \text{score}}(\phi)^{\frac{1}{2}}
     \left( \left\|G^0 \right\|^4_{W^{1,4}} +1\right)^{\frac{1}{2}}\nonumber \\
    & \leq \frac{K_0(\phi)}{n_0} \left(\left\|G^0 \right\|^4_{W^{1,4}}+1\right)
\end{align}
where $K_0(\phi)$ is used to combine all of the constants. This now concludes the first part of our results, which bounds the variance of the first term in the MLMC telescoping sum.

We can now derive a similar bound for the other terms (i.e. to simplify \Cref{eq:Poincare}). We do this by first only considering the norm inside of the expectation:
    \begin{align}
      & \left\| \nabla_{\z} f_{\phi}^l(\z) - \nabla_{\z}  f_{\phi}^{l-1}(\z) \right\|_2 \nonumber \\
     & = \left\| \nabla_{\z}  \log q^{\text{NLE}}_{\phi}\left(g^l(\z)\right) - \nabla_{\z}  \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right)  \right\|_2 \nonumber \\
      &  = \Big\|  \nabla_{\z} g^{l}(\z) \nabla \log  q^{\text{NLE}}_{\phi}(g^l(\z)) -  \nabla_{\z} g^{l-1}(\z) \nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \Big\|_2 \label{eq:terml1_1}\\
      & \leq \Big\|  \nabla_{\z} g^{l}(\z) \left( \nabla \log q^{\text{NLE}}_{\phi}\left(g^l(\z)\right) - \nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \right)\Big\|_2 \nonumber \\
        & \quad + \Big\| \left(\nabla_{\z} g^{l}(\z) - \nabla_{\z} g^{l-1}(\z)\right) \nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \Big\|_2  \label{eq:terml1_2} \\
         & \leq \Big\|  \nabla_{\z} g^{l}(\z) \Big\|_2 
        \Big\|\nabla \log q^{\text{NLE}}_{\phi}(g^l(\z)) - \nabla \log q^{\text{NLE}}_{\phi}(g^{l-1}(\z))\Big\|_2 \nonumber \\
        & \quad + 
        \Big\| \nabla_{\z} g^{l}(\z) - \nabla_{\z} g^{l-1}(\z)\Big\|_2
        \Big\| \nabla \log q^{\text{NLE}}_{\phi}(g^{l-1}(\z)) \Big\|_2  \label{eq:terml1_3} 
      \end{align}
      Here, \Cref{eq:terml1_1} follows from the chain rule, \Cref{eq:terml1_2} follows by adding and subtracting the term $\nabla_{\z} g^{l}(\z) \nabla \log q^{\text{NLE}}_{\phi}(g^{l-1}(\z))$ and using the triangle inequality, and \Cref{eq:terml1_3} follows from the Cauchy-Schwarz inequality of the 2-norm.
      Squaring both sides of this inequality and taking expectations, we then obtain:
    \begin{align}
     & \mathbb{E}\left[\left\| \nabla_{\z} f_{\phi}^l(\z) - \nabla_{\z}  f_{\phi}^{l-1}(\z) \right\|^2_2\right]  \nonumber \\
     & \leq \mathbb{E}\Big[\Big(  \Big\|  \nabla_{\z} g^{l}(\z) \Big\|_2 
        \Big\|\nabla \log q^{\text{NLE}}_{\phi}(g^l(\z)) - \nabla \log q^{\text{NLE}}_{\phi}(g^{l-1}(\z))\Big\|_2 \nonumber \\
        & \quad + 
        \Big\| \nabla_{\z} g^{l}(\z) - \nabla_{\z} g^{l-1}(\z)\Big\|_2
        \Big\| \nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \Big\|_2 \Big)^2 \Big]\nonumber \\
     & \leq \mathbb{E}\Big[ 2 \Big\|  \nabla_{\z} g^{l}(\z) \Big\|^2_2 
        \Big\|\nabla \log q^{\text{NLE}}_{\phi}(g^l(\z)) - \nabla \log q^{\text{NLE}}_{\phi}(g^{l-1}(\z))\Big\|_2^2  \nonumber \\
        & \qquad + 2
        \Big\| \nabla_{\z} g^{l}(\z) - \nabla_{\z} g^{l-1}(\z)\Big\|_2^2
        \Big\| \nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \Big\|_2^2\Big].\label{eq:terml1_5} \\
        & \leq  2   \mathbb{E}\left[\Big\|  \nabla_{\z} g^{l}(\z) \Big\|^4_2 \right]^{\frac{1}{2}}
        \mathbb{E}\left[\Big\|\nabla \log q^{\text{NLE}}_{\phi}(g^l(\z)) - \nabla \log q^{\text{NLE}}_{\phi}(g^{l-1}(\z))\Big\|_2^4 \right]^{\frac{1}{2}} \nonumber \\
        & \qquad + 2
        \mathbb{E}\left[\Big\| \nabla_{\z} g^{l}(\z) - \nabla_{\z} g^{l-1}(\z)\Big\|_2^4\right]^{\frac{1}{2}}
        \mathbb{E}\left[\Big\| \nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \Big\|_2^4\right]^{\frac{1}{2}}.\label{eq:terml1_6} 
    \end{align}
where \Cref{eq:terml1_5} follows from that fact that for $a,b \in \mathbb{R}$, we have $(a+b)^2\leq 2a^2+ 2 b^2$, and \Cref{eq:terml1_6} follows from the Cauchy-Schwarz inequality for expectations. To conclude this proof, we notice that the derivation from \Cref{gradg_0} to \Cref{gradg_3} can be modified by replacing $G^0$ by $G^l$ to get:
\begin{align}
    \mathbb{E}\left[\left\|  \nabla_{\z} g^l(\z)\right\|^4_2\right] \leq K_{\text{grad}} \left(\left\|G^l \right\|^4_{W^{1,4}} +1\right) \leq K_{\text{grad}} \left(S_l^4 +1\right). \label{eq:gradGl}
\end{align}
where the last inequality holds thanks to Assumption \hyperref[A2]{(A2)}. 
Similarly, replacing $G^0$ by $G^{l}-G^{l-1}$ gives 
\begin{align}
    \mathbb{E}\left[\left\|  \nabla_{\z} g^l(\z) - \nabla_{\z} g^{l-1}(\z)\right\|^4_2\right] \leq K_{\text{grad}} \left(\left\|G^l - G^{l-1} \right\|^4_{W^{1,4}} +1\right).\label{eq:gradGlGl-1}
\end{align}
Additionally, we could replace $G^0$ by $G^{l-1}$ in the the bound from \Cref{eq:scoreterm1} to \Cref{eq:scoreterm3} in order to get:
\begin{align}
\mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_{\phi}\left(g^{l-1}(\z)\right) \right\|^4_2\right] & \leq K_{\text{score}}(\phi) \left( \left\|G^{l-1} \right\|_{W^{1,4}}^4 +1\right)\\
& \leq K_{\text{score}}(\phi) \left( S_{l-1}^4 +1\right)
 \label{eq:gradloqGl-1}
\end{align}
where once again we used Assumption \hyperref[A2]{(A2)}. 

 Finally, we split the following expression to make use of our local Lipschitz property:
\begin{align}
&\mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_\phi \left(g^l(z) \right) - \nabla \log q^{\text{NLE}}_\phi \left(g^{l-1}(z)\right)\right\|^4_2\right] \\
& = \mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_\phi \left(g^l(z)\right) - \nabla \log q^{\text{NLE}}_\phi \left(g^{l-1}(z) \right)\right\|^4_2 \Big| \left\|G^l(z)-G^{l-1}(z)\right\|_2 \geq \delta \right] \nonumber \\
& \qquad \quad \times \mathbb{P}\left[\left\|G^l (z)-G^{l-1}(z)\right\|_2 \geq \delta \right] \nonumber\\
& \quad + 
\mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_\phi \left(g^l(z)\right) - \nabla \log q^{\text{NLE}}_\phi \left(g^{l-1}(z)\right)\right\|^4_2 \Big| \left\|G^l(z)-G^{l-1}(z) \right\|_2 < \delta \right]  \nonumber \\
& \qquad \quad \times \mathbb{P}\left[\left\|G^l(z)-G^{l-1}(z) \right\|_2 < \delta \right]\label{eq:llipschitz1}
\\
& \leq \frac{16}{\delta} \left(\mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_\phi \left(g^l(z)\right)\right\|^4_2\right] + \mathbb{E}\left[\left\|\nabla \log q^{\text{NLE}}_\phi \left(g^{l-1}(z)\right)\right\|^4_2 \right]\right) 
\mathbb{E}\left[\left\|G^l(z)-G^{l-1}(z)\right\|_2\right] \nonumber\\
& \quad + K_\text{Lip}(\phi)^4
\mathbb{E}\left[\left\|g^l(z) - g^{l-1}(z)\right\|^4_2 \right] \times 1 \label{eq:llipschitz2} \\
& \leq K_{\text{score-diff}}(\phi,\delta)
\Big\|G^l - G^{l-1}\Big\|_{W^{1,4}}^4\label{eq:llipschitz3}
\end{align}
where \Cref{eq:llipschitz1} follows due to the law of total expectation. For \Cref{eq:llipschitz2}, the bound on the first term follows due to the triangle inequality and Markov's inequality, and the bound on the second term follows due to the local-Lipschitz condition (i.e. Assumption \hyperref[A3]{(A3)}) and the fact that a probability is always upper bounded by $1$. Finally, \Cref{eq:llipschitz3} follows using \Cref{eq:gradloqGl-1} and the definition of Sobolev norm, and by grouping all constants.
Combining all of the above (i.e. \Cref{eq:Var_MCterms2}, \Cref{eq:Poincare}, \Cref{eq:terml1_3}, \Cref{eq:gradGl}, \Cref{eq:gradGlGl-1}, \Cref{eq:gradloqGl-1}, and \Cref{eq:llipschitz3}), we end up with 
\begin{align*}
    \text{Var}\left[h_l(\phi)\right] 
    & \leq  \frac{2}{n_l} K_{\text{Poin}} \Big(K_{\text{grad}}^\frac{1}{2} (S_l^4+1)^{\frac{1}{2}} K^{\frac{1}{2}}_{\text{score-diff}}(\phi,\delta)
\Big\|G^l - G^{l-1}\Big\|_{W^{1,4}}^2 \nonumber \\
& \qquad \qquad + K_{\text{grad}}^{\frac{1}{2}}\left(\left\|G^l - G^{l-1} \right\|^4_{W^{1,4}} +1\right)^{\frac{1}{2}} K_{\text{score}}(\phi)^{\frac{1}{2}} \left( S_{l-1}^4 +1\right)^{\frac{1}{2}}\Big) \\
     & \leq \frac{K_l(\phi)}{n_l}\left(\left\|G^l - G^{l-1} \right\|^2_{W^{1,4}}+1\right), 
\end{align*}
where $K_l(\phi)$ combines all constants. This proves our second result and therefore concludes our proof.

Note that the proof follows analogously for NPE with the alternative locally-Lipschitz and growth condition assumptions.
\end{proof}



\subsection{Proof of \Cref{thm:sample_size_per_level}}\label{sec:appendix_proof_sample_per_level}

\begin{proof}
We first recall both the cost and the variance of our estimator, modifying our notation slightly to emphasise the number of samples $n_0,\ldots,n_L$. The total cost of this method is given by
\begin{align*}
    \text{Cost}({\ell}_{\text{MLMC}}(\phi);n_0,\ldots,n_L) = n_0 C_0+\sum_{l=1}^L n_l (C_l+C_{l-1}),
\end{align*} 
where $C_l$ is the cost of evaluating $f^l$ at level $l$. In addition, we also have the following upper bound on the variance using \Cref{thm:main_result}: 
\begin{align*}
    \text{Var}\left[{\ell}_{\text{MLMC}}(\phi);n_0,\ldots,n_L \right] \leq \frac{K_0(\phi)}{n_0} \left(\left\|G^0 \right\|^4_{W^{1,4}}+1\right) + \sum_{l=1}^L \frac{K_l(\phi)}{n_l}  \left(\left\|G^l - G^{l-1} \right\|^2_{W^{1,4}}+1\right), 
\end{align*}
where once again we write  $\|\cdot\|_{W^{1,4}}$ to denote the weighted norm $\|\cdot\|_{W^{1,4}(\pi\times \mathbb{U})}$.
Overall, we would like to solve the following optimisation problem:
\begin{align*}
    (n_0^\star,\ldots,n_L^\star)^\top := \arg\min_{(n_0,\ldots,n_L)^\top} \text{Var}\left[{\ell}_{\text{MLMC}}(\phi);n_0,\ldots,n_L \right] \\\quad \text{such that} \quad \text{Cost}({\ell}_{\text{MLMC}}(\phi);n_0,\ldots,n_L) \leq C_{\text{budget}},
\end{align*}
where $C_{\text{budget}}$ is the computational budget.
We relax the problem slightly by minimising  the upper bound on the variance instead, thus the problem can be expressed in the following Lagrangian form: 
\begin{align*}
    & \mathcal{L}(n_0,\ldots,n_L,\nu) \\
    & := \frac{K_0(\phi)}{n_0}\left(\left\|G^0 \right\|^4_{W^{1,4}}+1\right) + \sum_{l=1}^L \frac{K_l(\phi)}{n_l}  \left(\left\|G^l - G^{l-1} \right\|^2_{W^{1,4}}+1\right) \nonumber \\
    & \qquad + \nu \left(  \text{Cost}({\ell}_{\text{MLMC}}(\phi);n_0,\ldots,n_L) - C_{\text{budget}}\right)\\
    & = \frac{K_0(\phi)}{n_0} \left(\left\|G^0 \right\|^4_{W^{1,4}}+1\right) + \sum_{l=1}^L \frac{K_l(\phi)}{n_l}  \left(\left\|G^l - G^{l-1} \right\|^2_{W^{1,4}}+1\right)\nonumber \\
    & \qquad + \nu \left( n_0 C_0 +\sum_{l=1}^L n_l (C_l+C_{l-1})-C_{\text{budget}} \right).
\end{align*}
This can be solved by setting all partial derivatives with respect to $(n_0,\ldots,n_L)$ and $\nu$ equal to zero and solving the associated system of equations.  Firstly, we get:
\begin{align}
    \frac{\partial \mathcal{L}(n_0,\ldots,n_L,\nu)}{\partial n_0} & =  - K_0(\phi) \left(\left\|G^0 \right\|^4_{W^{1,4}} +1\right)n_{0}^{-2} + \nu C_0 = 0 \\
    & \quad \Leftrightarrow \quad n^{\star}_0 = \sqrt{\frac{K_0(\phi)}{\nu C_0} \left(\left\|G^0 \right\|_{W^{1,4}}^4+1\right)}, \label{eq:n0_opt_1}
\end{align}
and for $l\in\{1,\ldots,L\}$, we have:
\begin{align}
    \frac{\partial \mathcal{L}(n_0,\ldots,n_L,\nu)}{\partial n_l} = - K_l(\phi)\left(\left\|G^l - G^{l-1} \right\|^2_{W^{1,4}} +1\right)n_{l}^{-2} + \nu (C_l+C_{l-1}) = 0 \nonumber \\
    \quad \Leftrightarrow \quad n^{\star}_l = \sqrt{\frac{K_l(\phi)}{\nu (C_l+C_{l+1})} \left(\left\|G^l - G^{l-1} \right\|_{W^{1,4}}^2+1\right)}.\label{eq:n0_opt_l}
\end{align}
Finally, taking the partial derivative with respect to $\nu$  confirms that our constraint is active (i.e. we are on the boundary of the feasible region):
\begin{align}
    & \frac{\partial L(n_0,\ldots,n_L,\nu)}{\partial \nu} = n_0 C_0+\sum_{l=1}^L n_l (C_l+C_{l-1}) - C_{\text{budget}} = 0 \nonumber\\
     \Leftrightarrow &  \quad C_{\text{budget}} = n_0 C_0+\sum_{l=1}^L n_l (C_l+C_{l-1}). \label{eq:nu_opt_1}
\end{align}
Plugging the results of \Cref{eq:n0_opt_1} and \Cref{eq:n0_opt_l} into \Cref{eq:nu_opt_1}, we get:
\begin{align*}
    C_{\text{budget}} & = n_0 C_0+\sum_{l=1}^L n_l (C_l+C_{l-1}) \\
    & = \sqrt{\frac{K_0(\phi)}{\nu C_0}\left(\left\|G^0 \right\|^4_{W^{1,4}}+1\right)} \times C_0+\sum_{l=1}^L \sqrt{\frac{K_l(\phi)}{\nu (C_l+C_{l+1})} \left(\left\|G^l - G^{l-1} \right\|_{W^{1,4}}^2+1\right)
}\times  (C_l+C_{l-1}) \\
    & = \nu^{-\frac{1}{2}} \left( \sqrt{K_0(\phi)C_0 \left(\left\|G^0 \right\|_{W^{1,4}}^4+1\right)} +\sum_{l=1}^L \sqrt{K_l(\phi) (C_l+C_{l+1})\left(\left\|G^l - G^{l-1} \right\|_{W^{1,4}}^2+1\right)} \right),
\end{align*}
which gives
\begin{align}
    \nu =  \frac{\left( \sqrt{K_0(\phi)C_0 \left(\left\|G^0 \right\|_{W^{1,4}}^4+1\right)}+\sum_{l=1}^L \sqrt{K_l(\phi) (C_l+C_{l+1}) \left(\left\|G^l - G^{l-1} \right\|^2_{W^{1,4}} +1\right)}\right)^2}{C_{\text{budget}}^2} .\label{eq:nu_opt_2}
\end{align}
We can now use the expression for $\nu$ that we obtained in \Cref{eq:nu_opt_2} to obtain a simplified expression for $n_0,\ldots,n_L$ (using \Cref{eq:n0_opt_1} and \Cref{eq:n0_opt_l}):
\begin{align*}
    n_0^\star & \propto \frac{C_{\text{budget}} }{\sqrt{C_0}} \sqrt{\left\|G^0 \right\|_{W^{1,4}}^4+1}, \quad
    \quad n_l^\star & \propto \frac{C_{\text{budget}} }{\sqrt{C_l+C_{l+1}}} \sqrt{\left\|G^l - G^{l-1} \right\|_{W^{1,4}}^2+1} \quad \text{for } l \in \{1,\ldots,L\}.
\end{align*}
This completes our proof.
\end{proof}


\section{Experimental details \& additional results}
\label{app:experiments}
For all the experiments, we use a Mac M4 CPU with $16$ GB memory for the training of neural networks. Running all the experiments roughly takes half a day. For optimisation, we use batch gradient descent with the Adam optimiser \citep{kingma2014adam} using Pytorch \citep{paszke2017automatic}. For the construction of the conditional density estimator, we use the SBI package \citep{Tejero-Cantero2020}. We also use the BayesFlow package \citep{Radev2023} for some of the figures. For each experiment, we fix the number of epochs unless stated otherwise. We use the same setting and stopping criterion for the NPE and the NLE baseline as in the default implementation of the SBI package. 
We set the learning rate to $10^{-4}$ for all the experiments.





\subsection{The g-and-k distribution}
\label{app:g-and-k}

\textbf{Simulator setup.} 
The g-and-k distribution can be written in simulator form as follows:
\begin{align*}
    G_\theta(u)  = \theta_1 + \theta_2 \left(1+0.8 \left(\frac{1-\exp(-\theta_3 z(u))}{1+\exp(-\theta_3 z(u))} \right)\right)\left(1+z(u)^2 \right)^{\log(\theta_4)} z(u), \\
    \qquad z(u)  = \Phi^{-1}(u) = \sqrt{2}\text{erf}^{-1}(2u - 1),
    \qquad u \sim \text{Unif}([0,1]),
\end{align*}

where $\Phi^{-1}$ is the quantile function of the standard normal distribution and $\text{erf}^{-1}$ is the inverse of error function.
We set the prior distribution to be a tensor product of marginal distributions on each parameter: $\theta_1, \theta_2, \theta_3 \sim \text{Unif}([0,3]^3)$ and $\theta_4 \sim \text{Unif}([0,\exp(0.5)])$. Note that we always resort to an approximation method for the evaluation of $\text{erf}^{-1}(\cdot)$. For the high-fidelity simulator, we use an accurate approximation implemented in Scipy \citep{2020SciPy-NMeth}. For the low-fidelity simulator, we use a Taylor expansion of $\text{erf}^{-1}$ up to the third order:
\begin{align*}
    z_{\text{low}}(u) := \sqrt{2}\text{erf}^{-1}_\text{low}(2u - 1), \quad \text{erf}^{-1}_\text{low}(v) :=\frac{\pi}{2} \left(u + \frac{\pi}{12} u^3\right).
\end{align*}

An advantage of the g-and-k distribution is that its density can be approximated numerically almost exactly. Following \citet{Rayner2002}, we first numerically obtain $G_{\theta}^{-1}(x)$ by solving numerically for $x_i-G_\theta(u_i) = 0$ using a root-solving algorithm \citep{press2007numerical}\footnote{
Note that since $G_{\theta}(u)$ is a quantile function, $F_\theta(x) := G_{\theta}^{-1}(x)$ is a cumulative distribution function.}, then we obtain the density function by taking $\hat{p}(x \given \theta) := F'_\theta(x)= \partial F_\theta(x) / \partial x$. For this second step, we typically use a finite difference approximation. Seed-matching is simply done by using same the $u$ and $\theta$.

\paragraph{Neural network details} 

\paragraph{NLE:} We use the neural spline flow (NSF) \citep{durkan2019neural}. We pick $10$ bins, span of $[-7, 7]$ and $1$ coupling layer since we only have one dimensional input. The conditioner for the NSF is a multilayer perceptron neural network (MLP) with $3$ hidden layers of 50 units, and $10\%$ dropout, trained for $10,000$ epochs.

\paragraph{NPE:} We use NSF with $3$ bins, span of $[-3, 3]$ and $3$ coupling layers. The conditioner for the NSF is a MLP with $2$ hidden layers of $50$ units, and $10\%$ dropout, trained for $800$ epochs. For each true parameter values, we produce $m =1000$ i.i.d samples and obtain quantile based $4$-dimensional summary statistics following \citet{Prangle2016}.

\paragraph{Evaluations details}

\paragraph{NLE:} We calculate the forward KL-divergence between the almost exact density and the approximated density over $2000$ equidistant points in $[-30, 30]$.

\paragraph{NPE:} We calculate NLPD over $500$ simulations. Empirical coverage is estimated using average value of $500$ simulated datasets, where we draw $2000$ posterior samples from each simulations. We then calculate $1 - \beta$-highest posterior density credible interval, where $\beta$ is $101$ equidistant points between $0$ and $1$.


