\includegraphics[width=0.8\linewidth]{Images/Q_degrad_35.pdf} 
\end{center}
\caption{Degradation of the quality factor for the three structures as a function of the input power, with radius equal to $3.5 \mu m$ and $k^2 = 0.0055$.}
\label{Degrad_Q_new}
