	\section{Introduction.}





	In this paper, we prove the following equivariant stability results pertaining to \emph{$G$-metric spaces}: metric spaces equipped with actions of a group $G$ by isometries.


	\label{page:main-theorem}

	\begin{theorem*}[Stability results]
		For any finite group $G$, any two compact $G$-metric spaces $X$ and $Y$, $p\in[1,\infty]$, and every integer $k\geq 0$, we have the following inequalities:
		$$
		2\,\dgh^G(X,Y)\geq\dht^G\big((\Pfin(X),\diam_p^X),(\Pfin(Y),\diam_p^Y)\big) \geq \left\{\begin{array}{ll} \di^G\big(\h_k(\vrm_p(X;\bullet)),\h_k(\vrm_p(Y;\bullet))\big)\\
			\\
			\sup_{\varepsilon\geq 0}c_p^G(X,Y;\varepsilon)
		\end{array}
		\right. 
		$$
		\noindent
		where, for each $\varepsilon>0$,

		$$c_p^G(X,Y;\varepsilon):=\inf\{\eta>0:\text{there is a }G\text{-map }\vrm_p(Y;\varepsilon)\toG \vrm_p(X;\varepsilon+\eta)\}$$
		and, for $\epsilon=0$,
		$$\hspace{-.89in}c_p^G(X,Y;0):=\inf\{\eta>0:\text{there is a }G\text{-map }Y\toG \vrm_p(X;\eta)\}.$$
	\end{theorem*}

	Here, $\dgh^G$ is a variant of the \emph{Gromov-Hausdorff} distance designed to interact well with given $G$-equivariant isometric actions on compact metric spaces,   $\Pfin(X)$ is the collection of all finitely supported probability measures $\mu$ on $X$, $\diam_p(\mu):=\big(\iint d_X^p(x,x')\,d\mu(x)d\mu(x')\big)^{1/p}$ is the \emph{$p$-diameter} of $\mu$, and 
	$\vrm_p(X;\bullet)$ is the \emph{$p$-Vietoris-Rips metric thickening filtration of $X$}: for $\varepsilon>0$,  $\vrm_p(X;\varepsilon)$ is the collection of all  $\mu\in\Pfin(X)$  such that $\diam_p(\mu)<\varepsilon$;
	see \Cref{def:VRm}. Also, $\dht^G$ and $\di^G$ are suitable $G$-equivariant variants of the  \emph{homotopy type distance} from \cite{frosini2017persistent} and the \emph{interleaving distance} \cite{chazal2009proximity} between \emph{persistent modules}, respectively. The theorem above is obtained from \Cref{Gdhtstability}, \Cref{coro:dHTG-dIG-Katetov}, and \Cref{prop:strongercGpXYlbdd}.  

	The quantity $c_p^G$ is an instance of the concept of \emph{$G$-persistent index} which we describe in \Cref{def:clowerbdd}. In general, the two rightmost lower bounds are incomparable; see~\Cref{ex:compatibility}. Furthermore, we consider the following variants of $c_p^G(X,Y;\varepsilon)$ (see \Cref{def:clowerbdd}):

	\begin{itemize}
		\item $c_{\vr}^G(X,Y;\varepsilon):=\inf\{\eta>0:\text{there is a }G\text{-map }\vert\vr(Y;\varepsilon)\vert\toG \vert\vr(X;\varepsilon+\eta)\vert\}$, and

		\item $c_\TS^G(X,Y;\varepsilon):=\inf\{\eta>0:\text{there is a }G\text{-map }B_\varepsilon(Y,\TS(Y))\toG B_{\varepsilon+\eta}(X,\TS(X))\}$.
	\end{itemize}
	Here $\vr(X;\bullet)$ denotes the \emph{Vietoris-Rips} filtration of $X$ (see \Cref{def:VR}) and $\TS(X)$ denotes its \emph{tight span} (see \Cref{def:TS}). Precise connections between the three quantities $c_\infty^G$, $c_\vr^G$, and $c_\TS^G$, as well as applications, can be found in \Cref{prop:strongercGpXYlbddalernatives} and in \Cref{sec:GdGHresults-sph}. In particular, under mild conditions, we have that $$c_\infty^G(X,Y;0)=c_{\vr}^G(X,Y;0)=2c_\TS^G(X,Y;0).$$ Finally, we have that $c_\infty^{\Z_2}(\Sp^m,\Sp^{m+1};0)=\zeta_m:=\arccos\left(\frac{-1}{m+1}\right)$; see \Cref{rmk:cinftyZ2SmSm+1}. For $G=\Z_2$, the case $(\varepsilon=0, p=\infty)$ of the $c_p^G$ is related to and improves upon an invariant introduced in \cite{adams2022gromov}; see \Cref{rmk:referpolymath} and \Cref{sec:lb-dght-pi}.






	We employ the stability results in the statement above to prove novel $G$-equivariant rigidity (\Cref{thm:rigidity} and \Cref{cor:rigidity})  and finiteness  (\Cref{cor:Riemfinite})  theorems and to provide nontrivial (and in some situations, tight) estimates  of the $G$-Gromov-Hausdorff distance (\Cref{sec:GdGHresults}).  In \Cref{sec:qbu} we show how our techniques can be used to obtain a $G$-equivariant \emph{quantitative Borsuk-Ulam theorem} that generalizes \cite{dubins1981equidiscontinuity,lim2021gromov,adams2022gromov}. In 

	Our constructions and results offer a unified framework that both extends and generalizes recent uses of $\Z_2$-equivariant topology, which have been instrumental in obtaining sharp bounds on the Gromov–Hausdorff distance between spheres \cite{lim2021gromov,adams2022gromov}; see also \cite{harrison2023quantitative,martin2024some,memoli2024embedding}.


