	\section{Preliminaries.}\label{sec:preliminary}

	Here we collect all basic terminology, definitions and the notation we will frequently employ in this paper.

	\begin{itemize}\label{notations}
		\item A \emph{function} $f:X\longrightarrow Y$ is any, possibly discontinuous, function.

		\item A \emph{map} $f:X\longrightarrow Y$ is a continuous function.    

		\item For a bounded metric space $(X,d_X)$, $\diam(X):=\sup\limits_{x,x'\in X}d_X(x,x')$ is the \emph{diameter} of $X$. \nomenclature[01]{$\diam(X)$}{Diameter of $X$}

		\item For a nonnegative integer $n\geq 0$, let
		$$\Sp^n:=\left\{(x_0,x_1,\cdots,x_n)\in\R^{n+1}:\sum_{i=0}^{n}x_i^2=1\right\}$$
		be the usual round unit $n$-sphere and let $d_{\Sp^n}$ denote the geodesic distance on $\Sp^n$. i.e., $d_{\Sp^n}(u,v):=\arccos(\langle u,v \rangle)$ for all $u,v\in\Sp^n$. Alternatively, one may consider the Euclidean metric $d_{\SpE^n}$ on $\Sp^n$ inherited from $\R^{n+1}$, i.e. $d_{\SpE^n}(u,v):=\Vert u-v \Vert$ for all $u,v\in\Sp^n$ where $\Vert\cdot\Vert$ denotes the Euclidean norm in $\R^{n+1}$. Finally, we will use the notation $\SpE^n$ instead of $\Sp^n$ whenever the underlying $n$-sphere is equipped with the Euclidean metric $d_{\SpE^n}$ instead of the geodesic metric $d_{\Sp^n}$.

		\item For an nonnegative integer $n\geq 0$, let
		\begin{itemize}
			\item $\R^n_\infty=(\R^n,\ell^\infty)$.

			\item $\mathbb{D}^n_\infty:=(\mathbb{D}^n,\ell^\infty)$ where $\mathbb{D}^n$ is the usual closed unit ball in $\R^n$ with the Euclidean distance.

			\item $\Sp^n_\infty:=(\Sp^n,\ell^\infty)$ where $\Sp^n = \partial \mathbb{D}^{n+1}$ is the usual unit (round)  sphere.

			\item $\blacksquare^n_\infty:=(\blacksquare^n,\ell^\infty)$ where $$\blacksquare^n:=\{(x_0,\dots,x_{n-1})\in\R^n:x_i\in [-1,1]\textrm{ for all }i=1,\dots,n\}$$ is the closed unit ball in $\R_\infty^n$.

			\item $\square^n_\infty:=(\square^n,\ell^\infty)$ where 
			\begin{align*}\square^n &:= \partial \blacksquare^{n+1}\\
				&= \{(x_0,\dots,x_n)\in\R^{n+1}:(x_0,\dots,x_n)\in\blacksquare^{n+1}_\infty \textrm{ and }x_i=\pm 1\textrm{ for some }i=0,\dots,n\}
			\end{align*}
			is the unit sphere in $\R^{n+1}_\infty$.
		\end{itemize}

	\end{itemize}

	\nomenclature[02]{$\Sp^n$}{$n$-dimensional unit sphere with the geodesic metric}
	\nomenclature[03]{$\SpE^n$}{$n$-dimensional unit sphere with the Euclidean metric}
	\nomenclature[04]{$\Sp^n_\infty$}{$n$-dimensional unit sphere with the $\ell^\infty$ metric}
	\nomenclature[05]{$\square^n_\infty$}{$n$-dimensional cube with the $\ell^\infty$ metric}



	\subsection{Filtrations.}

	\begin{definition}[Filtrations] \label{def:pers-fams}
		A \emph{filtration} of a topological space $Z$ is a collection $U_\bullet = \big(U_r,\iota_{r,s} \big)_{r\leq s \in \R}$ where:
		\begin{itemize}

			\item for each $r\in \R$, $U_r$ is a subspace of $Z$, and

			\item for each $r\leq s$, $U_r\subseteq U_s$ and
			$\iota_{r,s}: U_r \hookrightarrow U_s$ is the canonical inclusion map. 
		\end{itemize}
	\end{definition}

	When there is no risk of confusion, we will simply say that $U_\bullet$ is a filtration without mentioning the topological space $Z$, with the understanding that $Z$ can be recovered as the colimit of $U_\bullet$.

	\medskip
	The following two constructions of filtrations will be considered in the rest of the paper.
	\begin{definition}[Sub-level set filtrations]\label{def:sub-level} 
		Suppose the pair $(Z,\beta_Z)$ is given where $Z$ is a topological space and $\beta_Z:Z\rightarrow\R$ is a real-valued map. Then, the family $\big(\beta_Z^{-1}((-\infty,r))\big)_{r\in \R}$ together with the canonical inclusions is a filtration (of $Z$). Filtrations of this type are often called \emph{sub-level set filtrations}.
	\end{definition}

	\begin{definition}[Vietoris-Rips filtration]\label{def:VR}
		Let $X$ be a metric space and $r>0$. The \emph{(open) Vietoris-Rips complex} $\vr(X;r)$ of $X$ at scale $r$ is the simplicial complex whose vertices are the points of $X$ and whose simplices are those finite subsets of $X$ with diameter strictly less then $r$. For $r\leq 0$ we define $\vr(X;r):=\emptyset$. Note that $\vr(X;r)\subseteq \vr(X;s)$ whenever $r\leq s$.




		\medskip
		Note that, at the level of the geometric realization, 
		{\small$$|\vr(X;r)|=\left\{\sum_{i=1}^n u_i x_i: n\in \mathbb{N},x_i\in X \text{s.t. $\diam(\{x_1,\ldots,x_n\})<r$ and $u_i\geq 0$ s.t. $\sum_{i=1}^n u_i = 1$}\right\}.$$}

		The above implies that there exists a canonical inclusion $\iota_{r,s}:\vert\vr(X;r)\vert\longhookrightarrow\vert\vr(X;s)\vert$ for  $r\leq s$. Also, $\vert\vr(X;r)\vert$ is a subspace of $\vert\vr(X;\infty)\vert$ for any $r\in\R$ where $\vert\vr(X;\infty)\vert$ is the colimit of $\big(\vert\vr(X;r)\vert,\iota_{r,s} \big)_{r\leq s}$.
		The family $\vert\vr(X;\bullet)\vert$ of nested geometric realizations is a filtration, called the \emph{(open) Vietoris-Rips filtration} of $X$.
	\end{definition}


	Note that the Vietoris-Rips filtration $\vert\vr(X;\bullet)\vert$ of $X$ is identical to the sub-level set filtration induced by the pair $\big(\vert\vr(X;\infty)\vert,\diam\big)$ where
	\begin{align*}
		\diam:\vert\vr(X;\infty)\vert&\longrightarrow\R\\
		\sum_{i=1}^nu_ix_i&\longmapsto\diam(\{x_1,x_2,\dots,x_n\}).
	\end{align*}


	Under suitable assumptions on $X$, Hausmann proved in \cite{hausmann1994vietoris} that $|\vr(X;r)|$ is homotopy equivalent to $X$ for small enough $r>0$.  In \Cref{thm:Z2hausmannsphere} we provide an optimal $\Z_2$-equivariant Hausmann-type theorem for spheres.

	\subsection{The Vietoris-Rips metric thickening of a metric space.}

	Let $X$ be a metric space and $\mathcal{P}(X)$ be the space of all Borel probability measures on $X$ with the weak topology \cite{dudley2018real}. Given a map $\varphi:X\to Y$ where $Y$ is a metric space,  the \emph{pushforward} $\varphi_\sharp\alpha$ of $\alpha\in\mathcal{P}(X)$ via $\varphi$ is the probability measure on $Y$ defined by $\varphi_\sharp\alpha(U):=\alpha\big(\varphi^{-1}(U)\big)$ for all Borel subsets $U\subset Y$.\nomenclature[06]{$\mathcal{P}(X)$}{Space of all Borel probability measures on $X$ with the weak topology.}

	For each $r> 0$ and $p\in[1,\infty]$, the \emph{$p$-Vietoris-Rips metric thickening} $\vrm_p(X;r)$ of $X$ at scale $r$ is the subspace of probability measures~$\mu$ on $X$ whose \emph{support} $\supp[\mu]$ is finite and has $p$-diameter smaller than $r$, equipped with the inherited weak topology. Precise definitions are as follows; see \cite{adamaszek2018metric,adams2024persistent} for other aspects.

	\begin{definition}[$p$-diameter]\label{def:pdiam}
		Let $(X,d_X)$ be a bounded metric space and $p\in[1,\infty]$. Then, the $p$-diameter map $\diam_p^X:\mathcal{P}(X)\rightarrow [0,\infty)$ is defined as follows: 
		$$\diam_p^X(\mu):=\begin{cases}\left(\iint_{X\times X}d_X^p(x,x')\,d\mu(x)\,d\mu(x')\right)^{\frac{1}{p}} &\text{if }p<\infty,\\
			\\\diam(\supp[\mu]) &\text{if }p=\infty.\end{cases}$$\nomenclature[08]{$\diam_p^X(\mu)$}{$p$-diameter of the probability measure $\mu \in \mathcal{P}(X)$}
	\end{definition}
	Note that if $1\leq p \leq q \leq \infty$, then we have $\diam_p(\mu)\leq\diam_q(\mu)$ for every $\mu\in\mathcal{P}(X)$.


	From now on, the set of all probability measures on $X$ with finite support will be denoted by $\Pfin(X)$. That is
	$$\Pfin(X):=\left\{\mu := \sum_{i=0}^n u_i\delta_{x_i}:u_i \geq 0, \sum_i u_i = 1, x_1,\ldots,x_n \in X, n\in\mathbb{N}\right\}$$
	where $\delta_x$ denotes the Dirac delta measure supported on the point $x\in X.$ We view $\Pfin(X)\subset \mathcal{P}(X)$ as a topological space by endowing it with the inherited (weak) topology.\nomenclature[07]{$\Pfin(X)$}{Subspace of $\mathcal{P}(X)$ with the finite support}

	\begin{definition}[$p$-Vietoris-Rips metric thickening filtrations]\label{def:VRm}
		Let $(X,d_X)$ be a metric space, $r> 0$, and $p\in[1,\infty]$. The \emph{$p$-Vietoris-Rips metric thickening} $\vrm_p(X;r)\subseteq \Pfin(X)$ of $X$ at scale $r$ is defined in the following way: 
		$$\vrm_p(X;r):=\left\{\mu \in\Pfin(X): \diam_p^X(\mu)<r\right\}.$$
		Furthermore, we regard $\vrm_p(X;r)$ as a topological space by endowing it with the weak topology inherited from $\mathcal{P}(X)$. For $r\leq 0$ we define $\vrm_p(X;r):=\emptyset$. Note that if $r\leq s$, then $\vrm_p(X;r)$ is contained in $\vrm_p(X;s)$. Hence, the family $\vrm_p(X;\bullet)$ is a filtration, called the \emph{$p$-Vietoris-Rips metric thickening filtration} of $X$. \nomenclature[09]{$\vrm_p(X)$}{$p$-Vietoris-Rips metric thickening of $X$}
	\end{definition}

	Observe that, for each $r>0$ we have that 
	$$\vrm_p(X;r):=\left(\diam_p^X\vert_{\Pfin(X)}\right)^{-1}\big((-\infty,r)\big).$$

	In other words, the filtration $\vrm_p(X;\bullet)$ can be regarded as a sub-level set filtration. This representation will be used in subsequent sections to express the stability of the assignment $X\mapsto \vrm_p(X;\bullet).$



	Note that one may metrize $\vrm_p(X;r)$ with the $q$-Wasserstein distance \cite[Theorem 7.3]{villani2021topics} for any $q\in[1,\infty]$. Furthermore, if $X$ is compact and $q<\infty$, the weak topology on $\vrm_p(X;r)$ and the metric topology induced by the $q$-Wasserstein distance coincide \cite{dudley2018real}. Hence, the superscript $\mathrm{m}$ denotes ``metric'', since the metric thickening $\vrm_p(X;r)$ can be seen as a metric space, whereas the simplicial complex $\vr(X;r)$ may not be metrizable if $X$ is not discrete \cite{adamaszek2018metric}.
	By identifying each point $x \in X$ with the Dirac measure~$\delta_{x}$, there is a natural isometric (i.e. distance preserving) embedding from $X$ into~$\vrm_p(X;r)$, via the injective map $x\mapsto \delta_x$.
	Furthermore, note that the underlying set of the metric thickening $\vrm_\infty(X;r)$ is equal to the underlying set of (the geometric realization of) the simplicial complex $\vr(X;r)$, although the topology of these two spaces may differ~\cite{adamaszek2018metric}.
	Also note that for each $r>0$ there is a distinguished map $\mathrm{id}_r:|\vr(X;r)|\to \vr^m_\infty(X;r)$ given by  $$\sum_{i=1}^n u_i x_i \mapsto \sum_{i=1}^n u_i\delta_{x_i}.$$
	Recently, in \cite{gillespie2024vietoris} Gillespie proved that $\mathrm{id}_r$ is for each $r>0$ a weak homotopy equivalence so that his results imply that the Vietoris-Rips metric thickening filtration is functorially \emph{weakly} homotopy equivalent to the Vietoris-Rips filtration of $X$; see \cite[Section 7]{gillespie2024vietoris}. 


	Under suitable assumptions on $X$, \cite{adamaszek2018metric} establishes a Hausmann-type result for the Vietoris-Rips metric thickening; $\vrm_\infty(X;r)$ is homotopy equivalent to $X$ for small enough $r>0$.  \Cref{thm:vrmHausmann-G},  extends this result to the $G$-equivariant setting. In \Cref{thm:Z2hausmannspherevrm} we specialize this to the case of spheres with $\Z_2$ actions with an optimal range for $r$.


	\subsection{Tight span of a metric space.}\label{sec:katetov}
	In his seminal paper \cite{gromov1983filling} Gromov introduced the notion of \emph{filling radius} $\filrad(M)$ of an orientable $m$-dimensional Riemannian manifold $M$ by considering its isometric embedding into $L^\infty(M)$ via the Kuratowski map  $\kappa:M\to L^\infty(M)$ given by $x\mapsto d_M(x,\cdot).$ Then, $\filrad(M)$ is defined as the infimal $\delta>0$ such that $\Hom_m(\iota_\delta;\Z)([M])=0$ where $\iota_\delta: M\to B_\delta(M; L^\infty(M))$ is the map induced by the inclusion $\kappa(M)\subseteq B_\delta(M,L^\infty(M))$ into the $\delta$-neighborhood of $\kappa(M)$ in $L^\infty(M)$.
	In this paper, we will employ a closely related but ``smaller" space.

	\begin{definition}[{Tight span \cite{dress1984trees,isbell1964six}}]\label{def:TS}
		The \emph{tight span} $\TS(X)$ of a compact metric space $(X,d_X)$ is defined as follows:
		$$\TS(X):=\{f\in\Delta(X):\text{if }g\in\Delta(X)\text{ and }g\leq f,\text{ then }g=f\,(\text{i.e., }f\text{ is minimal})\}$$

		where $\Delta(X):=\{f\in L^\infty(X):f(x)+f(x')\geq d_X(x,x')\text{ for all }x,x'\in X\}$. We endow $\TS(X)$ with the metric induced by $\ell^\infty$-norm.
	\end{definition}

	It is known that both $\TS(X)$ and $L^\infty(X)$ are metric spaces that satisfy the property called \emph{injectivity} \cite{dress1984trees,isbell1964six}, or equivalently \emph{hyperconvexity} \cite{aronszajn1956extension}. In particular, $\TS(X)$ is known to be the smallest injective metric space into which $X$ can be embedded, and it is unique up to isometry. Furthermore, the tubular neighborhoods of a given compact metric space $(X,d_X)$ inside of its tight span  are functorially homotopy equivalent to the Vietoris-Rips complexes of $X$.  More precisely, for $r>0$ let 
	$$B_r(X,\TS(X)):=\{f\in\TS(X):\Vert f-d_X(x,\cdot)\Vert<r\text{ for some }x\in X\}.$$
	Let \emph{tight span neighborhood filtration} of the compact metric space $X$ be the filtration
	$$B_\bullet(X,\TS(X)):=\big(B_r(X,\TS(X))\subseteq B_s(X,\TS(X))\big)_{r<s}$$
	with the provision that $B_r(X,\TS(X)):=\emptyset$ for $r\leq 0$. 

	\begin{theorem}[{\cite[Theorem 4.1]{lim2020vietoris}}]\label{thm:vr-neigh}
		There exist homotopy equivalences $\varphi_{r}:\vr_{2r}(X)\rightarrow B_r(X,\TS(X))$ for each $r>0$ such that for each $t>s>0$ the following diagram commutes up to homotopy:
		$$\begin{tikzcd}
			\vr_{2r}(X) \arrow[r, hook] \arrow[d, "\varphi_{r}"' , rightarrow]
			& \vr_{2s}(X) \arrow[d, "\varphi_{s}"]\\
			B_r(X, \TS(X)) \arrow[r,hook] & B_s(X, \TS(X))
		\end{tikzcd}$$
	\end{theorem}

