	\section{$G$-equivariant distances.}\label{sec:Gdistances}


	Throughout this paper, $G$ will  denote a group and $G_0$ will denote the trivial group. Given a group homomorphism $h:\widetilde{G}\to G$ and any $G$-group action $\alpha_X:G\times X \to X$ on a set $X$, by $h^\sharp\alpha_X:\widetilde{G}\times X\to X$ we will denote the \emph{pullback $\widetilde{G}$-action on X} defined through $$(h^\sharp\alpha_X)(\tilde{g},x):=\alpha_X(h(\tilde{g}),x)\,\,\text{for $\tilde{g}\in \widetilde{G}$ and $x\in X$.}$$

	\begin{definition}[$G$-set, $G$-topological space, $G$-function, $G$-map, $G$-metric space, and $G$-isometry]
		Suppose that a group $G$ is given. We define the following concepts:

		\begin{itemize}

			\item A pair $(X,\alpha_X)$ is a \emph{$G$-set} if $X$ is a set and $\alpha_X:G\times X\to X$ is a (left) $G$-group action on $X$.

			\item A pair $(X,\alpha_X)$ is a \emph{$G$-topological space} if $X$ is a topological space and $\alpha_X:G\times X\rightarrow X$ is a (left) $G$-group action on $X$ such that $\alpha_X(g,\cdot):X\rightarrow X$ is a homeomorphism for all $g\in G$.

			\item A \emph{$G$-function} (resp. \emph{$G$-map}) between two $G$-sets (resp. $G$-spaces) $X$ and $Y$ is any function (resp. map) $\varphi:X\rightarrow Y$ such that $$\varphi(\alpha_X(g,x)) = \alpha_Y(g,\varphi(x))$$ for all $x\in X$ and all $g\in G$. We will use the notation $\varphi:X\toG Y$ to denote that $\varphi$ is a $G$-function or a $G$-map.

			\item A triple $(X,d_X,\alpha_X)$ is said to be a \emph{$G$-metric space} if $(X,d_X)$ is a metric space and $\alpha_X:G\times X\rightarrow X$ is a (left) $G$-group action on $X$ such that $\alpha_X(g,\cdot):X\rightarrow X$ is an isometry for all $g\in G$. 

			\item If a given $G$-map $\varphi:X\toG Y$ between two $G$-metric spaces $X$ and $Y$ is  distance preserving, then $\varphi$ is called a \emph{$G$-isometric embedding}. Finally, if a given $G$-map $\varphi:X\toG Y$ is an isometry, then $\varphi$ is called a \emph{$G$-isometry}.
		\end{itemize}

	\end{definition}



	Note that all $G$-objects defined above boil down to their usual counterparts (sets, topological spaces, etc) whenever $G$ is the trivial group $G_0$. We will henceforth denote by $\mathcal{M}^G$ the collection of all compact $G$-metric spaces. Note that $G$-isometry is the natural notion of isomorphism on $\mathcal{M}^G$; see \Cref{thm:dghGmetric}.\nomenclature[10]{$\mathcal{M}^G$}{The collection of all compact $G$-metric spaces}



	\begin{example}\label{ex:spheres-Z2}
		Here are some simple examples of $G$-(sets, topological spaces, metric spaces):
		\begin{enumerate}
			\item Let $G$ be an arbitrary group and $X$ be an arbitrary (set, topological space, metric space). If we consider the $G$-group action $\alpha_X$ on $X$ defined as follows:
			$$\alpha_X(g,\cdot):=\mathrm{id}_X\,\,\text{for all}\,\,g\in G,$$
			then $X$ can be promoted to a  $G$-(set, topological space, metric space). This $\alpha_X$ is called the \emph{trivial} $G$-group action.

			\item Here are a few interesting choices of groups $G$ and group actions $\alpha_X$ on $n$-spheres $(X,d_X)=(\Sp^n,d_{\Sp^n})\text{ or }(\SpE^n,d_{\SpE^n})$ so that $(X,d_X,\alpha_X)$ becomes a $G$-metric space:
			\begin{enumerate}
				\item Let $G=\Z_2:=\{-1,1\}$ and $\alpha_X(-1,u):=-u$ for all $u\in X$ (the antipodal  \emph{involution}). 

				\item For odd $n=2k-1$, let $G=\Sp^1$ where we identify $\Sp^1$ with the real line modulo the equivalence relation $t\sim s$ iff $t-s = 2\pi m$ for some integer $m$. Also, consider the following $G$-group action,
				$$\alpha_X(\theta,\cdot):=T_\theta\,\,\text{for all}\,\,\theta\in\Sp^1$$
				where $T_\theta$ is a rotation given, in matrix form, by
				$$\begin{bmatrix}
					M(\theta) & 0 & 0 & 0 &\cdots & 0\\
					0 & M(\theta) & 0 & 0 &\cdots & 0\\
					0 & 0 & M(\theta) & 0 &\cdots & 0\\
					0 & 0 & 0 & M(\theta) &\cdots & 0\\
					\vdots & \vdots & \vdots & \vdots &\ddots & \vdots\\
					0 & 0 & 0 & 0 &\cdots & M(\theta)\\
				\end{bmatrix} \in \R^{2k\times 2k}$$
				where
				$$M(\theta):=\begin{bmatrix}
					\cos\theta & -\sin\theta\\
					\sin\theta & \cos\theta
				\end{bmatrix}.$$

			\end{enumerate}

			\item Let $G=\Z_2$, $(X,d_X)=(\square^n_\infty,\ell^\infty)\text{ or }(\Sp^n_\infty,\ell^\infty)$, and $\alpha_X(\pm1,u):=\pm u$ for all $u\in X$. Then, $(X,d_X,\alpha_X)$ becomes a $\Z_2$-metric space.
		\end{enumerate}
	\end{example}






	\subsection{The $G$-Gromov-Hausdorff distance.}\label{sec:sec:ggh}

	Recall that a \emph{correspondence} between two sets $X$ and $Y$ is any surjective relation $R\subset X\times Y$; see \cite[Chapter 7]{burago2022course}. 
	\begin{definition}[$G$-correspondence]
		For any two $G$-sets  $(X,\alpha_X)$ and $(Y,\alpha_Y)$, a correspondence $R$ between $X$ and $Y$ is said to be a \emph{$G$-correspondence} if
		$$(\alpha_X(g,x),\alpha_Y(g,y))\in R$$ for all $(x,y)\in R$ and all $g\in G$. The set of all $G$-correspondences between $X$ and $Y$ will be denoted by $\mathcal{R}_G(X,Y)$.
	\end{definition}


	\begin{remark}\label{rmk:R-order} Note that
		\begin{enumerate}

			\item if $G=G_0$ then $G$-correspondences are just (standard) correspondences.

			\item  for any $G$-sets $(X,\alpha_X)$, $(Y,\alpha_Y)$, a $G$-function $\varphi:X\toG Y$, and for any group homomorphism $h:\widetilde{G}\to G$ we have that $\varphi$ is also a $\widetilde{G}$-function between the $\widetilde{G}$-sets $(X,h^\sharp\alpha_X)$ and $(Y,h^\sharp\alpha_Y)$.

			\item for any $G$-sets $(X,\alpha_X)$ and $(Y,\alpha_Y)$, for any $G$-correspondence $R$ between them, and for any group homomorphism $h:\widetilde{G}\to G$ we have that $R$ is also a $\widetilde{G}$-correspondence between the $\widetilde{G}$-sets $(X,h^\sharp\alpha_X)$ and $(Y,h^\sharp\alpha_Y)$.    

			\item If $\varphi:X\toG Y$ and $\psi:Y\toG X$ are $G$-functions, then $R(\varphi,\psi):=\mathrm{graph}(\varphi)\cup \mathrm{graph}(\psi)$ is a $G$-correspondence.
		\end{enumerate}
	\end{remark}

	\begin{definition}[Distortion and codistortion]
		Suppose two bounded metric spaces $(X,d_X)$ and $(Y,d_Y)$ are given. Then, for any non-empty relation $R\subseteq X\times Y$, its distortion is defined by $$\dis(R):=\sup_{(x,y),(x',y')\in R}\big|d_X(x,x')-d_Y(y,y')\big|.$$
		Also, for any (not necessarily continuous) functions $\varphi:X\rightarrow Y$ and $\psi:Y\rightarrow X$, their distortion and codistortion are defined by
		\begin{align*}
			\dis(\varphi)&:=\sup_{x,x'\in X}\big|d_X(x,x')-d_Y(\varphi(x),\varphi(x'))\big|,\\
			\codis(\varphi,\psi)&:=\sup_{x\in X,y\in Y}\big|d_X(x,\psi(y))-d_Y(\varphi(x),y)\big|.
		\end{align*}
	\end{definition}
	Note that, with the above definitions,
	$$\dis(R(\varphi,\psi))=\max\{\dis(\varphi),\dis(\psi),\codis(\varphi,\psi)\}.$$

	\begin{definition}[The $G$-Gromov-Hausdorff distance]
		For any two $G$-metric spaces $X$ and $Y$, the $G$-Gromov-Hausdorff distance is defined as:
		$$\dgh^G(X,Y):=\frac{1}{2}\inf\{\dis(R):R\in\mathcal{R}_G(X,Y)\}.$$ \nomenclature[11]{$\dgh^G$}{$G$-Gromov-Hausdorff distance}
	\end{definition}


	As in items 2 and 3 of \Cref{ex:spheres-Z2}, consider the $\Z_2$-metric spaces $\Sp^n$, $\SpE^n$, $\Sp^n_\infty$, and $\square^n_\infty$ equipped with their canonical $\Z_2$-actions. In \Cref{sec:GdGHresults}, using the Main Theorem (see page~\pageref{page:main-theorem}), we establish lower bounds—and in some cases, exact values—for the $\Z_2$-equivariant Gromov–Hausdorff distances $\dgh^{\Z_2}(\Sp^m,\Sp^n)$, $\dgh^{\Z_2}(\SpE^m,\SpE^n)$, $\dgh^{\Z_2}(\Sp^m_\infty,\Sp^n_\infty)$, and $\dgh^{\Z_2}(\square^m_\infty,\square^n_\infty)$.


	\begin{remark}\label{rmk:G-dGH}
		We make several remarks:
		\begin{enumerate}
			\item Note that $\mathcal{R}_G(X,Y)$ is nonempty since $X\times Y$ always belongs to $\mathcal{R}_G(X,Y)$. Moreover, this implies that
			$$\dgh^G(X,Y)\leq\frac{1}{2}\max\{\diam(X),\diam(Y)\}$$
			for any two $G$-metric spaces $(X,d_X,\alpha_X)$ and $(Y,d_Y,\alpha_Y)$.

			\item By item 1 of \Cref{rmk:R-order}, if $G$ is the trivial group $G_0$, then $\dgh^G$ reduces to the standard Gromov-Hausdorff distance.

			\item Assume a group homomorphism $h:\widetilde{G}\to G$ is given.  Then, any two $G$-metric spaces, $(X,d_X,\alpha_X)$ and $(Y,d_Y,\alpha_Y)$ induce the $\widetilde{G}$-metric spaces $(X,d_X,h^\sharp\alpha_X)$ and $(Y,d_Y,h^\sharp\alpha_Y)$, respectively. Then, via  item 3 of \Cref{rmk:R-order} we see that 
			$$\dgh^G\big((X,d_X,\alpha_X),(Y,d_Y,\alpha_Y)\big)\geq \dgh^{\widetilde{G}}\big((X,d_X,h^\sharp\alpha_X),(Y,d_Y,h^\sharp\alpha_Y)\big).$$
			In particular, $\dgh^G$ is always an upper bound to the standard Gromov-Hausdorff distance.

			\item Note that \cite[Section 4.4.2]{polterovich2020topological} already considered the $\Z_2$-Gromov-Hausdorff distance. In \cite[Examples 4.4.14]{polterovich2020topological}, the authors employed the $\Z_2$-Gromov-Hausdorff distance in order to verify that some $\Z_2$-group actions cannot be induced by $\Z_4$-group actions.

			\item  Let $(X,d_X)$ be a metric space and let $\alpha_1$, $\alpha_2$ be two $G$-actions on $X$ and $R$ be a $G$-correspondence $R$ between $(X,d_X,\alpha_1)$ and $(X,d_X,\alpha_2)$. Then, it is easy to verify that 
			$$\dis(R)\geq\inf_{(x_1,x_2)\in X\times X}\sup_{g\in G}\big\vert d_X(x_1,\alpha_1(g,x_1))-d_X(x_2,\alpha_2(g,x_2))\big\vert.$$
			Hence, we have that
			\begin{align*}\dgh^G\big((X,d_X,\alpha_1),(X,d_X,\alpha_2)\big)&\geq\frac{1}{2}\inf_{(x_1,x_2)\in X\times X}\sup_{g\in G}\big\vert d_X(x_1,\alpha_1(g,x_1))-d_X(x_2,\alpha_2(g,x_2))\big\vert\\
				&\geq \frac{1}{2}\inf_{(x_1,x_2)\in X\times X}\big|e_1(x_1)-e_2(x_2)\big|,
			\end{align*}
			where $e_i:X\to \R_+$ is given by $x\mapsto\sup_{g\in G}d_X(x,\alpha_i(g,x))$, for $i=1,2$. For example, if $X=\Sp^n$, $G=\Z_2$, $\alpha_1$ is the canonical antipodal action and $\alpha_2$ is trivial, then $e_1 \equiv \pi$ whereas $e_2\equiv 0.$ This implies that

			$$\dgh\big((\Sp^n,d_{\Sp^n},\alpha_1),(\Sp^n,d_{\Sp^n},\alpha_2)\big)=\tfrac{\pi}{2}.$$
		\end{enumerate}
	\end{remark}

	\medskip
	The following proposition is a generalization of \cite[Theorem 2.1]{kalton1999distances} to the $G$-equivariant setting. See \Cref{app:proofs-GHG} for its proof.

	\begin{proposition}\label{prop:GGHeqmaps}
		For any $G$-metric spaces $X$ and $Y$ we have
		$$\dgh^G(X,Y)=\frac{1}{2}\inf\Big\{\dis(R(\varphi,\psi)):\varphi:X\to Y \text{and } \psi:Y\to X\text{ are }G\text{-functions}\Big\}.$$
	\end{proposition}
	The following proposition is a generalization of \cite[Theorem 7.3.25]{burago2022course} to the $G$-equivariant setting. See \Cref{app:proofs-GHG} for its proof.

	\begin{proposition}\label{prop:GGHeqembeds}
		For any $G$-metric spaces $X$ and $Y$ we have
		$$\dgh^G(X,Y)=\inf_{Z,f,g}d_{\mathrm{H}}^Z(f(X),g(Y))$$
		where the infimum is taken over all $G$-metric spaces $Z$ and $G$-isometric embeddings $f:X\hooktoG Z$ and $g:Y\hooktoG Z$. %\facundo{there's an alphaZ hidden here}
	\end{proposition}



	The following theorem is a generalization of \cite[Theorem 7.3.30]{burago2022course} to the $G$-equivariant setting. See \Cref{app:proofs-GHG} for its proof.

	\begin{theorem}\label{thm:dghGmetric}
		Assume that $G$ is a finite or countably infinite group. Then, the $G$-Gromov-Hausdorff distance $\dgh^G$ is a metric on the collection of $G$-isometry classes of compact $G$-metric spaces.
	\end{theorem}


	\subsection{The $G$-homotopy type distance.}\label{sec:dHT-G}

	We extend the notion of \emph{(persistent) homotopy type distance} from \cite{frosini2017persistent} to the setting of $G$-spaces. First we need the following definitions.

	\begin{definition}[$G$-homotopy equivalence]
		Suppose that two $G$-spaces $X$ and $Y$ are given. We say that two $G$-maps $\varphi:X\toG Y$ and $\varphi':X\toG Y$ are \emph{$G$-homotopic} if there is a map $H:X\times [0,1]\longrightarrow Y$ such that
		\begin{enumerate}
			\item $H(\cdot,0)=\varphi$
			\item $H(\cdot,1)=\varphi'$
			\item $H(\cdot,t):X\toG Y$ is a $G$-map for each $t\in [0,1]$.
		\end{enumerate}
		Any such map will be called a  \emph{$G$-homotopy} between $\varphi$ and $\varphi'$. We write $\varphi\Gsimeq\varphi'$ whenever $\varphi$ and $\varphi'$ are $G$-homotopic. Also, we say that $X$ and $Y$ are \emph{$G$-homotopy equivalent} if there are $G$-maps $\varphi:X\toG Y$ and $\psi:Y\toG X$ such that $\psi\circ\varphi$ and $\mathrm{id}_X$ are $G$-homotopic and $\varphi\circ\psi$ and $\mathrm{id}_Y$ are $G$-homotopic. Finally, if $X$ and the one-point space $\{\ast\}$ are $G$-homotopy equivalent, then $X$ is said to be \emph{$G$-contractible}.
	\end{definition}

	We now define the concept of filtered $G$-topological spaces.

	\begin{definition}[Filtered $G$-topological spaces]
		Given a $G$-topological space $(X,\alpha_X)$, a map $\beta_X:X\to \R$
		is said to be \emph{$G$-invariant} if $\beta_X(\alpha_X(g,x))=\beta_X(x)$ for all $x\in X$ and $g\in G$.

		Any triple $(X,\alpha_X,\beta_X)$ where $(X,\alpha_X)$ is a $G$-topological space and $\beta_X:X\to \R$ is a $G$-invariant map is said to be a \emph{filtered $G$-topological space}.
	\end{definition}


	The following proposition shows that a $G$-group action on a metric space $X$ can be transferred to a $G$-group action on $\Pfin(X)$, the space of all probability measures on $X$ with finite support. Furthermore, with this action, $\Pfin(X)$ becomes a filtered $G$-topological space.


	\begin{proposition}\label{prop:PfinGaction}
		Let $(X,d_X,\alpha_X)$ be a $G$-metric space. Then the function 
		\begin{align*}
			\alpha_{\Pfin(X)}:G\times \Pfin(X)&\longrightarrow \Pfin(X)\\
			\left(g,\mu\right)&\longmapsto  \alpha_X(g,\cdot)_\sharp \mu
		\end{align*}
		is a well defined $G$-group action\footnote{More explicitly, for $\mu=\sum_{i=1}^m u_i \delta_{x_i}$, $\alpha_{\Pfin(X)}(g,\mu) = \sum_{i=1}^mu_i\delta_{\alpha_X(g,x_i)}.$} on the topological space $\Pfin(X)$. Furthermore, for each $p\in [1,\infty]$, the map $\diam_p^X:\Pfin(X)\rightarrow\R$ is $G$-invariant so that $$\big(\Pfin(X),\alpha_{\Pfin(X)},\diam_p^X\big)$$ becomes a filtered $G$-topological space.
	\end{proposition}

