	\begin{example}\label{ex:GVRfilteredspace}
		For a  metric space $X$, recall that $\vert\vr(X;\infty)\vert$ is the colimit of $\big(\vert\vr(X;r)\vert,\iota_{r,s} \big)_{r\leq s}$ (see \Cref{def:VR}). Furthermore, if $(X,d_X,\alpha_X)$ is a $G$-metric space, then there exists a canonical $G$-group action $\alpha_{\vert\vr(X;\infty)\vert}$ on $\vert\vr(X;\infty)\vert$ defined as follows:
		$$\alpha_{\vert\vr(X;\infty)\vert}\left(g,\sum_{i=1}^nu_ix_i\right):=\sum_{i=1}^nu_i\alpha_X(g,x_i)\,\forall\, g\in G\text{ and }\sum_{i=1}^nu_ix_i\in\vert\vr(X;\infty)\vert.$$

		Finally, it is easy to verify that the map $\diam:\vert\vr(X;\infty)\vert\longrightarrow\R$ is $G$-invariant. Hence, the triple $$\big(\vert\vr(X;\infty)\vert,\alpha_{\vert\vr(X;\infty)\vert},\diam\big)$$ is a filtered $G$-topological space.
	\end{example}

	\begin{example}\label{ex:spheres-Z2-vrvrm} Recall  items (2) and (3) of \Cref{ex:spheres-Z2}. By \Cref{prop:PfinGaction} and \Cref{ex:GVRfilteredspace}, we have that $(\Pfin(X),\alpha_{\Pfin(X)},\diam_p^X)$ and $(\vert\vr(X;\infty)\vert,\alpha_{\vert\vr(X;\infty)\vert},\diam)$ are filtered $\Z_2$-topological spaces for $X=\Sp^n,\SpE^n,\Sp^n_\infty,$ and $\square^n_\infty$ with the canonical $\Z_2$-actions.
	\end{example}

	\begin{definition}[$(G,\delta)$-maps]
		Consider two filtered $G$-topological spaces $(X,\alpha_X,\beta_X)$ and $(Y,\alpha_Y,\beta_Y)$. For a given $\delta\geq 0$, we say that a $G$-map $\Phi:X\toG Y$ is a  \emph{$(G,\delta)$-map} if
		$$\beta_Y\circ\Phi(x)\leq \beta_X(x)+\delta\text{ for all } x\in X.$$
	\end{definition}

	\begin{remark}\label{rmk:G-delta-map}
		It is easy to verify that for any $(G,\delta)$-map $\Phi:X\rightarrow Y$ and any group homomorphism $h:\widetilde{G}\to G$, we have that $\Phi$ is also a $(\widetilde{G},\delta)$-map; cf. the item (2) of \Cref{rmk:R-order}.
	\end{remark}


	\begin{definition}[$(G,\delta)$-homotopies]
		Suppose two filtered $G$-topological spaces $(X,\alpha_X,\beta_X)$ and $(Y,\alpha_Y,\beta_Y)$ together with $(G,\delta)$-maps $\Phi_0,\Phi_1:X\rightarrow Y$ are given. Then, we say that $\Phi_0$ and $\Phi_1$ are \emph{$(G,\delta)$-homotopic}  if there exists a map $H:X\times [0,1]\rightarrow Y$ such that:
		\begin{enumerate}
			\item $H(\cdot,0)=\Phi_0$,

			\item $H(\cdot,1)=\Phi_1$, and

			\item $H(\cdot,t)$ is $(G,\delta)$-map for all $t\in [0,1]$.
		\end{enumerate}
		Any such $H$ map will be referred to as a \emph{$(G,\delta)$-homotopy}.
	\end{definition}

	\begin{definition}[The $G$-homotopy type distance]
		We say that two filtered $G$-topological spaces $(X,\alpha_X,\beta_X)$ and $(Y,\alpha_Y,\beta_Y)$ are \emph{$(G,\delta)$-homotopy equivalent} if there are $(G,\delta)$-maps $\Phi:X\rightarrow Y$ and $\Psi:Y\rightarrow X$ such that
		\begin{enumerate}
			\item $\Psi\circ\Phi$ is $(G,2\delta)$-homotopic  to $\mathrm{id}_X$, and

			\item $\Phi\circ\Psi$ is $(G,2\delta)$-homotopic  to $\mathrm{id}_Y$.
		\end{enumerate}

		Finally, we  define the \emph{$G$-homotopy type distance} between $(X,\alpha_X,\beta_X)$ and $(Y,\alpha_Y,\beta_Y)$ as follows:
		$$\dht^G(X,Y):=\inf\{\delta\geq 0:(X,\alpha_X,\beta_X)\text{ and }(Y,\alpha_Y,\beta_Y)\text{ are }(G,\delta)\text{-homotopy equivalent}\}.$$
		We set $\dht^G(X,Y)=\infty$ whenever $X$ and $Y$ fail to be $G$-homotopy equivalent. \nomenclature[12]{$\dht^G$}{$G$-homotopy type distance}
	\end{definition}

	The following proposition is a generalization of \cite[Proposition 2.10]{frosini2017persistent} to the $G$-equivariant setting.

	\begin{proposition}\label{prop:dHTG}
		$\dht^G$ is an extended pseudometric on the collection of all filtered $G$-topological spaces.
	\end{proposition}


	\begin{remark}\label{rmk:dhtGmonotone}
		Note that:
		\begin{enumerate}
			\item When $G=G_0$, $\dht^G$ boils down to the original homotopy type distance from \cite{frosini2017persistent}.

			\item If $h:\widetilde{G}\longrightarrow G$   is a group homomorphism, then any two filtered $G$-topological spaces $(X,\alpha_X,\beta_X)$ and $(Y,\alpha_Y,\beta_Y)$ induce the filtered $\widetilde{G}$-topological space $(X,h^\sharp\alpha_X,\beta_X)$ and $(Y,h^\sharp\alpha_Y,\beta_Y)$, respectively. Furthermore, by \Cref{rmk:G-delta-map}, for any  $(G,\delta)$-map $\Phi:X\rightarrow Y$ we have that $\Phi$ is also a $(\widetilde{G},\delta)$-map. Hence, if $(X,\alpha_X,\beta_X)$ and $(Y,\alpha_Y,\beta_Y)$ are $(G,\delta)$-interleaved, then they are also $(\widetilde{G},\delta)$-interleaved. Finally, we obtain that
			$$\dht^G\big((X,\alpha_X,\beta_X),(Y,\alpha_Y,\beta_Y)\big)\geq\dht^{\widetilde{G}}\big((X,h^\sharp\alpha_X,\beta_X),(Y,h^\sharp\alpha_Y,\beta_Y)\big).$$
		\end{enumerate}
	\end{remark}


