	\subsection{The $G$-interleaving distance.}\label{sec:sec:gdi}




	We first recall the concept of persistence module and associated notions; see \cite{carlsson2010zigzag,bubenik2014categorification}.

	\begin{definition}[Persistence module]
		A \emph{persistence module} $V_\bullet=(V_r,v_{r,s})_{r\leq s\in \R}$  is a family of $\mathbb{F}$-vector spaces $V_r$ for some given field $\mathbb{F}$ with linear maps $v_{r,s}:V_r \to V_s$ for each $r \leq s$ such that 
		\begin{itemize}
			\item $v_{r,r}=\mathrm{id}_{V_r}$,
			\item $v_{s,t}\circ v_{r,s}=v_{r,t}$ for each $r\leq s \leq t$.
		\end{itemize}
		In other words, a persistence module is a functor from the poset $(\R,\leq)$ to the category of vector spaces. The maps $v_{\bullet,\bullet}$ are referred to as the \emph{structure maps} of $V_\bullet$.
	\end{definition}

	By $0_\bullet$ we will denote the zero persistence module.


	\begin{definition}[Persistence morphism, isomorphism, and automorphism]
		Suppose two persistence modules $V_\bullet=(V_r,v_{r,s})_{r\leq s}$ and $W_\bullet=(W_r,w_{r,s})_{r\leq s}$ are given. Then, 
		\begin{itemize}
			\item A family of linear transformations $T_\bullet=(T_r:V_r\rightarrow W_r)_{r}$ is said to be a \emph{persistence morphism} from $V_\bullet$ to $W_\bullet$ if they satisfy $w_{r,s}\circ T_r=T_s\circ v_{r,s}$ for all $r\leq s$. 

			\item We define composition of persistence morphisms in the obvious way. 

			\item We say that a persistence morphism $T_\bullet:V_\bullet\rightarrow W_\bullet$ as a \emph{persistence isomorphism} if there exists an inverse persistence morphism $T'_\bullet:W_\bullet\rightarrow V_\bullet$ such that the composition $T'_\bullet\circ T_\bullet$ is equal to the identity persistence morphism on $V_\bullet$ and the composition $T_\bullet\circ T'_\bullet$ is equal to the identity persistence morphism on $W_\bullet$. 

			\item If there is a persistence isomorphism between $V_\bullet$ and $W_\bullet$, then we say that the two persistence modules $V_\bullet$ and $W_\bullet$ are \emph{isomorphic}.

			\item A persistence isomorphism between $V_\bullet$ and $V_\bullet$ itself is called a \emph{persistence automorphism} on $V_\bullet$. The \emph{group} of persistence automorphisms on $V_\bullet$ is denoted by $\gl(V_\bullet)$.

			\item Given a persistence module $V_\bullet=(V_r,v_{r,s})_{r\leq s}$ and $\delta\in \R$, by $V_{\bullet+\delta}$ we will denote the \emph{$\delta$-shifted} persistence module $(V_{r+\delta},v_{r+\delta,s+\delta})_{r\leq s}$.\footnote{In other words, if $V'_\bullet = V_{\bullet+\delta}$ then, $V'_r = V_{r+\delta}$ for all $r$ and $v'_{r,s}:=v_{r+\delta,s+\delta}$ for all $r\leq s$.} 
		\end{itemize}
	\end{definition}


	For an integer $k\geq 0$, applying the degree $k$ homology functor (with coefficients in a given field $\mathbb{F}$) to a filtration $U_\bullet = \big(U_r,\iota_{r,s} \big)_{r\leq s}$ produces the persistence module $\mathrm{H}_k(U_\bullet;\mathbb{F})$ where the structure maps are those induced by the inclusions $\big(\iota_{r,s}\big)_{r\leq s}$. Following the existing literature, we will use the term \emph{persistent homology} of a  filtration to refer to the persistence module obtained  upon applying the  homology functor to the given filtration. 
	\begin{center}\textbf{From now on, we will fix a field $\mathbb{F}$ and omit it from our notation.}
	\end{center}



	\begin{example}\label{ex:PMod-sub-level} 
		The sub-level set filtration from \Cref{def:sub-level} gives rise to the persistence module $\h_k(\beta_X\big((-\infty,\bullet)\big)$.
	\end{example}

	\begin{example}\label{ex:PMod-VRm}
		For any $p\in[1,\infty]$, the $p$-Vietoris-Rips metric thickening filtration $\vrm_p(X;\bullet)$ from \Cref{def:VRm} gives rise to the persistence module $\h_k(\vrm_p(X;\bullet))$.
	\end{example}

	\begin{example}\label{ex:PMod-VR}
		The Vietoris-Rips filtration from 
		\Cref{def:VR} gives rise to the persistence module $\h_k(|\vr(X;\bullet)|)$.
		%\facundo{also VRpm}
	\end{example}

	\paragraph{Introducing $G$-group actions.} $G$-equivariant formulations of persistence modules and the interleaving distance have been already defined and studied in \cite[Section 4.4]{polterovich2020topological}. Recall that a representation of a group $G$ is a pair $(V,\nu)$ where $V$ is a vector space and $\nu$ is a homomorphism from $G$ to $\gl(V)$. 

	\begin{definition}[{\cite[Definition 4.4.1]{polterovich2020topological}}]
		A \emph{$G$-persistence module} is a pair $(V_\bullet,\nu_\bullet)$ where $V_\bullet=(V_r,v_{r,s})_{r\leq s}$ is a persistence module and  $\nu_\bullet$  is  a homomorphism from $G$ to $\gl(V_\bullet)$. We will refer to $\nu_\bullet$ as a \emph{persistent representation of $G$ (on $V_\bullet$).}\nomenclature[13]{$(V_\bullet,\nu_\bullet)$}{$G$-persistence module}
	\end{definition}

	\begin{remark}
		Note that:
		\begin{enumerate}
			\item The defining condition of $\nu_\bullet$ means that for all $r\leq s$ and all $g\in G$ the following diagram commutes:
			$$\begin{tikzcd}
				V_r\ar[r,"v_{r,s}"]\ar[loop, ->, in=170,out=100,looseness=5,"\nu_r(g)"']&[10pt] V_s \ar[loop, ->, in=10,out=80,looseness=5,"\nu_s(g)"] 
			\end{tikzcd}$$

			\item When $G=G_0$, $G$-persistence modules boil down to  (standard) persistence modules.
		\end{enumerate}
	\end{remark}





	\begin{example}
		Suppose a filtered $G$-topological space $(Z,\alpha_Z,\beta_Z)$ is given.  Then, the persistence module from \Cref{ex:PMod-sub-level} can be promoted to a $G$-persistence module through the following persistent representation of $G$: $$\nu_\bullet:G\to \gl\left(\h_k\big(\beta_Z^{-1}(-\infty,\bullet)\big) \right)$$ such that for each $g\in G$ and $r\in \R$, 
		$$\nu_r(g):=\h_k\Big({\beta_Z^{-1}\big((-\infty,r)\big)}\stackrel{\alpha_Z(g,\cdot)}{\xrightarrow{\hspace{1cm}}} {\beta_Z^{-1}\big((-\infty,r)\big)}\Big).$$

		Note that this is well-defined since $\beta_Z$ is $G$-invariant. 

		\begin{quote}
			\textbf{For conciseness, whenever clear from context, we will omit specifying the associated persistence representation of the module $\h_k\big(\beta_Z^{-1}(-\infty,\bullet)\big)$.}
		\end{quote}

	\end{example}

	In particular, when $X$ is a $G$-metric space, the filtered $G$-topological spaces $$\text{$(\Pfin(X),\alpha_{\Pfin(X)},\diam_p^X)$ and $(\vert\vr(X;\infty)\vert,\alpha_{\vert\vr(X;\infty)\vert},\diam)$}$$ (see \Cref{prop:PfinGaction} and \Cref{ex:GVRfilteredspace})  induce $G$-persistence modules. 

	\begin{example}\label{ex:GvrmPH}
		Assume that a $G$-metric space $(X,d_X,\alpha_X)$ is given. Then, for any $p\in [1,\infty]$, the persistence module from \Cref{ex:PMod-VRm} can be promoted to a $G$-persistence module via the following persistence representation of $G$:
		$$\nu_\bullet:G\to \gl\big(\h_k(\vrm_p(X;\bullet))\big)$$
		such that for each $g\in G$ and $r\in \R$, 

		$$\nu_r(g):=\h_k\Big(\vrm_p(X;r) \stackrel{\alpha_{\Pfin(X)}(g,\cdot)}{\xrightarrow{\hspace{1cm}}} \vrm_p(X;r)\Big).$$

		See \Cref{prop:PfinGaction} for the precise definition of $\alpha_{\Pfin(X)}$.
	\end{example}

	\begin{example}\label{ex:GvrPH}
		Assume that a $G$-metric space $(X,d_X,\alpha_X)$ is given. Then, the persistence module from \Cref{ex:PMod-VR} can be promoted to a $G$-persistence module via the following persistence representation of $G$:
		$$\nu_\bullet:G\to \gl\left(\h_k\big(|\vr(X;\bullet)|\big) \right)$$
		such that for each $g\in G$ and $r\in \R$, 

		$$\nu_r(g):=\h_k\Big(|\vr(X;r)| \stackrel{\alpha_{\vert\vr(X;\infty)\vert}(g,\cdot)}{\xrightarrow{\hspace{1cm}}} |\vr(X;r)|\Big).$$

		See \Cref{ex:GVRfilteredspace} for the precise definition of $\alpha_{\vert\vr(X;\infty)\vert}$.

	\end{example}
	\begin{example}\label{ex:spheres-Z2-vrvrmPH}
		Recall  items (2) and (3) of \Cref{ex:spheres-Z2}. By \Cref{ex:GvrmPH,ex:GvrPH}, we have that $\h_k(\vrm_p(X;\bullet))$ and $\h_k(\vert\vr(X;\bullet)\vert)$ are $\Z_2$-persistence modules for $X=\Sp^n,\SpE^n,\Sp^n_\infty,$ and $\square^n_\infty$ with the canonical $\Z_2$-actions.
	\end{example}

	\begin{definition}[$G$-persistence morphism]
		Let $(V_\bullet,\nu_\bullet)$ and $(W_\bullet,\omega_\bullet)$ be two $G$-persistence modules. We say that a persistence morphism $T_\bullet:V_\bullet\rightarrow W_\bullet$ is a \emph{$G$-persistence morphism} if the following diagram commutes for all $r\leq s\in \R$ and all $g\in G$:

		$$\begin{tikzcd}
			V_r\ar[r,"v_{r,s}"]\ar[loop, ->, in=170,out=100,looseness=5,"\nu_r(g)"']\ar[dd,"T_r"']  &[10pt] V_s \ar[loop, ->, in=10,out=80,looseness=5,"\nu_s(g)"]\ar[dd,"T_s"] \\
			\\
			W_r\ar[r,"w_{r,s}"]\ar[loop, ->, in=-170,out=-100,looseness=5,"\omega_r(g)"] &[10pt] W_s \ar[loop, ->, in=-10,out=-80,looseness=5,"\omega_s(g)"'] 
		\end{tikzcd}$$
	\end{definition}

	\begin{definition}[{$(G,\delta)$-interleavings and  $G$-interleaving distance \cite[Definition 4.4.7]{polterovich2020topological}}]\label{def:gint-dist}
		Two $G$-persistence modules $(V_\bullet,\nu_\bullet)$ and $(W_\bullet,\omega_\bullet)$ are said to be \emph{$(G,\delta)$-interleaved} for some $\delta\geq 0$ if there are $G$-persistence morphisms  $T_\bullet:V_\bullet \to W_{\bullet+\delta}$ and $T'_\bullet: W_\bullet \to V_{\bullet+\delta}$ such that the following two diagrams commute for every $r\in \R$:


		$$\begin{tikzcd}
			V_r\ar[rr,"v_{r,r+2\delta}"]\ar[ddr,"T_r"']  &&  V_{r+2\delta}  \\
			\\
			&W_{r+\delta}\ar[uur,"T_{r+\delta}'"'] &  
		\end{tikzcd}
		\begin{tikzcd}
			&V_{r+\delta} \ar[ddr,"T_{r+\delta}"]&
			\\ 
			\\
			W_r\ar[rr,"w_{r,r+2\delta}"]\ar[uur,"T_r'"]  &&  W_{r+2\delta}
		\end{tikzcd}
		$$
		The pair $(T_\bullet,T_\bullet')$ is said to be a \emph{$(G,\delta)$-interleaving} between $(V_\bullet,\nu_\bullet)$ and  $(W_\bullet,\nu_\omega)$. 
		The \emph{$G$-interleaving distance} between $(V_\bullet,\nu_\bullet)$ and $(W_\bullet,\omega_\bullet)$ is defined as $$\di^G\big((V_\bullet,\nu_\bullet),(W_\bullet,\omega_\bullet)\big):=\inf\{\delta\geq 0:\,\mbox{$(V_\bullet,\nu_\bullet)$ and $(W_\bullet,\omega_\bullet)$ are $(G,\delta)$-interleaved}\}.$$
		\nomenclature[14]{$\di^G$}{$G$-interleaving distance}
	\end{definition}

	The following proposition is a generalization of \cite[Proposition 5.3]{chazal2016structure} to the $G$-equivariant setting.\footnote{Since \cite{polterovich2020topological} does not state or give a proof of this fact, we provide one in \Cref{app:proofs-GHG}.}

	\begin{proposition}\label{prop:diGpsdmtr}
		$\di^G$ is an extended pseudometric on the collection of $G$-persistence modules.
	\end{proposition}





	\begin{remark}\label{rmk:diGmonotone}
		Note that:
		\begin{enumerate}
			\item when $G=G_0$, $\di^G$ boils down to the standard interleaving distance from \cite[Definition 4.2]{chazal2009proximity}.

			\item  Assume that a group homomorphism $h:\widetilde{G}\to G$ is given. Then, any $G$-persistence module $(V_\bullet,\nu_\bullet)$ induces the $\widetilde{G}$-persistence module $(V_\bullet,h^\sharp\nu_\bullet)$ where $h^\sharp\nu_\bullet:=\nu_\bullet\circ h$. Also, any $G$-persistence morphism $T_\bullet:(V_\bullet,\nu_\bullet)\rightarrow (W_\bullet,\omega_\bullet)$ induces the $\widetilde{G}$-persistence morphism $T_\bullet:(V_\bullet,h^\sharp\nu_\bullet)\rightarrow (W_\bullet,h^\sharp\omega_\bullet)$. Hence, if $(V_\bullet,\nu_\bullet)$ and $(W_\bullet,\omega_\bullet)$ are $(G,\delta)$-interleaved, then they are also $(\widetilde{G},\delta)$-interleaved and in particular 
			$$\di^G\big((V_\bullet,\nu_\bullet),(W_\bullet,\omega_\bullet)\big)\geq\di^{\widetilde{G}}\big((V_\bullet,h^\sharp\nu_\bullet),(W_\bullet,h^\sharp\omega_\bullet)\big).$$

		\end{enumerate}
	\end{remark}






