	\begin{lemma}[{\cite[Propositions 6.1 and 6.2]{adamaszek2018metric}}] \label{lemma:homeo}
		The canonical identity map \begin{align*}\mathrm{id}:\vert\vr(X;\eta)\vert&\to\vrm_\infty(X;\eta)  \\\sum_{i=0}^n u_ix_i&\mapsto\sum_{i=0}^n u_i\delta_{x_i}
		\end{align*}
		is continuous. Furthermore, if $X$ is a finite metric space, then $\mathrm{id}$ is a homeomorphism.
	\end{lemma}

	\begin{lemma}\label{lemma:Ginvdeltanetexst}
		Let $G$ be a finite group and $X$ be a totally bounded $G$-metric space. Then, for any $\delta>0$, there exists a finite $G$-invariant $\delta$-net $U$ of $X$.\footnote{I.e., $\alpha_X(g,x)\in U$ for every $g\in G$ and $u\in U$.} 
	\end{lemma}
	\begin{proof}
		Since $X$ is totally bounded, there exists a finite $\delta$-net $\widetilde{U}\subseteq X$. Then, one can choose $U:=\{\alpha_X(g,x):g\in G\text{ and }x\in U\}$.
	\end{proof}


