	In \cite[Corollary 5.10]{adams2024persistent}, the authors showed that $\di\big(\h_k(\vrm_\infty(X;\bullet)),\h_k(\vert\vr(X;\bullet)\vert)\big)=0$ for any totally bounded metric space $X$ and $k\geq 0$. The following proposition is a generalization of that result to the $G$-equivariant setting.

	\begin{proposition}\label{prop:vrvrmdIGsame}
		Let $G$ be a finite group. Then, for any totally bounded $G$-metric space $X$ and  $k\geq 0$, we have that
		$$\di^G\big(\h_k(\vrm_\infty(X;\bullet)),\h_k(\vert\vr(X;\bullet)\vert)\big)=0.$$
	\end{proposition}

