	\begin{corollary}\label{cor:vrvrmdIGsame}
		Let $G$ be a finite group. Then, for any two totally bounded $G$-metric spaces $X$ and $Y$, we have that
		$$\di^G\big(\h_k(\vrm_\infty(X;\bullet)),\h_k(\vrm_\infty(Y;\bullet))\big)=\di^G\big(\h_k(\vert\vr(X;\bullet)\vert),\h_k(\vert\vr(Y;\bullet)\vert)\big).$$
