	\subsubsection{An exact calculation for the case of spheres.} 



	Fix arbitrary positive integers $n> m>0$. By \cite[Theorem 4.1 and Corollary 9.39]{lim2024vietoris}, we know that $$\di\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)=\frac{\zeta_m}{2}.$$
	Given the item (2) of \Cref{rmk:diGmonotone}, one  wonders whether the $\Z_2$-interleaving distance might be \emph{strictly better} than the standard one in the case at hand, i.e. whether
	$$\di^{\Z_2}\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)>\di\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)=\frac{\zeta_m}{2}$$ holds when the persistence modules appearing in the LHS are endowed with the canonical $\Z_2$-persistent representation induced by the canonical $\Z_2$-action (i.e. the antipodal involution) on spheres with the geodesic metric; see the item (2) of \Cref{ex:spheres-Z2}. This is \emph{not} the case. Furthermore, the following proposition shows that  \emph{no group $G$ acting by isometries on the spheres has an impact on  the value of the resulting $G$-interleaving distance} $\di^{G}\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)$.


	\begin{proposition}\label{prop:Gdnmatter}
		Let $n>m>0$ be positive integers and $G$ be a group. Consider any $G$-group actions on $\Sp^n$ and $\Sp^m$ by isometries. Then, we have that
		$$\di^{G}\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)=\di\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)=\frac{\zeta_m}{2}.$$
	\end{proposition}

	The following example shows that there are $G$-spaces $X$ and $Y$ such that 
	$$\di^{G}\big(\h_k(\vert\vr(X;\bullet)\vert),\h_k(\vert\vr(Y;\bullet)\vert)\big) > \di\big(\h_k(\vert\vr(X;\bullet)\vert),\h_k(\vert\vr(Y;\bullet)\vert)\big).$$

	\begin{figure}
		\begin{center}
			\includegraphics[width = 0.8\linewidth]{ex-dI-G.pdf}
		\end{center}
		\caption{Description of $(X,d_X)$ from \Cref{ex:dIGdIstrictineq}.}
		\label{fig:dIGdIstrictexampleX}
	\end{figure}

	\begin{example}\label{ex:dIGdIstrictineq}
		Let $(X,d_X)$ and $(Y,d_Y)$ be the following two six-points metric spaces: \begin{itemize}
			\item $X:=\{a_1,a_2,a_3,b_1,b_2,b_3\}$ where $d_X$ is the shortest path distance on the graph having the points in $X$ as vertices and $\{(a_1,a_2),(a_2,a_3),(a_3,a_1),(b_1,b_2),(b_2,b_3),(b_3,b_1),(a_1,b_1)\}$ as the set of edges; see \Cref{fig:dIGdIstrictexampleX}. 
			\item $Y:=\{u_1,u_2,u_3,u_4,v_1,v_2\}$ and $d_Y$ is the discrete metric: $d_Y(y,y'):=\begin{cases}1&\text{if }y\neq y'\\ 0&\text{if }y= y'.\end{cases}$
		\end{itemize}

		Let $V_\bullet:=\h_0(\vert\vr(X;\bullet)\vert)$ and $W_\bullet:=\h_0(\vert\vr(Y;\bullet)\vert)$ be the degree-$0$ Vietoris-Rips persistent homology of $X$ and $Y$ (see \Cref{ex:PMod-VR}). Then, it is easy to verify that, as standard persistence modules, $V_\bullet$  and $W_\bullet$ are isomorphic so that $\di(V_\bullet,W_\bullet)=0$.


		Next, we will consider $\Z_2$-persistence representations for $V_\bullet$ and $W_\bullet$. We will view $\Z_2$ as $\{-1,1\}$ with  multiplication as the binary operation. Let $\alpha_X:\Z_2\times X\rightarrow X$ be s.t. $\alpha_X(-1,a_i):=b_i$ (equivalently, $\alpha_X(-1,b_i):=a_i$) for $i=1,2,3$. Then, $(X,d_X,\alpha_X)$ is a $\Z_2$-metric space. Furthermore, $\alpha_X$ naturally induces a persistent representation $\nu_\bullet:\Z_2\rightarrow\gl(V_\bullet)$ (see \Cref{ex:GvrPH}) so that $(V_\bullet,\nu_\bullet)$ is a $\Z_2$-persistence module. As for $W_\bullet$, we will first equip  $Y$ with a $\Z_4$-action. We will view $\Z_4$ as $\{\cx,-1,-\cx,1\}$, where $\cx=\sqrt{-1}$, with  multiplication as the binary group operation. Let $\alpha_Y:\Z_4\times Y\rightarrow Y$ be s.t. $\alpha_Y(\cx,u_1):=u_2$, $\alpha_Y(\cx,u_2):=u_3$, $\alpha_Y(\cx,u_3):=u_4$, $\alpha_Y(\cx,u_4):=u_1$, $\alpha_Y(\cx,v_1):=v_2$, and $\alpha_Y(\cx,v_2):=v_1$. Then, $(Y,d_Y,\alpha_Y)$ is a $\Z_4$-metric space. Also, $\alpha_Y$ naturally induces a  persistent representation $\omega_\bullet:\Z_4\rightarrow\gl(W_\bullet)$ so that $(W_\bullet,\omega_\bullet)$ is a $\Z_4$-persistence module. Furthermore, we define a $\Z_2$-persistence representation $\omega_\bullet^{\otimes 2}:\Z_2\rightarrow\gl(W_\bullet)$ s.t. $\omega_\bullet^{\otimes 2}(-1):=\omega_\bullet(-1)$. Then, $(W_\bullet,\omega_\bullet^{\otimes 2})$ is a $\Z_2$-persistence module.


		By \cite[Theorem 4.4.11]{polterovich2020topological}, we have that
		$$\di^{\Z_2}\big((V_\bullet,\nu_\bullet),(W_\bullet,\omega_\bullet^{\otimes 2})\big)\geq m_\mathrm{odd}(L^{V_\bullet})$$
		where
		\begin{itemize}
			\item $L^{V_\bullet}$ is the persistence module s.t. $(L^{V_\bullet})_r:=\mathrm{ker}(\nu_r(-1)-(-1)\cdot\mathrm{id}_{V_r})$ (see \cite[Example 4.4.5 and pg.43]{polterovich2020topological}) for every $r\in\R$. i.e., $(L^{V_\bullet})_r$ is the eigenspace of $\nu_r(-1)$ associated to the eigenvalue $-1$ for each $r\in\R$;

			\item $m_\mathrm{odd}(L^{V_\bullet})$ is the maximum over ``multiplicity functions" $m_j(L^{V_\bullet})$ for all odd $j$ (see \cite[Definition 4.3.2]{polterovich2020topological}).
		\end{itemize}
		Then, it is easy to verify that
		$$(L^{V_\bullet})_r=\begin{cases}\mathrm{span}(\{a_1-b_1,a_2-b_2,a_3-b_3\})&\text{if }r\in (0,1] \\ 0 &\text{otherwise}\end{cases}$$
		so that $m_\mathrm{odd}(L^{V_\bullet})=m_3(L^{V_\bullet})=\frac{1}{4}$. In conclusion, we have that
		$$\di^{\Z_2}\big((V_\bullet,\nu_\bullet),(W_\bullet,\omega_\bullet^{\otimes 2})\big)\geq\frac{1}{4}>0=\di(V_\bullet,W_\bullet).$$
	\end{example}


