	\section{$G$-equivariant precompactness, rigidity and finiteness.}\label{sec:finiteness}



	In a series of works including \cite{weinstein1967homotopy,cheeger1970finiteness,grove1988bounding,yamaguchi1988homotopy,peter1990finiteness,grove1990geometric} it was shown that suitably constrained families of metric spaces admit only finitely many equivalence classes—whether up to homeomorphism, diffeomorphism, or homotopy equivalence. A number of these finiteness results typically combine precompactness in the Gromov–Hausdorff topology with appropriate rigidity theorems. In this section, building on results from earlier sections, we establish  finiteness results for the $G$-homotopy equivalence.

	\medskip
	Let $G$ be an arbitrary group. Recall that $\mathcal{M}^G$  denotes the collection of all compact $G$-metric spaces. 

	\begin{definition}[The class $\mathcal{H}^G$]\label{def:HG}
		Let $\mathcal{H}^G\subseteq\mathcal{M}^G$ be the subcollection of all compact $G$-metric spaces $(X,d_X,\alpha_X)$ that satisfy the following condition: there exists $r^G(X)>0$ such that:

		\begin{enumerate}
			\item For each $\varepsilon\in(0,r^G(X)]$, there exists a $G$-homotopy equivalence $p_\varepsilon^X:\vrm_\infty(X;\varepsilon)\toG X$ that admits as a $G$-homotopy inverse the canonical isometric embedding \begin{align*}j_\varepsilon^X:X&\hooktoG \vrm_\infty(X;\varepsilon)\\
				x&\longmapsto \delta_x.\end{align*}

			\item The following diagram commutes up to $G$-homotopy, for any $0<\varepsilon\leq\varepsilon'\leq r^G(X)$:
			$$\begin{tikzcd}
				\vrm_\infty(X;\varepsilon) \arrow[r, hook, "\iota_{\varepsilon,\varepsilon'}^X"] \arrow[dr, "p_\varepsilon^X"]
				& \vrm_\infty(X;\varepsilon') \arrow[d, "p_{\varepsilon'}^X"]\\ & X
			\end{tikzcd}$$
			where $\iota_{\varepsilon,\varepsilon'}^X:\vrm_\infty(X;\varepsilon)\hooktoG \vrm_\infty(X;\varepsilon')$ denotes the canonical inclusion.\footnote{I.e. the condition requires that $p_{\varepsilon'}^X\circ\iota_{\varepsilon,\varepsilon'}^X$ and $p_{\varepsilon}^X$ be $G$-homotopic.}
		\end{enumerate}
		\nomenclature[15]{$\mathcal{H}^G$}{The class $\mathcal{H}^G$ of compact $G$-metric spaces}
	\end{definition}



	\subsection{Complete $G$-Riemannian manifolds are in $\mathcal{H}^G$.}
	In \cite[Theorem 4.2]{adamaszek2018metric}, the authors proved a Hausmann-type of theorem for Vietoris-Rips metric thickenings via the notion of \emph{Karcher mean} or \emph{Riemannian center of mass} \cite{karcher1977riemannian}. Using the fact that Karcher means are actually well behaved under isometries (which introduces equivariance)---as pointed out in \cite[Section 1.4.1]{karcher1977riemannian}---in \Cref{thm:vrmHausmann-G} below we obtain a generalization of  \cite[Theorem 4.2]{adamaszek2018metric} to the $G$-equivariant setting.

	More precisely, the Riemannian center of mass map $p_\varepsilon^M$ is defined as follows: fix an arbitrary $\mu\in\vrm_\infty(M;\varepsilon)$. Then, $\supp[\mu]$ is a finite subset of $M$ contained in a ball of radius $\varepsilon\leq r(M)$ (see \Cref{thm:vrmHausmann-G} for the definition of $r(M)$). Hence, by \cite[Theorem 1.2 and Definition 1.3]{karcher1977riemannian}, the map $x\longmapsto\frac{1}{2}\int_{M}d_M(x,y)^2\,d\mu(y)$ has a unique minimizer, where $d_M$ is the geodesic metric. Then,  $p_\varepsilon^M(\mu)$ is defined as this unique minimizer.


	Assume that a group $G$ and a complete Riemannian manifold $M$ are given. We say that $(M,\alpha_M)$ is a \emph{complete $G$-Riemannian manifold} if $\alpha_M:G\times M\longrightarrow M$ is a $G$-group action such that $(M,d_M,\alpha_M)$ becomes a $G$-metric space.\footnote{That is, $\alpha_M$ acts by isometries on $(M,d_M)$.}

	\begin{theorem}[$G$-equivariant Hausmann theorem for $\vrm_\infty$]\label{thm:vrmHausmann-G} Let $G$ be a group and $M$ be a complete $G$-Riemannian manifold. Let  $$r(M):=\min\Big\{\mathrm{Conv}(M),\tfrac{1}{4}\pi\Delta_M^{-1/2}\Big\},$$ where $\mathrm{Conv}(M)$ is the convexity radius of $M$ and $\Delta_M>0$ is a uniform upper bound on the sectional curvature of $M$. Then, for each $\varepsilon\in(0,r(M)]$, the Riemannian center of mass (or Karcher mean) map $p_\varepsilon^M:\vrm_\infty(M;\varepsilon)\toG M$ is a $G$-homotopy equivalence that has the canonical isometric embedding $j_\varepsilon^M:M\hooktoG \vrm_\infty(M;\varepsilon)$ as a $G$-homotopy inverse.
	\end{theorem}
	Note that, thanks to \Cref{thm:vrmHausmann-G}, every complete $G$-Riemannian manifold $M$ satisfies the first condition in \Cref{def:HG} with $r^G(M) = r(M)$.  Additionally, the second condition in \Cref{def:HG} is also  satisfied since, obviously, $p_{\varepsilon'}^M\circ\iota_{\varepsilon,\varepsilon'}^M=p_{\varepsilon}^M$.  We immediately obtain:
	\begin{corollary}
		\label{prop:RMnice}
		If $M$ is a complete $G$-Riemannian manifold, then $M$ belongs to $\mathcal{H}^G$.
	\end{corollary}
	\begin{proof}[\textbf{Proof of \Cref{thm:vrmHausmann-G}}]
		As \cite[Theorem 4.2]{adamaszek2018metric} explains, for each $\varepsilon\in(0,r(M)]$, the Riemannian center of mass map $p_\varepsilon^M:\vrm_\infty(M;\varepsilon)\longrightarrow M$ is a (standard) homotopy equivalence that has the canonical isometric embedding $j_\varepsilon^M:M\longhookrightarrow \vrm_\infty(M;\varepsilon)$ as a homotopy inverse (which is certainly a $G$-map). Since $p_\varepsilon^M\circ j^M_\varepsilon = \mathrm{id}_M$ one only needs to verify that the identity on $\vrm_\infty(M;\varepsilon)$ and $j_\varepsilon^M\circ p^M_\varepsilon$ are homotopic. For this, the authors consider the homotopy $H:\vrm_\infty(M;\varepsilon)\times[0,1]\to \vrm_\infty(M;\varepsilon)$ given, for $\mu\in\vrm_\infty(M;\varepsilon)$,  by the \emph{straight-line} homotopy $$H(\mu,t) := (1-t)\mu + t\,j^M_\varepsilon\circ p^M_\varepsilon(\mu).$$
		That $H$ is well defined and continuous is verified in \cite{adamaszek2018metric}. Given these facts, in order to obtain our claim that $p_\varepsilon^M:\vrm_\infty(M;\varepsilon)\to M$ is a $G$-homotopy equivalence with  $j^M_\varepsilon$ as a $G$-homotopy inverse,  it suffices to prove that:
		\begin{itemize}
			\item[(1)] $p^M_\varepsilon$ is $G$-equivariant.
			\item[(2)] $t\mapsto H(\cdot,t)$ is a $G$-map for each $t\in[0,1].$
		\end{itemize}



		We first prove (1) which is equivalent to the condition that $\alpha_M(g,p_M^\varepsilon(\mu)) = p_\varepsilon^M(\alpha_M(g,\cdot)_\sharp\mu)$ for all $\mu\in \vrm_\infty(M;\varepsilon)$ and $g\in G$.  Observe that, for each $g\in G$ and $\mu\in\vrm_\infty(M;\varepsilon)$ we have that 
		\begin{align*}\int_{M}d_M^2(x,y)\,d\big(\alpha_M(g,\cdot)_\sharp\mu\big)(y)=\int_{M}d_M^2(x,\alpha_M(g,y))\,d\mu(y)
			= \int_M d_M^2(\alpha_M(g^{-1},x),y)\,d\mu(y).\end{align*}
		Since both the support of $\mu$ and (therefore) that of $\alpha_{M}(g,\cdot)_\sharp \mu$ are contained in a ball of radius $\varepsilon\leq r(M)$, both measures admit a unique Riemannian center of mass. This, together with the equalities above then imply that 
		$p_\varepsilon^M(\alpha_{M}(g,\cdot)_\sharp \mu)=\alpha_M(g,p_\varepsilon^M(\mu))$, as we wanted.

		Now,  (2) it equivalent to proving that for all $\mu\in \vrm_\infty(M;\varepsilon)$ and $g\in G$ we have that 
		\begin{equation}\label{eq:H}
			\alpha_M(g,\cdot)_\sharp H(\mu,t) = H\big(\alpha_M(g,\cdot)_\sharp\mu,t\big)\,\,\mbox{for all $t\in[0,1]$}.
		\end{equation}
		Starting from the LHS, we have
		\begin{align*}
			\alpha_M(g,\cdot)_\sharp H(\mu,t) &= (1-t)\alpha_M(g,\cdot)_\sharp \mu + t \,\alpha_M(g,\cdot)_\sharp j^M_\varepsilon \circ p_\varepsilon^M(\mu) \nonumber\\
			&= (1-t)\alpha_M(g,\cdot)_\sharp \mu + t\, \alpha_M(g,\cdot)_\sharp \delta_{p^M_\varepsilon(\mu)}\nonumber\\
			&= (1-t)\alpha_M(g,\cdot)_\sharp \mu + t\, \delta_{\alpha_M(g,p^M_\varepsilon(\mu))}\\
			&\stackrel{(*)}{=}(1-t)\alpha_M(g,\cdot)_\sharp \mu + t\, \delta_{p^M_\varepsilon(\alpha_M(g,\cdot)_\sharp \mu))}\nonumber\\
			&=(1-t)\alpha_M(g,\cdot)_\sharp \mu + t\, j_\varepsilon^M\circ p^M_\varepsilon(\alpha_M(g,\cdot)_\sharp\mu))\nonumber
			=H\big(\alpha_M(g,\cdot)_\sharp\mu,t\big)\nonumber
		\end{align*}
		where equality $(*)$ follows from item (1) above.
	\end{proof}





	\subsection{A precompactness theorem for $\dgh^G$.}
	For each $X\in\mathcal{M}^G$ and $\varepsilon>0$, we define the $(G,\varepsilon)$-covering number of $X$ as follows: $$N_X^G(\varepsilon):=\inf\{\vert U \vert: U\text{ is a }G\text{-invariant }\varepsilon\text{-net of }X\}.$$



	\begin{remark}
		Assume that $(X,d_X,\alpha_X)\in\mathcal{M}^G$, $\varepsilon>0$, and a group homomorphism $h:\widetilde{G}\to G$ are given. Then, it is easy to verify that any $G$-invariant $\varepsilon$-net $U$ of $(X,d_X,\alpha_X)$ is also $\widetilde{G}$-invariant $\varepsilon$-net of $(X,d_X,h^\sharp\alpha_X)$. Therefore, we have that $N_{(X,d_X,\alpha_X)}^G(\varepsilon)\geq N_{(X,d_X,h^\sharp\alpha_X)}^{\widetilde{G}}(\varepsilon)$ for each $\epsilon>0$.
	\end{remark}

	\begin{definition}[Uniformly $G$-totally bounded family]
		We say that a family $\mathcal{F}\subseteq\mathcal{M}^G$ is \emph{uniformly $G$-totally bounded} if
		\begin{enumerate}
			\item There exists $D>0$ such that $\diam(X)\leq D$ for all $X\in\mathcal{F}$, and

			\item For each $\varepsilon>0$, the number $N_{\mathcal{F}}^G(\varepsilon):=\sup_{X\in\mathcal{F}}N_X^G(\varepsilon)$ is finite.



		\end{enumerate}
	\end{definition}

	The following theorem is a generalization of Gromov's precompactness theorem (see \cite[Theorem 7.4.15]{burago2022course}) to the $G$-equivariant setting.

	\begin{theorem}[$G$-equivariant  Gromov's precompactness theorem]\label{thm:Gequivprcpt}
		Assume that $G$ is a finite group. If $\mathcal{F}\subseteq\mathcal{M}^G$ is uniformly $G$-totally bounded, then $\mathcal{F}$ is precompact with respect to $\dgh^G$.\footnote{I.e., any sequence in $\mathcal{F}$ contains a converging subsequence.}
	\end{theorem}

	The proof of the theorem is relegated to \Cref{app:proofs-finiteness}.


	\subsection{An application: rigidity and finiteness results.}



	In \Cref{sec:rigidity}, we work out rigidity results for both the homotopy type and Gromov-Hausdorff distances. In \Cref{sec:finite}, we combine these results with \Cref{thm:Gequivprcpt} to obtain a finiteness result for the number of $G$-homotopy class of suitably constrained Riemannian manifolds. 

	\subsubsection{Rigidity}\label{sec:rigidity}
	The following theorem provides a rigidity result with respect to the $G$-homotopy type distance and \Cref{cor:rigidity} below translates it into a rigidity claim with respect to the $G$-Gromov-Hausdorff distance.

	\begin{theorem}\label{thm:rigidity}
		Suppose that $X,Y\in\mathcal{H}^G$. If
		$$\dht^G\big((\Pfin(X),\diam_\infty^X),(\Pfin(Y),\diam_\infty^Y)\big)<\tfrac{1}{2}\min\{r^G(X),r^G(Y)\},$$
		then $X$ and $Y$ are $G$-homotopy equivalent.
	\end{theorem}


	From \Cref{Gdhtstability} and \Cref{thm:rigidity} we obtain:

	\begin{corollary}\label{cor:rigidity}
		Suppose that $X,Y\in\mathcal{H}^G$. If $\dgh^G(X,Y)<\tfrac{1}{4}\min\{r^G(X),r^G(Y)\}$, then $X$ and $Y$ are $G$-homotopy equivalent.
	\end{corollary}

	See \cite[Theorem A]{peter1990finiteness} for results of similar flavor. Indeed, on page 392 of \cite{peter1990finiteness}, Petersen concludes that any two $n$-dimensional\footnote{In \cite{peter1990finiteness}, Petersen uses the Lebesgue covering dimension.} compact metric spaces $X$ and $Y$ such that there exists $R>0$ such that balls of radius of at most $R$ are contractible within themselves, then $X$ and $Y$ are homotopy equivalent as soon as $\dgh(X,Y)<\tfrac{R}{32 n^2}$; see also \cite[Theorem 2]{yamaguchi1988homotopy}.

	\begin{remark}
		\Cref{thm:rigidity} and \Cref{cor:rigidity} yield interesting consequences even when $G$ is the trivial group $G_0$. For example, if $X,Y\in\mathcal{H}^{G_0}$ are \emph{not} homotopy equivalent, then $\dgh(X,Y)\geq \tfrac{1}{4}\min\{r^{G_0}(X),r^{G_0}(Y)\}$. In particular, for $n\neq m$, via \Cref{thm:Z2hausmannspherevrm}, we find that $\dgh(\Sp^n,\Sp^m)\geq \tfrac{1}{4}\min(\zeta_n,\zeta_m)\geq \tfrac{\pi}{8}.$  Similarly, if $T^d$ denotes the $d$-dimensional flat torus,\footnote{Since $r(T^d)\geq \tfrac{\pi}{2}$.} then $\dgh(\Sp^n,T^d)\geq \tfrac{\pi}{8}$ for all positive integers $n,d$ not simultaneously equal to $1$.  

	\end{remark}


