	\subsubsection{Finiteness for a class of Riemannian manifolds.}\label{sec:finite}


	For each $n\in\Z_{>0}$, $C,D,K,t\in\R_{>0}$, and $\kappa\in\R$, let $\mathcal{F}_{n,C,D,\kappa,K,t}^G$ be the collection of all complete $n$-dimensional $G$-Riemannian manifolds $(M,g_M)$ with $\diam(M)\leq D$, $\mathrm{Conv}(M)\geq C$,  Ricci curvature  bounded below $\kappa (n-1) g_M$,  sectional curvatures upper bounded by $K$, and $\mathrm{Sep}^G(M)\geq t$. Then, for each $M\in\mathcal{F}_{n,C,D,\kappa,K,t}^G$, we have that $r^G(M)\geq\min\{C,\frac{1}{4}\pi K^{-1/2}\}=:r_{C,K}$.  Also let $\nu(n,\kappa,r)$ denote the volume of a ball of radius $r$ in the $n$-dimensional model space with  constant sectional curvature $\kappa$. 

	\medskip
	We then have the following.



	\begin{theorem}\label{cor:Riemfinite}
		For each $n\in\Z_{>0}$ $C,D,K\in\R_{>0}$, and $\kappa\in\R$, the collection $\mathcal{F}_{n,C,D,\kappa,K,t}^G$ has at most
		$$\sum_{j=1}^{M_{n,C,D,K,\kappa}}\left(j^{\frac{j^2-j}{2}}\cdot\vert\hom(G,\mathcal{S}_j)\vert\right)$$
		many $G$-homotopy types, where $M_{n,C,D,K,\kappa}:=\Big\lceil\frac{\nu(n,\kappa,D)}{\nu\left(n,\kappa,\min\{\frac{r_{C,K}}{24},\frac{t}{6}\}\right)}\Big\rceil$ and $\hom(G,\mathcal{S}_j)$ denotes the set of all homomorphisms from $G$ to the symmetric group $\mathcal{S}_j$ on $[j]:=\{1,2,\dots,j\}$.
	\end{theorem}



	The following lemma is a generalization to the $G$-equivariant setting of a result that has been implicitly used in several publications such as \cite{peter1990finiteness,yamaguchi1988homotopy} and \cite[page 274]{gromov1999metric}. Its proof is deferred to \Cref{app:proofs-finiteness}.



	\begin{lemma}\label{lemma:prcptcoverbdd}
		Let $\mathcal{F}\subseteq\mathcal{M}^G$ be a precompact family of connected compact $G$-metric spaces. Then, for any $\varepsilon>0$, $(\mathcal{F},\dgh^G)$ can be covered by
		$$\sum_{j=1}^{N_{\mathcal{F}}^G(\varepsilon/3)}\left(j^{\frac{j^2-j}{2}}\cdot\vert\hom(G,\mathcal{S}_j)\vert\right)$$
		many $\varepsilon$-balls (in the sense of the $G$-Gromov-Hausdorff distance).
	\end{lemma}



	\begin{remark}
		If $G=G_0$ then $\vert\hom(G_0,\mathcal{S}_m)\vert=1$ and in that case \Cref{lemma:prcptcoverbdd} recovers the statement of \cite[Lemma 6.4]{memoli2024persistent}.
	\end{remark}



	The following  lemma is a generalization of a classical result relating packing numbers and covering numbers; see \cite[pg.299]{petersen2006riemannian}. 

	\begin{lemma}\label{lemma:Gcoveringpacking}
		Let $X$ be a compact $G$-metric space with $\mathrm{Sep}^G(X)>0$. Then, for any $\varepsilon\in(0,\mathrm{Sep}^G(X)]$, we have that
		$$N_M^G(\varepsilon)\leq\sup\{\vert U \vert: U\subseteq X\text{ is a }G\text{-invariant set s.t. }\{B_{\varepsilon/2}(u)\}_{u\in U}\text{ is a packing in }X\}.$$
	\end{lemma}

	%%%%%%%%%%%%%%%%%%%%%%%%
	\input{proofs/proof_lemma_Gcoveringpacking.tex}
	%%%%%%%%%%%%%%%%%%%%%%%%


	\begin{proof}[\textbf{Proof of \Cref{cor:Riemfinite}}]
		By \Cref{lemma:Gcoveringpacking} we have that $N_M^G(\varepsilon)\leq\frac{\nu(n,\kappa,D)}{\nu(n,\kappa,\varepsilon/2)}$ for any $\varepsilon\in (0,t]$ (see \cite[Lemma 36 and the proof of Corollary 31]{petersen2006riemannian}). The proof follows from \Cref{cor:rigidity} and \Cref{lemma:prcptcoverbdd}.
	\end{proof}


