	\section{$G$-index and lower bounds for $\dht^G$.}\label{sec:Gindices}

	We first introduce the notion of $G$-persistence index and then use this concept to establish a lower bound for the $G$-homotopy type distance.
	\subsection{$G$-persistent indices} 
	\begin{definition}[$G$-index]
		Let $Y$ be a $G$-space and $\{X_\xi\}_{\xi\in\Xi}$  be a collection of $G$-spaces indexed by a nonempty subset $\Xi\subseteq\R_{> 0}$. Then, we define the $G$-index $\mathrm{ind}_G(Y,\{X_\xi\}_{\xi\in\Xi})$ from $Y$ to $\{X_\xi\}_{\xi\in\Xi}$ in the following way:
		$$\mathrm{ind}_G(Y,\{X_\xi\}_{\xi\in\Xi}):=\inf\{\xi\in\Xi:\text{there is a }G\text{-map }Y\toG X_\xi\}.$$
	\end{definition}

	\begin{remark}
		When $G=\Z_2$, the $\Z_2$-index $\mathrm{ind}_{\Z_2}(Y,\{\Sp^n\}_{n\in\Z_{\geq 0}})$ from $Y$ to $\{\Sp^n\}_{n\in\Z_{\geq 0}}$  boils down to the following classical notion $\mathrm{ind}_{\Z_2}(Y)$, the $\Z_2$-index of $Y$ \cite{yang1955theorems}:
		$$\mathrm{ind}_{\Z_2}(Y):=\min\{n\in\Z_{\geq 0}:\text{there is a }\Z_2\text{-map }Y\toZtwo \Sp^n\}.$$


		This notion of $\Z_2$-index has been employed to obtain a certain generalization of the Borsuk-Ulam theorem \cite[Chapter 5]{matouvsek2003using}.
	\end{remark}

	We are now ready to introduce three (a priori distinct) quantities, defined via the notion of $G$-index, which will ultimately provide lower bounds for the $G$-homotopy type distance between filtered $G$-topological spaces, and, via \Cref{Gdhtstability}, for the $G$-Gromov–Hausdorff distance between $G$-metric spaces. Below, note that $\vrm_p(X;\bullet)$, $\vert\vr(X;\bullet)\vert$, and $B_\bullet(X,\TS(X))$ are all filtrations, in particular they are collections of $G$-spaces indexed by the whole real line $\R$ (see \Cref{def:pers-fams,def:VR,def:VRm} and \Cref{sec:katetov}).

	\begin{definition}[$G$-persistent indices]\label{def:clowerbdd}
		For any two $G$-metric spaces $X,Y$, $p\in[1,\infty]$, and $\varepsilon\in\R_{\geq 0}$, we define the following quantities which we call \emph{$G$-persistence indices}: 

		\begin{enumerate}
			\item \emph{$G$-persistent index induced by the $p$-Vietoris-Rips thickening filtration:}\\ $c_p^G(X,Y;\varepsilon):=\begin{cases}\mathrm{ind}_G(Y,\vrm_p(X;\bullet))&\text{if }\varepsilon=0\\ \mathrm{ind}_G(\vrm_p(Y;\varepsilon),\vrm_p(X;\varepsilon+\bullet))&\text{if }\varepsilon>0,\end{cases}$

			\item \emph{$G$-persistent index induced by the Vietoris-Rips filtration: }\\$c_{\vr}^G(X,Y;\varepsilon):=\begin{cases}\mathrm{ind}_G(Y,\vert\vr(X;\bullet)\vert)&\text{if }\varepsilon=0\\ \mathrm{ind}_G(\vert\vr(Y;\varepsilon)\vert,\vert\vr(X;\varepsilon+\bullet)\vert)&\text{if }\varepsilon>0,\text{ and}\end{cases}$

			\item \emph{$G$-persistent index induced by the tight span neighborhood filtration:}\\$c_\TS^G(X,Y;\varepsilon):=\begin{cases}\mathrm{ind}_G\big(Y,B_\bullet(X,\TS(X))\big)&\text{if }\varepsilon=0\\ \mathrm{ind}_G\big(B_\varepsilon(X,\TS(X)),B_{\varepsilon+\bullet}(X,\TS(X))\big)&\text{if }\varepsilon>0.\end{cases}$
		\end{enumerate}
		\nomenclature[16]{$c_p^G(X,Y;\varepsilon)$}{The $G$-persistent index associated to $\vrm_p(X;\bullet)$}
		\nomenclature[17]{$c_{\vr}^G(X,Y;\varepsilon)$}{The $G$-persistent index associated to $\vert\vr(X;\bullet)\vert$}
		\nomenclature[18]{$c_\TS^G(X,Y;\varepsilon)$}{The $G$-persistent index associated to $B_\bullet(X,\TS(X))$}
	\end{definition}

	\begin{remark}\label{rmk:referpolymath}
		The case when $G = \mathbb{Z}_2$ and $\varepsilon = 0$ of $c_{\vr}^G(X, Y; \varepsilon)$ agress with an invariant that was considered in \cite[Definition 1.1]{adams2022gromov}, specifically when $X$ and $Y$ are spheres equipped with the standard antipodal action. Introducing the parameter $\varepsilon$, as we do in this paper,  allows, in general, for sharper lower bounds on the Gromov–Hausdorff distance compared to the $\varepsilon = 0$ case; see \Cref{ex:eps-good-1,ex:eps-good-2}. Note that neither $c_\vr(X,Y;0)$ nor the case $\varepsilon=0$ of the other two $G$-persistent indices ``see" the metric structure of $Y$: only its topology is taken into account.
	\end{remark}



	In \Cref{sec:lb-dght-pi} below we establish the lower bound for $\dht^G$ (and also for $\dgh^G$) via $c_p^G$ stated in the Main Theorem on page \pageref{page:main-theorem}. In \Cref{sec:rel-pis} we will establish several inequalities between  three different persistence indices $c_p^G$, $c_\vr^G$ and $c_\TS^G$. Regarding the former point, persistence indices, however,  provide useful lower bound for the $G$-Gromov-Hausdorff distance only in situations when the group $G$ acts freely on one of the spaces $X$ and $Y$.

	\begin{remark}[Persistent indices and fixed points]\label{rem:fixed-points}
		Assume that $x_0\in X$ is a fixed point for the $G$-action: $\alpha_X(g,x_0)=x_0$ for all $g\in G$. Then, the constant map $\psi:Y\to X$ defined by $y\mapsto x_0$ is a $G$-map. Also, for each $\varepsilon>0$, $\psi$ induces $G$-maps $\psi_\varepsilon:\vrm(Y;\varepsilon)\toG \vrm(X;\varepsilon)$ by sending every $\mu$ in the domain to $\delta_{x_0}$. As a consequence, $c_p(X,Y;\varepsilon)=0$ for all $\varepsilon>0$.  A similar argument also shows that $c_\vr^G(X,Y;\varepsilon)= c_\TS^G(X,Y;\varepsilon)=0$ in this case.
	\end{remark}

	\subsection{A lower bound for $\dht^G$ via $G$-persistent indices.}\label{sec:lb-dght-pi}
	The following proposition exhibits a lower bound for the $\dht^G$ distance between two filtrations of the form given by \Cref{prop:PfinGaction} via the $G$-persistent index $c_p^G$.




	\begin{proposition}\label{prop:strongercGpXYlbdd}
		For any two $G$-metric spaces $X,Y$ and $p\in[1,\infty]$, we have that
		$$\dht^G\big((\Pfin(X),\diam_p^X),(\Pfin(Y),\diam_p^Y)\big)\geq \sup_{\varepsilon\geq 0}c_p^G(X,Y;\varepsilon).$$
	\end{proposition}

	%%%%%%%%%%%%%%%%%%%%%%%%
	\input{proofs/proof_prop_strongercGpXYlbdd.tex}
	%%%%%%%%%%%%%%%%%%%%%%%%

	It is natural to ask if  there are cases when $\sup_{\varepsilon\geq 0}c_p^G(X,Y,\varepsilon)$ strictly larger than $c_p^G(X,Y;0)$ for which we need to understand how the function $\varepsilon\mapsto c_p^G(X,Y;\varepsilon)$ behaves.

	\begin{example}
		Assume that $G=\Z_2$, $X=\Sp^1$, and $Y=\Sp^2$. Then, it is easy to verify that,  by \Cref{thm:Z2hausmannsphere}, for any $\varepsilon\in[0,\zeta_2]$ we have $c_\infty^{\Z_2}(\Sp^1,\Sp^2;\varepsilon)=\frac{2\pi}{3}-\varepsilon$.
	\end{example}

	The example above suggests the possibility that the function $\varepsilon\mapsto c_p^G(X,Y;\varepsilon)$ is always nonincreasing. However, the following examples show that this is not the case, in general; see also \Cref{q:spheres-mono} below.

	\begin{example}\label{ex:eps-good-1}
		Assume that $G=\Z_2$ and $X=\Sp^1$. Also, let $Y\subset\Sp^N$ ($N\gg 1$) be a finite $\Z_2$-invariant subset of the  sphere $\Sp^N$ such that there exists positive numbers $\eta,\eta',\delta$ s.t. $\eta'\geq \eta$ with the following properties:\footnote{Latschev's theorem \cite{latschev2001vietoris} guarantees that it suffices to choose $Y$ as a sufficiently dense finite sample of $\Sp^N$.} 
		\begin{itemize}
			\item[(1)] $\vrm_\infty(Y;\varepsilon)=Y$ if $\varepsilon\in (0,\eta]$,  and 
			\item[(2)] $\vrm_\infty(Y;\varepsilon)$ is  $\Z_2$-homotopy equivalent to $\Sp^N$ if $\varepsilon\in (\eta',\eta'+\delta)$. 
		\end{itemize}
		Then, it follows that $c_\infty^{\Z_2}(\Sp^1,Y;\varepsilon)=0$ for any $\varepsilon\in(0,\eta]$ and $c_\infty^{\Z_2}(\Sp^1,Y;\varepsilon)\gg 0$ for any $\varepsilon\in(\eta',\eta'+\delta)$.%\facundo{mention latschev}
	\end{example}




	\begin{example}\label{ex:eps-good-2}
		We also have an example involving a connected space $Y$. Fix a tiny positive real number $r\ll 1$. Now, let $G=\Z_2$, $X=\Sp^2$, and $Y=r\cdot\Sp^1$. First of all, if $\varepsilon\in\left(0,\frac{2r\pi}{3}\right]$, then $\vrm_\infty(Y;\varepsilon)$ is $\Z_2$-homotopy equivalent to $\Sp^1$ by \Cref{thm:Z2hausmannspherevrm}. Therefore,

		$$c_\infty^{\Z_2}(\Sp^2,Y;\varepsilon)=0\text{ if }\varepsilon\in\left(0,\frac{2r\pi}{3}\right].$$


		Also, by \cite[Theorem 7.4]{adamaszek2017vietoris} and \cite[Proposition 5.3.2]{matouvsek2003using}, there is a $\Z_2$-map from $\Sp^{2n-1}$ to $\vr(Y;\varepsilon)$ if $\varepsilon\in\left(\frac{2(n-1)r\pi}{2n-1},\frac{2nr\pi}{2n+1}\right]$. Hence, with the aid of \Cref{thm:Z2hausmannsphere} and  item 1.(b) of \Cref{prop:strongercGpXYlbddalernatives}, one can verify that
		$$c_\infty^{\Z_2}(\Sp^2,Y;\varepsilon)\geq c_\vr^{\Z_2}(\Sp^2,Y;\varepsilon) > \zeta_2-\varepsilon\text{ if }\varepsilon>\frac{2r\pi}{3}.$$


		Furthermore, one may increase the dimension of $Y$ by letting $Y=(r\cdot\Sp^1)^N$ for any positive integer $N$. Then, with the help of  \cite[Corollary 5.2]{adams2021operations}, one can still verify the analogous result for this $Y$, too. 
	\end{example}


	\Cref{ex:eps-good-1,ex:eps-good-2} above imply that, as a lower bound for $\dgh^G$, in the sense provided by the inequality $2\dgh^G(X,Y)\geq c_\infty^G(X,Y;0)$ stated in the main theorem (on page \pageref{page:main-theorem}), $c_\infty^G(X,Y;0)$ can be strictly worse than $\sup_{\varepsilon>0}c_\infty^G(X,Y;\varepsilon).$

	\begin{question}\label{q:spheres-mono}
		Is it true that $\varepsilon\mapsto c^{\Z_2}_\infty(\Sp^n,\Sp^m;\varepsilon)$ is non-increasing for all positive integers $n,m$ such that $n>m$?
	\end{question}


	The following example compares the values of the persistent homology based and the persistent index based lower bounds stated in the Main Theorem on page \pageref{page:main-theorem}. Recall, from \Cref{prop:Gdnmatter}, that in the case of spheres, viewed as $\Z_2$-metric spaces, for $n>m$, we have
	$$\di^{\Z_2}\big(\h_m(\vert\vr(\Sp^m;\bullet)\vert),\h_m(\vert\vr(\Sp^n;\bullet)\vert)\big)=\frac{\zeta_m}{2},$$
	which, by \Cref{cor:vrvrmdIGsame}, also implies that for the $\infty$-Vietoris-Rips metric thickenings,
	$$\di^{\Z_2}\big(\h_m(\vrm_\infty(\Sp^m;\bullet)),\h_m(\vrm_\infty(\Sp^n;\bullet))\big)=\frac{\zeta_m}{2}.$$
	In contrast, item (1) of \Cref{prop:cforspheres} states that $$c_{\infty}^{\Z_2}(\Sp^m,\Sp^n;0)\geq\zeta_m.$$ That is, in this case, the lower bound on $\dgh^{\Z_2}(\Sp^m,\Sp^n)$ derived from persistent indices is twice as strong as the one obtained from persistent homology. The example below illustrates a situation where the reverse holds—i.e., persistent homology provides a sharper lower bound than persistent indices.

	\begin{figure}
		\begin{center}
			\includegraphics[width = 0.8\linewidth]{ex-comp.pdf}  
		\end{center}
		\caption{The geodesic $\Z_3$-metric spaces $X$ and $Y$ from \Cref{ex:compatibility}. The $\Z_3$-action on each of these spaces exchanges different branches leaving the center points fixed.}
		\label{fig:compatibility}
	\end{figure}

	\begin{example}\label{ex:compatibility}
		This  example shows that, for some choices of $G$, $X$, and $Y$, we can have
		$$\di^G\big(\h_k(\vrm_p(X;\bullet)),\h_k(\vrm_p(Y;\bullet))\big)>\sup_{\varepsilon\geq 0}c_p^G(X,Y;\varepsilon).$$
		Consider the 1-dimensional geodesic $\Z_3$-metric spaces $X$ and $Y$ with  $\Z_3$-actions shown in \Cref{fig:compatibility}. Note that $x_0$ and $y_0$ are fixed points w.r.t the respective $\Z_3$-actions. Then, by \Cref{rem:fixed-points},  one  concludes that $\sup_{\varepsilon\geq 0}c_\infty^{\Z_3}(X,Y;\varepsilon)=\sup_{\varepsilon\geq 0}c_\infty^{\Z_3}(Y,X;\varepsilon)=0$. However, note that
		$$\di^{\Z_3}\big(\h_1(\vrm_\infty(X;\bullet)),\h_1(\vrm_\infty(Y;\bullet))\big)\geq\di\big(\h_1(\vrm_\infty(X;\bullet)),\h_1(\vrm_\infty(Y;\bullet))\big)>0.$$ 
		Indeed, whereas $\h_1(\vrm_\infty(X;\bullet))=0$, $\h_1(\vrm_\infty(Y;\bullet))$ will not be trivial as it detects the presence and size of the 3 geodesic loops.\footnote{If $s$ is the common length of the 3 loops in $Y$, one can in fact prove that the interleaving distance above equals $\tfrac{s}{6}$.} This example can obviously be generalized to a case exhibiting $\Z_k$ symmetry, for every positive integer $k$, by considering versions of $X$ and $Y$ with $k$-branches.
	\end{example}


	\subsection{Relationship between different $G$-persistent indices.}\label{sec:rel-pis}


	Now, we will compare the three $G$-persistent indices defined in \Cref{def:clowerbdd}. But, before that we need the following definition.

	\begin{definition}[$G$-separation]
		Let $G$ be a finite group and $X$ be a $G$-metric space. Then, we define the \emph{$G$-separation} of $X$ as follows:
		$$\mathrm{Sep}^G(X):=\inf\{d_X(x,\alpha_X(g,x)):g\in G\text{ is nontrivial element and }x\in X\}.$$

		If $G$ is a trivial group, then we define $\mathrm{Sep}^G(X):=+\infty$.
		\nomenclature[19]{$\mathrm{Sep}^G(X)$}{$G$-separation}
	\end{definition}



	Note that if the $G$-action on $X$ is trivial, then its $G$-separation is zero. However, the following lemma shows that one can guarantee  the $G$-separation to be strictly positive when $X$ is compact and the $G$-action is free.

	\begin{lemma}\label{lemma:posGsep}
		Let $G$ be a finite group and $X$ be a compact $G$-metric space with a free action $\alpha_X$. Then, we always have $\mathrm{Sep}^G(X)>0$.
	\end{lemma}


	%%%%%%%%%%%%%%%%%%%%%%%%
	\input{proofs/proof_lemma_posGsep.tex}
	%%%%%%%%%%%%%%%%%%%%%%%%

	\begin{example}\label{ex:G-sep}
		Consider the following $\Z_2$-metric spaces $X$:
		\begin{enumerate}
			\item $X=\Sp^n$ (see the item (2) of \Cref{ex:spheres-Z2}). Then, $\mathrm{Sep}^{\Z_2}(X)=\pi$ since $d_X(x,\alpha_X(-1,x))=\pi$ for all $x\in X$.

			\item $X=\square^n_\infty$ (see the item (3) of \Cref{ex:spheres-Z2}). Then, $\mathrm{Sep}^{\Z_2}(X)=2$ since $d_X(x,\alpha_X(-1,x))=2$ for all $x\in X$.

			\item $X=\Sp^n_\infty$ (see the item (3) of \Cref{ex:spheres-Z2}). Then, for each $x=(x_0,x_1,\cdots,x_n)\in X$, we have that $d_X(x,\alpha_X(-1,x))=2\Vert (x_0,x_1,\cdots,x_n) \Vert_{\ell^\infty}$. Therefore, one can easily verify that $\mathrm{Sep}^{\Z_2}(X)=\frac{2}{\sqrt{n+1}}$.
		\end{enumerate}
	\end{example}

	\begin{proposition}\label{prop:strongercGpXYlbddalernatives}
		Suppose that $G$ is a finite group. Then, for any two compact $G$-metric spaces $X$ and $Y$ the followings hold:
		\begin{enumerate}
			\item
			\begin{itemize}
				\item[(a)] For $\varepsilon=0$, we have that $$c_{\infty}^G(X,Y;0)=c_{\vr}^G(X,Y;0).$$

				\item[(b)] For any $\varepsilon>0$, we have that
				$$c_{\vr}^G(X,Y;\varepsilon)\leq c_{\infty}^G(X,Y;\varepsilon)\leq\inf_{\delta>0}\big\{c_{\vr}^G(X,Y;\varepsilon+\delta)+\delta\big\}.$$
			\end{itemize}

			\item 
			\begin{itemize}
				\item[(a)] For $\varepsilon=0$, we have that $$c_{\vr}^G(X,Y;0)\leq 2c_\TS^G(X,Y;0).$$ Furthermore, if $\mathrm{Sep}^G(X)>0$ and either $c_{\vr}^G(X,Y;0)<\mathrm{Sep}^G(X)$ or $2c_\TS^G(X,Y;0)<\mathrm{Sep}^G(X)$, then we have that $$c_{\vr}^G(X,Y;0)=2c_\TS^G(X,Y;0).$$


				\item[(b)] Assume that $\mathrm{Sep}^G(X),\mathrm{Sep}^G(Y)>0$. For any $\varepsilon\in \left(0,\frac{\mathrm{Sep}^G(Y)}{2}\right]$, if either $$\text{$c_{\vr}^G(X,Y;2\varepsilon)<\mathrm{Sep}^G(X)-2\varepsilon$ or $2c_\TS^G\left(X,Y;\varepsilon\right)<\mathrm{Sep}^G(X)-2\varepsilon$,}$$ then we have that $$c_{\vr}^G(X,Y;2\varepsilon)=2c_\TS^G\left(X,Y;\varepsilon\right).$$
			\end{itemize}
		\end{enumerate}
	\end{proposition}

	\begin{question}
		\begin{itemize}
			\item About item 1 (b): Are there $G, X, Y$, and $\varepsilon>0$ such that $c_\infty^G(X,Y;\varepsilon)$ is strictly larger than $c_{\vr}(X,Y;\varepsilon)$? If so, is the upper bound $\inf_{\delta>0}\{c_{\vr}^G(X,Y;\varepsilon+\delta)+\delta\}$ tight?


			\item About item 2 (a): Can we find an example of $G$, $X$, and $Y$ such that $c_{\vr}^G(X,Y;0)$ is strictly smaller than $2c_\TS^G(X,Y;0)$? Note that this would necessarily require that $$\min\big(c_{\vr}^G(X,Y;0),2c_\TS^G(X,Y;0)\big)\geq\mathrm{Sep}^G(X).$$

		\end{itemize}
	\end{question}


	\begin{example}\label{ex:cvrce}
		\begin{enumerate}
			\item As already mentioned in \Cref{rmk:referpolymath}, the quantity $c_\vr^{\Z_2}(\Sp^m,\Sp^n;0)$ was already considered in \cite{adams2022gromov}. Furthermore, by \cite[Remark 5.6]{adams2022gromov}, we have that $c_\vr^{\Z_2}(\Sp^m,\Sp^n;0)<\pi=\mathrm{Sep}^{\Z_2}(\Sp^m)$ (see the item (1) of \Cref{ex:G-sep}) for all $0< m < n <\infty$. Hence, by \Cref{prop:strongercGpXYlbddalernatives}, we have that
			$$c_{\infty}^{\Z_2}(\Sp^m,\Sp^n;0)=c_{\vr}^{\Z_2}(\Sp^m,\Sp^n;0)=2c_\TS^{\Z_2}(\Sp^m,\Sp^n;0)$$
			for all $0< m < n <\infty$.

			\item Let's consider the case when $G=\Z_2$, $X=\square^m_\infty$, and $Y=\square^n_\infty$ for some $0< m < n <\infty$. Later, we will see that both of $c_{\vr}^{\Z_2}(\square^m_\infty,\square^n_\infty;0)$ and $2c_{\TS}^{\Z_2}(\square^m_\infty,\square^n_\infty;0)$ are greater than or equal to $2=\mathrm{Sep}^{\Z_2}(\square^m_\infty)$ (see the item (2) of \Cref{ex:G-sep}, the item (1) of \Cref{prop:cforsphereslinfty} and its proof). In particular, we cannot guarantee the equality between $c_{\vr}^{\Z_2}(\square^m_\infty,\square^n_\infty;0)$ and $2c_{\TS}^{\Z_2}(\square^m_\infty,\square^n_\infty;0)$ via \Cref{prop:strongercGpXYlbddalernatives}.

			\item Let's consider the case when $G=\Z_2$, $X=\Sp^m_\infty$, and $Y=\Sp^n_\infty$ for some $0< m < n <\infty$. Later, we will see that both of $c_{\vr}^{\Z_2}(\Sp^m_\infty,\Sp^n_\infty;0)$ and $2c_{\TS}^{\Z_2}(\Sp^m_\infty,\Sp^n_\infty;0)$ are greater than or equal to $\frac{2}{\sqrt{m+1}}=\mathrm{Sep}^{\Z_2}(\Sp^m_\infty)$ (see the item (3) of \Cref{ex:G-sep}, the item (2) of \Cref{prop:cforsphereslinfty} and its proof). In particular, we cannot guarantee the equality between $c_{\vr}^{\Z_2}(\Sp^m_\infty,\Sp^n_\infty;0)$ and $2c_{\TS}^{\Z_2}(\Sp^m_\infty,\Sp^n_\infty;0)$ via \Cref{prop:strongercGpXYlbddalernatives}.
		\end{enumerate}
	\end{example}









	\subsection{Proof of \Cref{prop:strongercGpXYlbddalernatives}.}


	We need a few technical elements --including a $G$-equivariant nerve lemma-- in order to prove \Cref{prop:strongercGpXYlbddalernatives}.

	\begin{definition}[$G$-invariant cover]\label{def:Ginvcov}
		Assume that a $G$-space $(X,\alpha_X)$ is given. Then, a cover $\mathcal{U}=\{U_\lambda\}_{\lambda\in\Lambda}$ of $X$ is said to be \emph{$G$-invariant} if there is a $G$-action $\alpha_{\Lambda}:G\times\Lambda\rightarrow\Lambda$ on the index set $\Lambda$ such that $U_{\alpha_\Lambda(g,\lambda)}=\alpha_X(g,U_\lambda)$ for all $g\in G$ and $\lambda\in \Lambda$.
	\end{definition}


	\begin{proposition}[$G$-nerve lemma]\label{prop:Gnerve}
		Assume that a finite group $G$, a paracompact $G$-space $(X,\alpha_X)$, and a $G$-invariant open cover $\mathcal{U}:=\{U_\lambda\}_{\lambda\in\Lambda}$ of $X$ are given. Also, assume that $U_\sigma:=\bigcap_{\lambda\in\sigma} U_\lambda$ is $G_\sigma$-contractible for every simplex $\sigma\in\mathrm{N}\,\mathcal{U}$ where $\mathrm{N}\,\mathcal{U}$ is the nerve complex associated to $\mathcal{U}$ and $G_\sigma:=\{g\in G:\alpha_\Lambda(g,\sigma)=\sigma\}$ is the isotropy subgroup of $G$. Then, $X$ and $\vert\mathrm{N}\,\mathcal{U}\vert$ are $G$-homotopy equivalent. 
	\end{proposition}

	\begin{remark}\label{rmk:trivialcontractibiliy} If $G$ is the trivial group, then $G$-contractibility is just boils down the standard notion of contractibility.
	\end{remark}

	\begin{remark}
		Various versions of the $G$-nerve lemma have been already studied in the following articles. Each version of $G$-nerve lemma holds under  different assumptions all of which are more restrictive than those in \Cref{prop:Gnerve}:

		\begin{itemize}
			\item \cite[Lemma 2.5]{hess2013topology} requires the space $X$ to be a $G$-simplicial complex.

			\item \cite[Theorem 2.19]{yang2014equivariant} requires the space $X$ to be $G$-CW complex $X$ and the cover $\mathcal{U}$ to be locally finite and ``regular" (see \cite[Definition 2.7]{yang2014equivariant}).

			\item \cite[Theorem 4.6]{gonzalez2024equivariant} requires the cover $\mathcal{U}$ to be locally finite.
		\end{itemize}
	\end{remark}

	The proof of the above proposition is relegated to \Cref{sec:Gnerve}. As an application, we obtain the following. 





	\begin{proposition}\label{prop:GvrTS}
		Let $G$ be a finite group and $X$ be a $G$-metric space with $\mathrm{Sep}^G(X)>0$. Then, $\vert\vr(X;2r)\vert$ and $B_r(X,\TS(X))$ are $G$-homotopy equivalent for any $r\in \left(0,\frac{\mathrm{Sep}^G(X)}{2}\right]$.
	\end{proposition}


	\begin{remark}
		That for a compact  metric space $(X,d_X)$, $|\vr(X;2r)|$ and $B_r(X,\TS(X))$ are homotopy equivalent \emph{for all $r>0$} is a  known fact; see \cite[Proposition 2.27]{lim2020vietoris}. 
	\end{remark}

	\begin{example}
		Note, for example, that when $G=\Z_2$ and  $X=\Sp^n$ with the canonical antipodal action,  \Cref{prop:GvrTS}  together with \Cref{ex:G-sep}, gives that $|\vr(\Sp^n;2r)|$ and $B_r(\Sp^n,\TS(\Sp^n))$ are $\Z_2$-homotopy equivalent for all $r\in(0,\tfrac{\pi}{2}]$, which is optimal. 
	\end{example}

	\begin{remark}\label{remark:z3-contract}
		Let $G=\Z_3:=\left\{0,\frac{2\pi}{3},\frac{4\pi}{3}\right\}$, $X=\Sp^1$, and the $\Z_3$-action $\alpha_{\Sp^1}$ is defined by $\alpha_{\Sp^1}(g,\theta):=\theta+g$ for any $g\in\Z_3$ and $\theta\in\Sp^1$. Then, it is easy to verify that $\mathrm{Sep}^{\Z_3}(\Sp^1)=\frac{2\pi}{3}$. Hence, by \Cref{prop:GvrTS}, $\vert\vr(\Sp^1;2r)\vert$ and $B_r(\Sp^1,\TS(\Sp^1))$ are $\Z_3$-homotopy equivalent for all $r\in \left(0,\frac{\pi}{3}\right]$.
	\end{remark}



