	One implication of the $G$-homotopy equivalence whose  existence is guaranteed by \Cref{prop:GvrTS} is that there are $G$-maps from $|\vr(X;2r)|$ to $B_r(X,\TS(X))$ and vice-versa, when $r\in \left(0,\frac{\mathrm{Sep}^G(X)}{2}\right]$. This fact will be useful in the proof of \Cref{prop:strongercGpXYlbddalernatives}. Moreover, by careful analysis on the proof of \Cref{prop:Gnerve} (see \Cref{sec:Gnerve}), one can conclude that, \emph{for every $r>0$},  there is a one-sided $G$-map from $B_r(X,\TS(X))$ to $\vert\vr(X;2r)\vert$, as \Cref{lemma:onesidedTStoVR} below shows.


	\begin{lemma}\label{lemma:onesidedTStoVR}
		Let $G$ be a finite group and $X$ be a $G$-metric space. Then, for every $r>0$ there is a $G$-map from $B_r(X,\TS(X))$ to $\vert\vr(X;2r)\vert$.
	\end{lemma}
	\begin{proof}
		Consider the $G$-invariant open cover $\mathcal{U}:=\{B_r(x,\TS(X))\}_{x\in X}$ of $B_r(X,\TS(X))$ as in the proof of \Cref{prop:GvrTS}. Next, let $\{\psi_x\}_{x\in X}$ be a $G$-partition of unity subordinate to $\mathcal{U}$, whose existence is guaranteed by \Cref{lemma:Gptofuty}. Then, one can verify that the following map
		$$f\mapsto (\psi_x(f))_{x\in X}$$
		is a well defined $G$-map from $B_r(X,\TS(X))$ to $\vert\vr(X;2r)\vert$.
	\end{proof}

	\begin{lemma}\label{lemma:vrmtovr}
		Let $G$ be a finite group, $X$ be a totally bounded $G$-metric space, and $p\in [1,\infty]$. Then, for any $\varepsilon,\delta>0$, there exists a $G$-map $\Theta:\vrm_\infty(X;\varepsilon)\toG\vert\vr(X;\varepsilon+\delta)\vert$.
	\end{lemma}

