	\subsection{Bounding  modulus of discontinuity via  $G$-persistent indices.}\label{sec:qbu}

	Let $X$ be a metric space, $Y$ be a topological space, and $\psi:Y\longrightarrow X$ be a function. Importantly, $\psi$ is not necessarily continuous. Then, the \emph{modulus of discontinuity} $\delta(\psi)$ of a function $\psi$ is the infimum of all numbers $\delta>0$ such that every point in $Y$ has a neighborhood whose image has a diameter of at most $\delta$. This quantity $\delta(\psi)$ measures how much discontinuous $\psi$ is. In particular, $\delta(\psi)=0$ if and only if $\psi$ is continuous.


	In \cite{dubins1981equidiscontinuity}, Dubins and Schwarz proved the following ``quantitative" version of the Borsuk-Ulam theorem:

	\begin{quote}
		\emph{If $0 < m < n <\infty$, then  any $\Z_2$-function $\psi$ from $\Sp^n$ to $\Sp^m$ (that is necessarily discontinuous by the classical Borsuk-Ulam theorem) must have  $\delta(\psi)\geq \zeta_m$.}
	\end{quote}

	Later, this result was employed in \cite{lim2023gromov} for proving that $2\,\dgh(\Sp^m,\Sp^n)\geq\zeta_m$ for all $n>m$. Motivated by these ideas, recently as the result of a polymath project we were able to establish the the following stronger version of the quantitative Borsuk-Ulam theorem (cf. \cite[Theorem 1.3]{adams2022gromov}):

	\begin{quote}
		\emph{If $0 < m < n <\infty$, then any $\Z_2$-function $\psi$ from $\Sp^{n}$ to $\Sp^m$ must have  $$\delta(\psi)\geq c_{m,n}:=\inf\{\eta>0:\text{there is a }\Z_2\text{-map }\Sp^n\stackrel{\Z_2}{\longrightarrow} \vert\vr(\Sp^m;\eta)\vert\}.$$}
	\end{quote}

	Note that $c_{m,n}$ is equal to $c_{\vr}^{\Z^2}(\Sp^m,\Sp^n;0)$; see \Cref{def:clowerbdd}. With the ideas considered this paper, we now obtain  the following generalization to the $G$-equivariant version of the  quantitative Borsuk-Ulam  theorems recalled above.


	\begin{proposition}[$G$-equivariant quantitative Borsuk-Ulam theorem]\label{prop:GquantBU}
		Assume that a finite group $G$, a $G$-metric space $X$, a compact $G$-metric space $Y$, and a $G$-function $\psi:Y\toG X$ are given. Then, we have that $\delta(\psi)\geq c_\infty^G(X,Y;0)$.
	\end{proposition}

	The following lemma is a generalization of \cite[Lemma 7.4]{adams2022gromov} to the $G$-equivariant setting.

	\begin{lemma}\label{lemma:vrmmodcti}
		Assume that a finite group $G$, a $G$-metric space $X$, a compact $G$-metric space $Y$, and a $G$-function $\psi:Y\toG X$ are given. Then, for any $\eta>0$ there exists $\alpha_\eta>0$ such that there is a $G$-map
		$$\widetilde{\psi}_B:\vrm_\infty(B;\alpha_\eta)\toG\vrm_\infty(X;\delta(\psi)+\eta)$$
		for any finite $G$-invariant subset $B \subseteq Y$.
	\end{lemma}

	Now we are ready to prove \Cref{prop:GquantBU}.

	\begin{proof}[Proof of \Cref{prop:GquantBU}]
		Fix an arbitrary $\eta>0$ and choose $\alpha_\eta$ as in \Cref{lemma:vrmmodcti}. By \Cref{lemma:Ginvdeltanetexst}, one can choose a finite $G$-invariant $\frac{\alpha_\eta}{2}$-net $B$ of $Y$. Then, by \Cref{lemma:G2deltamapexst}, we have a $G$-map $\iota:Y\toG\vrm_\infty(B;\alpha_\eta)$. Hence, the composition $\widetilde{\psi}_B\circ\iota$ is a $G$-map from $Y$ to $\vrm_\infty(X;\delta(\psi)+\eta)$. Therefore, we have that $c_\infty^G(X,Y;0)\leq\delta(\psi)+\eta$. Since the choice of $\eta$ is arbitrary, one can conclude that $c_\infty^G(X,Y;0)\leq\delta(\psi)$.
	\end{proof}

	\begin{proof}[Proof of \Cref{lemma:vrmmodcti}]
		Fix an arbitrary $\eta>0$. Then, following the proof of \cite[Lemma 7.4]{adams2022gromov}, we know that there exists $\alpha_\eta>0$ such that $d_X(\psi(y),\psi(y'))<\delta(\psi)+\eta$ for any $y,y'\in Y$ with $d_Y(y,y')<\alpha_\eta$. We write the argument for the completeness. By the definition of the modulus of discontinuity, for each $y\in Y$ we have $r_y>0$ such that the open ball $B_{r_y}(y)$ satisfies $\diam\big(\psi(B_{r_y}(y))\big)<\delta(\psi)+\eta$. Then, $\{B_{r_y/2}(y)\}_{y\in Y}$ is an open covering of $Y$. Since $Y$ is compact, one can choose finitely many points $y_1,\dots,y_k$ such that $\{B_{r_{y_i}/2}(y_i)\}_{i=1}^k$ covers whole $Y$. Finally, we choose $\alpha_\eta:=\min\left\{\frac{r_{y_1}}{2},\dots,\frac{r_{y_k}}{2}\right\}$. Now, choose arbitrary two points $y,y'\in Y$ with $d_Y(y,y')<\alpha_\eta$. Then, there exists $y_i\in Y$ such that $y\in B_{r_{y_i}/2}(y_i)$. Hence, by the triangle inequality we have that $d_Y(y_i,y')\leq d_Y(y_i,y)+d_Y(y,y')\leq\frac{r_{y_i}}{2}+\alpha_\eta\leq r_{y_i}$. This implies that $y,y'\in B_{r_{y_i}}(y_i)$
		so that $d_X(\psi(y),\psi(y'))<\delta(\psi)+\eta$ as we wanted.


		Finally, for any finite $G$-invariant subset  $B\subseteq Y$, one can define
		$$\widetilde{\psi}_B:\vrm_\infty(B;\alpha_\eta)\toG\vrm_\infty(X;\delta(\psi)+\eta)$$
		as the composition of the following maps:
		{\small$$\vrm_\infty(B;\alpha_\eta)\stackrel{\mathrm{id}^{-1}}{\longrightarrow}\vert\vr(B;\alpha_\eta)\vert\longrightarrow\vert\vr(\psi(B);\delta(\psi)+\eta)\vert\stackrel{\mathrm{id}}{\longrightarrow}\vrm_\infty(\psi(B);\delta(\psi)+\eta)\longhookrightarrow\vrm_\infty(X;\delta(\psi)+\eta)$$}
		where the first and the third maps are the canonical identity maps in \Cref{lemma:homeo}, the fourth map is the canonical inclusion, and the second map is the canonical map induced by $\psi$. Note that $\widetilde{\psi}_B$ is well-defined and continuous because of the above choice of $\alpha_\eta$ and the finiteness of $B$.
	\end{proof}



