	\section{Applications to determining $\dgh^{\Z_2}$ 
		between spheres.}\label{sec:GdGHresults-sph}

	In this section we apply the material developed in previous sections to estimate and sometimes fully determining the value of the $\Z_2$-Gromov-Hausdorff distance between spheres.

	\subsection{Results for $\Z_2$-persistence indices of spheres.}\label{sec:Spnresults}

	Recall that $\Sp^n,\SpE^n,\Sp^n_\infty$, and $\square^n_\infty$ are $\Z_2$-metric spaces with  canonical $\Z_2$-actions; see items (2) and (3) of \Cref{ex:spheres-Z2}. Then, one can obtain the lower bounds below for the following $\Z_2$-persistence indices  (see \Cref{def:clowerbdd}):


	\begin{proposition}\label{prop:cforspheres}
		For all $0<m<n<\infty$, we have the following
		\begin{enumerate}
			\item $c_{\infty}^{\Z_2}(\Sp^m,\Sp^n;0)\geq\zeta_m$. 

			\item $c_{\infty}^{\Z_2}(\SpE^m,\SpE^n;0)\geq\sqrt{\frac{2m+4}{m+1}}$.
		\end{enumerate}
	\end{proposition}

	\begin{remark}\label{rmk:cinftyZ2SmSm+1}
		When $n=m+1$, the inequality in item (1) of \Cref{prop:cforspheres} is actually tight. Indeed, by \Cref{prop:strongercGpXYlbddalernatives} and \cite[Theorem 5.2]{adams2022gromov}, we have that $c_{\infty}^{\Z_2}(\Sp^m,\Sp^{m+1};0)=\zeta_m$.
	\end{remark}

	\begin{proposition}\label{prop:cforsphereslinfty}
		For all $0<m<n<\infty$, we have the following
		\begin{enumerate}
			\item $c_{\infty}^{\Z_2}(\square^m_\infty,\square^n_\infty;0)\geq 2$. 

			\item $c_{\infty}^{\Z_2}(\Sp^m_\infty,\Sp^n_\infty;0)\geq\frac{2}{\sqrt{m+1}}$.
		\end{enumerate}
	\end{proposition}

	\begin{remark}
		The inequality in item (1) of \Cref{prop:cforsphereslinfty} is an equality for all $n>m$ as it will follow from \Cref{thm:Z2dGHsqmsqn}.
	\end{remark}
	%%%%%%%%%%%%%%%%%%%%%%%%
	\subsubsection{Proofs of \Cref{prop:cforspheres,prop:cforsphereslinfty}.}

	As a special case of \cite[Theorem 3.5]{hausmann1994vietoris}, it is known that there is a homotopy equivalence $T_r:\vert\vr(\Sp^n;r)\vert\rightarrow \Sp^n$ for all $r\in (0,\frac{\pi}{2}]$. Also, in \cite[Theorem 7.1]{lim2024vietoris}, we were able to improve  Hausmann's result by proving the existence of a homotopy equivalence $T_r:\vert\vr(\Sp^n;r)\vert\rightarrow \Sp^n$ for all $r\in (0,\zeta_n]$ (observe that $\zeta_n>\frac{\pi}{2}$).\footnote{The range $(0,\zeta_n]$ is tight for $n=1,2$ and it is believed to be tight in general; see \cite[Conjecture 7.8]{lim2024vietoris}.} Furthermore, one can make this result even stronger in the sense that $T_r$ can be chosen to be a \emph{$\Z_2$-homotopy equivalence}.




	\begin{theorem}[$\Z_2$-equivariant Hausmann theorem for Vietoris-Rips complexes of spheres]\label{thm:Z2hausmannsphere}
		For any $n\in\mathbb{Z}_{>0}$ and $r\in (0,\zeta_n]$, there is a $\Z_2$-homotopy equivalence
		$T_r:\vert\vr(\Sp^n;r)\vert\toZtwo\Sp^n.$
	\end{theorem}

	The proof of this theorem is given in \Cref{app:proof-Z2-H}. Also, from \Cref{thm:vrmHausmann-G}, for the case when $M=\Sp^n$ and $G=\Z_2$, one can obtain an analogous result for the Vietoris-Rips metric thickening $\vrm_\infty(\Sp^n;r)$. However, since $r(\Sp^n)=\tfrac{\pi}{2}$, the range of values of $r$ such that $\vrm_\infty(\Sp^n;r)\stackrel{\Z_2}{\simeq}\Sp^n$ is smaller than the one guaranteed by \Cref{thm:Z2hausmannsphere} for the standard Vietoris-Rips filtration $\vr(\Sp^n;r).$ The following statement, giving a $\Z_2$-equivariant version of \cite[Proposition 5.3]{adamaszek2018metric}, provides an improved range of values of $r$.

	\begin{theorem}[$\Z_2$-equivariant Hausmann theorem for Vietoris-Rips thickenings of spheres]\label{thm:Z2hausmannspherevrm}
		For any $n\in\mathbb{Z}_{>0}$ and $r\in (0,\zeta_n]$, there is a $\Z_2$-homotopy equivalence
		$p_r^n:\vrm_\infty(\Sp^n;r)\toZtwo\Sp^n.$
	\end{theorem}


