	\subsection{Determining $\dgh^{\Z_2}(\Sp^m,\Sp^n)$,  $\dgh^{\Z_2}(\SpE^m,\SpE^n)$ and $\dgh^{\Z_2}(\SpE^m,\SpE^n)$.}\label{sec:GdGHresults}
	In this section we apply the techniques developed in previous sections to the case of $\dgh^{\Z_2}(\Sp^m,\Sp^n)$ (\Cref{sec:precise-dgh-sph}), the case of $\dgh^{\Z_2}(\SpE^m,\SpE^n)$ (\Cref{sec:Z2dGHEsphere}), and the case of $\dgh^{\Z_2}(\square^m_\infty,\square^n_\infty)$ (\Cref{sec:Z2dGHinftysphere}).

	\subsubsection{The case of $\dgh^{\Z_2}(\Sp^m,\Sp^n)$.}\label{sec:precise-dgh-sph}


	We first prove that the $\Z^2$-Gromov-Hausdorff distance between spheres endowed with their geodesic distance and canonical involution is \emph{equal} to the standard  Gromov-Hausdorff.

	\begin{proposition}\label{prop:Z2dGHSmSn}
		For any $0\leq m<n<\infty$, we have that $$\dgh^{\Z_2}(\Sp^m,\Sp^n)=\dgh(\Sp^m,\Sp^n).$$
	\end{proposition}

	\begin{remark}\label{rmk:recovpolymath}
		Note that one can recover \cite[Main Theorem]{adams2022gromov} by applying \Cref{Gdhtstability},  \Cref{prop:strongercGpXYlbddalernatives}, \Cref{prop:strongercGpXYlbdd}, and \Cref{prop:Z2dGHSmSn}.
	\end{remark}

	The following is an immediate generalization of the ``helmet trick" from \cite{lim2023gromov}; see \cite[Proposition 2.2]{martin2024some} for a proof.



	\begin{lemma}\label{lemma:antipodalcorrespondence}
		Suppose $0\leq m<n<\infty$. Then, for any correspondence $R\in\mathcal{R}(\Sp^m,\Sp^n)$, there is a $\Z_2$-correspondence $\widetilde{R}\in\mathcal{R}_{\Z_2}(\Sp^m,\Sp^n)$ such that $\dis(\widetilde{R})=\dis(R)$.
	\end{lemma}


	%%%%%%%%%%%%%%%%%%%%%%%%
	\input{proofs/proof_prop_Z2dGHSmSn.tex}
	%%%%%%%%%%%%%%%%%%%%%%%%

	Therefore, by the Main Theorem (see pg.\pageref{page:main-theorem}) and \Cref{prop:Z2dGHSmSn}, the following inequalities hold:
	\begin{align*}
		2\dgh(\Sp^m,\Sp^n)=2\dgh^{\Z^2}(\Sp^m,\Sp^n)&\geq\dht^{\Z^2}\big((\Pfin(\Sp^m),\diam_p^{\Sp^m}),(\Pfin(\Sp^n),\diam_p^{\Sp^n})\big)\\
		&\geq \di^{\Z^2}\big(\h_k(\vrm_p(\Sp^m;\bullet)),\h_k(\vrm_p(\Sp^n;\bullet))\big).
	\end{align*}

	However, the following corollary and remark show that the topological lower bound


	$\dht^{\Z^2}\big((\Pfin(\Sp^m),\diam_p^{\Sp^m}),(\Pfin(\Sp^n),\diam_p^{\Sp^n})\big)$ is \emph{strictly better} than the algebraic lower bound $\di^{\Z^2}\big(\h_k(\vrm_p(\Sp^m;\bullet)),\h_k(\vrm_p(\Sp^n;\bullet))\big)$.

	\begin{corollary}\label{cor:SmSnlbddvr}
		For all $0<m<n<\infty$, we have the following
		$$\dht^{\Z_2}\big((\Pfin(\Sp^m),\diam_\infty^{\Sp^m}),(\Pfin(\Sp^n),\diam_\infty^{\Sp^n})\big)\geq c_\infty^{\Z_2}(\Sp^m,\Sp^n;0)\geq\zeta_m.$$
	\end{corollary}
	\begin{proof}
		Apply \Cref{prop:strongercGpXYlbdd} for $p=\infty$ and  item (1) of \Cref{prop:cforspheres}.
	\end{proof}

	\begin{remark}\label{rmk:vrminftysmsn}
		By \Cref{cor:vrvrmdIGsame} and \Cref{prop:Gdnmatter}, we have that
		$$\di^{\Z^2}\big(\h_k(\vrm_\infty(\Sp^m;\bullet)),\h_k(\vrm_\infty(\Sp^n;\bullet))\big)=\frac{\zeta_m}{2}.$$
	\end{remark}


	\subsubsection{The case of $\dgh^{\Z_2}(\Sp_\mathrm{E}^m,\Sp_\mathrm{E}^n)$.}\label{sec:Z2dGHEsphere}

	Recall that $\Sp_{\mathrm{E}}^m$ denotes the $m$-sphere equipped with the Euclidean metric inherited from $\mathbb{R}^{m+1}$ (see page~\pageref{notations}). In \cite[Section 9]{lim2023gromov}, we computed several nontrivial bounds for the Gromov–Hausdorff distance $\dgh(\Sp_{\mathrm{E}}^m, \Sp_{\mathrm{E}}^n)$ for arbitrary dimensions $0 \leq m < n \leq \infty$. However, unlike the case of spheres equipped with the geodesic metric, we were unable to determine the exact values of $\dgh(\Sp_{\mathrm{E}}^1, \Sp_{\mathrm{E}}^2)$, $\dgh(\Sp_{\mathrm{E}}^1, \Sp_{\mathrm{E}}^3)$, and $\dgh(\Sp_{\mathrm{E}}^2, \Sp_{\mathrm{E}}^3)$. This was primarily due to the difficulty of establishing tight lower bounds for $\dgh(\Sp_{\mathrm{E}}^m, \Sp_{\mathrm{E}}^n)$—in contrast to the geodesic case $\dgh(\Sp^m, \Sp^n)$, where exact values could be computed (see~\cite[Theorem B]{lim2023gromov}) using the helmet trick described above. In other words, the helmet trick fundamentally relies on the structure of the geodesic distance on spheres and is therefore inapplicable when the spheres are equipped with their Euclidean metrics.

	\medskip
	In this section, however, we successfully compute the exact value of the $\Z_2$-Gromov–Hausdorff distances $\dgh^{\Z_2}(\Sp_{\mathrm{E}}^m,\Sp_{\mathrm{E}}^n)$ for the specific cases $(m,n) = (1,2), (1,3),$ and $(2,3)$, leveraging the lower bound established in~\Cref{sec:Gindices}.


	\begin{theorem}\label{thm:SEmSEm+1lb}
		For any positive integers $0 < m < n < \infty$, we have
		$$\dgh^{\Z_2}(\Sp_\mathrm{E}^m,\Sp_\mathrm{E}^n)\geq\frac{1}{2}\,\sqrt{\frac{2m+4}{m+1}}.$$
	\end{theorem}
	\begin{proof}
		Apply \Cref{Gdhtstability}, \Cref{prop:strongercGpXYlbdd} for $p=\infty$, and  item (2) of \Cref{prop:cforspheres}.
	\end{proof}

	It turns out that the lower bound given in \Cref{thm:SEmSEm+1lb} is tight in the following cases.

	\begin{corollary}\label{cor:SEmnprecise}
		We have the following equalities:
		\begin{enumerate}
			\item $\dgh^{\Z_2}(\Sp_\mathrm{E}^1,\Sp_\mathrm{E}^{2})=\frac{\sqrt{3}}{2}$,

			\item $\dgh^{\Z_2}(\Sp_\mathrm{E}^1,\Sp_\mathrm{E}^{3})=\frac{\sqrt{3}}{2}$, and

			\item $\dgh^{\Z_2}(\Sp_\mathrm{E}^2,\Sp_\mathrm{E}^{3})=\sqrt{\frac{2}{3}}.$
		\end{enumerate}
	\end{corollary}
	\begin{proof}
		Apply \Cref{thm:SEmSEm+1lb}, \cite[Lemma 9.7]{lim2023gromov}, and the fact that the correspondences of \cite[Propositions 1.16,1.18,1.19]{lim2023gromov} are actually all $\Z_2$-correspondences.
	\end{proof}

	\Cref{thm:SEmSEm+1lb} and \Cref{cor:SEmnprecise} lead to formulating the following conjecture (cf. \cite[Conjecture 1]{lim2023gromov}):

	\begin{conjecture}
		For all positive integers $m$,  we have that $\dgh^{\Z_2}(\Sp_\mathrm{E}^m,\Sp_\mathrm{E}^{m+1})=\frac{1}{2}\,\sqrt{\frac{2m+4}{m+1}}$.
	\end{conjecture}

	By adapting a construction from \cite{lim2021gromov}, we can obtain the following upper bound (which is tight for $m=1$).
	\begin{proposition}\label{prop:SEmSEm+1ub}
		For any positive integers $m\geq 1$, we have
		$$\dgh^{\Z_2}(\Sp_\mathrm{E}^m,\Sp_\mathrm{E}^{m+1})\leq\frac{1}{2}\eta_m^{\mathrm{E}}$$
		where
		$$\eta_m^{\mathrm{E}}:=\begin{cases}2\sqrt{\frac{m+2}{m+3}}&\text{for odd }m\\ \sqrt{2+2\sqrt{\frac{m}{m+4}}}&\text{for even }m.\end{cases}$$
	\end{proposition}

