		\section{Methods}
	\subsection{RPA approximation for spin correlation functions}


	We consider the magnon Hamiltonian 
	\begin{equation}
		H = \sum_{\boldsymbol{k} }\epsilon(\boldsymbol{k}) a^\dagger_{\boldsymbol{k} }a_{\boldsymbol{k}}- \frac{\Delta}{2N}\sum_{\boldsymbol{q,k,p}}J(\boldsymbol{q})\,  a^\dagger_{\boldsymbol{k+q}}a^\dagger_{\boldsymbol{p-q}}a_{\boldsymbol{p}}a_{\boldsymbol{k}},
	\end{equation}
	where $\epsilon(\boldsymbol{k})$ and $J(\boldsymbol{q})$ were given in Eqs.~\eqref{dispersion}~and~\eqref{Jz_q}, respectively. The Keldysh action for this model is given by~\cite{kamenev2023field}
	\begin{equation}
		S = S_0 + S_\mathrm{int},
	\end{equation}
	\begin{equation}
		S_0 = \sum_{s=\pm}\sum_{\boldsymbol{k} }s \int dt \, \bar{a}_{s,{\boldsymbol{k}}} \Big(i \partial_t - \epsilon(\boldsymbol{k})\Big)a_{s,\boldsymbol{k}},
	\end{equation}
	\begin{equation}
		S_\mathrm{int} = \frac{\Delta}{2N}\sum_{s=\pm} \sum_{\boldsymbol{q,k,p}} s \int dt \,  J(\boldsymbol{q})\, \bar{a}_{s,\boldsymbol{k+q}}a_{s,\boldsymbol{k}} \,\bar{a}_{s,\boldsymbol{p-q}}a_{s,\boldsymbol{p}},
	\end{equation}
	where $s=\pm$ specifies the branch of the Keldysh contour to which the fields belong. We define the density field similarly to the main text:
	\begin{equation}\label{rho_def}
		\rho_s(\boldsymbol{q},t)= \frac{1}{\sqrt{N}}\sum_{\boldsymbol{k} }\bar{a}_{s,\boldsymbol{k}}(t) a_{s,\boldsymbol{k+q}}(t),
	\end{equation}
	such that we can write $S_\mathrm{int}$ as
	\begin{multline}
		S_\mathrm{int} =\frac{\Delta}{2}\sum_{s,\boldsymbol{q}} s  \int dt \,
		J(\boldsymbol{q})\rho_s(\boldsymbol{-q},t)\rho_s(\boldsymbol{q},t)\\+\sum_{s,\boldsymbol{q}} s  \int dt \,   \varphi_s(\boldsymbol{-q},t)\bigg( \rho_s(\boldsymbol{q},t) - \frac{1}{\sqrt{N}}\sum_{\boldsymbol{k} }\bar{a}_{s,\boldsymbol{k}}(t) a_{s,\boldsymbol{k+q}}(t) \bigg),
	\end{multline}
	where $\varphi$ is Lagrange multiplier field that imposes the condition in Eq.~\eqref{rho_def}. In the next step, we apply a rotation and express fields in the classic/quantum basis define as~\cite{kamenev2023field}
	\begin{equation}
		a_c = \frac{1}{\sqrt{2}}(a_+ + a_-), \quad  a_q = \frac{1}{\sqrt{2}}(a_+ - a_-).
	\end{equation}
	In RPA, we integrate out magnon fields and keep the resulting effective action to quadratic order in $\rho$ and $\varphi$~\cite{altland2010condensed}:
    \begin{figure}[!t]
        \centering
        \includegraphics[width=0.45\linewidth]{gauss_fm_3.pdf}\includegraphics[width=0.45\linewidth]{gauss_fm_5.pdf}\\ \includegraphics[width=0.45\linewidth]{zz_fm_3.pdf} \includegraphics[width=0.45\linewidth]{zz_fm_5.pdf}
        \caption{Longitudinal spin correlation function for $\Delta=2$, obtained from the truncated Gaussian approximation (top row) and TWA (bottom row) at two different times. The other parameters are $L=100$,  $J/h=0.2$, $\Delta=2$, $\xi/h=0.1$ and $S=5$.}
        \label{fig:gauss_vs_twa}
    \end{figure}
	\begin{equation}
		S \approx \frac12 \sum_{\boldsymbol{q}} \iint \Phi^T(\boldsymbol{-q},t) \cdot \boldsymbol{M}_{\boldsymbol{q}}(t,t')\cdot  \Phi(\boldsymbol{q},t'),
	\end{equation}
	where $\Phi(\boldsymbol{q},t)= \big(\rho_c(\boldsymbol{q},t), \varphi_c(\boldsymbol{q},t), \rho_q(\boldsymbol{q},t), \varphi_q(\boldsymbol{q},t)\big)^T$ and 
    \begin{equation}
        \boldsymbol{M}_{\boldsymbol{q}}(t,t') = \begin{pmatrix} \boldsymbol{0}_{2\times2} & M_{\boldsymbol{q}}^A(t,t') \\ & \\ M_{\boldsymbol{q}}^R(t,t') & M_{\boldsymbol{q}}^K(t,t')
			\end{pmatrix},
    \end{equation}
    with
    \begin{equation}
        \boldsymbol{M}^R_{\boldsymbol{q}}(t,t')= \big(\boldsymbol{M}^A_{\boldsymbol{q}}(t,t')\big)^\dagger = \begin{pmatrix} \Delta J(\boldsymbol{q})\delta(t-t') & \delta(t-t') \\ \delta(t-t') &  -\Pi_{\boldsymbol{q}}(t,t')
			\end{pmatrix},
    \end{equation}
    \begin{equation}
        \boldsymbol{M}^K_{\boldsymbol{q}}(t,t') = \begin{pmatrix} 0 & 0 \\ 0 & +2i\tilde{C}^{zz}_{\boldsymbol{q}}(t,t')
			\end{pmatrix}.
    \end{equation}
    $\Pi_{\boldsymbol{q}}$ was defined in Eq.~\eqref{pi_free} and $\tilde{C}^{zz}_{\boldsymbol{q}}$ is the symmetric density correlation function in the truncated Gaussian approximation
	\begin{multline}
		\tilde{C}^{zz}_{\boldsymbol{q}}(t,t') =  \frac12 \Big\langle \Big\{\rho(\boldsymbol{q},t),\rho(\boldsymbol{-q},t')\Big\}\Big\rangle_\mathrm{Gauss} \\ = \frac{1}{2N} \sum_{\boldsymbol{k}} \Big(\langle a^\dagger_{\boldsymbol{k}}(t)a_{\boldsymbol{k}}(t')\rangle \langle  a_{\boldsymbol{k+q}}(t)a^\dagger_{\boldsymbol{k+q}}(t')\rangle \\ + \langle a^\dagger_{\boldsymbol{k+q}}(t')a_{\boldsymbol{k+q}}(t)\rangle \langle  a_{\boldsymbol{k}}(t')a^\dagger_{\boldsymbol{k}}(t)\rangle\Big).
	\end{multline}
     The connected part of the symmetric correlation function can be found from
    \begin{equation}
    C^{zz}_{\boldsymbol{q}}(t,t') =  \frac12 \langle \rho_c(\boldsymbol{q},t)\, \rho_c(-\boldsymbol{q},t')\rangle_c,
    \end{equation}
    which is given by the inverse of $M_{\boldsymbol{q}}$. In the frequency domain
    \begin{equation}\
        C^{zz}_{\boldsymbol{q}}(\omega)=\big[M^{-1}_{\boldsymbol{q}}(\omega)\big]_{11}=\frac{\tilde{C}^{zz}_{\boldsymbol{q}}(\omega)}{\big|1+\Delta J(\boldsymbol{q})\tilde{\chi}^{zz}_{\boldsymbol{q}}(\omega)\big|^2},
    \end{equation}
    which is Eq.~\eqref{C_zz_RPA_w} of the main text.


