\begin{lemma}
\label{lem:3hsing}
    The function $[a_0,a_1,a_2] \in \AAA_K(\mathcal{G}_{3S})$ is singular if and only if $a_{0}+a_{1}+a_{2} = 0_{K}$. Thus: 
    \begin{equation*}
        \mathcal{S}_{K}(\mathcal{G}_{3 S}) = \{ [a_{0},a_{1}, -(a_{0} + a_{1})] \in \AAA_K(\mathcal{G}_{3 S}) : a_{0}, a_{1} \in K \}. 
    \end{equation*}
\end{lemma} 

\begin{proof}
    As in \cref{2h_singnosuppbody}, a function $f \in \SSS_{K}(\GGG_{3S})$ is singular if and only if it has no support on the body of the snake. Thus, as in \cref{singfuncform}, 
the values of $f$ on the heads of the snake must sum to $0$ in order for $f$ to have no support on the body. 
\end{proof}


\begin{prop} \label{listofsing_3h}
    The singular functions of $\AAA_K(\mathcal{G}_{3 S})$ are: 
    \[ \mathcal{S}_{K}(\mathcal{G}_{3 S}) = \{ k[0,1,-1] : k \in K \} \sqcup \{ k[1, b , -(b+1)]: b,k \in K \}. \]
\end{prop} 

\begin{proof}
    Given $a_{0}, a_{1}, a_{2} \in K$, we know by \cref{lem:3hsing} that $ [ a_{0}, a_{1}, a_{2} ]$ is singular if and only if $a_{0}+a_{1}+a_{2} = 0$. Since $0+1-1 = 0 = 1 + b -(b+1) = 0$ for all $b \in K$, all scalar multiples of $[0,1,-1]$ and $[1, b, -(b+1)]$ are singular functions. 

    Conversely, choose any $f = [ a_{0}, a_{1}, -(a_{0} + a_{1}) ] \in \mathcal{S}_{K}(\GGG_{3S})$. There are two cases: 
    \begin{itemize}
    \item if $a_{0} = 0$, then $f = [0, a_{1}, -a_{1}] = a_{1} [ 0,1,-1]$ is of the required form; 

    \item if $a_{0} \neq 0$, then $\frac{1}{a_0} \in K$ and $f = a_0 [1, \frac{a_1}{a_0}, \frac{-a_{1}}{a_0} - 1]$. Setting $b := \frac{a_1}{a_0} \in K$, we have $f = a_{0} [1, b, -(b+1)]$, which is of the required form. 
    \end{itemize}
\end{proof} 

\begin{theorem}
\label{prop:fullideal}
    The ideal $\mathcal{S}_K(\mathcal{G}_{3 S})$ is principal and generated by $[0,1,-1]$: 
    \[ \mathcal{S}_K(\mathcal{G}_{3 S}) = \langle [0,1,-1] \rangle. \]
\end{theorem} 

\begin{proof}
From \cref{listofsing_3h}, we have only to prove that $\SSS_{K}(\GGG_{3S}) \subseteq \langle [0,1,-1] \rangle$. It suffices to show that, for any $b \in K$, we have $[1,b,-(b+1)] \in \langle [0,1,-1] \rangle $. Fix $b\in K$. Then we have a function $[1, b, 1-b] \in \AAA_K(\GGG_{3S})$, and \eqref{conv} shows that: 
    \begin{align*}
        [1,-b,1-b] * [0,1,-1] =& [0-(-b)+(1-b), -(1-b)+1+0, (-b)-1+0] \\ 
        =& [1,b,-(b+1)] \in  \langle [0,1,-1] \rangle
    \end{align*} 
   as required.  
\end{proof} 


\subsection{Singular ideals of $\AAA_K(\mathcal{G}_{3 S})$} 
In this subsection, we provide a full description of the singular ideals of $\AAA_K(\GGG_{3S})$, as well as a first necessary and sufficient condition for their existence. 

Recall that a singular ideal of $\AAA_K(\mathcal{G}_{3 S})$ is a proper subset of $\SSS_{K}(\GGG_{3S})$ that is also an ideal of $\AAA_K(\mathcal{G}_{3 S})$. 

\begin{lemma}
\label{lem:principal}
    All singular ideals of $\AAA_K(\mathcal{G}_{3 S})$ are principal. 
\end{lemma} 
\begin{proof}
    Assume towards a contradiction that $J \subsetneq \SSS_{K}(\GGG_{3S})$ is a non-zero singular ideal of $\AAA_K(\GGG_{3S})$ that is not generated by a single function. Choose $f \neq g$ nonzero generators of $J$. As $J$ is a proper subset of $ \SSS_{K}(\GGG_{3S})$, neither $f$ nor $g$ may be multiples of $[0,1,-1]$. Thus, by \cref{listofsing_3h}, we have $m \neq n \in K$ such that $f$ is a scalar multiple of $[1,m,-(m+1)]$ and $g$ is a multiple of $[1,n,-(n+1)]$. 
    Therefore, as $m-n \neq 0$, we have: 
    \begin{align*}
        \frac{1}{m-n}([1,m,-(m+1)] - [1,n,-(n+1)]) = [0,1,-1] \in J
    \end{align*} 
    a contradiction. Thus $J$ must be singly generated. 



