As the function $[0,1,-1]$ generates all of $\SSS_K(\GGG_{3S})$, \cref{lem:principal} tells us that any singular ideal of $\AAA_K(\mathcal{G}_{3 S})$ -- if they exist -- must be of the form $\langle [1, b , -(b+1)] \rangle$ for some $b \in K$. 

We now show that the existence of an appropriate $b$ is dependent on the choice of $K$. 

For $b \in K$, define the quantity $\Delta_{b}$ by\footnote{The reader familiar with number theory will recognize here the third cyclotomic polynomial (evaluated at $b$): this is not a coincidence, as we will explore in the future.}: 
\begin{equation} \label{3h:discr}
\Delta_{b} := b^{2}+b+1.
\end{equation}
The following two lemmas show that $\AAA_K(\GGG_{3S})$ has singular ideals (associated with $b$) if and only if $\Delta_b = 0_K$. 

\begin{lemma} \label{3h_DeltaNeqZero_inverses} 
    Let $b \in K$ such that $\Delta_b \neq 0$. Then:
    \[ \langle [1,b,-(b+1)] \rangle = \SSS_{K}(\GGG_{3S}) . \] 
    That is, $\langle [1,b,-(b+1)] \rangle$ is not a proper subset of $\SSS_K(\GGG_{3S})$, and therefore not a singular ideal of $\AAA_K(\GGG_{3S})$. 
\end{lemma} 

\begin{proof}
    As $\Delta_b \neq 0$, we have the function $\frac{1}{\Delta_b}[0,-b, -(b+1)] \in \AAA_K(\GGG_{3S})$. Then \cref{conv} gives: 
\[
        \frac{1}{\Delta_b}[0,-b, -(b+1)] * [1,b,-(b+1)] = \frac{1}{\Delta_b} [0,\Delta_b,-\Delta_b] = 
        [0,1,-1] \ . 
    \]
Then by \cref{prop:fullideal} we have $\SSS_{K}(\GGG_{3S}) \subseteq \langle [1,b,-(b+1)] \rangle$, and the reverse inclusion is clear. 
\end{proof} 

\begin{lemma} \label{3h_DeltaZero_scalarconv} 
    Let $b \in K$ such that $\Delta_b = 0$. Then: 
    \[ \langle [1, b, -(b+1)] \rangle \subsetneq \SSS_K(\GGG_{3S}) . \]
    That is, $\langle [1, b, -(b+1)] \rangle$ is a singular ideal of $\AAA_K(\GGG_{3S})$.
\end{lemma}

\begin{proof}
We show that for all $f \in \AAA_K(\GGG_{3S})$:  
 \[ f * [1,b,-(b+1)] = k_{f} [1,b,-(b+1)]  \] 
for some $k_{f} \in K$. 

First, note that as $\Delta_b = b^2+b+1  = 0$, we have: 
    \begin{align*}
b(b+1) = -1 \ \text{ and } (b+1)^{2} = b^{2}+2b+1 = b. 
    \end{align*} 

Choose $f = [a_0,a_1,a_2] + \sum\limits_{B \in F_w} a_B 1_B \in \AAA_K(\GGG_{3S})$. 
Set: \[k_f := a_0 -(b+1)a_1 +ba_2 \in K .\] 

Then: 
    \begin{align*}
        bk_f &= ba_0 -b(b+1)a_1 + b^2 a_2 \\ 
        &= ba_0 + a_1 -(b+1)a_2 \\ 
        \\ 
        &\text{ and: } \\ 
        \\
        -(b+1)k_f &= -(b+1)a_0 + (b+1)^2 a_1 -b(b+1)a_2 \\ 
        &= -(b+1)a_0 +ba_1 +a_2. 
    \end{align*} 

By \cref{conv} we now have: 
\begin{align*}
    f * [1,b,-(b+1)] =& 
         [ a_0 -(b+1)a_1 +ba_2,
         -(b+1)a_2 +ba_0+a_1, ba_1-(b+1)a_0+a_2 ] \\ 
         =& [k_f, bk_f, -(b+1)k_f]
\end{align*}
as claimed. 

Now, if $[0,1,-1] \in \langle [1,b,-(b+1)] \rangle$, we must have $k_f \in K$ such that $k_f = 0$ and $bk_f = 1$; a contradiction. Thus $[0,1,-1] \notin \langle [1,b,-(b+1)] \rangle$, and so $\langle [1, b, -(b+1)] \rangle \subsetneq \SSS_K(\GGG_{3S})$, as needed. 
\end{proof} 

