%Second, let $b \in K$ be a root of $x^2+x+1$. Then $\Delta_b = b^2+b+1 = 0$, so $\langle [1,b,-(b+1)] \rangle$ is a proper subset ideal of $\mathcal{S}_K(\mathcal{G}_{3 S})$. 
%\end{proof} 



We can deduce a first interesting case, which recovers a well-known result when $K = \mathbb{C}$ is the field of complex numbers. %{\color{red}{Reference to add here for this result over $\mathbb{C}$.}}
\begin{cor} \label{3h:algclosedfields}
    If $K$ is an algebraically closed field, then $\mathcal{S}_{K}(\mathcal{G}_{3 S})$ is not $S$-simple. 
\end{cor}

At the opposite of the case of algebraically closed field, let us provide an example where $\mathcal{S}_{K}(\GGG_{3S})$ is $S$-simple.
\begin{example} \label{3h:exchar2}
    If $K = \mathbb{Z} / 2 \mathbb{Z}$, then $\Phi_{3}(T)$ has no root in $K$ as:
    \[\displaystyle \Phi_{3}(0) = 0^{2} + 0^{2} + 1 = 1 \not= 0 \ \text{ in } \Z/2\Z \text{ and } \Phi_{3}(1) = 1^{2} + 1^{2} + 1 = 1 \not= 0 \ \text{ in } \Z/2\Z \ .\]
    By \cref{3h_nonsimpleiffroots}, this ensures that $\SSS_{\Z/2\Z}(\GGG_{3S})$ is $S$-simple.
\end{example}

The next result provides the number of singular ideals of $\AAA_K(\GGG_{3S})$ when $K$ is a splitting field for $\Phi_{3}(T)$.

\begin{thm}
\label{thm:3hsIdeals}
Let $K$ be a splitting field of $\Phi_{3}(T) = T^{2} + T + 1$. 
\begin{enumerate}
\item  If $char(K) = 3$, then there is a unique singular ideal of $\AAA_K(\GGG_{3S})$, namely $\langle [1,1,1] \rangle$. 
  \item If $char(K) \neq 3$, then there are exactly two singular ideals of $\AAA_K(\GGG_{3S})$, namely $\langle [1, b, -(b+1)] \rangle$ and $\langle [1, -(b+1), b ] \rangle$, where $b$ is a root of $\Phi_{3}(T)$ in $K$. 
  \end{enumerate}
\end{thm}

\begin{proof}
Let $K$ be a splitting field of $\Phi_{3}(T) = T^{2} + T + 1$, which by \cref{3h_nonsimpleiffroots} says $\SSS_{K}(\GGG_{3S})$ is not $S$-simple. Let $b$ be a root of $\Phi_{3}(T)$ in $K$: then the other root of $\Phi_{3}(T)$ in $K$ is equal to $-(b+1)$. It remains to check whether these two roots are equal in $K$. 
\begin{itemize}
\item If $char(K) = 3$, then $\Z/3\Z$ is the prime subfield of $K$ and we have the following equalities in $K$ :
\[\displaystyle b + (b+1) = 2b + 1 = -b + 1 \ .\]
Hence, $b = -(b+1)$ in $K$ if and only if $-b + 1 = 0$, i.e $b = 1$. Moreover, $1 \in K$ is the only root (with multiplicity $2$) of $\Phi_{3}(T)$ in $K$, as: 
\[\displaystyle (T - 1)^{2} = T^{2} - 2T + 1 = T^{2} + T + 1 \ \text{ in $\Z/3\Z[T] \subseteq K[T]$ \ . } \]

\item If $char(K) \neq 3$, then pick a root $b \in K$ of $\Phi_{3}(T)$ and assume that it is a multiplicity $2$ root of $\Phi_{3}(T)$. Then $\Phi_{3}(T) = (T - b)^{2}$, i.e.:
\begin{equation} \label{3h:polchar}
\displaystyle  T^{2} + T + 1 = T^{2} - 2bT + b^{2} \ . 
\end{equation}
The comparison of the degree $1$ coefficients in \eqref{3h:polchar} implies that $2(-b) = 1$; hence, $2 = 1_K$, and so $char(K) \neq 2$.
The comparison of the constant terms in \eqref{3h:polchar} now implies that $b^{2} = 1$, i.e. $b = 1$ or $b = -1$, which (as $char(K) \neq 2$) are two distinct elements.

But recall that $b$ being a multiplicity $2$ root for $\Phi_{3}(T)$ means that $b = -(b+1)$, so we must either have $1 = -(1+1)$ (if $b = 1$), or $-1 = -(-1+1)$ (if $b = -1$). The first case becomes $3=0$ and so only holds if $char(K) = 3$, a contradiction; the second case cannot happen as $-1 \not= 0$ in any $K$. Thus $K$ contains two distinct roots, and so $\AAA_K(\GGG_{3S})$ has exactly two singular ideals. 
\end{itemize}



\end{proof}

\subsection{Splitting fields of $\Phi_{3}(T)$}
We conclude by providing a classification of the splitting fields of $\Phi_{3}(T)$, using elementary number-theoretic arguments. 
\subsubsection{Case 1 -- Splitting fields of characteristic zero}
First, we consider the case where $\mathrm{char}(K) = 0$: this implies that $K$ contains a subfield isomorphic\footnote{We assume that such an isomorphism is fixed once for all, and we will write $\Q \subseteq K$ accordingly.} to $\Q$. Fix an algebraic closure $\overline{K}$ of $K$ that contains $\overline{\Q}$, and let $i, \sqrt{3} \in \overline{\Q} \subset \overline{K}$ be fixed square roots of $-1$ and $3$ respectively. We then have the following result.

\begin{prop}
The field $K$ is a splitting field of $\Phi_{3}(T)$ if and only if it contains $\frac{i\sqrt{3}}{2}$ -- that is, if $K$ is a field extension of $\Q\left[\frac{i\sqrt{3}}{2}\right]$.

In this case, the two singular ideals of $\AAA_K(\GGG_{3S})$ are: 
    \[ \displaystyle \left\langle \left[1,\frac{-1 + i\sqrt{3}}{2} , \frac{-1 - i\sqrt{3}}{2} \right] \right\rangle \text{ and } \left\langle \left[1, \frac{-1 - i\sqrt{3}}{2}, \frac{-1 + i\sqrt{3}}{2}\right] \right\rangle. \]
\end{prop}

\begin{proof}
In $\overline{K}[T]$ we have:
\[ \begin{array}{rcl} \displaystyle \left(T - \frac{-1 + i\sqrt{3}}{2} \right)\left(T - \frac{-1-i\sqrt{3}}{2}\right) & = &  \displaystyle T^{2} + \frac{1 - i\sqrt{3} + 1 + i\sqrt{3}}{2} T + \frac{(1 - i\sqrt{3})(1 + i\sqrt{3})}{4} \\
& = & T^{2} + T + 1 \\
& = & \Phi_{3}(T) \ , 
\end{array}\]
and so the roots of $\Phi_{3}(T)$ in $\overline{K}$ are $\displaystyle \frac{-1 + i\sqrt{3}}{2} \text{ and } \frac{-1 - i\sqrt{3}}{2}$.
\end{proof}

% [OTHER WEIRD CHAR 0 FIELDS ? : Say hello to p-adic numbers :-) This is why I suppressed any reference to embedding in the field of complex numbers ;-) This is also why I do not use the notation Z_{p} for the finite field with p elements, it can be misleading.]

\subsubsection{Case 2 -- Splitting fields of positive characteristic} Assume now that $K$ is a splitting field of $\Phi_{3}(T)$ of positive characteristic $p$, and let $\F_{p} = \Zmodp$ be the prime subfield of $K$. We have the following result, which is standard but included here for completeness.

\begin{lemma} \noindent  
\begin{enumerate}
\label{3h_Deltabfactors0or1mod3}
    \item\label{it1:galois} 
    Let $b \in \mathbb{Z}$. 
    All factors of $b^{2}+b+1$ are congruent to either $0 \ \mathrm{mod}\  3$ or $1 \ \mathrm{mod} \ 3$. 
    \item \label{it2:galois} The field $\F_{p}$ is a splitting field for $T^{2}+T+1$ if and only if $p = 3$ or $p \equiv 1 \ \mathrm{mod} \ 3$. 
    \end{enumerate}

\end{lemma}

\begin{proof}
    First we prove \eqref{it1:galois}. If $q$ is a prime factor of $b^{2}+b+1$, then $q$ is odd as $b^{2}$ and $b$ have the same parity, hence $b^{2} + b + 1$ is odd. Moreover, $q$ must also divide
    \[ 4 (b^{2}+b+1) = (2b+1)^{2} + 3, \] 
    so $-3$ must be a quadratic residue mod $q$. Hence, the corresponding Legendre symbol $\left(\frac{-3}{q}\right)$ must be equal to $1$. The multiplicativity of the Legendre symbol and  the Quadratic Reciprocity Law applied to the pair of odd primes $(3,q)$ then imply that $q$ must satisfy: 
    \begin{equation} \label{LRQ}
\displaystyle \left(\frac{-1}{q}\right)\left(\frac{q}{3}\right) = \left(-1\right)^{\frac{q-1}{2}} \ . 
    \end{equation}
Depending on whether $-1$ is a square mod $q$, i.e. whether we have $q \equiv 1 \ \mathrm{mod} \ 4$, we have the following dichotomy: 
\begin{itemize}
\item If $-1$ is a square mod $q$, i.e. if $q \equiv 1 \ \mathrm{mod} \ 4$, then Equation \eqref{LRQ} becomes:
\[\displaystyle\left(\frac{q}{3}\right) = 1 \ , \text{ i.e. $q$ is a square mod $3$.} \]
As $q$ is a prime number, it cannot be divisible by $3$ unless it equals $3$ (in which case it is a square mod $3$); as the only squares mod $3$ are $0$ and $1$, we obtain that either $q = 3$, or $q$ is congruent to $1$ mod $3$.
\item If $-1$ is not a square mod $q$, i.e. if $q \equiv -1 \ \mathrm{mod} \ 4$, then Equation \eqref{LRQ} becomes:
\[\displaystyle -\left(\frac{q}{3}\right) = -1, \ \text{ i.e.} \left(\frac{q}{3}\right) = 1 \ ,\]
and we can use again the previous argument to prove that either $q = 3$, or $q$ is congruent to $1$ mod $3$.
\end{itemize}
% Doing the exercise is fun, no ? :-) 

Now we prove \eqref{it2:galois}. Suppose that $\mathbb{F}_p$ is a splitting field for $T^{2}+T+1$. Then there exists an integer $b \in \Z$ such that $b^{2}+b+1 \equiv 0 \ \mathrm{mod} \ p$. This means that $p$ is a prime factor of $b^{2}+b+1$ in $\mathbb{Z}$, and \eqref{it1:galois} above ensures that either $p = 3$ or $p \equiv 1 \ \mathrm{mod} \ 3$, as claimed. 

First, assume that  $p = 3$. Then $char(\mathbb{F}_3) = 3$, so by \cref{thm:3hsIdeals} we have that $\mathbb{F}_3$ is a splitting field of $\Phi_{3}(T)$.

    Second, assume that $p \equiv 1 \ \mathrm{mod} \ 3$. Then $p$ is a quadratic residue mod $3$, so the multipli- cativity of the Legendre symbol and the Quadratic Reciprocity law ensure that: 
    \begin{equation} \label{CSLRQ}
    \displaystyle \left(\frac{-3}{p}\right) = \left(\frac{-1}{p}\right)\left(\frac{3}{p}\right) = \left(\frac{-1}{p}\right)\left(\frac{p}{3}\right) (-1)^{\frac{p-1}{2}} = (-1)^{\frac{p-1}{2}} \left(\frac{-1}{p}\right)\ . 
    \end{equation}
    Since $-1$ is a quadratic residue mod $p$ if and only if $p \equiv 1 \ \mathrm{mod} \ 4$, which is itself equivalent to $(-1)^{\frac{p-1}{2}} = 1$, we obtain that the right-hand side of \eqref{CSLRQ} is equal to $1$, which proves that $-3$ is a quadratic residue mod $p$.

% CAREFUL IN YOUR ARGUMENT, YOU CANNOT REQUIRE THAT N IS BOTH ODD AND BETWEEN 0 AND P-1 ! THIS IS WHY I MADE THE FOLLOWING CHANGES IN THE LAST PART OF THE PROOF.
    Now: choose integer $n$ such that $p$ divides $n^{2} + 3$. Replacing $n$ by $n + p$ if necessary, we can assume without loss of generality that $n$ is odd, and write $n = 2b + 1$ with $b \in \Z$. Thus, we have:
    \[\displaystyle (2b+1)^{2} \equiv -3 \ \mathrm{mod} \ p \ , \text{ i.e. } \ 4b^{2} + 4b +4 \equiv 0 \ \mathrm{mod} \ p \ .\]
    As $p$ is odd (hence coprime to $4$), this proves that such a integer $b$ satisfies: 
    \[ \displaystyle b^{2} + b + 1 \equiv 0 \ \mathrm{mod} \ p \ . \]
    The image $b \in \F_{p}$ is thus a root of $\Phi_{3}(T) = T^{2} + T + 1$ in $\F_{p}$. Thus $\F_{p}$ is a splitting field of $\Phi_{3}(T)$, so the proof is complete.
\end{proof}



\begin{cor} \label{3h:CSnonsimple}
    If the characteristic of $K$ is either $3$ or a prime integer congruent to $1$ modulo $3$, then the ideal $\mathcal{S}_{K}(\mathcal{G}_{3 S})$ is not $S$-simple. 
\end{cor}

\begin{proof}
Let $p >0$ be the characteristic of $K$, and $\F_{p} \subseteq K$ be the prime subfield of $K$. Our assumption on $p$ ensures by \cref{3h_Deltabfactors0or1mod3} that $\F_{p}$ and therefore $K$ are splitting fields of $\Phi_{3}(T)$. The conclusion follows from \cref{3h_nonsimpleiffroots}.
\end{proof}

\begin{remark}
\cref{3h:CSnonsimple} provides a sufficient condition, but certainly not a necessary one. Indeed, if $K$ is an algebraic closure of $\F_{2} = \Z/2\Z$, then $K$ is a field of positive characteristic $2$: it does not satisfy the assumption of \cref{3h:CSnonsimple}. Nevertheless, \cref{3h:algclosedfields} ensures that, as $K$ is algebraically closed, $\SSS_{K}(\GGG_{3S})$ is not $S$-simple. 
\end{remark}



