\section{Background on Differential Equations and Stochastic Processes}\label{app:background-ODE-MT}

This appendix contains some preliminaries that are required to follow the proofs in the main text, in particular on the theory of ordinary differential equations (ODEs) and initival value problems (IVPs), as well as probability and Markov theory.

\subsection*{Ordinary Differential Equations}\label{appx:ode}

An ordinary differential equation is a description of the local dynamics of a system in terms of its current state and derivatives; in particular, a first order ordinary differential equation describes the rate of change of a quantity $x$ as a function of the current time $t$ and the current state $x(t)$. That is, $x'(t)=f(t,x(t))$ for some $f$. A problem with such a description along with boundary data (e.g., $x(t_0)=x_0$) is called an \emph{initial value problem}. A main theme in differential equations is to understand when such local descriptions give rise to solutions, either in some small neighborhood of a point, or globally. Lipschitz continuity is an important property in differential equations, as it is a sufficient condition for the existence of such solutions as we will argue next.

\begin{definition}[Lipschitz continuity]
A function $f:\bbR^m\to\bbR^n$ is \emph{Lipschitz continuous} under norm $\norm{\cdot}$ on $U\subseteq\bbR^m$ if there exists some $L\geq 0$ such that
\begin{align*}
\norm{f(x)-f(y)}\leq L\norm{x-y},
\end{align*}
for all $x,y\in U$. We call $L$ the Lipschitz constant of $f$ on $U$.
\end{definition}

The standard result for the existence and uniqueness of solutions to initial value problems of ordinary differential equations comes from variations of the Picard-Lindel\"of Theorem, which roughly state that if $f$ is Lipschitz at a point, a solution exists and is unique in some neighborhood of that point. The following is a version that extends this fact to the positive reals for the one dimensional case, adapted from \cite[Theorem~2.2 and Corollary~2.6]{teschl2024ordinary}.

\begin{theorem}\label{thm:picardlindelof}
Consider the initial value problem
\begin{align}\label{eq:ivp-appendix}
    x'=f(t,x), \quad x(t_0)=x_0,
\end{align} where $(t_0,x_0)\in U$ for some open set $U \subseteq \bbR^2$ and $f:U\to\bbR$ is a Lipschitz continuous function. Then if $[t_0,\infty)\cross\bbR\in U$ there exists a unique solution $x(t)$ to~\eqref{eq:ivp-appendix} for all $t\geq t_0$.
\end{theorem}

\subsection*{Probability and Markov theory}\label{appx:mc}

In this section we briefly cover some fundamentals of general probability and Markov theory. The treatment is not fully formal as we omit certain regularity conditions and assumptions -- however such conditions are immediately satisfied by the objects we study in this paper. We refer to \cite{grimmett2020probability} for further details.

Recall that a random variable $X$ on a probability triple $(\Omega,\mcF,\mb)$ is a measurable real-valued function from $(\Omega,\mcF)$ to $(\bbR,\mcL)$.


\begin{definition}[Stochastic process]
A stochastic process on a state space $\mcS\subseteq\bbR$ is a set of random variables $\set{X_t}_{t\in\mcT}$ on the same probability triple that are indexed by some $\mcT$ (thought of as time) and each take values in $\mcS$ (that is, $X_t\in\mcS$ for all $t\in\mcT$).
\end{definition}

Common cases are $\mcT=\set{0,1,2,3,\dots}$ or $\mcT=\set{0,\Delta,2\Delta,3\Delta,\dots}$ for some $\Delta>0$ for \emph{discrete time} processes and $\mcT=[0,\infty)$ for \emph{continuous time} processes.

\paragraph{Convergence.} Consider a sequence $\set{X^n}_{n=1,2,\dots}$ of random variables on the same probability triple $(\Omega,\mcF,\mb)$. We recall some ways in which $X^n$ may converge to some other random variable $X$.

\begin{definition}[Convergence in Probability]
The sequence of random variables $\{X^n\}_{n=1,2,\dots}$ converges to the random variable $X$ in probability, denoted $X^n\stackrel{\mcP}{\to}X$ if for all $\eps>0$,
\begin{align*}
\lim_{n\to\infty}\mbb{\abs{X^n-X}\geq\eps}\to 0,
\end{align*}
as $n\to\infty$.
\end{definition}

A stochastic process can converge pointwise (for all $t\in\mcT$) in probability, but clearly a stronger condition is that of uniform convergence, where this convergence is uniform through $\mcT$.

\begin{definition}[Uniform convergence in probability]
The sequence of stochastic processes $\set{X^n_t}_{t\in\mcT,n=1,2,\dots}$ on $\mcT$ converges uniformly in probability to $\set{X_t}_{t\in\mcT}$ if for all $\eps>0$,
\begin{align*}
\mbb{\sup_{t\in\mcT}\abs{X^n_t-X_t}\geq\eps}\to0,
\end{align*}
as $n\to\infty$.
\end{definition}

That is, the maximum deviation over the index set between the $X^n_t$ and $X_t$ is itself bounded and vanishes in probability.

\begin{definition}[Convergence in $r$-mean]
The sequence of random variables $\{X^n\}_{n=1,2,\dots}$ converges to a random variable $X$ in $r$-mean, denoted $X^n\stackrel{L^r}{\to}X$ if for all $\eps>0$, $\lim_{n\to\infty}\meb{\abs{X^n-X}^r}\to 0$, as $n\to\infty$.
\end{definition}

Note in particular that for $r=1$, this is convergence in mean, that is, $\meb{X^n}\to\meb{X}$. Convergence in probability does not automatically imply convergence in $r$-mean, though the converse is true. One special case where the converse holds is when $X^n$ and $X$ are bounded.

\begin{lemma}\label{lem:r-mean-conv}
Suppose $X^n\stackrel{\mcP}{\to}X$ and $\abs{X}\leq M$ and $\abs{X^n}\leq M$ for some $M\geq 0$. Then $X^n\stackrel{L^r}{\to}X$ for all $r\geq 1$.
\end{lemma}

\paragraph{Markov processes.} A Markov process is a stochastic process which additionally satisfies a property of being \emph{memoryless}, meaning that its future evolution is entirely dictated by its current state independent of the past. We restrict ourselves to time-homogeneous Markov chains with finite state spaces.

\begin{definition}[Discrete time Markov chain]
A \emph{discrete time Markov chain} is a stochastic process on a finite state space $\mcS\subseteq\bbR$ and index set $\mcT=\set{0,1,2,3,\dots}$ that satisfies the property
\begin{align*}
\mbb{X_{t+1}=j\given X_t=i_t,X_{t-1}=i_{t-1},\dots,X_1=i_1}=\mbb{X_{t+1}=j\given X_t=i_t},
\end{align*}
for all states $j,i_\cdot\in\mcS$ and all $t\in \mcT$. The evolution of such a Markov chain is therefore determined by its (one step) \emph{transition probabilities} $p(i,j)$ for $i,j\in\mcS$, arranged in a transition matrix $P$ defined by
\begin{align*}
p(i,j)=\mbb{X_{t+1}=j\given X_t=i}.
\end{align*}
\end{definition}

\begin{definition}[Continuous time Markov chain]
A \emph{continuous time Markov chain} is a stochastic process on a finite state space $\mcS\subseteq\bbR$ and index set $\mcT=[0,\infty)$ that satisfies the property
\begin{align}\label{eq:continuous-MC}
\mbb{X_{t+s}=j\given X_t=i,X_{t_l}=i_l,X_{t_{l-1}}=i_{l-1},\dots,X_0=i_0}&=\mbb{X_s=j\given X_0=i},
\end{align}
for all $s\geq 0$, $t>t_l>t_{l-1}>\cdots>t_1>t_0\geq 0$ and all $j,i,i_\cdot\in\mcS$.
\end{definition}

Note that~\eqref{eq:continuous-MC} implies that the transition times must also be random and memoryless. It turns out that this property embodies continuous time Markov chains with a large amount of structure. In particular, the time between transitions (when the chain moves from one state to another) must be exponentially distributed (this is the only memoryless continuous distribution, satisfying $\mbb{X\leq x\given X\geq y}=\mbb{X\leq x-y}$).

In the discrete case the evolution was defined by the one step transition probabilities $P$. In the continuous case, these are replaced by a Matrix-valued function of time $P(t)$. It turns out there is a compact way to represent the possible transitions via \emph{transition rates} $q(i,j)$ that describe the instantaneous rate of moving from state $i$ to state $j$ as formalized by the following lemma.

\begin{theorem}[Transition rates]
For a continuous time Markov chain on a finite state space, let $p(i,j;t)=\mbb{X_t=j\given X_0=i}$ for $t\geq 0$. Denote by $P(t)$ the matrix with entries $p(i,j;t)$. Then there exists a \emph{transition rate} matrix $Q$ with entries $q(i,j)$ that is the unique solution to
\begin{align*}
Q=\lim_{t\to0}\frac{P(t)-I}{t},
\end{align*}
note that $q(i,i)=-\sum_{j\neq i}q(i,j)$. 

\end{theorem}

We next introduce the concept of a Poisson point process in order to build continuous time Markov chains from discrete time ones. Intuitively, a homogeneous Poisson point process simply counts the number of events that have happened until time $t$, where the time between successive events is iid and exponentially distributed.

\begin{definition}[Homogeneous Poisson point process]
Let $\lambda>0$. Define the stochastic process $\{H_t\}_{t\geq 0}$ with state space $\set{0,1,2,\dots}$ as follows. For $i=1,2,\dots$ let $E_i\distributed\Exp(\lambda)$, and let $H_t=\sup_{i=0,1,2,\dots}\set{\sum_{j=1}^iE_j\leq t}$. We call $\{H_t\}_{t\geq 0}$ the homogeneous Poisson process with rate $\lambda$ on $t\geq 0$. Note that $H_t\distributed\Pois(\lambda t)$, and in particular $\meb{H_t}=\lambda t$ for all $t\geq 0$.
\end{definition}

A Homogeneous Poisson point process is an example of a very simple Markov chain.

\begin{lemma}
A homogeneous Poisson point process with rate $\lambda$ is a continuous time Markov chain on the countable state space $\mcS=\set{0,1,2,\dots}$ with transition rates
\begin{align*}
q(i,j)&=\piecewise{
\lambda,& j=i+1, \\
-\lambda,& j=i, \\
0,& \text{otherwise}.
}
\end{align*}
\end{lemma}

Given a continuous time Markov chain, one can decompose it into a discrete time Markov chain that describes the transition probabilities at jump times, and a per-state rate of an Exponential distribution that describes the duration that the chain stays in that state before jumping to the next.

The following theorem gives one variation of a theorem that allows easily constructing continuous time Markov chains from discrete time Markov chains.

\begin{theorem}[Constant-rate Markov Chain Embedding]\label{thm:embedding}
Let $\set{X_n}_{n=0,1,2,\dots}$ be a discrete time Markov chain on finite state space $\mcS$ with $X_0=s_0$ for some initial state $s_0\in\mcS$. Let $\lambda>0$ be some rate and let $\{H_t\}_{t\geq 0}$ be the homogeneous Poisson point process with rate $\lambda$ on $[0,\infty)$.

Define a stochastic process $\set{Z_t}_{t\geq 0}$ 
by $Z_t=X_{H_t}$. Then $\set{Z_t}_{t\geq0}$ is a continuous time Markov chain whose state space is $\mcS$, initial state is $s_0$, and that has rates $q(i,j)=\lambda p(i,j)$ for $i\neq j$ and $q(i,i)=-\lambda(1-p(i,i))$. This continuous time Markov chain is called an \emph{embedded} chain because its transition rates follow the transition probabilities of the discrete chain, that is, $\mbb{Z_s=j\given Z_t=i}=p(i,j)$ if $H_t=H_s+1$.
\end{theorem}



\paragraph{Martingales.} A martingale is a stochastic process with the property that its expected value in the future is the current value.

\begin{definition}[Martingale]
A stochastic process $\{X_t\}_{t\geq 0}$ is a \emph{martingale} if \, $\meb{X_s\given X_t}=X_t$ for all $s\geq t$.
\end{definition}

The homogeneous Poisson process corrected for its mean is a martingale. That is, $H_t-\lambda t$ is a martingale. The following is a standard result in martingale theory.

\begin{theorem}[Doob's martingale inequality]\label{thm:doob}
If $\{X_t\}_{t\geq 0}$ is a martingale, then for all $T\geq 0$ and $C>0$,
\begin{align*}
\mbb{\sup_{t\in[0,T]}X_t\geq C}\leq \frac{\meb{\max(X_T,0)}}{C}.
\end{align*}
Further, for $r\geq 1$, we have
\begin{align*}
\mbb{\sup_{t\in[0,T]}\abs{X_t}\geq C}\leq\frac{\meb{\abs{X_T}^r}}{C^r}.
\end{align*}
\end{theorem}

\section{Extension to Schools Having Multiple Seats}\label{appx:q_ge_1}

In Section~\ref{para:multiple-seats}, we set up an analogue of the discrete model of Section~\ref{sec:discrete} in the case that each school has $q=1,2,3,\dots$ seats. In this appendix, we roughly trace the steps of Section~\ref{sec:models} for the case of arbitrary $q$. We first describe the continuous model for the multiple-seat case, then discuss how Theorem~\ref{thm:xts} may be extended to this case. In particular, we develop the initial value problem equivalents of~\eqref{eq:ivp} for arbitrary $q=1,2,3,\dots$ and $d\geq 1$. We discuss the solutions to the initial value problem for $d=1$, then discuss how we may use this solution for $d>1$.

\paragraph{The continuous model with multiple seats.} Recall that $T^{n,d}_i$ is the number of schools with $q$ seats taken after students $\set{1,2,3,\dots,i-1}$ have had their turn, and $S^k_i$ is the number of schools with $k$ seats taken at this point for $k=1,2,\dots,q-1$. We again keep track of the continuous analogues, for $i=\floor{tn}$, letting $x_d(t)$ be the proportion of schools with all seats taken, and $y_d^k(t)$ be the proportion of schools with $k$ seats taken for $k=0,\dots,q-1$. Initially all schools have no seats taken, so
\begin{align}
x_d(0)=0, \qquad y_d^0(0)=1, \qquad y_d^k(0)=0,\quad k=1,2,\dots,q-1. \label{eq:q_ge_1_iv}
\end{align}
As we discuss in the main body, the probability that student $t$ is matched to any student goes to $1-x_d(t)^d$ in probability, and the proportion of time they get matched to a school with $k$ seats taken is proportional to $S^k_i$, we therefore get that the rate at which schools with $k$ seats taken become schools with $k+1$ seats taken is
\begin{align*}
(1-x_d(t)^d)\frac{y_d^k(t)}{\sum_{m=0}^{q-1}y_d^m(t)}&=\frac{1-x_d(t)^d}{1-x_d(t)}y_d^k(t),
\end{align*}
since $x_d(t)+\sum_{k=0}^{q-1}y_d^k(t)=1$. Note further that this is a positive flow into $y_d^{k+1}$ and negative for $y_d^k$. We have each of these flows from $y_d^k$ to $y_d^{k+1}$ for $k=0,\dots,q-1$ and one from $y_d^{q-1}$ to $x_d$. For convenience, define
\begin{align*}
\gamma_d(t)=\frac{1-x_d(t)^d}{1-x_d(t)}.
\end{align*}
Denoting derivative with respect to time with a dot for clarity to avoid multiple superscripts, this gives us the following differential equation
\begin{align}
\dot y_d^0(t)&=-\gamma_d(t)y_d^0(t), \nonumber \\
\dot y_d^k(t)&=\gamma_d(t)(y_d^{k-1}(t)-y_d^k(t)),\qquad k=1,\dots,q-1, \label{eq:q_ge_1_ode} \\
\dot x_d(t)&=\gamma_d(t)y_d^q(t). \nonumber
\end{align}

\paragraph{Connection with the discrete model.} Following the steps in Section~\ref{sec:continuous-to-discrete}, we can apply a slightly more general equivalent of Theorem~\ref{thm:xts} for this multi-dimensional case, again from \cite[Theorem~17.3.1]{kroese2013handbook} to prove the following lemma.

\begin{lemma}\label{lem:xts-q_ge_1}
Fix $d\in\bbN$, $q=1,2,\dots$ and define the initial value problem for $\{x_d,y_d^k\}$ for $k=0,1,\dots,q-1$ via~\eqref{eq:q_ge_1_iv} and~\eqref{eq:q_ge_1_ode}. For $t\geq 0$, let $T^{n,d}_i$ and $S^k_i$ for $k=0,\dots,q-1$ be as in Section~\ref{para:multiple-seats}. Then $n^{-1}T^{n,d}_{\floor{tn}}\to x_d(t)$ and $n^{-1}S^k_{\floor{tn}}\to y_d^k(t)$ for $k=0,1,\dots,q-1$ uniformly in probability as $n\to\infty$, where $\{x_d(t),y_d^k(t)\}$ for $k=0,1,\dots,q-1$ is the unique solution satisfying the initial value problem of \eqref{eq:q_ge_1_iv} and~\eqref{eq:q_ge_1_ode} for $t\geq 0$.
\end{lemma}
\begin{proof}
The proof follows identically to the proof of Theorem~\ref{thm:xts} in Section~\ref{sec:proofs}, adapted to the case of multiple equations.
\end{proof}

\paragraph{Dynamics of the multiple seats model for $d=1$.} Observe that for $d=1$, we have $\gamma_d\equiv 1$. As in the earlier continuous model, we can again solve this explicitly. It's easy to see we get $y_1^0(t)=\exp(-t)$, and for $k=1$, we now have $\dot y_1^1=\exp(-t)-y_1^1$, which yields $y_1^1(t)=t\exp(-t)$. Following this pattern, we have
\begin{align}
y_1^k(t)&=\frac{t^k}{k!}e^{-t}, \qquad k=0,\dots,q-1, \nonumber \\
x_1(t)&=1-e^{-t}\sum_{k=0}^{q-1}\frac{t^k}{k!}.\label{eq:q_ge_1_sol_d1}
\end{align}

Readers familiar with probability or phase-type distributions will note that this is the cumulative distribution function of an Erlang distribution with parameters $k=q$ and $\lambda=1$. Figure~\ref{fig:q_ge_1_sample} shows the solution for $d=1$, $q=4$.

\begin{figure}[!h]
    \centering
    \includegraphics[width=0.75\linewidth]{arxiv-plots/q_ge_1_sample.pdf}
    \caption{Solution to the multiple-seat continuous market for $d=1$, $q=4$.}
    \label{fig:q_ge_1_sample}
\end{figure}

Recall finally that a student $t$ gets matched with probability that goes to $1-x_d(t)^d$. Denote by $M^{n,d,q}_{i}$ be the indicator random variable of whether a student $i$ gets matched with $n$ schools, $d$ length lists, and $q$ seats per school. We therefore have
\begin{align*}
\mbb{M^{n,d,q}_i=1}\stackrel{\mcP}{\to}1-x_d(t)^d,
\end{align*}
as $n\to\infty$. This follows similarly to Lemma~\ref{lem:prob-to-xprime} via Lemma~\ref{lem:xts-q_ge_1}. Note that the difference to Lemma~\ref{lem:prob-to-xprime} is simply that this time $x_d'(t)$ is not necessarily equal to $1-x_d(t)^d$.

\paragraph{Discussion of dynamics for $q>1$.} The fact that $\gamma_d$ multiplies every equation in~\eqref{eq:q_ge_1_ode} suggests the following idea. Define an initial value problem for $\tau_d$ as
\begin{align}\label{eq:tau_ivp}
\tau_d(0)&=0, \qquad 
\dot\tau_d(t)=\frac{1-x_1(\tau_d(t))^d}{1-x_1(\tau_d(t))}.
\end{align}
It is not hard to show that the following now holds
\begin{align}
y_d^k(t)&=y_1^k(\tau_d(t)), \qquad k=0,1,\dots,q-1 \nonumber \\
x_d(t)&=x_1(\tau_d(t)). \label{eq:q_ge_1_sol_dgen}
\end{align}
This now suggests a procedure for computing solutions to the initial value problem defined by~\eqref{eq:q_ge_1_iv} and~\eqref{eq:q_ge_1_ode}: first compute the solution to~\eqref{eq:q_ge_1_sol_d1}, then solve~\eqref{eq:tau_ivp} to compute $\tau_d(t)$ and plug it into~\eqref{eq:q_ge_1_sol_dgen}.

We further remark that one can interpret $\tau_d(x)$ as describing the ratio of how much faster students are matched to schools when they get $d>1$ tries compared to a single try. $1-x_1^d$ is the probability of getting matched to any school given a list of length $d$ and $1-x_1$ is that probability with lists of length $1$. The interpretation via~\eqref{eq:q_ge_1_sol_dgen} then tells us that the case for general $d$ is exactly the same as for $d=1$ except now the rate at which students are matched to schools is rescaled by a factor of $\tau_d$.


\section{Missing Proofs }\label{appx:lemmas_and_proofs}

\paragraph{From Section~\ref{sec:implications-extensions}.}

\corSerial*

\begin{proof}
By symmetry, we have $$\mbb{R^{n,d}=1}= \frac{n}{m} \mbb{H^{n,d}_1(m)=1},$$ where $m$ is the number of students in the market. From Lemma~\ref{lem:school-love}, $\mbb{H^{n,d}_1(m)=1}$ increases with $d$, so $\mbb{R^{n,d}=1}$ also increases with $d$.
\end{proof}

\begin{theorem}\label{thm:ig}
Suppose $x(d,t)\geq 0$ is defined implicitly via
\begin{align*}
\int_0^x\frac{1}{1-v^d}\,dv=t.
\end{align*}
Then for $t \in [0,1]$, $d\geq 1$, we have
\begin{align}
\int_0^x\frac{1+\log u}{1-u^d}\,du\leq 0.\label{eq:ig-to-prover}
\end{align}
\end{theorem}
\begin{proof}
Observe that $x(d,t)$ is monotonically increasing in $t$ and that $x(d,t)\leq t$. The integrand in \eqref{eq:ig-to-prover} is negative on $u\in[0,1/e]$ and vanishes at $u=1/e$ after which it increases monotonically. The results therefore follows immediately when $x(d,t)\in[0,1/e]$, and since the integral increases for $x\in[1/e,1)$, it suffices to show the result for $x(d,1)$.
In Lemma~\ref{lem:xd-bounds} we show that
\begin{align*}
x(d,1)\leq\br{\frac{d+1}{2d+1}}^{1/d},
\end{align*}
for $d\geq 1$ and in Lemma~\ref{lemma:x1a_ineq} we show
\begin{align*}
\int_0^{\br{\frac{d+1}{2d+1}}^{1/d}}\frac{1+\log(u)}{1-u^d}\,du&\leq0,
\end{align*}
for $d \geq 1$ which completes the proof.
\end{proof}

\lemXdBounds*
\begin{proof}
We first show the upper bound. Recall $x(d,1)$ is defined via
\begin{align*}
1=\int_0^{x(d,1)}\frac{du}{1-u^d}.
\end{align*}
Since $(1-u^d)$ is strictly positive, it suffices to show
\begin{align*}
\int_0^{x(d,1)}\frac{du}{1-u^d}\leq \int_0^{\br{\frac{d+1}{2d+1}}^{1/d}}\frac{du}{1-u^d},
\end{align*}
or equivalently
\begin{align*}
1\leq \int_0^{\br{\frac{d+1}{2d+1}}^{1/d}}\frac{du}{1-u^d}.
\end{align*}

$(1-u^d)^{-1}$ is the sum of a geometric series for $u^d\in(0,1)$, so with $z\in(0,1)$ write

\begin{align}
\int_0^z\frac{du}{1-u^d}&=\int_0^z\sum_{r=0}^\infty u^{rd}\,du \nonumber \\
&=\sum_{r=0}^\infty\int_0^zu^{rd}\,du \nonumber \\
&=\sum_{r=0}^\infty\frac{z^{rd+1}}{rd+1} \nonumber \\
&=z\br{1+\sum_{r=1}^\infty\frac{(z^d)^r}{rd+1}}\label{eq:x1a-mid} \\
&\geq z\br{1+\sum_{r=1}^\infty\frac{(z^d)^r}{r(d+1)}} \nonumber \\
&=z\br{1-\frac{1}{d+1}\log(1-z^d)}.\label{eq:x1a-last}
\end{align}

The validity of exchanging the order of summation and integration follows by the Tonelli theorem since the integrand is non-negative. Now substitute $z=\br{\frac{d+1}{2d+1}}^{1/d}$ and $q=1/d$. We have $q\in(0,1]$ and $z=\br{\frac{q+1}{q+2}}^q$, and we need to show that \eqref{eq:x1a-last} is lower bounded by $1$. After some rearranging, this reduces to showing
\begin{align*}
\log(2+q)&\geq\br{\frac{q+1}{q}}\br{\br{1+\frac{1}{q+1}}^q-1},
\end{align*}
for $q \in (0,1]$, which we show in Lemma~\ref{lemma:first_ineq}.

For the lower bound, we apply identical reasoning until~\eqref{eq:x1a-mid}, but must show that for $z=\br{\frac{2d+1}{4d+1}}^{1/d}$, we have
\begin{align*}
1\geq z\br{1+\sum_{r=1}^\infty\frac{(z^d)^r}{rd+1}}.
\end{align*}
We again substitute $q=1/d$ and this time get $z=\br{\frac{q+2}{q+4}}^q$, and this yields
\begin{align*}
z\br{1+\sum_{r=1}^\infty\frac{(z^d)^r}{rd+1}}&=z\br{1+\frac{z^d}{d+1}+\sum_{r=2}^\infty\frac{(z^d)^r}{rd+1}} \\
&\leq z\br{1+\frac{z^d}{d+1}+\sum_{r=2}^\infty\frac{(z^d)^r}{rd}} \\
&=z\br{1+\frac{z^d}{d+1}-\frac{z^d}{d}-\frac{1}{d}\log(1-z^d)} \\
&=z\br{1-\frac{z^d}{d(d+1)}-\frac{1}{d}\log(1-z^d)} \\
&=\br{\frac{q+2}{q+4}}^q\br{1-\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{\frac{2}{q+4}}}.
\end{align*}
To complete the proof, we therefore need
\begin{align*}
\br{\frac{q+2}{q+4}}^q\br{1-\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{\frac{2}{q+4}}}&\leq 1
\end{align*}
for $q \in (0,1]$, which we show in Lemma~\ref{lemma:technical_2}.
\end{proof}

\begin{lemma}\label{lemma:technical_2}
$1-\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{\frac{2}{q+4}}\leq \br{\frac{q+4}{q+2}}^q$ for $q\in[0,1]$.
\end{lemma}
\begin{proof}

\begin{align*}
&1-\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{\frac{2}{q+4}}\leq \br{\frac{q+4}{q+2}}^q \\
& \iff \br{\frac{q+4}{q+2}}^q+\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{2+\frac{q}{2}}-1\geq 0 \\
&\iff \br{\frac{q+4}{q+2}}\br{\frac{q+4}{q+2}}^{q-1}+\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{2+\frac{q}{2}}-1\geq 0.
\end{align*}

Now apply Claim~\ref{claim:ineqs2} and Claim~\ref{claim:two-ineqs} to get
\begin{align*}
&\br{\frac{q+4}{q+2}}\br{\frac{q+4}{q+2}}^{q-1}+\frac{q^2(q+2)}{(q+1)(q+4)}-q\log\br{2+\frac{q}{2}}-1 \\
&\qquad\geq\br{\frac{q+4}{q+2}}\br{\frac{1}{2}+\frac{q}{8}(1+4\log(2))}+\frac{q^2(q+2)}{(q+1)(q+4)}-q\br{\frac{1}{4} \left(1-\frac{q}{10}\right) q+\log (2)}-1 \\
&\qquad=\frac{q^2 \left(q^4-3 q^3-11 q^2-20 q^2 \log (2)+53 q-100 q \log (2)+100-80 \log (2)\right)}{40 (q+1) (q+2) (q+4)}
\end{align*}

This is positive if $q^4-3 q^3-11 q^2-20 q^2 \log (2)+53 q-100 q \log (2)+100-80 \log (2)\geq 0$, but this is a polynomial with two real roots, both at $q>1$, so since this equation is positive for $q=0$, it must be non-negative for all $q\in[0,1]$.
\end{proof}


\begin{claim}\label{claim:ineqs2}
$\left(\frac{q+4}{q+2}\right)^{q-1}\geq\frac{1}{2}+\frac{q}{8}(1+4\log(2))$ for $q\in[0,1]$.
\end{claim}
\begin{proof}
Observe this holds at equality for $q=0$ and apply Claim~\ref{claim:two-ineqs} to the the derivative of the difference to get:
\begin{align*}
\frac{\partial}{\partial q}\sbr{
\br{\frac{q+4}{q+2}}^{q-1}-\frac{1}{2}-\frac{q}{8}(1+4\log(2))}&\geq\frac{1}{16}\br{(q+2)(q+4)\log\br{\frac{q+4}{q+2}}-2(q+4\log(2))}.
\end{align*}
This is now true if and only if
\begin{align}\label{eq:name}
\log\br{\frac{q+4}{q+2}}-\frac{2(q+4\log(2))}{(q+2)(q+4)}\geq 0.
\end{align}
One easily checks
\begin{align*}
\frac{\partial}{\partial q}\sbr{\log\br{\frac{q+4}{q+2}}-\frac{2(q+4\log(2))}{(q+2)(q+4)}}=\frac{4 (-3 q+4 q \log (2)-8+12 \log (2))}{(q+2)^2 (q+4)^2}\geq 0,
\end{align*}
where the inequality holds since both the numerator and the denominator are nonnegative. Since one readily verifies that~\eqref{eq:name} is valid for $q=0$, the claim follows.
\end{proof}

\begin{claim}\label{claim:two-ineqs}
$\br{\frac{q+4}{q+2}}^q\geq\frac{(q+4)^2}{16}$ and $\log\left(2+\frac{q}{2}\right)\leq\log(2)+\frac{1}{4}\left(1-\frac{q}{10}\right)q$ for $q\in[0,1]$.
\end{claim}
\begin{proof}

For the first:
\begin{align*}
\br{\frac{q+4}{q+2}}^q&\geq\frac{(q+4)^2}{16} \\
\iff \br{\frac{q+4}{q+2}}^q&\geq\br{1+\frac{q}{4}}^2 \\
\iff \log\br{\frac{q+4}{q+2}}&\geq \frac{2}{q}\log\br{1+\frac{q}{4}}.
\end{align*}
Note that the left hand side always exceeds $\log(5/3)>1/2$, and the right hand side never exceeds $1/2$ because $\log(1+q/4)\leq q/4$.

For the second, take the derivative of the difference of the left term and the right term:
\begin{align*}
\frac{\partial}{\partial q}\br{\log\left(2+\frac{q}{2}\right)-\frac{1}{4}\left(1-\frac{q}{10}\right)q-\log (2)}&=\frac{1}{q+4}+\frac{q-5}{20} \\
&=\frac{(q-1)q}{20(q+4)},
\end{align*}
which is now clearly non-positive.
\end{proof}

\begin{lemma}\label{lemma:x1a_ineq}
For $d\geq 1$, we have
\begin{align*}
\int_0^{\br{\frac{d+1}{2d+1}}^{1/d}}\frac{1+\log(u)}{1-u^d}\,du&\leq0.
\end{align*}
\end{lemma}
\begin{proof}
Change variables with $q=1/d$ (so $q\in[0,1]$) and define $A=\frac{d+1}{2d+1}=\frac{q+1}{q+2}$, then write
\begin{align*}
\int_0^{A^q}\frac{1+\log(u)}{1-u^{1/q}}\,du&=\int_0^{A^q}\sum_{n=0}^\infty u^{n/q}(1+\log(u))\,du \\
&=\sum_{n=0}^\infty\int_0^{A^q}u^{n/q}(1+\log(u))\,du \\
&=\sum_{n=0}^\infty\br{\int_0^{A^q}u^{n/q}\,du+\int_0^{A^q}u^{n/q}\log(u)\,du} \\
&=\sum_{n=0}^\infty\br{\frac{qA^{n+q}}{n+q}+\frac{qA^{n+q}\log(A^q)}{n+q}-\frac{q^2A^{n+q}}{(n+q)^2}} \\
&=A^q\br{(1+\log(A^q))\sum_{n=0}^\infty\frac{qA^n}{n+q}-\sum_{n=0}^\infty\frac{q^2A^n}{(n+q)^2}} \\
&=A^q\br{(1+\log(A^q))\br{1+\frac{qA}{q+1}+qA^2\sum_{n=2}^\infty\frac{A^{n-2}}{n+q}}-1-\frac{q^2A}{(q+1)^2}-\sum_{n=2}^\infty\frac{q^2A^n}{(n+q)^2}} \\
&\leq A^q\br{(1+\log(A^q))\br{1+\frac{qA}{q+1}+2qA^2(\log(4)-1)}-1-\frac{q^2A}{(q+1)^2}} \\
&\leq A^q\br{(1+q\log(A))2A(1+qA(\log(4)-1))-1-\frac{q^2}{(q+2)^2}} \\
&\leq A^q\br{\br{1-\frac{2q\log^2(2)}{q+\log(4)}}(1+q\log(2))-1-\frac{q^2}{(q+2)^2}}.
\end{align*}
In the first inequality we removed non-positive terms and applied Lemma~\ref{lemma:bound_polygamma}. In the second we applied the facts that $1+\frac{qA}{q+1}=2A$ and $\frac{q^2}{(q+2)^2}\leq\frac{q^2A}{(q+1)^2}$. The last inequality follows from Lemma~\ref{lemma:bound_log_A} and Lemma~\ref{lemma:bound_1_qAB}.

This quantity is now non-positive if
\begin{align*}
\br{1-\frac{2q\log^2(2)}{q+\log(4)}}(1+q\log(2))-1-\frac{q^2}{(q+2)^2}&\leq 0.
\end{align*}
This holds at equality for $q=0$, so it suffices to show that the derivative is non-positive. Writing $x=\log(2)$, abbreviating by $\cdots$ the left-hand-side of the previous inequality, we have
\begin{align*}
\frac{\partial}{\partial q}\br{\cdots}&=\frac{\partial}{\partial q}\br{\br{1-\frac{2q\log^2(2)}{q+\log(4)}}(1+q\log(2))-1-\frac{q^2}{(q+2)^2}} \\
&=\frac{\partial}{\partial q}\br{q\log(2)-\frac{2q\log^2(2)}{q+\log(4)}(1+q\log(2))-\frac{q^2}{(q+2)^2}} \\
&=-\frac{\partial}{\partial q}\br{2x^2\frac{q}{q+2x}+2x^3\frac{q^2}{q+2x}}+x-\frac{2q(q+2)^2-2q^2(q+2)}{(q+2)^4} \\
&=-2x^2\br{\frac{q+2x-q}{(q+2x)^2}}-2x^3\br{\frac{2q(q+2x)-q^2}{(q+2x)^2}}+x-\frac{4q}{(q+2)^3} \\
&=\frac{(q+2x)^2x-4x^3-2x^3q(q+4x)}{(q+2x)^2}-\frac{4q}{(q+2)^3} \\
&=\frac{xq^2+4qx^2+4x^3-4x^3-2x^3q^2-8x^4q}{(q+2x)^2}-\frac{4q}{(q+2)^3} \\
&=\frac{xq(q+4x-2x^2(q+4x))}{(q+2x)^2}-\frac{4q}{(q+2)^3} \\
&=\frac{qx(1-2x^2)(q+4x)}{(q+2x)^2}-\frac{4q}{(q+2)^3} \\
&=q\br{\frac{\log(2)\br{1-2\log^2(2)}(q+\log(16))}{(q+\log(4))^2}-\frac{4}{(q+2)^3}} \\
&\leq q\br{\frac{\log(2)\br{1-2\log^2(2)}(1+\log(16))}{(0+\log(4))^2}-\frac{4}{(1+2)^3}} \\
&\leq -0.08q \\
&\leq 0,
\end{align*}
\end{proof}

\begin{lemma}\label{lemma:bound_log_A}
For $q\in[0,1]$ and $A=\frac{q+1}{q+2}$,
\begin{align*}
-\frac{\log(2)}{1+q\log(2)}\leq\log(A)\leq -\frac{2\log^2(2)}{q+2\log(2)}.
\end{align*}
\end{lemma}
\begin{proof}
For the first inequality from the thesis, we need

\begin{align*}
\log(A)+\frac{\log(2)}{1+q\log(2)}&\geq 0 \\
\iff \br{1+q\log(2)}\log\br{\frac{q+1}{q+2}}+\log(2)&\geq 0.
\end{align*}

One can readily show that the second derivative is negative, so the function is concave and exceeds a line between the endpoints, where the inequality also holds. This means the inequality holds for all $q\in[0,1]$. More in detail, we have
\begin{align*}
\frac{\partial}{\partial q}\sbr{\br{1+q\log(2)}\log\br{\frac{q+1}{q+2}}}&=\log(2)\log\br{\frac{q+1}{q+2}}+\frac{1+q\log(2)}{(q+1)(q+2)}, \\
\frac{\partial^2}{\partial^2 q}\sbr{\br{1+q\log(2)}\log\br{\frac{q+1}{q+2}}}&=\frac{\partial}{\partial q}\br{\log(2)\log\br{\frac{q+1}{q+2}}+\frac{1+q\log(2)}{(q+1)(q+2)}} \\
&=\frac{\log{2}}{(q+1)(q+2)}+\frac{\log(2)(q+1)(q+2)-(1+q\log(2))(2q+3)}{(q+1)^2(q+2)^2} \\
&=\frac{2\log(2)(q+1)(q+2)-(1+q\log(2))(2q+3)}{(q+1)^2(q+2)^2} \\
&=\frac{\log(2)(2q^2+6q+4)-(1+q\log(2))(2q+3)}{(q+1)^2(q+2)^2} \\
&=\frac{\log(2)(3q+4)-(2q+3)}{(q+1)^2(q+2)^2} \\
&=\frac{q(3\log(2)-2)+4\log(2)-3}{(q+1)^2(q+2)^2}.
\end{align*}

The numerator is linear in $q$ and negative for $q=0$ and $q=1$, while the numerator is strictly positive for every $q$. So, the second derivative is negative for all $q$.

The second inequality from the thesis holds at equality for $q=0$. Further, one can show that the derivative of the difference is negative for $q\in[0,1)$:

\begin{align*}
\frac{\partial}{\partial q}\br{\log(A)+\frac{2\log^2(2)}{q+\log(4)}}&=\frac{1}{(q+1)(q+2)}-\frac{2 \log^2(2)}{(q+\log(4))^2}.
\end{align*}

It is not hard to verify that for $q\in[0,1]$

\begin{align*}
(q+1)(q+2)\geq\frac{(q+\log(4))^2}{2\log^2(2)},
\end{align*}

which completes the proof.

\end{proof}

\begin{lemma}\label{lemma:bound_1_qAB}
For $q\in[0,1]$ and $A=\frac{q+1}{q+2}$, we have

\begin{align*}
2A(1+qA(\log(4)-1))\leq 1+q\log(2).
\end{align*}
\end{lemma}
\begin{proof}
\begin{align*}
2A(1+qA(\log(4)-1))&\leq1+q\log(2) \\
\iff \frac{2(1+q)(1+qA(\log(4)-1))}{2+q}-1-q\log(2)&\leq 0 \\
\iff \frac{q^2 (q (\log (8)-2)-3+\log (16))}{(q+2)^2}&\leq 0 \\
\iff q(\log(8)-2)-3+\log(16)&\leq 0.
\end{align*}

This is increasing in $q$ and one can verify this inequality holds for $q=1$.
\end{proof}

\begin{lemma}\label{lemma:bound_polygamma}
For $A=\frac{q+1}{q+2}$, $q\in[0,1]$, we have
\begin{align*}
\sum_{n=2}^\infty\frac{A^{n-2}}{n+q}&\leq2(\log(4)-1).
\end{align*}
\end{lemma}
\begin{proof}
One can verify that the sum is decreasing in $q$, so the left hand side is maximized at $q=0$. Then, using the fact that $\sum_{n=1}^\infty\frac{2^{-n}}{n}=\log(2)$ (this is the polylogarithm of order $1$ evaluated at $1/2$), we have
\begin{align*}
\sum_{n=2}^\infty\frac{A^{n-2}}{n+q}&\leq\sum_{n=2}^\infty\frac{2^{2-n}}{n}=-2+4\sum_{n=1}^\infty\frac{2^{-n}}{n}=2(\log(4)-1).
\end{align*}
\end{proof}


\begin{lemma}\label{lemma:first_ineq}
For $q\in[0,1]$,
\begin{align*}
1+\br{\frac{q}{q+1}}\log\br{q+2}\geq\br{\frac{q+2}{q+1}}^q.
\end{align*}
\end{lemma}
\begin{proof}
We will show this inequality after taking a logarithm on both sides.

We begin with two bounds for the logarithm, for $x\in[0,1]$, we have
\begin{align}
\log(1+x)&\geq\frac{2x}{2+x}, \label{eq:equnoo} \\
\log(2+x)&\geq\log(2)+\frac{x}{2}-\frac{x^2}{4(1+x)}. \label{eq:eqdue}
\end{align}
Both are easy to verify as they hold for $x=0$ and the difference of the left and the right side has positive derivative on $x\in[0,1]$.
In fact, the first holds for all $x\geq 0$ (note $2x/(2+x)=x-x^2/(2+x)$):

\begin{align*}
\frac{\partial}{\partial x}\br{\log(1+x)-x+\frac{x^2}{2+x}}&=\frac{1}{1+x}-1+\frac{2x(2+x)-x^2}{(2+x)^2} \\
&=\frac{1}{1+x}-1+\frac{(4+x)x}{(2+x)^2} \\
&=\frac{-x(2+x)^2+(4+x)x(1+x)}{(1+x)(2+x)^2} \\
&=\frac{x^2}{(1+x)(2+x)^2}.
\end{align*}

The second for $x\in[0,\sqrt{2}]$:

\begin{align*}
\frac{\partial}{\partial x}\br{\log(2+x)-\log(2)-\frac{x}{2}+\frac{x^2}{4(1+x)}}&=\frac{1}{2+x}-\frac{1}{2}+\frac{8x(1+x)-4x^2}{16(1+x)^2} \\
&=\frac{x(2-x^2)}{4(1+x)^2(2+x)}.
\end{align*}

Applying~\eqref{eq:equnoo} and~\eqref{eq:eqdue} to the logarithm of the left hand side, we have

\begin{align*}
\log\br{1+\br{\frac{q}{q+1}}\log\br{q+2}}&\geq\log\br{1+\br{\frac{q}{q+1}}\br{\log(2)+\frac{q}{2}-\frac{q^2}{4(q+1)}}} \\
&=\log\br{1+\frac{4q(q+1)\log(2)+q^2(q+2)}{4(q+1)^2}} \\
&\geq2\times\frac{4q(q+1)\log(2)+q^2(q+2)}{4(q+1)^2}\times\frac{4(q+1)^2}{4q(q+1)\log(2)+q^2(q+2)+8(q+1)^2} \\
&=\frac{8q(q+1)\log(2)+2q^2(q+2)}{4q(q+1)\log(2)+q^2(q+2)+8(q+1)^2}.
\end{align*}

Next apply Lemma~\ref{lemma:bound_log_A}, to get

\begin{align*}
\frac{q\log(2)}{1+q\log(2)}&\geq q\log\br{\frac{q+2}{q+1}}.
\end{align*}

The proof now hinges on showing that

\begin{align*}
\frac{8q(q+1)\log(2)+2q^2(q+2)}{4q(q+1)\log(2)+q^2(q+2)+8(q+1)^2}&\geq\frac{q\log(2)}{1+q\log(2)}.
\end{align*}
Via simple algebraic manipulation, one can show that this holds if and only if
\begin{align*}
q^2\log(2)-2(1-\log(2))(2\log(2)-1)q+4(\log(2)-1)^2&\geq 0.
\end{align*}
This is now a quadratic in $q$, and in fact it has negative discriminant, so it has no real roots. Further, it is positive at $q=0$, so the quadratic is positive for all $q\in[0,1]$.
\end{proof}


