%    By Claim~\ref{lem4.1}, \( |L^\lambda| < (10C_\mathbb{H})^{\lambda-10}n \). Substituting these into \eqref{eq:6}-\eqref{eq:8} yields \eqref{eq:5}.
\end{proof}

