    %e(L_0, L_{1,2}^4) \leq |L_0||L^4|\leq (10C_\mathbb{H})^{-4}n \quad \text{and} \quad e(\overline{L}_1^4\setminus L_0, L_{1,2}^4) \leq |N_1(u)|(\gamma_\mathbb{H}-1)
    %\]
