% it can be seen that the batch size $n$ is related to the Lipschitz constant $L$ of the model. Although the relationship between $n$ and $L$ is not strictly linear(since$(p_i - y_i)\in(-1,1)$), increasing $n$ expands the range of \( L \), potentially increasing $L$. \
The above derivation demonstrates that the Lipschitz constant of the loss function grows with the batch size $n$, since each additional sample introduces a potential gradient term. Although the contribution of each sample is bounded ($(p_i - y_i)\in(-1,1)$), the cumulative effect leads to a looser Lipschitz bound as $n$ increases. A higher Lipschitz constant of implies that the gradient of the loss with respect to model outputs can vary more sharply, making the backpropagated gradients more volatile. As a result, the model explores a larger and potentially less stable solution space, especially when the temporal information is inconsistent across samples. This explains the degraded performance in large-batch training under temporal discontinuity.



\subsection{Constraints on Multi-head Attention}
\begin{corollary}
        \label{Multi_head}
    If each attention head is continuous and differentiable, then multi-head attention as defined in Eq \ref{eq:multi_head_attn}) is:
\begin{equation}\label{eq:model_lipschitz}
    L_F(Model) \leq \sup_{x \in \mathbb{X}}\| W_0 \|_* \sqrt{\sum_{k=1}^h \left( L_F(Att) \right)^2},
\end{equation}
\begin{align}
    L_F(Att) &\leq \sup_{x \in \mathbb{X}}\left[\frac{1}{d_k} \left[ (mn)^2 \Lambda + m^2 n^{3/2} \Lambda - \frac{2n \sigma^2}{(mn)^2}\Delta  \right]\right]^{\frac{1}{2}}\label{eq:lipschitz-bound},\\
    &\Lambda = \| M_q V^T \|_F \| M_q V^T \|_{\max} \| V \|_F \| V \|_{\max}\label{eq:IAIM},\\
    &\Delta = \left\| \left(\sqrt{S(g(x)) VV^T}\right)^T M_q V^T \right\|_*^2\label{eq:Delta},\\
   &S(g(x)) = softmax(g(x))\label{eq:softmax(g(x))}.
\end{align}

\end{corollary}
In Eq \ref{eq:lipschitz-bound}, \( m \) represents the sequence length, which corresponds to the number of neighborhood nodes considered during the aggregation process. The parameter \( n \) refers to the dimension of the input feature associated with each node. The constant \( \sigma \) is a small positive value introduced specifically to define the lower bound of the softmax function. 

The derived upper bound reveals that the Lipschitz constant of the model is influenced by multiple architectural and data-dependent terms, especially attention structures (e.g., $\Lambda$, $\Delta$). When attention scores become highly uneven or unstable,  the resulting bound becomes looser. This implies that the model's output can exhibit larger variations in response to small changes in the input. Notably, this bound highlights the critical role of attention stability in dynamic graph modeling.

\begin{proof}[Proof Sketch]

\textbf{Input.} Multi-head attention $MultiAtt(x)$ defined as:
\[
MultiAtt(x) = W_0 \left( Att(g(x)_1) \| Att(g(x)_2) \| \dots \| Att(g(x)_h) \right).
\]
\textbf{Step 1.}
Compute the derivative of $MultiAtt(x)$ with respect to $x$:
\[
\frac{\partial (MultiAtt(x))}{\partial x} = W_0 \left( \frac{\partial (Att(g(x)_1))}{\partial x} \| \dots \| \frac{\partial (Att(g(x)_h))}{\partial x} \right).
\]
\textbf{Step 2.}
 Apply the Frobenius norm inequality:
\[
\| AB \|_F^2 \leq \| A \|_*^2 \| B \|_F^2 ,
\]
\[
\left\| \frac{\partial (MultiAtt(x))}{\partial x} \right\|_F^2 \leq \| W_0 \|_*^2 \sum_{k=1}^h L_F(Att)^2.
\]
\textbf{Step 3.}
Using the Cauchy-Schwarz inequality, the H\H{o}lder's inequality and the properties of the softmax function.
\begin{align*}
&\left\| \frac{\partial (Att(x))}{\partial x_1} \right\|_F \leq \frac{1}{d_k} \left( B + C \cdot D \right),\\
&B = - \frac{2n\sigma^2}{(mn)^2} \left\| \left( \sqrt{softmax(g(x)) VV^T} \right)^T M_q V^T \right\|_*^2 ,\\
&C = \left( \sum_{i,j,p,q} (softmax(g(x))_{ij})^4 \right)^{\frac{1}{2}} 
     \left( \sum_{i,j,p,q} (M_q V^T)_{ip}^4 \right)^{\frac{1}{2}}, \\
&D = \left( \sum_{i,j,p,q} V_{jq}^4 \right)^{\frac{1}{2}} + \left( \sum_{i,j,p,q} ((softmax(g(x)) V)_{iq})^4 \right)^{\frac{1}{2}}.
\end{align*}
\textbf{Step 4.}
Applying properties of the softmax function and inequality:
\[
\sum_{i,j} M_{ij}^4  \leq (\|M\|_{\max})^2 \|M\|_F^2,
\]
\[L_F(Att) \leq \sup_{x \in \mathbb{X}}\left[\frac{1}{d_k} \left[ (mn)^2 \Lambda + m^2 n^{3/2} \Lambda - \frac{2n \sigma^2}{(mn)^2}\Delta  \right]\right]^{\frac{1}{2}}.\] 
\end{proof}
