        &\Bigl[ \kappa \bigl( 3\beta_0^{2} - \beta_0^{6} h^{4} + \beta_0^{4} h^{2}(h^{2}-4) + 1 \bigr) \cos((g-h)z) + 2\beta_0^{2} \bigl( (1-3\beta_0^{2}) h^{2} + 2 \bigr) \Bigr]\delta x \\
        &- \beta_0^{2} \Bigl[ \kappa(h^{2}-1)(\beta_0^{2} h^{2}-1) \sin((g-h)z) \delta \varphi - \kappa (\beta_0^{2}-1) (\beta_0^{2} h^{2}-1) (g-h) \sin((g-h)z) \delta x^{\prime} \\
        &+ 2(\kappa \cos((g-h)z) + 1) \Bigl( h\bigl(\beta_0^{2}(h^{2}+1)-2\bigr) \delta \varphi^{\prime} + (\beta_0^{2}-1)(\beta_0^{2} h^{2}-1) \delta x^{\prime \prime} \Bigr) \Bigr]=0 \\
        & \kappa (\beta_0^{2}-1) \delta \varphi(z) (\beta_0^{2} h^{2}-1) (\beta_0^{2} g h-1) \bigl( \kappa(\cos(2(g-h)z) + 3) + 4 \cos((g-h)z) \bigr) \\
        &+ 4\beta_0^{2} (\kappa \cos((g-h)z) + 1) \Bigl[ (\beta_0^{2}-1) \bigl( \kappa(g-h) \sin((g-h)z) \delta \varphi^{\prime}(z)- 2 (\kappa \cos((g-h)z) + 1) \delta \varphi^{\prime \prime} \bigr) \\
        &- 2h \bigl( \beta_0^{2}(h^{2}+1)-2 \bigr) (\kappa \cos((g-h)z) + 1) \delta x + \kappa \bigl( h(\beta_0^{2}(g h^{2}+g-2h)-2g+h) + 1 \bigr) \sin((g-h)z) \delta x \Bigr]=0\,.
    \end{aligned}
\end{equation}
\end{widetext}
The parameters are defined as follows: $g=\mu_\chi/\mu_\phi$, $\kappa=\lambda\Phi_{0\star}/\mu_\chi^2$, $\Omega=\sqrt{GM/(2r_0)^3}=\alpha/2\sqrt{2}r_0$, $\beta_0=\Omega (2r_0)=\alpha/\sqrt{2}$, $h=C/\Omega$.

To determine the stability of this system of linear equations with periodic coefficients, we employ Floquet theory. The procedure involves converting the second-order perturbation equations into a first-order matrix system of the form $\dot{\mathbf{Y}}(z) = \mathbf{A}(z) \mathbf{Y}(z)$, where $\mathbf{Y}(z)$ is the state vector of perturbations and their derivatives (e.g., $\mathbf{Y}_\theta(z) = [\delta\theta(z), \delta\dot{\theta}(z)]^T$) and $\mathbf{A}(z)$ is the periodic coefficient matrix.

For a linear system with a periodic matrix $\mathbf{A}(z)$ of period $T$, Floquet theory states that the long-term stability is determined by the monodromy matrix, $\mathbf{M}$. This constant matrix maps any initial perturbation state $\mathbf{Y}(0)$ to its state after one full period $T = 2\pi/|h - g|$:
\begin{equation}
\mathbf{Y}(T) = \mathbf{M}\mathbf{Y}(0)\,.
\end{equation}
The matrix $\mathbf{M}$ is computed by numerically integrating the system $\dot{\mathbf{Y}} = \mathbf{A}(z)\mathbf{Y}$ over one period with a set of standard basis vectors as initial conditions. The stability is determined by the eigenvalues, $\rho_i$, of $\mathbf{M}$, known as the Floquet multipliers. An orbit is stable only if all of its Floquet multipliers have a magnitude less than or equal to one, $|\rho_i| \le 1$.

We compute the monodromy matrices for the vertical and planar motions, $\mathbf{M}_\theta$ and $\mathbf{M}_{x\varphi}$, numerically. Our analysis confirms that there are significant regions of parameter space where all Floquet multipliers satisfy the stability condition. This analytical result depicts a particle maintaining a stable, localized trajectory in the equatorial plane, and is consistent with by direct numerical integration of the full nonlinear equations of motion presented in the main text (see Fig.~\ref{radial_motion}). 

%As a concrete example, Figure~\ref{fig:combined_analysis} shows the trajectory of a particle with benchmark parameters. The results depict a particle maintaining a stable, localized trajectory in the equatorial plane, consistent with the conclusions of our Floquet analysis. 

Conversely, we have applied the same Floquet analysis to the particle trajectories produced by the quartic interaction. In that case, we find that the resulting orbits are generally unstable, with Floquet multipliers satisfying $|\rho_i| > 1$. This confirms that particles are not trapped and will escape to infinity, a conclusion that is also consistent with our direct numerical solutions showing particle acceleration and ejection (see Fig.~\ref{fourpointtrajectory} and Fig.~\ref{fourpointLorentz}).


\section{Derivation of the Averaged Backreaction Term}
\label{app:backreaction}

In this appendix, we detail the derivation of the time-averaged approximation for the backreaction term $\langle\chi^2\rangle$ used in the main text.

The analysis begins with the formal expression for the expectation value of the squared field operator. In the presence of particle production, this can be expressed in terms of the Bogoliubov coefficients, $\alpha_k$ and $\beta_k$, for each momentum mode $k$. The expectation value contains a contribution from the produced particles (with occupation number $n_k = |\beta_k|^2$) and an oscillatory term~\cite{Kofman:1997yn}:
\begin{equation}
	\langle\chi^2\rangle = \int\frac{\dd[3]k}{(2\pi)^3}\frac{1}{\omega_k(t)} \left( n_k + \operatorname{Re}\left[\alpha_{k} \beta_{k}^{*} e^{-2 i \int_{0}^{t} \omega_{k}(t') dt'}\right] \right)\,,
\end{equation}
%The phase in this  expression is a oscillation term with a very high frequency compared to $\mu_{\phi}$, i.e. $\sim \cos\left( \frac{4\sqrt{ \lambda \Phi }}{\mu_{\phi}}\cos(\mu_{\phi}t) \right)$, plus some small correction. 
%$$
%\left\langle\chi^{2}\right\rangle \approx \frac{1+C \cos \left( \frac{4 \sqrt{ \lambda \Phi_{0} }}{\mu_{\phi}}\cos \mu_{\phi} t \right)}{2 \pi^{2} } \int_{0}^{\infty} \frac{d k k^{2}}{\omega_{k}} n_{k}
%$$
where we have omitted the vacuum fluctuation terms, as they can be renormalized into the mass of $\phi$.

The crucial part of the expression is the oscillatory term. Its time evolution is governed by the phase, which depends on the time-dependent frequency $\omega_k(t)$. In the regime of efficient production, where $\lambda\Phi_0 \gtrsim \mu_\chi^2$, the frequency is approximately $\omega_k \sim \sqrt{\mu_\chi^2+\lambda\phi}\gg \mu_\phi$, the phase in this  expression is equal to $\cos\left( \frac{4\sqrt{ \lambda \Phi }}{\mu_{\phi}}\cos(\mu_{\phi}t) \right)$ plus some small correction. The expression is thus simplified to
\begin{equation}
\left\langle\chi^{2}\right\rangle \approx \left[{1+C \cos \left( \frac{4 \sqrt{ \lambda \Phi_{0} }}{\mu_{\phi}}\cos \mu_{\phi} t \right)}\right] \int_{0}^{\infty} \frac{\dd[3] k}{(2\pi)^3\omega_{k}} n_{k}\,,	
\end{equation}
where $C$ is some constant. Consequently, the phase term $e^{-2i \int \omega_k dt'}$ oscillates at a very high frequency compared to the evolution of the background field $\phi(t)$ itself, which occurs at the low frequency $\mu_\phi$. When $\langle\chi^2\rangle$ acts as a source in the equation of motion for $\phi$, the contribution from this rapidly oscillating term is negligible~\cite{Kofman:1997yn}. Therefore, for modeling the backreaction on the evolution of the $\phi$ cloud, the expectation value is dominated by the particle number term: $\overline{\langle\chi^2\rangle} \approx \int \frac{d^3k}{(2\pi)^3} \frac{n_k}{\omega_k(t)}$.
%\begin{equation}
%	\overline{\langle\chi^2\rangle} \approx \int \frac{d^3k}{(2\pi)^3} \frac{n_k}{\omega_k(t)}.
%\end{equation}
By defining the total number density as $n_\chi = \int \frac{d^3k}{(2\pi)^3} n_k$, we arrive at the simplified expression used in the main text:
\begin{equation}
	\langle\chi^2\rangle \approx \frac{n_\chi}{{\omega}_k(t)} \approx \frac{n_\chi}{\sqrt{\mu_\chi^2+\lambda\phi(t)}}\,.
\end{equation}
It should be noted that while the integral for $n_\chi$ is formally over all modes, the long-term, stable particle number density is dominated by the trapped particles forming the ring. Thus, $n_\chi$ in this context effectively represents the number density of the saturated ring.


