\title{Enhancement of axial anomaly effects in hot two-color QCD: \\
FRG approach in the linear sigma model}

\author{Gergely Fej\H{o}s}
\affiliation{Institute of Physics and Astronomy, E\"otv\"os University, 1117 Budapest, Hungary,}
\affiliation{RIKEN Center for Interdisciplinary Theoretical and Mathematical Sciences (iTHEMS), Wako, Saitama 351-0198, Japan}
\author{Daiki Suenaga}
