%\begin{eqnarray}
%\big({\rm tr}[\tilde{\Sigma}\Sigma + \tilde{\Sigma}^\dagger\Sigma^\dagger] \big)^2 = -8{\rm tr}[(\Sigma^\dagger\Sigma)^2] + 4 \big({\rm tr}[\Sigma^\dagger\Sigma]\big)^2 + 16({\rm det}\Sigma + {\rm det}\Sigma^\dagger)\ .
%\end{eqnarray}
%}

