%&=& 2\left[{\rm det}(\bar{\psi}_{L,J}\psi_{R,I}) + {\rm H.c.} \right] -2(d_L^\dagger\sigma^2\tau_c^2 u_L^*)(d_R^T\sigma^2\tau_c^2u_R) \nonumber\\
