\section{Derivation of flow equations for $\lambda_{1k}$, $\lambda_{2k}$, $c_{1k}$ and $c_{2k}$}
%%%%%%%%%%%%%%%%%%%
\label{sec:kTildeDerivative}

In Sec.~\ref{sec:EffectiveAction} it is demonstrated that the flow equations for $m_k$ and $a_k$ can be obtained via evaluating part of the effective potential that is quadratic in the field variables. In this Appendix, we show derivations of flow equations for the remaining quartic couplings: $\lambda_{1k}$, $\lambda_{2k}$, $c_{1k}$ and $c_{2k}$.

According to the expansion~(\ref{OmegaExpanded}), the ${\cal O}(\Sigma^4)$ part of the potential flow reads
\begin{eqnarray}
\partial_k V_k^{(4)} \equiv - \frac{T}{4}\sum_n\int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k{\rm tr}\Big[{\cal D}_{0,k}V_{(2)k}''{\cal D}_{0,k}V_{(2)k}''\Big]\ , \nonumber\\\label{Vk4Def}
\end{eqnarray}
where the definitions of ${\cal D}_{0,k}$ and $V_{(2)k}''$ are given by Eq.~(\ref{D0kInverse}), see also the explanations below Eq.~(\ref{OmegaExpanded}). As long as we stick to the zero chemical potential, ${\cal D}_{0,k}$ is diagonal and no Matsubara frequencies $\omega_n$ appear in any numerator, thus the evaluation of the RHS of Eq.~(\ref{Vk4Def}) can be performed in a straightforward way. Making use of the identity
\begin{eqnarray}
\frac{1}{(i\omega_n)^2-\epsilon^2} = \frac{1}{2\epsilon}\left(\frac{1}{i\omega_n-\epsilon}-\frac{1}{i\omega_n+\epsilon}\right)
\end{eqnarray}
to decompose the propagators, the Matsubara summations are readily done by virtue of ($\omega_n=2\pi nT$)
\begin{eqnarray}
&& T\sum_n\frac{1}{(i\omega_n-\epsilon_1)(i\omega_n-\epsilon_2)} = \frac{f_B(\epsilon_2)-f_B(\epsilon_1)}{\epsilon_1-\epsilon_2}\ , \nonumber\\
&&  T\sum_n\frac{1}{(i\omega_n-\epsilon)^2} = \lim_{\epsilon_2\to \epsilon}\frac{f_B(\epsilon_2)-f_B(\epsilon)}{\epsilon-\epsilon_2} = -\frac{df_B(\epsilon)}{d\epsilon}\ , \nonumber\\
\end{eqnarray}
with the Bose-Einstein distribution function $f_B(\epsilon) = 1/({\rm e}^{\epsilon/T}-1)$. Then, the flow of $V_k^{(4)}$ is evaluated as
\begin{widetext}
\begin{eqnarray}
\partial_k V_k^{(4)}= \left( \partial_k\hat{V}_{M,k}^{I_1^2} + \partial_k\hat{V}_{B,k}^{I_1^2} \right)I_1^2 + \left(  \partial_k\hat{V}_{M,k}^{I_2} + \partial_k\hat{V}_{B,k}^{I_2}  \right)I_2 + \left(  \partial_k\hat{V}_{M,k}^{I_A^2} + \partial_k\hat{V}_{B,k}^{I_A^2}  \right)I_A^2 + \left(  \partial_k\hat{V}_{M,k}^{I_1I_A} + \partial_k\hat{V}_{B,k}^{I_1I_A}  \right)I_1I_A\ , \nonumber\\
\end{eqnarray}
where
\begin{eqnarray}
\partial_k\hat{V}_{M,k}^{I_1^2} &=&-\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k \nonumber\\
&&\Bigg(\frac{16 (c_{1,k}^2 + 3 c_{1,k} c_{2,k} + 3 c_{2,k}^2 + 4 c_{1,k} \lambda_{1,k} + 9 c_{2,k} \lambda_{1,k} + 7 \lambda_{1,k}^2) + 12 (c_{2,k} + 2 \lambda_{1,k}) \lambda_{2,k}+ 3 \lambda_{2,k}^2}{8(E_{k}^+)^{2}} F_1(E_k^+) \nonumber\\
 && +\frac{16 (c_{1,k}^2 - 3 c_{1,k} c_{2,k} + 3 c_{2,k}^2 + 4 c_{1,k} \lambda_{1,k} - 9 c_{2,k} \lambda_{1,k} + 7 \lambda_{1,k}^2) - 12 (c_{2,k} - 2 \lambda_{1,k}) \lambda_{2,k} + 3 \lambda_{2,k}^2}{8(E_{k}^-)^2} F_1(E_k^-) \nonumber\\
 && + \frac{16 c_{1,k}^2 - 32 c_{1,k} \lambda_{1,k} + 16 \lambda_{1,k}^2 + 3  \lambda_{2,k}^2}{4E_{k}^+E_{k}^-}F_2(E_k^+,E_k^-) \Bigg)\ ,  \label{VI12Mk}\\
\partial_k\hat{V}_{B,k}^{I_1^2} &=&-\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k\Bigg(\frac{(2 c_{2,k} + 4 \lambda_{1,k} + \lambda_{2,k})^2 }{4(E_{k}^+)^2}F_1(E_k^+) +\frac{(2 c_{2,k} - 4 \lambda_{1,k} - \lambda_{2,k})^2}{4(E_{k}^-)^2}F_1(E_k^-) + \frac{\lambda_{2,k}^2}{2E_{k}^+E_{k}^-}F_2(E_k^+,E_k^-) \Bigg)\ , \nonumber\\
\partial_k\hat{V}_{M,k}^{I_2} &=& -\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k\Bigg(\frac{4(c_{1,k}+c_{2,k}+\lambda_{1,k})\lambda_{2,k}}{(E_{k}^+)^2} F_1(E_k^+) + \frac{4(c_{1,k}-c_{2,k}+\lambda_{1,k})\lambda_{2,k}}{(E_{k}^-)^2} F_1(E_k^-) \nonumber\\
&& \hspace{2.7cm}  - \frac{2(8c_{1,k}-8\lambda_{1,k}-\lambda_{2,k})\lambda_{2,k}}{E_{k}^+E_{k}^-}F_2(E_k^+,E_k^-) \Bigg)\ , 
\end{eqnarray}
\begin{eqnarray}
\partial_k\hat{V}_{B,k}^{I_2} &=& -\frac{1}{4}\int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k \left(-\frac{2\lambda_{2,k}^2}{E_{k}^+E_{k}^-}F_2(E_k^+,E_k^-)\right)\ , \\
\partial_k\hat{V}_{M,k}^{I_A^2} &=& -\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k\nonumber\\
&&\Bigg(\frac{16 (7 c_{1,k}^2 + 9 c_{1,k} c_{2,k} + 3 c_{2,k}^2 + 4 c_{1,k} \lambda_{1,k} + 3 c_{2,k} \lambda_{1,k} + \lambda_{1,k}^2) - 12 (2 c_{1,k} + c_{2,k}) \lambda_{2,k} + 3 \lambda_{2,k}^2}{8(E^+_{k})^2} F_1(E_k^+) \nonumber\\
&& +\frac{16 (7 c_{1,k}^2 - 9 c_{1,k} c_{2,k} + 3 c_{2,k}^2 + 4 c_{1,k} \lambda_{1,k} - 3 c_{2,k} \lambda_{1,k} + \lambda_{1,k}^2) + 12 (-2 c_{1,k} + c_{2,k}) \lambda_{2,k} + 3 \lambda_{2,k}^2}{8(E_{k}^-)^2}F_1(E_k^-)\nonumber\\
 && - \frac{16c_{1,k}^2-32c_{1,k}\lambda_{1,k}+16\lambda_{1,k}^2+3\lambda_{2,k}^2}{4E_{k}^+E_{k}^-}F_2(E_k^+,E_k^-)  \Bigg)\ , \\
\partial_k\hat{V}_{B,k}^{I_A^2}  &=& -\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k\nonumber\\
&&\Bigg(\frac{(4 c_{1,k} + 2 c_{2,k} - \lambda_{2,k})^2 }{4(E_{k}^+)^2}F_1(E_k^+)  +\frac{(4 c_{1,k} - 2 c_{2,k} - \lambda_{2,k})^2}{4(E_{k}^-)^2}F_1(E_k^-) - \frac{\lambda_{2,k}^2}{2E_{k}^+E_{k}^-}F_2(E_k^+,E_k^-)  \Bigg)\ , \nonumber\\
\partial_k\hat{V}_{M,k}^{I_1I_A} &=&-\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k\\
&&\Bigg(\frac{16 (2 c_{1,k}^2 + 6 c_{1,k} c_{2,k} + 3 c_{2,k}^2 + 8 c_{1,k} \lambda_{1,k} + 6 c_{2,k} \lambda_{1,k} +  2 \lambda_{1,k}^2) + 12 (c_{1,k} - \lambda_{1,k}) \lambda_{2,k} - 3 \lambda_{2,k}^2}{4(E_{k}^+)^2} F_1(E_k^+)  \nonumber\\
 && -\frac{16 (2 c_{1,k}^2 - 6 c_{1,k} c_{2,k} + 3 c_{2,k}^2 + 8 c_{1,k} \lambda_{1,k} - 6 c_{2,k} \lambda_{1,k} +  2 \lambda_{1,k}^2) + 12 (c_{1,k} - \lambda_{1,k}) \lambda_{2,k} - 3 \lambda_{2,k}^2}{4(E_{k}^-)^2} F_1(E_k^-)\Bigg)\ , \nonumber\\
\end{eqnarray}
and
\begin{eqnarray}
&&\hspace{-4.5cm}\partial_k\hat{V}_{B,k}^{I_1I_A} = -\frac{1}{4} \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k\Bigg(\frac{(4 c_{1,k} + 2 c_{2,k} - \lambda_{2,k}) (2 c_{2,k} + 4 \lambda_{1,k} + \lambda_{2,k}) }{2(E_{k}^+)^2}F_1(E_k^+)  \nonumber\\
&& + \frac{(4 c_{1,k} - 2 c_{2,k} - \lambda_{2,k}) (2 c_{2,k} - 4 \lambda_{1,k} - \lambda_{2,k}) }{2(E_{k}^-)^2}F_1(E_k^-)\Bigg)  \label{VI1IABk}
\end{eqnarray}
\end{widetext}
are representing contributions of mesonic and baryonic fluctuations to the respective coefficients. In addition, we note that $E_k^\pm = \sqrt{{\bm p}^2+R_k({\bm p})+(m^\pm_{{\rm eff},k})^2}$ with $(m^\pm_{{\rm eff},k})^2 = m_k^2\pm a_k $, and $\tilde{\partial}_k$ is a differential operator acting only on the regulator $R_k$. In the above equations we have also defined
\begin{eqnarray}
F_1(\epsilon) &\equiv& \frac{1}{2\epsilon}\Big(1+2f_B(\epsilon)\Big)-\frac{d f_B(\epsilon)}{d\epsilon} \ , \nonumber\\
F_2(\epsilon_1,\epsilon_2) &\equiv& \frac{1}{\epsilon_1+\epsilon_2}\Big(1+f_B(\epsilon_1)+f_B(\epsilon_2)\Big) \nonumber\\
&& -\frac{f_B(\epsilon_1) - f_B(\epsilon_2)}{\epsilon_1-\epsilon_2}.
\end{eqnarray}
Here, the first terms in $F_1(\epsilon)$ and $F_2(\epsilon_1,\epsilon_2)$ stand for particle-antiparticle contributions, while the second ones stand for particle-hole contributions, respectively.


Using Eqs.~(\ref{VI12Mk})~-~(\ref{VI1IABk}), flow equations for the quartic couplings are obtained by
\begin{eqnarray}
\partial_k \lambda_{1k} &=& \partial_k\hat{V}^{I_1^2}_{M,k} + \partial_k\hat{V}^{I_1^2}_{B,k}\ , \nonumber\\
\partial_k \lambda_{2k} &=& \partial_k\hat{V}^{I_2}_{M,k} + \partial_k\hat{V}^{I_2}_{B,k}\ , \nonumber\\
\partial_k c_{1k} &=& \partial_k\hat{V}^{I_A^2}_{M,k} + \partial_k\hat{V}^{I_A^2}_{B,k}\ , \nonumber\\
\partial_k c_{2k} &=& \partial_k\hat{V}^{I_1I_A}_{M,k} + \partial_k\hat{V}^{I_1I_A}_{B,k}\ .
\end{eqnarray}

The $\tilde{\partial}_k$ derivatives are evaluated using
\begin{eqnarray}
&& \int\frac{d^3p}{(2\pi)^3}\tilde{\partial}_k{\cal F}_k(E_k^+,E_{k}^-) \nonumber\\
&=& \int\frac{d^3p}{(2\pi)^3}\theta(k^2-{\bm p}^2)\nonumber\\
&&\ \ \ \  \times \sum_{\alpha=\pm}\left[\frac{k}{E_{k}^\alpha}\frac{\partial{\cal F}_k(E_{k}^+, E_{k}^-)}{\partial E_{k}^\alpha}\right]_{E_{k}^\pm= \sqrt{k^2+(m^\pm_{{\rm eff},k})^2}}  \nonumber\\ \label{KDFormula}
%&& \times \left[\frac{k}{E_{k}^+}\frac{\partial{\cal F}(E_{k}^+,E_{k}^-)}{\partial E_{k}^+}+\frac{k}{E_{k}^-} \frac{\partial{\cal F}(E_{k}^+,E_{k}^-)}{\partial E_{k}^-}\right]_{E_{k}^\pm= \sqrt{k^2+m^2\pm a}}  \nonumber\\
&=& \frac{k^4}{6\pi^2}\sum_{\alpha=\pm}\left[\frac{1}{E_{k}^\alpha}\frac{\partial{\cal F}_k(E_{k}^+,E_{k}^-)}{\partial E_{k}^\alpha}\right]_{E_{k}^\pm= \sqrt{k^2+(m^\pm_{{\rm eff},k})^2}}\, , \nonumber\\\
%&=& \frac{k^4}{6\pi^2}\left[\frac{1}{E_{k}^+}\frac{\partial{\cal F}(E_{k}^+,E_{k}^-)}{\partial E_{k}^+}+\frac{1}{E_{k}^-} \frac{\partial{\cal F}(E_{k}^+,E_{k}^-)}{\partial E_{k}^-}\right]_{E_{k}^\pm= \sqrt{k^2+m^2\pm a}}\, , \nonumber\\\
\end{eqnarray}
where
\begin{eqnarray}
\frac{\partial E_{k}^\pm}{\partial k} &=& \frac{\delta(k^2-{\bm p}^2)(k^2-{\bm p}^2)}{E_{k}^\pm} + \frac{\theta(k^2-{\bm p}^2)k}{E_{k}^\pm} \nonumber\\
&\overset{p\, {\rm integral}}{\to}& \frac{\theta(k^2-{\bm p}^2)k}{\sqrt{k^2+(m^\pm_{{\rm eff},k})^2} } 
\end{eqnarray}
is adopted.


%%%%%%%%%%%%%%%%%%%
\section{Hadron mass formulas}
%%%%%%%%%%%%%%%%%%%
\label{sec:HadronMassFormula}

Here we show analytic formulas for the hadron masses, which are the eigenvalues of the second derivative matrix (\ref{VkDerivative}) of the potential~(\ref{VkAnsatz}) in the homogeneous background, $\sigma_0$. Using (\ref{VkAssume}), the resultant formulas read
\begin{eqnarray}
M_{\eta,k}^2 &=& m_k^2-a_k+\lambda_{1,k}\sigma_0^2-c_{1,k} \sigma_0^2 \nonumber\\
M_{\pi,k}^2 &=& M_{B,k}^2= M_{\bar{B},k}^2 \nonumber\\
&=& m_k^2+a_k+\lambda_{1,k}\sigma_0^2 +(c_{1,k}+c_{2,k})\sigma_0^2 \ ,  \label{PiMass}
\end{eqnarray}
and
\begin{eqnarray}
M_{\sigma,k}^2 &=& m_k^2+a_k+3\lambda_{1,k}\sigma_0^2 + 3(c_{1,k}+c_{2,k})\sigma_0^2 \ ,\nonumber\\
M_{a_0,k}^2 &=& M_{B',k}^2 = M^2_{\bar{B}',k} \nonumber\\
&=& m_k^2-a_k+\left(\lambda_{1,k}+\frac{\lambda_{2,k}}{2}\right)\sigma_0^2 -c_{1,k}\sigma_0^2 \ . \nonumber\\ \label{SigmaMass}
\end{eqnarray}

The gap equation that determines $\sigma_0$ is
\begin{eqnarray}
 m_k^2+a_k+\lambda_{1,k}\sigma_0^2 +(c_{1,k}+c_{2,k})\sigma_0^2 = \frac{\sqrt{2}m_q\bar{c}}{\sigma_0} \ , \label{GapEq}
\end{eqnarray}
where $m_q\bar{c}$ does not depend on the separation scale $k$. Thus, one can find
\begin{eqnarray}
M^2_{\pi,k} \sigma_0 = \sqrt{2}m_q\bar{c} = ({\rm constant})\ , \label{PiMassRelation}
\end{eqnarray}
at any $k$ and temperatures. In the chiral limit $m_q\bar{c}\to0$, inserting Eq.~(\ref{GapEq}) into Eq.~(\ref{PiMass}) leads to $M_{\pi,k}^2=M_{B(\bar{B}),k}^2=0$, which yields the appearance of five NG bosons corresponding to the breaking pattern of $SU(4)\to Sp(4)$.

From Eqs.~(\ref{PiMass}) and~(\ref{SigmaMass}), one can confirm
\begin{eqnarray}
M_{\sigma,k}^2- M_{\pi,k}^2 &=& 2(\lambda_{1,k}-c_{1,k}-c_{2,k})\sigma_0^2 \ ,\nonumber\\
M_{a_0,k}^2- M_{\eta,k}^2 &=& \frac{\lambda_{2,k}}{2}\sigma_0^2\ . \label{MassDiff}
\end{eqnarray}
Hence, when chiral symmetry is restored, $\sigma_0\to0$, the chiral partner structures $M_{\sigma,k}=M_{\pi,k}$ and $M_{a_0,k}=M_{\eta,k}$ are realized, as they should.

Under the assumption that $c_{1,k}$ and $c_{2,k}$ are negligible, the mass difference between $\eta$ and $\pi$ is approximated as
\begin{eqnarray}
M^2_{\eta,k} &=& -2a_k-(2c_{1,k}+c_{2,k})\sigma_0^2 \nonumber\\
&\approx& M^2_{\pi,k}  -2a_k\ , \label{PiEtaMass}
\end{eqnarray}
indicating that the $\eta$ mass is dominantly generated by the quadratic anomalous term.



