\section{I. Semiclassical emission rate}
\label{contourdeform}

The classically forbidden process for our lattice model is obtained by computing the imaginary part of the action \cite{ParikhWilczek-PRL2000, Stalhammar-NJP2023} 
\begin{equation}
\textnormal{Im}(S^{\pm})=\textnormal{Im}\left(\int\limits_{r_{\textnormal{in}}}^{r_{\textnormal{out}}} dr \tilde{k}_r^{\pm}\right)=I^{\pm},
\label{SM1}
\end{equation}
where the momentum $\tilde{k}_r^{\pm}$ is restricted to the tilting profile,
\begin{equation}
	\tilde{k}_r^{\pm}=\frac{\gamma f(r)}{1-f^2(r)}\pm\Biggl\{\frac{\gamma^2}{\left[1-f^2(r)\right]^2}\Biggr\}^{1/2}.
	\label{SM2}
\end{equation}
These solutions correspond to the particle ($+$) and antiparticle ($-$) channels involved in the tunneling process. We now focus on the classically forbidden processes associated with the particle channel near the horizon at $r_1$. Specifically, we consider a spontaneous radiation process in which a particle with positive frequency energy $\omega > 0$ is emitted. This implies that particles radiate outward from the black hole interior, causing the black hole mass to decrease from $M_o$ to $M_o - \omega$, which in turn leads to a shrinking of the horizon. Taking into account this change in mass, the integration limits around the horizon are set as $r_{\textnormal{in}} = r_1$ and $r_{\textnormal{out}} = r_1 - 2\omega$, where $r_1=2M_o$. Inserting $\tilde{k}^+_r$ into $\textnormal{Im}(S^{+})$, we obtain
\begin{equation}
	I^{+}=\textnormal{Im}\left[\int\limits_{r_1}^{r_1-2\omega} dr\left(\frac{\gamma f(r)}{1-f^2(r)}+\left\{\frac{\gamma^2}{[1-f^2(r)]^2}\right\}^{1/2}\right)\right].
	\label{SM3}
\end{equation}
The integral has a divergence at $r=r_1$ when $f(r_1)=\kappa_3=1$. To overcome this issue, we perform a Taylor expansion in Eq.~\eqref{SM3} around $r_1$. Keeping only linear order terms in $r$ and considering that the chain is sufficiently large, i.e. $r_1\ll r_2$, we can write the imaginary part of the action for the particle channel as
\begin{equation}
	I^+=\textnormal{Im}\left(\int\limits_{r_1}^{r_1-2\omega}dr\frac{\gamma \left[1-\frac{\kappa_1-\kappa_2}{2l}(r-r_1)\right]}{\frac{1}{2r_1}\left(r-r_1\right)}
	+\left\{\frac{\gamma^2}{\left[\frac{1}{2r_1}\left(r-r_1\right)\right]^2}\right\}^{1/2}\right).
	\label{SM4}
\end{equation}
\begin{figure}[tbh]
	\centering
	\includegraphics[scale=2]{contour_ver3.png}
	\caption{Contour deformation of the function $\tilde{r}$. Green (red) line represents the particle (antiparticle) channel and $\varepsilon$ represents the radius of the curve.}
	\label{contour}
\end{figure}
If we perform a change of variable $\tilde{r}=r_1-r$, Eq.~\eqref{SM4} becomes
\begin{equation}
	I^+=\textnormal{Im}\Biggl\{\int\limits_{0}^{2\omega}d\tilde{r}\Biggl[\frac{2r_1\gamma \left(1+\frac{\tilde{r}}{2r_1}\right)}{\tilde{r}}
	-\Biggl(\frac{4r_1^2\gamma^2}{\tilde{r}^2}\Biggr)^{1/2}\Biggr]\Biggr\}.
	\label{SM5}
\end{equation}

A first order pole can be found at $\tilde{r}=0$. The integral can be solved by deforming the contour of $\tilde{r}$ around zero, see Fig.~\ref{contour}. By applying a change of variable $\tilde{r}=\varepsilon e^{i\phi}$ and taking the limit $\varepsilon \rightarrow 0$, Eq.~\eqref{SM5} takes the form
\begin{equation}
	I^+=\lim_{\varepsilon\rightarrow 0}\Biggl(\textnormal{Im}\Biggl\{\int\limits_{\pi/2}^{0}i\varepsilon e^{i\phi}d\phi\Biggl[\frac{2r_1\gamma \left(1+\frac{1}{2r_1}\varepsilon e^{i\phi}\right)}{\varepsilon e^{i\phi}}
	-\Biggl(\frac{4r_1^2\gamma^2}{\varepsilon^2e^{2i\phi}}\Biggr)^{1/2}\Biggr]\Biggr\}\Biggl).
	\label{SM6}
\end{equation}
Solving the integral, we find
\begin{eqnarray}
    I^+&=& \int\limits_{\pi/2}^{0}2r_1(\gamma-|\gamma|)d\phi \nonumber \\
    &=&-\pi r_1(\gamma-|\gamma|),
    \label{SM7}
\end{eqnarray}
which leads to the solution
\begin{numcases}{I^+=}
    2 \pi r_1|\gamma| \quad &$\gamma<0$ \nonumber \\
    0 \quad &$\gamma\geq0$.
    \label{SM8}
\end{numcases}
The integral of the antiparticle channel has a similar functional form as Eq.~\eqref{SM7}, but it is important to take into account the correct integration limits
\begin{equation}
    I^-=\int\limits_{-\pi/2}^{0}2r_1(\gamma+|\gamma|)d\phi,
    \label{SM9}
\end{equation}
and then the solution is
\begin{numcases}{I^-=}
    2\pi r_1|\gamma| \quad &$\gamma>0$ \nonumber \\
    0 \quad &$\gamma\leq0$.
    \label{SM10}
\end{numcases}

The semiclassical emission rate is obtained by taking into account that both channels (particle and antiparticle) contribute to the probability of the tunneling process \cite{ParikhWilczek-PRL2000}. Thus, using the condition that $r_1=2M_o$, the amplitude for both channels reads  
\begin{equation}
    \mathcal{A}^{\pm}=e^{-I^{\pm}}=e^{-4\pi M|\gamma|}\Theta(\mp\gamma)
    \label{SM11}
\end{equation}
where $\Theta(x)$ is the Heaviside theta-function and it is defined as
\begin{numcases}{\Theta(x)=}
    1 \quad &$x>0$ \nonumber \\
    0 \quad &$x\leq0$.
    \label{SM12}
\end{numcases}
Then, the semiclassical emission rate is
\begin{equation}
	\Gamma\propto (\mathcal{A}^+ + \mathcal{A}^-)^2 = (\mathcal{A}^+)^2+(\mathcal{A}^-)^2+\mathcal{A}^+\mathcal{A}^-.
    \label{SM13}
\end{equation}
The last term of the above equation vanishes because $\mathcal{A}^+$ and $\mathcal{A}^-$ do not belong to the same domain \cite{Stalhammar-NJP2023}. Therefore, the semiclassical emission rate reads
\begin{equation}
    \Gamma \propto e^{-8\pi M|\gamma|},
    \label{SM14}
\end{equation}
and the argument of the exponential can be promptly related to the Bekenstein-Hawking entropy \cite{ParikhWilczek-PRL2000, bekenstein_black_1972, bekenstein_black_1973, hawking_particle_1975}, $\Delta S_{B-H}=-8\pi M|\gamma|$.

\section{II. Frequency $\omega$ in terms of the on-site potential $\gamma$}

The thermal entropy is written as
\begin{align}
    \Delta S&=\int\limits_{M_o}^{M_o-\omega}8\pi M dM \nonumber \\
    &=\int\limits_{r_1/2}^{r_1/2-\omega}4\pi\Bigl[\frac{rf^4(r)}{2}+r^2f^3(r)f'(r)\Bigr]dr.
    \label{SM15}
\end{align}

The solution of the above integral is
\begin{equation}
    \Delta S=\pi r^2f^4(r)\Bigg|_{r_1/2}^{r_1/2-\omega}.
    \label{SM16}
\end{equation}

Now, we must perform a Taylor expansion at leading order in $r$ around $r_1$. Then, the difference in the thermal entropy reads
\begin{equation}
    \Delta S=-\frac{3\pi}{2}\left(\frac{l}{\kappa_1-\kappa_2}\omega+\omega^2\right).
    \label{SM17}
\end{equation}

Equating the Bekenstein-Hawking entropy with Eq.~\eqref{SM17} ($\Delta S_{\textnormal{B-H}}=\Delta S$), we obtain a relation for the frequency $\omega$ of particles and antiparticles,
\begin{equation}
  -8\pi M|\gamma|=-\frac{3\pi}{2}(2M\omega+\omega^2).
  \label{SM18}
\end{equation}

In terms of the lattice parameters the frequency reads
\begin{equation}
    \omega^{\pm}=-\frac{l}{2(\kappa_1-\kappa_2)}\pm\sqrt{\frac{l^2}{4(\kappa_1-\kappa_2)^2}+\frac{8l|\gamma|}{3(\kappa_1-\kappa_2)}}.
    \label{SM19}
\end{equation}

Taking into account that $(\kappa_1-\kappa_2)/2l \ll 1$, we obtain within linear response the frequency of particles $\omega^+$ with respect to $\gamma$ by performing a Taylor expansion around zero in Eq.~\eqref{SM19}. This relation reads 
\begin{equation}
    \omega^+=\frac{8}{3}|\gamma|.
\end{equation}

