	\section{Linear terms}\label{app:linear}
	Here we study a generalization of the problem considered in the main text,
	\begin{align}
		\hat{\mathcal{Q}} = \exp\left[ -\tfrac{i}{\hbar} \left( \tfrac{1}{2} \hat{\bm{r}}^T \bm{H} \hat{\bm{r}} + \hat{\bm{r}}^T \bar{\bm{r}}\right)\right],
	\end{align}
	where $\bar{\bm{r}} \in \mathbb{R}^{2M}$. 
	It will be useful to introduce the displacement (or Weyl) operator \begin{align}
		\W(\bm{r}) =\exp\left( \tfrac{i}{\hbar} \hat{\bm{r}}^T \bm{\Omega} \bm{r}\right) = \exp\left( - \tfrac{i}{\hbar} {\bm{r}}^T \bm{\Omega} \hat{\bm{r}}\right),
	\end{align}
	which in the Heisenberg picture satisfies
	\begin{align}
		\W^\dagger(\bm{r}) \bm{\hat r} \W (\bm{r}) = \bm{\hat r}+\bm{r}.
	\end{align}

	To obtain a decomposition we first eliminate the linear part in the exponential by inserting resolutions of the identity in terms of $\W$ as follows
	\begin{align}
		\hat{\mathcal{Q}} &= \W(\br) \W^\dagger(\br) \hat{\mathcal{Q}} \W(\br) \W^\dagger(\br) \nonumber \\ 
		&=  \W(\br)\\
		&\exp\left[ -\tfrac{i}{\hbar} \left( \tfrac{1}{2} (\hat{\bm{r}} + \br)^T \bm{H} (\hat{\bm{r}} + \br) + (\hat{\bm{r}}+\br)^T \bar{\bm{r}}\right)\right] \nonumber \\
		&\quad \W^\dagger (\br) \nonumber \\
		&=e^{-\frac{i}{2 \hbar} \br^T \bm{H} \br -\frac{i}{\hbar } \br^T \bar{\br}} \\
		&\W( \br ) \exp\left[ -\tfrac{i}{\hbar} \left( \tfrac{1}{2} \hat{\bm{r}}^T \bm{H} \hat{\bm{r}} +\hbr^T\{\bar{\br} +  \bm{H} \br \} \right) \right]  \W^\dagger(\br). \nonumber
	\end{align}
	If we pick as displacement 
	\begin{align}\label{choice}
		\br = -\bm{H}^{-1} \bar{\br}
	\end{align} then the term inside the curly braces in the last equation vanishes and we are only left with an operator with a purely quadratic generator,
	\begin{align}
		\uu = \exp\left[ - \tfrac{i}{2 \hbar } \hat{\bm{r}}^T \bm{H} \hat{\bm{r}}  \right].
	\end{align}
	Moreover, under the choice of Eq.~\eqref{choice} one obtains
	\begin{align}
		\br^T \bm{H} \br +2 \br^T \bar{\br} = - \bar{\br}^T \bm{H}^{-1} \bar{\br}.
	\end{align}
	Putting everything together we have
	\begin{align}
		\hat{\mathcal{Q}} &= e^{\frac{i}{2 \hbar }  \bar{\br}^T \bm{H}^{-1} \bar{\br}} \W( \br ) \uu \W^\dagger( \br )  \\
		&=e^{-\frac{i}{2 \hbar }  \bar{\br}^T \bm{H}^{-1} \bar{\br}} \W( \br ) \uu \W( \br )^\dagger \uu^\dagger  \uu.
	\end{align}
	We now recall Eq.~\eqref{eq:heisenberg} 
	\begin{align}
		\uu \W( \br )^\dagger \uu^\dagger &= \exp\left(  \tfrac{i}{\hbar} {\br}^T \bm{\Omega} \uu \hat{\bm{r}} \uu^\dagger\right) \\
		&=\exp\left(  \tfrac{i}{\hbar} {\br}^T \bm{\Omega} \bm{S} \hat{\bm{r}} \right)\\
		&=\exp\left(  \tfrac{i}{\hbar} {\br}^T \bm{S}^{-T}\bm{\Omega}  \hat{\bm{r}} \right)\\
		&=\W(-\bm{S}^{-1} \bm{r}) = \W(\bm{S}^{-1} \bm{H}^{-1} \bar{\bm{r}}),
	\end{align}
	where we used $\bm{S} \bm{\Omega} = \bm{\Omega} \left( \bm{S}^{-1} \right)^{T}$.
	Now we need to simplify a product of two displacement operators for which we use
	\begin{align}
		\W(\bm{r}_1 + \bm{r}_2) e^{-\frac{i}{2 \hbar} \bm{r}_1^T \bm{\Omega} \bm{r}_2} = \W(\bm{r}_1) \W(\bm{r}_2),
	\end{align}
	to obtain
	\begin{align}
		&    \W( - \bm{H}^{-1} \bar{\br} )  \W(\bm{S}^{-1} \bm{H}^{-1} \bar{\bm{r}}) \\
		&    = \W([\bm{S}^{-1} - \mathbb{I}_{2M}] \bm{H}^{-1} \bar{\bm{r}}) 
		\exp( \tfrac{i}{2\hbar} \bar{\bm{r}}^T \bm{H}^{-1} \bm{\Omega} \bm{S}^{-1} \bm{H}^{-1} \bar{\bm{r}} ).\nonumber 
	\end{align}
	The whole decomposition is now
	\begin{align}
		\hat{\mathcal{Q}} =& \exp\left( \tfrac{i}{2\hbar} \left[  \bar{\bm{r}}^T \bm{H}^{-1} \bm{\Omega} \bm{S}^{-1} \bm{H}^{-1} \bar{\bm{r}} - \bar{\br}^T \bm{H}^{-1} \bar{\br} \right]  \right) \nonumber \\
		&\times \W([\bm{S}^{-1} - \mathbb{I}_{2M}] \bm{H}^{-1} \bar{\bm{r}})  \times \uu.
	\end{align}

	Below we show that, even if $\bm{H}$ is non-invertible, this expression is still well behaved. Consider first the argument of the Weyl operator
	\begin{align}
		[\bm{S}^{-1} - \mathbb{I}_{2M}] \bm{H}^{-1} =& \left[-\sum_{n=0}^\infty \frac{(-\bm{\Omega} \bm{H})^n}{(n+1)!} \bm{\Omega} \bm{H} \right] \bm{H}^{-1} \\
		=& -\sum_{n=0}^\infty \frac{(-\bm{\Omega} \bm{H})^n}{(n+1)!} \bm{\Omega} \equiv -F_1(-\bm{\Omega}\bm{H}) \bm{\Omega}, \nonumber
	\end{align}
	where $F_1(x) = \frac{e^x - 1}{x}$ is a well-behaved function of its argument. Now consider the phase
	\begin{align}
		&- \bar{\br}^T \bm{H}^{-1} \bar{\br} +\bar{\bm{r}}^T \bm{H}^{-1} \bm{\Omega} \bm{S}^{-1} \bm{H}^{-1} \bar{\bm{r}}  = - \bar{\br}^T \bm{H}^{-1} \bar{\br}  \\
		&\quad +\bar{\bm{r}}^T \bm{H}^{-1} \bm{\Omega} \left[ \mathbb{I}_{2M} - \bm{\Omega}\bm{H} + \sum_{n=0}^\infty \frac{(-\bm{\Omega \bm{H}})^{n+2}}{(n+2)!} \right] \bm{H}^{-1} \bar{\bm{r}} \nonumber  
	\end{align}
	Note that the first term inside the square brackets will be multiplied by the  antisymmetric symplectic matrix and then will contract to zero when multiplied from the left and the right by the same vector (as this forms a symmetric tensor). The second term inside the square brackets cancels out exactly the first term of the equation above leaving us with the third of the square bracket that can be simplified to
	\begin{align}
		-\bar{\bm{r}}^T  \left[   \sum_{n=0}^\infty \frac{(-\bm{\Omega \bm{H}})^{n}}{(n+2)!}  \bm{\Omega} \right] \bar{\bm{r}} = -\bar{\bm{r}}^T F_2(-\bm{\Omega}\bm{H})  \bm{\Omega} \bar{\bm{r}},	\end{align}
	where now $F_2(x) = \frac{e^x - x - 1}{x^2}$.
	Our final result is
	\begin{align}
		\hat{\mathcal{Q}} = e^{-\tfrac{i}{2 \hbar}  \bar{\bm{r}}^T F_2(-\bm{\Omega} \bm{H})\bm{\Omega } \bar{\bm{r}} } \W(- F_1(-\bm{\Omega} \bm{H}) \bm{\Omega} \bar{\bm{r}}) \uu
	\end{align}
	which has no explicit reference to $\bm{H}^{-1}$.  Moreover, note that once the phase of $\uu$ is known one can use the results in Eq. 24 of Ref.~\cite{miatto2020fast} to obtain the net phase of the transformation above.

