\section{Appendix}
\subsubsection{Proof of Theorem \ref{thm1}}
\label{pthm1}
Before proceeding to the proof of Theorem \ref{thm1}, we first establish the following lemma, which shows that the sets \( \hat{S} \) and \( \hat{\Delta} \) are Hausdorff consistent to the solution sets of the primal and dual problems, respectively. 

\begin{lemma}
\label{lem1}
Suppose that \ref{A1}, \ref{A1'} and \ref{A2} hold. Then $d_H(\hat{S},S_0)=o_p(1)$ and $d_H(\hat{\Delta},\Delta_0)=o_p(1)$.
\end{lemma}


\begin{proof}[\bf{Proof of Lemma \ref{lem1}}] We proceed in two steps. First, we establish the upper hemicontinuity of the solution sets of the primal and dual problems using Theorem 1 of \cite{SR2}. Second, we establish the lower hemicontinuity of these solution sets using Theorem 1 of \cite{SR1}. Both references study the stability of the feasible regions and solution sets of linear programs under perturbations.

\underline{Step 1} (Upper hemicontinuity)

Note that by Lemma \ref{lemMFCQ}, the MFCQ ensures that the set of dual optimal solutions, $\Delta_0$, is bounded. Indeed, there is a fundamental duality between the regularity of the primal problem and the boundedness of the solution sets of the dual problem(see also parts (a) and (b) of Theorem 1 in \citealt{SR2}). Since the feasible set of the primal problem, ${\cal P}$, is compact, the set of optimal solutions for the primal, $S_0$, is also bounded. Consequently, by part (c) of Theorem 1 in \cite{SR2}, there exist positive constants $c_1$ and $c_2$ that depend only on the input $d$ ($=\text{vec}(A,b,c)$), such that

\begin{equation}
\label{l1e1}
\|\hat{d}-d\|\leq c_1
\end{equation}
implies that the primal and dual problems corresponding to the inputs $\hat{d}$ are feasible, and satisfy
\begin{equation}
\label{l1e2}
\sup_{(\theta,\lambda)\in \hat{S}_0\times \hat{\Delta}_0} d\left((\theta,\lambda),S_0\times \Delta_0\right)<c_2 \|\hat{d}-d\|,
\end{equation}
where the sets $\hat{S}_0$ and $\hat{\Delta}_0$, which should not be confused with $\hat{S}$ and $\hat{\Delta}$, represent the sets of optimal solutions for the primal and dual problems, respectively, corresponding to the input $\hat{d}$. Inequality \ref{l1e2} establishes that when the estimation error is sufficiently small, the solution sets to the perturbed primal and dual problems remain close to those of the unperturbed primal and dual problems, with the distance being bounded by a fixed constant times the approximation error.  Let $\hat{\theta}_0$ and $\theta_0$ are the solutions to the perturbed and unperturbed primal problems, respectively, then the values $\hat{v}$ and $v$ of the perturbed and unperturbed primal programs satisfy $\hat{v}=\hat{c}^T\hat{\theta}_0$ and $v=c^T\theta_0$. Thus, whenever inequality \ref{l1e1} holds, inequality \ref{l1e2} and the first part of Assumption \ref{A2} imply that

\begin{equation}
\label{l1e3}
\hat{v}-v=O_p(1/\sqrt{N}).
\end{equation}
Note that since $\hat{S}$ and $\hat{\Delta}$ are, respectively, enlargements of $\hat{S}_0$ and $\hat{\Delta}_0$, inequalities \ref{l1e1} and \ref{l1e2} imply that $\hat{S}$ and $\hat{\Delta}$ are nonempty whenever inequality \ref{l1e1} holds. Lemma \ref{lemuhc} (see also Lemma 2 of \citealt{SR2}) applied to the systems

\[
S_0=\{\theta \in \mathbb{R}^d \ | \ A_E \theta =b_E, A_I \theta \leq b_I, c^T\theta \leq v \}
\]
and 
\[
\Delta_0=\{\lambda=(\lambda_E,\lambda_I) \in \mathbb{R}^p \ | \ A_E^T \lambda_E+A_I ^T \lambda_I = c, \ \lambda_I \leq 0, \ \lambda_E^T b_E+\lambda_I^Tb_I \geq v \},
\]
implies that there exists a positive constant $c_3$ and $c_4$ that depend only on the input $d$ such that whenever
\begin{equation}
\label{l1e4}
\hat{\delta}:=\max\{\|\hat{d}-d\|, |v-\hat{v}-\kappa_N/\sqrt{N}|, |v-\hat{v}+\kappa_N/\sqrt{N}| \}\leq  c_3
\end{equation}
we get
\begin{equation}
\label{l1e5}
\sup_{\theta \in \hat{S}} d(\theta,S_0)\leq c_4 \hat{\delta} \quad \sup_{\lambda \in \hat{\Delta}} d(\lambda,\Delta_0)\leq c_4 \hat{\delta}.
\end{equation}
Assumption \ref{A2} and inequality \ref{l1e3} then imply that $\hat{\delta}=O_p(\kappa_N/\sqrt{N})$, from which we conclude that 
\begin{equation}
\label{l1e6}
\sup_{\theta \in \hat{S}} d(\theta,S_0)=o_p(1 )\quad \text{and} \quad  \sup_{\lambda \in \hat{\Delta}} d(\lambda,\Delta_0)=o_p(1).
\end{equation}

\underline{Step 2} (Lower hemicontinuity) 

By Lemma \ref {lemMFCQ}, the compactness of the primal feasible region implies that the dual problem satisfies the MFCQ. By Lemma \ref{lemlhc} (see also Theorem 1 in \citealt{SR1}), since both the primal and dual problems satisfy the MFCQ, For any $R>0$, there exist constants $c_1$ and $c_2$ such that
\begin{equation}
\label{l1e7}
\|\hat{d}-d\|\leq c_1
\end{equation}
ensures that the feasible regions of the perturbed primal ($\hat{{\cal P}}$) and perturbed dual ($\hat{{\cal D}}$) problems, corresponding to the input $\hat{d}$, are nonempty and satisfy\footnote{Note that the feasible region of the dual is not necessarily bounded.}
\begin{equation}
\label{l1e8}
\max \Bigl\{ \sup_{\theta \in {\cal P}} d(\theta,\hat{{\cal P}}), \sup_{\lambda \in {\cal D}, \|\lambda\|\leq R} d(\lambda,\hat{{\cal D}}) \Bigr\}\leq c_2 \|\hat{d}-d\| .
\end{equation}
 Given a closed and convex subset $A\in \mathbb{R}^m$ for some $m\geq 1$, let $\Pi_A(x)$ denote the closest element to $x$ in $A$. For any $\theta\in S_0$, we have
\[
|\hat{v}-\hat{c}^T\Pi_{\hat{{\cal P}}}(\theta)|\leq |\hat{v}-v|+|\hat{c}^T(\theta-\Pi_{\hat{{\cal P}}}(\theta))|+|(\hat{c}-c)^T\theta|.
\]
By Assumptions \ref{A1'} and \ref{A2}, along with inequalities \ref{l1e3} and \ref{l1e8}, it follows that  
\[
\sup_{\theta \in S_0} |\hat{v}-\hat{c}^T\Pi_{\hat{{\cal P}}}(\theta)|=O_p(1/\sqrt{N}).
\]
Thus, we conclude that the following event occurs with probability approaching 1:
\begin{equation}
\label{l1e9}
\Pi_{\hat{{\cal P}}}(S_0)\subset \hat{S}=\bigl\{\theta \in \hat{{\cal P}} \  | \hat{c}^T\theta \leq \hat{v}+\kappa_N/\sqrt{N} \bigr\}.
\end{equation}
The latter, together with inequality \ref{l1e8}, implies that
\[
\sup_{\theta \in S_0} d(\theta,\hat{S})=O_p(1/\sqrt{N}).
\]
To derive the analogous bound for $\Delta_0$, first note that whenever inequality \ref{l1e1} holds, the boundedness of \( \Delta_0 \) and inequality \ref{l1e2} imply uniform (over all realizations of the sample satisfying \ref{l1e1}) boundedness of \( \Delta_0 \) and \( \hat{\Delta}_0 \). Moreover,  the constant \( R \) in inequality \ref{l1e8} can be chosen sufficiently large to serve as such a uniform bound. Then arguing as above, we obtain
\[
\sup_{\lambda \in \Delta_0} d(\lambda,\hat{\Delta})=O_p(1/\sqrt{N}).
\]
  Consequently, we obtain  
\begin{equation}
\label{l1e10}
\sup_{\theta \in S_0} d(\theta,\hat{S})=o_p(1 )\quad \text{and} \quad  \sup_{\lambda \in \Delta_0} d(\lambda,\hat{\Delta})=o_p(1).
\end{equation}
This completes the proof.
\end{proof}
