\begin{proof}[\bf{Proof of Theorem \ref{thm1}}]

The second part of Assumption \ref{A2} and Lemma \ref{lem1} imply that there exists a positive sequence of constants $\epsilon_N$ converging to zero sufficiently slowly such that the event (here $d_w$ denotes the dimension of the sample space for one observation)
\[
E_N := \left\{ \mathbb{W} \in \mathbb{R}^{d_w \times N} \ \middle| \ \max\left\{ d_H(\hat{S}, S_0), d_H(\hat{\Delta}, \Delta_0), d_{Pr}\left({\cal L}\left(\zeta^*_N \mid \mathbb{W}\right), \mathbb{G}\right) \right\} \leq \epsilon_N \right\}
\]
has probability tending to one asymptotically. Now we show that for any sequence $\{\mathbb{W}_N\}_{N \geq 1}$ such that $\mathbb{W}_N \in E_N$, we have

\begin{equation}
\label{1eqn1}
{\cal L}\left( \min_{\theta \in \hat{S}} \max_{\lambda \in \hat{\Delta}} \langle \zeta_c^*, \theta \rangle + \lambda^T\left(\zeta_b^* - \zeta_A^* \theta \right) \mid \mathbb{W}_N \right) \Rightarrow \min_{\theta \in S_0} \max_{\lambda \in \Delta_0} \langle \zeta_c, \theta \rangle + \lambda^T\left(\zeta_b - \zeta_A \theta \right)
\end{equation}
with $\zeta=(\zeta_A,\zeta_b,\zeta_c) \overset{d}{\sim} \mathbb{G}$, from which the claim of the theorem follows. Indeed, given such a sequence of data realizations $\{\mathbb{W}_N\}$, it follows from the definition of $E_N$ that 
\[
{\cal L}\left(\zeta^*_N \mid \mathbb{W}_N\right) \Rightarrow \mathbb{G}.
\]
Also, as $\hat{S}$ and $\hat{\Delta}$ are completely determined from the data,  along the data realizations $\{\mathbb{W}_N\}$, the sets $\{\hat{S}\}$, and $\{\hat{\Delta}\}$ are nonrandom and converge in the Haussdorf sense to $S_0$ and $\Delta_0$, respectively. By the Skorokhod representation theorem, there exists a sufficiently rich probability space where the latter convergence holds almost surely. Thus, given the realizations $\{\mathbb{W}_N\}$, we can assume that $\zeta^*_N \xrightarrow{a.s.} \zeta$ with $\zeta \overset{d}{\sim} \mathbb{G}$. Given a value of $\zeta$, let $F(\theta, \lambda; \zeta)$ be defined by 
\[
F(\theta, \lambda; \zeta) = \langle \zeta_c, \theta \rangle + \lambda^T\left(\zeta_b - \zeta_A \theta \right).
\]
Consider an outcome in our rich probability space where $\zeta_N^* \rightarrow \zeta$ (by assumption, the latter occurs with probability one) and set
\[
F_N(\theta, \lambda) := F(\theta, \lambda; \zeta_N^*)
\]
and
\[
F(\theta, \lambda) := F(\theta, \lambda; \zeta).
\]
Note that by the definition of $E_N$, the sets $\hat{S}$ and $\hat{\Delta}$ that correspond to realizations of the data $\mathbb{W}_N$ in $E_N$ are uniformly bounded over $N$, and we can assume that there exist compact sets $S$ and $\Delta$ such that for realizations of $\mathbb{W}_N \in E_N$, we have $\hat{S} \times \hat{\Delta} \subset S \times \Delta$. It is then not difficult to see (using the definitions of $F_N$ and $F$) that $F_N$ converges uniformly to $F$ on $S \times \Delta$. As $\max\{ d_H(\hat{S}, S_0), d_H(\hat{\Delta}, \Delta_0)\}=o(1)$ along the sequence $\{\mathbb{W}_N\}$, an application of Lemma \ref{lem2} then yields that 
\[
\min_{\theta \in \hat{S}} \max_{\lambda \in \hat{\Delta}} F_N(\theta, \lambda) \to  
\min_{\theta \in S_0} \max_{\lambda \in \Delta_0} F(\theta, \lambda).
\]
As the latter holds almost surely on our rich probability space, we conclude that 
\[
\min_{\theta \in \hat{S}} \max_{\lambda \in \hat{\Delta}} F(\theta, \lambda; \zeta_N^*) \xrightarrow{a.s.}  
\min_{\theta \in S_0} \max_{\lambda \in \Delta_0} F(\theta, \lambda; \zeta),
\]
which in turn implies \ref{1eqn1}.

\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{proof}[\bf{Proof of Theorem \ref{thmSSAS1}}]
\label{pthmSSAS1}
The starting point of the proof is equation \ref{eqnSSAS6} in Section \ref{sectionSSAS}, which we reproduce here:
\begin{equation}
\label{eqnPSSAS1}
\sqrt{N} T_N(\xi) \leq \bigl(\sqrt{N} \bigl(b_N(\xi) - b\bigr)\bigr)^\top \lambda_{\xi} .
\end{equation}
For all $\xi=(\xi_b,\xi_D)$ such that $\phi(\mu_N(\xi))$ is finite. The reader is refered to Section \ref{sectionSSAS} for the definition of the various terms involved in equation \ref{eqnPSSAS1}, and for some of the notation that is used below. Note that Assumption \ref{assSSAS1} and \ref{assSSAS2}-i) implies that the family $\{\mathcal{N}(0,\Sigma(Q))\mid Q\in \mathcal{Q}\}$ is tight, and Assumption \ref{assSSAS1} then implies that the family $\{\sqrt{N}(\hat{b}-b(Q))\mid Q\in {\cal Q}\}$ is asymptotically tight. Thus, Assumptions \ref{assSSAS1} through \ref{assSSAS3} imply that there exists $\alpha_N\downarrow 0$, such that for any $M_N\uparrow \infty$, we have 
\[
\sup_{Q\in {\cal Q}}d_{\text{Pr}}\Bigl(\sqrt{N}(\hat{b}-b), \mathcal{N}(0,\Sigma(Q))\Bigr)\leq \alpha_N
\]
and for all $Q \in {\cal Q}$, the event $E_N(Q)$ defined by
\[
E_N(Q):=\Bigl\{\mathbb{W}\ \big| \  \|\hat{D}-D\|\leq \alpha_N,\  d_{\text{Pr}}\bigl(\mathcal{L}(\zeta^*\mid \mathbb{W}),\mathcal{N}(0,\Sigma(Q))\bigr)\leq \alpha_N, \sqrt{N}\|\hat{b}-b(Q)\|\leq M_N \Bigr\}
\]
 satisfies
\[
\underline{\lim}_{N\to \infty} \inf_{Q\in {\cal Q}} Q(E_N(Q))=1.
\]
Choose $M_N\uparrow \infty$ such that $M_N=o(\kappa_N)$ and $M_N \alpha_N=o(1)$. Consider the set of pertubations $\mathcal{X}_N$ defined by
\[
\mathcal{X}_N := \left\{ \xi = (\xi_b, \xi_D) \;\middle|\; \|\xi_b\| \leq M_N, \; \|\xi_D\| \leq \sqrt{N} \alpha_N \right\},
\]

where $\xi_D$ are diagonal matrices of the same dimension as $D$. Below, we use $C$ to denote a generic constant that does not depend on $Q\in {\cal Q}$ or $N$ for all sufficiently large N. We allow the value of the constant $C$ to change from one line to the next. In the first three steps below, we establish inequality \ref{eqnSSAS4}. The fourth step gives the proof of inequality \ref{eqnSSAS5}.

\medskip

\underline{Step 1} In this step, we show there exists $\beta_N=o(1)$ such that for all sufficiently large N's and for all $Q\in {\cal Q}_0$, we have on the event $E_N(Q)$:
\begin{equation}
\label{eqnPSSAS2}
\sup_{\xi \in {\cal X}_N}\sup_{\lambda \in \Delta_{0,N}(\xi)} \Bigl\{ \xi_b^\top \lambda-\sup_{\lambda \in \hat{\Delta}} \xi_b^\top \lambda \Bigr\}\leq \beta_N,
\end{equation}
where $\hat{\Delta}$ is as in equation \ref{eqnSSAS3}. Let $\mathcal{D}$ and $\mathcal{D}_N(\xi)$ denote respectively the feasible regions of the perturbed and unperturbed LP, and defined by
\[
\mathcal{D}=\{\lambda \in \mathbb{R}_+^p \mid \|D\lambda\|_1\leq 1\} \quad \text{and} \quad \mathcal{D}_N(\xi)=\{\lambda \in \mathbb{R}_+^p \mid \|D_N(\xi)\lambda\|_1\leq 1\}.
\]
We first show that 
\begin{equation}
\label{eqnPSSAS3}
\sup_{\xi \in {\cal X}_N }d_H(\mathcal{D},\mathcal{D}_N(\xi))\leq C \alpha_N.
\end{equation}
Indeed, for $\xi \in {\cal X}_N$ and for all $N$ sufficiently large that $\alpha_N<\underline{\sigma}/2$, the diagonal entries of the matrix $D_N(\xi)$ are strictly positive and bounded below by $\underline{\sigma}/2$, where $\underline{\sigma}$ is as in Assumption \ref{assSSAS2}. We have
\[
\sigma_{min}(D_N(\xi)D^{-1})\|D\lambda\|_1\leq \|D_N(\xi)\lambda\|_1\leq \sigma_{max}(D_N(\xi)D^{-1})\|D\lambda\|_1
\]
where $\sigma_{min}(D)$ and $\sigma_{max}(D)$ denote respectively the smallest and largest eigenvalue of the diagonal matrix $D$. As the sets $\mathcal{D}$ and $\mathcal{D}_N(\xi)$ are star-shaped, \footnote{We say that a set $\mathcal{C}$ is star-shaped (with respect to the origin) if $x \in \mathcal{C}$ implies that $tx\in \mathcal{C}$ for all $t\in[0,1]$.} the latter inequality implies that 
\begin{equation}
\label{eqnPSSAS4}
\Bigl[\lambda \in \mathcal{D}_N(\xi)\Bigr]\Rightarrow \Bigl[\sigma_{min}\bigl(D_N(\xi)D^{-1}\bigr)\lambda \in \mathcal{D}\Bigr]
\end{equation}
and 
\begin{equation}
\label{eqnPSSAS5}
\Bigl[\lambda \in \mathcal{D}\Bigr]\Rightarrow \Bigl[\sigma_{min}\bigl(D_N(\xi)^{-1}D\bigr)\lambda \in \mathcal{D}_N(\xi)\Bigr].
\end{equation}
As $\|D_N(\xi)-D\|\leq \alpha_N \sqrt{N}$ on $\mathcal{X}_N$, we have 
\begin{equation}
\label{eqnPSSAS6}
\sigma_{min}\bigl(D_N(\xi)D^{-1}\bigr)\wedge \sigma_{min}\bigl(D_N(\xi)^{-1}D\bigr)\geq 1-C\alpha_N
\end{equation}
for all sufficiently large N's. Note that for all sufficiently large N's, the sets $\mathcal{D}$ and $\mathcal{D}_N(\xi)$ are bounded in the $l_1$-norm by $2/\underline{\sigma}$. Therefore, combining equations \ref{eqnPSSAS4}, \ref{eqnPSSAS5} and \ref{eqnPSSAS6}, and the fact that $\mathcal{D}$ and $\mathcal{D}_N(\xi)$ are star-shaped imply that inequality \ref{eqnPSSAS3} holds.
Note that on the event $E_N(Q)$, we have $\hat{\xi}=(\sqrt{N}(\hat{b}-b(Q)),\sqrt{N}(\hat{D}-D(Q)))\in {\cal X}_N$. Hence, the preceding argument also yields that on the event $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSAS7}
d_H\bigl(\mathcal{D},\hat{\mathcal{D}}\bigr)\leq C \alpha_N.
\end{equation}
where $\hat{\mathcal{D}}:=\{\lambda \in \mathbb{R}_+^p \mid \|\hat{D}\lambda\|_1\leq 1\} $. Moreover, inequality \ref{eqnPSSAS6} combined with its analogue for $\hat{D}$ and $D$, imply that every $\lambda \in \mathcal{D}$ has a positive scalar multiple that is in $\hat{\mathcal{D}}_N(\xi)$ and that is at a distance of at most $C\alpha_N$ from $\lambda$, and vice versa.

\medskip
Given $\lambda \in \mathbb{R}^p$, let $\hat{\Pi}(\lambda)$ denote the element on the ray $\{t\lambda\mid t\geq 0\}$ that is closest to $\lambda$ and that is in $\hat{\mathcal{D}}$. That is $\hat{\Pi}(\lambda)$ is the projection of $\lambda$ on the segment  $\{t\lambda\mid t\geq 0\}\cap \hat{\cal D}$. We now show that for all $\xi \in {\cal X}_N$, $Q\in {\cal Q_0}$, and all sufficiently large N's, on the event $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSAS8}
\hat{\Pi}(\Delta_{0,N}(\xi))\subset \hat{\Delta}.
\end{equation}
 Indeed, we have 
\[
\hat{T}_N=\sup_{\lambda \in \hat{\mathcal{D}}}\hat{b}^\top \lambda=\sup_{\lambda \in \hat{\mathcal{D}}}(\hat{b}-b)^\top \lambda+b^\top \lambda\leq \sup_{\lambda \in \hat{\mathcal{D}}}(\hat{b}-b)^\top \lambda\leq CM_N/\sqrt{N}, 
\]
where we have used the fact that $Q \in {\cal Q}_0$ implies that $b^\top \lambda\leq 0$ for all $\lambda \in {\cal D}$ (as well as those in $\hat{\cal D}$, by homogeneity),  and on $E_N(Q)$ the sets $\hat{{\cal D}}$ are uniformly bounded for all large N  (such that $\alpha_N \leq \underline{\sigma}/2$) and $\|\hat{b}-b\|\leq M_N/\sqrt{N}$. And for all $\lambda \in \Delta_{0,N}(\xi)$, we have
\[
\hat{b}^\top \hat{\Pi}(\lambda)=\bigl(\hat{b}-b_N(\xi)\bigr)^\top \hat{\Pi}(\lambda)+b_N(\xi)^\top \hat{\Pi}(\lambda)\geq \bigl(\hat{b}-b_N(\xi)\bigr)^\top \hat{\Pi}(\lambda)\geq -CM_N/\sqrt{N},
\]
since $b_N(\xi)^\top \lambda \geq 0$ for all $\lambda \in \Delta_{0,N}(\xi)$ (note that we always have $0\in \mathcal{D}_N(\xi)$), and $\|\hat{b}-b_N(\xi)\|\leq 2 M_N/\sqrt{N}$ on the event $E_N(Q)$ and for $\xi \in {\cal X}_N$. As $M_N=o(\kappa_N)$, the latter two inequalities imply that for all $\xi \in {\cal X}_N$, $Q\in {\cal Q_0}$, and all sufficiently large N's, on the event $E_N(Q)$, we have
\[
\lambda \in \Delta_{0,N}(\xi) \quad \Rightarrow \quad \hat{b}^\top \hat{\Pi}(\lambda)\geq \hat{T}_N-\kappa_N/\sqrt{N}
\]
which yields \ref{eqnPSSAS8}.

\medskip
We now establish equation \ref{eqnPSSAS2}. For all N sufficiently large, $\xi\in {\cal X}_N$, $\lambda \in \Delta_{0,N}(\xi)$, $Q\in {\cal Q}_0$, and on the event $E_N(Q)$,  we have
\[
\xi_b^\top \lambda=\xi_b^\top (\lambda-\hat{\Pi}(\lambda))+\xi_b^\top \hat{\Pi}(\lambda)\leq C M_N\alpha_N+ \sup_{\lambda \in \hat{\Delta}}\xi_b^\top \lambda
\]
where we have used the fact that every $\lambda \in \mathcal{D}_N(\xi)$ has a positive scalar multiple that is in $\hat{\mathcal{D}}$ and that is at a distance of at most $C\alpha_N$ from $\lambda$, equation \ref{eqnPSSAS8}, and the fact that $\|\xi_b\|\leq M_N$ for $\xi\in {\cal X}_N$.
Equation \ref{eqnPSSAS2} then follows by taking $\beta_N=C\alpha_N M_N$, and noting that $M_N$ is chosen such that $M_N\alpha_N=o(1)$.

\medskip

\underline{Step 2} We now use equation~\eqref{eqnPSSAS2} to couple our test statistic \( \hat{T}_N \) with a dominating statistic (in the sense of first-order stochastic dominance) whose distribution can be estimated uniformly with respect to \( Q \in \mathcal{Q}_0\).
This step culminates in equation~\eqref{eqnPSSAS14}, which establishes inequality~\eqref{eqnSSAS4} in Theorem \ref{thmSSAS1}. Let $\hat{\xi}^*=(\sqrt{N}(\hat{b}^*-b(Q)),\sqrt{N}(\hat{D}^*-D(Q)))$ be an independent and identically distributed version of the root $\hat{\xi}(Q)=(\sqrt{N}(\hat{b}-b(Q)),\sqrt{N}(\hat{D}-D(Q)))$, computed from a sample $\mathbb{W}_N^*$, such that $\mathbb{W}_N^*$ and $\mathbb{W}_N$ are independent and identically distributed. Using the notation of Section \ref{sectionSSAS} that is introduced prior to the derivation of equation \ref{eqnSSAS6}, let $\hat{T}_N^*=\phi(\mu_N(\hat{\xi}^*))$ be an independent version of $\hat{T}_N$ constructed from $\hat{\xi}^*$. For $Q\in {\cal Q}$, let the event $F^*_N=F^*_N(Q)$ be defined by 
\[
F_N^*(Q) := \left\{ \mathbb{W}^* \;\middle|\; \|\hat{\xi}^*_b\| > M_N \;\text{or}\; \|\hat{\xi}^*_D\| > \sqrt{N} \alpha_N \right\}.
\]

By our choice of $M_N$ and $\alpha_N$, we have 
\[
\delta_N:=\sup_{Q\in {\cal Q}} Q\bigl(F^*_N(Q)\bigr) \quad \text{satisfies}\quad \lim_{N\to \infty} \delta_N=0
\]
Equations \ref{eqnPSSAS1} and \ref{eqnPSSAS2} then imply that on the event $E_N(Q)$, $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSAS9}
\sqrt{N}\hat{T}_N^*\leq \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b, \lambda \rangle +\beta_N+\infty\cdot \mathbbm{1}_{\{F_N^*\}}.
\end{equation}
Let \( J_N(\cdot; Q) \) denote the CDF of \( \sqrt{N} \hat{T}_N \). Define
\[
\hat{G}_N(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b, \lambda \rangle + \beta_N + \infty \cdot \mathbbm{1}_{\{F_N^*\}} \,\middle|\, \mathbb{W}_N \right)
\]
as the conditional (on \( \mathbb{W}_N \)) CDF of the right-hand side of inequality \eqref{eqnPSSAS9}, viewed as a random element taking values in \( \mathbb{R} \cup \{\infty\} \).  
Similarly, define
\[
\hat{G}_\infty(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\]
where \( \zeta \sim N(0, \Sigma(Q)) \). And let $\hat{H}_N(;Q)$ be defined as in Theorem \ref{thmSSAS1}
\[
\hat{H}_N(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta^*_N, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\]
where $\zeta^*$ is the bootstrap estimate of of $\zeta$ that is given in Assumption \ref{assSSAS3}.
By Strassen's theorem (coupling characterization of the Prokhorov distance), Assumption \ref{assSSAS1}, and our choice of $\alpha_N$, we have on the event $E_N(Q)$
\begin{equation}
\label{eqnPSSAS10}
\begin{aligned}
d_{\text{Pr}}\Big( \hat{G}_N, \hat{G}_{\infty} \Big) 
&\leq d_{\text{Pr}}\Bigg( \hat{G}_N, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg) \\
&\quad + d_{\text{Pr}}\Bigg( \hat{G}_{\infty}, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg)\\
&\leq \beta_N+Q(F_N^*)+C \alpha_N
\end{aligned}
\end{equation}
where we have used in part the fact that \( d_{\text{Pr}}(\hat{\xi}_b^*, \zeta) \leq \alpha_N \) and Strassen's theorem imply that\footnote{Strassen's theorem implies that if $d_{Pr}(X,Y)\leq \epsilon$ and $f$ is a Lipschitz function that satisfies $\|f\|_{\text{Lip}}\leq C$, then $d_{Pr}(f(X),f(Y))\leq (C\vee 1) \epsilon$. The Lipschitz boundedness in our case follows since $\hat{\Delta}$ are uniformly (w.r.t sufficiently large N and $Q\in {\cal Q}_0$, and on the event $E_N(Q)$) bounded.}
\[
 d_{\text{Pr}}\Bigg( \hat{G}_{\infty}, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg)=d_{\text{Pr}}\left( \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta, \lambda \rangle \,\middle|\, \mathbb{W}_N \right), \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \right) \leq C \alpha_N,
\]
since for all sufficiently large \( N \), the sets \( \hat{\Delta} \) are uniformly bounded on the event \( E_N \).
Similarly, since we have the inequality
\[
d_{\text{Pr}}\bigl( \mathcal{L}(\zeta^* \mid \mathbb{W}), \mathcal{N}(0, \Sigma(Q)) \bigr) \leq \alpha_N
\]
on \( E_N(Q) \) (by the definition of \( E_N(Q) \)), it follows from Strassen's theorem that
\[
d_{\text{Pr}}\left( \hat{G}_{\infty}, \hat{H}_N \right) \leq C \alpha_N
\]
on \( E_N(Q) \), for all sufficiently large \( N \). 

\medskip
In conclusion, there exists $\gamma_N=o(1)$ such that for all sufficiently large N and all $Q \in {\cal Q}$, on the event $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSAS11}
d_{\text{Pr}}\bigl(\hat{G}_N,\hat{G}_{\infty}\bigr)\vee d_{\text{Pr}}\bigl(\hat{H}_N,\hat{G}_{\infty}\bigr)\leq \gamma_N.
\end{equation}
Let the significance level \( \alpha \) and the critical value \( \hat{c}_N(1-\alpha) \) be as in Theorem~\ref{thmSSAS1}.
For now, assume that there exists a constant \( C \) such that for all sufficiently large \( N \), for all \( Q \in \mathcal{Q}_0 \), and for all sample realizations \( \mathbb{W}_N \) on the event \( E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), we have the anti-concentration condition
\begin{equation}
\label{eqnPSSAS12}
\hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) + \gamma_N \big) - \hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) - \gamma_N \big) \leq C \gamma_N.
\end{equation}
We prove in the next step that inequality~\eqref{eqnPSSAS12} indeed holds. For \( \mathbb{W}_N \in E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), and $Q\in {\cal Q}_0$, we then have\footnote{This argument is similar to the proof of Theorem 2.1 in \cite{JRAS}}
\begin{equation}
\label{eqnPSSAS13}
\begin{aligned}
J_N\big( \hat{c}_N(1-\alpha) \big) 
&\geq \hat{G}_N\big( \hat{c}_N(1-\alpha) \big) \\
&\geq \hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) - \gamma_N \big) - \gamma_N\\
&\geq \hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) + \gamma_N \big) - C\gamma_N\\
&\geq \hat{H}_{N}\big( \hat{c}_N(1-\alpha)\big) - C\gamma_N\\
&\geq 1-\alpha-C\gamma_N
\end{aligned}
\end{equation}
where we have used ~\eqref{eqnPSSAS12} to derive the third inequality, and where the other inequalities follow from ~\eqref{eqnPSSAS11} and the fact that $\hat{H}_N(\hat{c}_N(1-\alpha))\geq 1-\alpha$ by the definition of $\hat{c}_N(1-\alpha)$. Let $q_{N}(\cdot)$ denote the quantiles of $J_N(\cdot)$. Inequality \ref{eqnPSSAS13} then implies that on the event \(E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), with $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSAS133}
q_N(1-\alpha-C\gamma_N)\leq \hat{c}_N(1-\alpha).
\end{equation}
We are now ready to establish inequality \ref{eqnSSAS4} from the theorem. We have
\begin{equation}
\label{eqnPSSAS14}
\begin{aligned}
\sup_{Q\in {\cal Q}_0}Q\Bigl(\{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \Bigr)&\leq \sup_{Q\in {\cal Q}_0}Q\Bigl(\{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \cap E_N(Q)\Bigr)+\delta_N\\
&\leq \sup_{Q\in {\cal Q}_0}Q\Bigl(\{ \sqrt{N} \hat{T}_N > q_N(1-\alpha-C\gamma_N) \}\Bigr)+\delta_N\\
&\leq \alpha+C\gamma_N+\delta_N.
\end{aligned}
\end{equation}
which yields equation \ref{eqnSSAS4}.

\medskip
\underline{Step 3} We now establish the anti-concentration condition in equation~\ref{eqnPSSAS12}. First, note that on the event $\{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \}$—that is, when the test rejects the null—the optimum of the linear program defining $\hat{T}_N$ is achieved at a vertex of the feasible set other than the origin, as rejection implies that $\hat{T}_N>0$, and $\hat{T}_N$ is given by 
\[
\hat{T}_N = \max \left\{ \hat{b}^\top \lambda \;\middle|\; \lambda \in \mathbb{R}^p_+, \; \|\hat{D} \lambda\|_1 \leq 1 \right\}.
\]
 It is straightforward to verify that the set of extreme points of the feasible region $\hat{\mathcal{D}}$, denoted $\mathrm{extr}(\hat{\mathcal{D}})$, is given by
\[
\mathrm{extr}(\hat{\mathcal{D}}) = \left\{ 0, \frac{\mathbf{e}_1}{\hat{\sigma}_1}, \ldots, \frac{\mathbf{e}_p}{\hat{\sigma}_p} \right\},
\]
where $\mathbf{e}_j$ is the $j$th canonical basis vector in $\mathbb{R}^p$ (i.e., the vector with a 1 in the $j$th coordinate and zeros elsewhere), and $\hat{\sigma}_i$ denotes the $i$th diagonal element of $\hat{D}$. For $i = 1, \ldots, p$, define $\hat{\lambda}_i := \mathbf{e}_i / \hat{\sigma}_i$.

From this, we conclude that on the event of a rejection, it must be that (with $\hat{\Delta}$ as in equation \ref{eqnSSAS3})
\begin{equation}
\label{eqnPSSAS15}
\hat{\Delta} \cap \left\{ \hat{\lambda}_i \mid i = 1, \ldots, p \right\} \neq \emptyset.
\end{equation}
Moreover, for all $N$ sufficiently large such that $\alpha_N \leq \underline{\sigma} / 2$, and for all $Q \in \mathcal{Q}$, on the event $E_N(Q)$, for any $i\in[p]$, we have
\begin{equation}
\label{eqnPSSAS16}
\mathcal{L}\left( \left\langle \zeta, \hat{\lambda}_i \right\rangle \;\middle|\; \mathbb{W}_N \right) \sim \mathcal{N}\left( 0, \frac{\sigma_i(Q)^2}{\hat{\sigma}_i^2} \right) \quad \text{and } \quad \frac{\sigma_i(Q)^2}{\hat{\sigma}_i^2}\geq 4/9
\end{equation}
where $\sigma_i(Q)^2$ denotes the $i^{th}$ diagonal element of the asymptotic covariance matrix $\Sigma(Q)$. Indeed, on the event $E_N(Q)$, we have $|\hat{\sigma}_i - \sigma_i| \leq \alpha_N$, and the condition $\alpha_N \leq \underline{\sigma}/2$ implies that $\hat{\sigma}_i \leq \tfrac{3}{2} \sigma_i$ for any $i \in \{1, \ldots, p\}$, and thus $\sigma_i / \hat{\sigma}_i \geq \tfrac{2}{3}$. 

Recalling that the sets $\hat{\mathcal{D}}$ (and thus $\hat{\Delta}$) are uniformly bounded for all sufficiently large $N$ and for all $Q \in \mathcal{Q}$, equations~\ref{eqnPSSAS15} and~\ref{eqnPSSAS16} can be used to verify the conditions of Proposition~\ref{prop1}, which yields the desired conclusion, namely equation~\ref{eqnPSSAS12}.



\medskip
\underline{Step 4} Fix $Q \in \mathcal{Q}_0$. Under Assumption~\ref{assSSAS1}, Lemma \ref{lemAD} implies that the asymptotic distribution of $\sqrt{N} \hat{T}_N$ is given by
\begin{equation}
\label{eqnPSSAS17}
\max \left\{ \zeta^\top \lambda \;\middle|\; \lambda \in \Delta_0(Q) \right\},
\end{equation}
where $\Delta_0(Q) := \arg\max \{ b(Q)^\top \lambda \mid \lambda \in \mathbb{R}^p_+, \|D(Q)\lambda\|_1 \leq 1 \}$ and $\zeta \sim \mathcal{N}(0, \Sigma(Q))$. Let $G_\infty(\cdot)$ denote the CDF of~\eqref{eqnPSSAS17}. Then $d_{\mathrm{Pr}}(\mathcal{L}(\sqrt{N} \hat{T}_N), G_\infty) = o(1)$. To prove~\eqref{eqnSSAS5}, it suffices to show
\begin{equation}
\label{eqnPSSAS18}
d_{\mathrm{Pr}}(\hat{H}_N, G_\infty) = o_p(1),
\end{equation}
where $\hat{H}_N$ is the conditional (given $\mathbb{W}_N$) CDF in~\eqref{eqnSSAS3}. We show below that $d_H(\Delta_0(Q), \hat{\Delta}) = o_p(1)$, from which~\eqref{eqnPSSAS18} follows via an almost sure representation argument as in Theorem \ref{thm1}.\footnote{If $d_H(\Delta_n,\Delta)\to 0$ and $\zeta_n \xrightarrow{a.s.} \zeta$, then $\max_{\lambda\in \Delta_n} \zeta_n^\top \lambda \to \max_{\lambda \in \Delta} \zeta^\top \lambda$ a.s.}

From~\eqref{eqnPSSAS7} and~\eqref{eqnPSSAS8} (with $\xi = 0$), on $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSAS19}
d_H(\mathcal{D}, \hat{\mathcal{D}}) \leq C\alpha_N, \quad \text{and} \quad \vec{d}_H(\Delta_0, \hat{\Delta}) \leq C\alpha_N.
\end{equation}
It remains to show $\vec{d}_H(\hat{\Delta}, \Delta_0) \to 0$ on $E_N(Q)$. Fix $\epsilon > 0$. On $E_N(Q)$,~\eqref{eqnPSSAS19} implies\footnote{We use $[A]^{\epsilon}$ to denote the $\epsilon$ neighborhood of the set $A$.}
\[
\hat{\Delta} \subset \hat{\mathcal{D}} \subseteq [\mathcal{D}]^{C\alpha_N},
\]
and for any $\lambda \in \hat{\mathcal{D}}$, there exists $\Gamma(\lambda) \in \mathcal{D}$ with $\|\lambda - \Gamma(\lambda)\| \leq C\alpha_N$. If $\lambda \in \hat{{\cal D}}\backslash[\Delta_0]^\epsilon$, then $d(\Gamma(\lambda), \Delta_0) > \epsilon-C\alpha_N>\epsilon/2$ for all large N. By the definition of $\Delta_0$, there exists $\delta>0$ such that $\langle b, \lambda \rangle < -\delta$ for all $\lambda \in {\cal D}\backslash [\Delta_0]^{\epsilon}$. Then on $E_N(Q)$, for $\lambda\in \hat{{\cal D}}\backslash[\Delta_0]^\epsilon$ and all large N,
\begin{equation}
\begin{aligned}
\label{eqnPSSAS20}
\langle \hat{b}, \lambda \rangle &= \langle \hat{b}, \lambda - \Gamma(\lambda) \rangle + \langle \hat{b} - b, \Gamma(\lambda) \rangle + \langle b, \Gamma(\lambda) \rangle \\
&\leq C(M_N/\sqrt{N} + \alpha_N) - \delta \leq -\delta/2,
\end{aligned}
\end{equation}
where we have used the fact that for $Q\in {\cal Q}_0$, $\langle b, \lambda\rangle \leq 0$ for any $\lambda \in {\cal D}$.
Also, from the proof of ~\eqref{eqnPSSAS8}, for $Q\in {\cal Q}_0$, we have $\hat{T}_N \leq C M_N / \sqrt{N}$ on $E_N(Q)$, so
\[
\hat{T}_N - \kappa_N / \sqrt{N} = o(1)
\]
since $\kappa_N = o(\sqrt{N})$. Combining this with~\eqref{eqnPSSAS20}, we get $\hat{\Delta} \subset [\Delta_0]^{\epsilon}$ on $E_N(Q)$ for all large $N$. As $\epsilon > 0$ is arbitrary and $Q(E_N) \to 1$, this yields $\vec{d}_H(\hat{\Delta}, \Delta_0) = o_p(1)$, as claimed.
\end{proof}

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{proof}[\bf{Proof of Theorem \ref{thmSSARP1}}]
\label{pthmSSARP1}
As in the proof of Theorem~\ref{thmSSAS1}, let $L(\lambda, x, y)$ denote the Lagrangian associated with the LP in \eqref{eqnSSARP0}, defined as
\[
L(\lambda, x, y) = b^\top \lambda + x(1 - \mathbbm{1}^\top D \lambda) - y^\top A^\top \lambda,
\]
where $x$ is a nonnegative scalar and $y \in \mathbb{R}^p$ are the Lagrange multipliers. Let $\Delta_0$ and $S_0$ denote, respectively, the sets of optimal solutions to the primal and dual problems associated with the LP in \eqref{eqnSSARP0}.

To analyze the value function under perturbations, let the input triple be denoted by $\mu = (b, A, D)$, and let $\phi(\mu)$ denote the value of the LP in \eqref{eqnSSARP0} given these inputs. For perturbations $\xi = (\xi_b, \xi_A, \xi_D)$ and sample size $N$, define the perturbed inputs as $\mu_N(\xi) = (b_N(\xi), A_N(\xi), D_N(\xi)) = \left(b + \frac{\xi_b}{\sqrt{N}}, A + \frac{\xi_A}{\sqrt{N}}, D + \frac{\xi_D}{\sqrt{N}}\right)$.

Since the matrix $A$ is known, we will only consider perturbations with $\xi_A = 0$, and by abuse of notation, write $\xi = (\xi_b, \xi_D)$ and $\mu_N(\xi) = (b_N(\xi), D_N(\xi))$. Let $L_N(\lambda, x, y; \xi)$ denote the Lagrangian associated with the LP in \eqref{eqnSSARP0} under the perturbed inputs $\mu_N(\xi)$, defined by
\[
L_N(\lambda, x, y; \xi) = b_N(\xi)^\top \lambda + x(1 - \mathbbm{1}^\top D_N(\xi) \lambda) - y^\top A^\top \lambda.
\]
Let $\Delta_{0,N}(\xi)$ and $S_{0,N}(\xi)$ denote, respectively, the sets of optimal solutions to the perturbed primal and dual problems. Note that the functions $L$ and $L_N$, as well as the sets $\Delta_0$, $\Delta_{0,N}$, and others, all depend on $\mu$ (or on $Q$); however, this dependence is omitted for notational simplicity.

The first step in our proof, as in that of Theorem~\ref{thmSSAS1}, is to establish the analogue of equation~\eqref{eqnSSAS6}. To that end, let $(\lambda_0, x_0, y_0) \in \Delta_0 \times S_0$ and $(\lambda_{\xi}, x_{\xi}, y_{\xi}) \in \Delta_{0,N}(\xi) \times S_{0,N}(\xi)$. By the saddle point property of the Lagrangian, for sufficiently small perturbations such that the LP remains feasible, we have
\begin{equation*}
\begin{aligned}
\sqrt{N} \bigl(\phi(\mu_N(\xi)) - \phi(\mu)\bigr)
&= \sqrt{N} \bigl(L_N(\lambda_{\xi}, x_{\xi}, y_{\xi}; \xi) - L(\lambda_0, x_0, y_0)\bigr) \\
&\leq \sqrt{N} \bigl(L_N(\lambda_{\xi}, x_0, y_0; \xi) - L(\lambda_{\xi}, x_0, y_0)\bigr) \\
&= \sqrt{N}(b_N(\xi) - b)^\top \lambda_{\xi} - x_0 \mathbbm{1}^\top \sqrt{N}(D_N(\xi) - D)\lambda_{\xi}.
\end{aligned}
\end{equation*}

Now, for $Q \in \mathcal{Q}_0$ we have $\phi(\mu) = 0$, and $(x_0, y_0) \in S_0$ implies that $x_0 = 0$ and $b - A y_0 \leq 0$. Therefore, the inequality simplifies to
\begin{equation}
\sqrt{N} \, \phi(\mu_N(\xi)) \leq \xi_b^\top \lambda_{\xi},
\label{eqnPSSARP0}
\end{equation}
which corresponds exactly to inequality~\eqref{eqnSSAS6}.

 Now, note that Assumptions \ref{assSSAS1} and \ref{assSSARP1}-i) imply that the family $\{\mathcal{N}(0,\Sigma(Q))\mid Q\in \mathcal{Q}\}$ is tight, and Assumption \ref{assSSAS1} then implies that the family $\{\sqrt{N}(\hat{b}-b(Q))\mid Q\in {\cal Q}\}$ is asymptotically tight. Thus, Assumptions \ref{assSSAS1}, \ref{assSSAS3} and \ref{assSSARP1} imply that there exists $\alpha_N\downarrow 0$, such that for any $M_N\uparrow \infty$, we have 
\[
\sup_{Q\in {\cal Q}}d_{\text{Pr}}\Bigl(\sqrt{N}(\hat{b}-b), \mathcal{N}(0,\Sigma(Q))\Bigr)\leq \alpha_N
\]
and for all $Q \in {\cal Q}$, the event $E_N(Q)$ defined by
\[
E_N(Q):=\Bigl\{\mathbb{W}\ \big| \  \|\hat{D}-D\|\leq \alpha_N,\  d_{\text{Pr}}\bigl(\mathcal{L}(\zeta^*\mid \mathbb{W}),\mathcal{N}(0,\Sigma(Q))\bigr)\leq \alpha_N, \sqrt{N}\|\hat{b}-b(Q)\|\leq M_N \Bigr\}
\]
 satisfies
\[
\underline{\lim}_{N\to \infty} \inf_{Q\in {\cal Q}} Q(E_N(Q))=1.
\]
Choose $M_N\uparrow \infty$ such that $M_N=o(\kappa_N)$ and $M_N \alpha_N=o(1)$. When $N$ is sufficiently large that $\alpha_N<\underline{\sigma}$, the indices of the diagonal entries of the matrices $\hat{D}$ and $D$ that are nonzero coincide, and correspond to the indices of the estimated components of $b$. In what follows, we let $\Pi^u$ denote the projection on the unknown components of b that must be estimated. \footnote{\label{footPSSARP1}For example, if $b = (b_1, b_2, b_3, b_4)$, and $b_1$ and $b_3$ are known while $b_2$ and $b_4$ are unknown and must be estimated, then $\Pi^u(b)$ denotes the vector $(0,b_2,0, b_4)$. Similarly, $\Pi^u(\lambda) = (0,\lambda_2, 0, \lambda_4)$.} Consider the set of pertubations $\mathcal{X}_N$ defined by
\[
\mathcal{X}_N := \left\{ \xi = (\xi_b, \xi_D) \;\middle|\; \|\xi_b\| \leq M_N, \; \|\xi_D\| \leq \sqrt{N} \alpha_N \right\},
\]
where, $\xi_D$ denotes diagonal matrices of the same dimensions as $D$, with diagonal entries corresponding to the deterministic components of $b$ equal to zero, and $\xi_b$ is a vector of the same dimension as $b$ with entries corresponding to the deterministic component of $b$ equal to zero. It is natural to consider such restrictive perturbations $\xi_D$, as they are similar to perturbations that arise from estimation ($\hat{D}-D$ has diagonal entries corresponding to known components of $b$ equal to zero).  Throughout the argument below, we use $C$ to represent a generic constant that does not depend on $Q \in \mathcal{Q}$ or on $N$, for all sufficiently large $N$. The value of $C$ may vary from line to line.

In the first three steps below, we establish inequality~\eqref{eqnSSARP5}. The fourth step provides the proof of inequality~\eqref{eqnSSARP6}. These steps closely mirror those used in the proof of Theorem~\ref{thmSSAS1}, and we occasionally refer to that proof when the arguments are essentially the same.

\medskip
\underline{Step 1}
In this step, we show there exists $\beta_N=o(1)$ such that for all sufficiently large N's and for all $Q\in {\cal Q}_0$, we have on the event $E_N(Q)$:
\begin{equation}
\label{eqnPSSARP1}
\sup_{\xi \in {\cal X}_N}\sup_{\lambda \in \Delta_{0,N}(\xi)} \Bigl\{ \xi_b^\top \lambda-\sup_{\lambda \in \hat{\Delta}} \xi_b^\top \lambda \Bigr\}\leq \beta_N,
\end{equation}
where $\hat{\Delta}$ is as in equation \ref{eqnSSARP4}. Let $\mathcal{D}$ and $\mathcal{D}_N(\xi)$ denote respectively the feasible regions of the unperturbed and perturbed LP. Note that since some diagonal entries of the matrices $D$ and $D_N(\xi)$ can be zero, it is possible for the sets ${\cal D}$ and ${\cal D}_N(\xi)$ to be unbounded. we first show that for all sufficiently large N, for all $Q\in {\cal Q}_0$, and $\xi \in {\cal X}_N$, we have that for each $\lambda \in {\cal D}_N(\xi)$ there exists $\Gamma(\lambda)\in \hat{{\cal D}}$ such that $\Gamma(\lambda)$ is a positive scalar multiple of $\lambda$ and 
\begin{equation}
\label{eqnPSSARP2}
\|\Pi^u(\lambda)-\Pi^u(\Gamma(\lambda))\|\leq C \alpha_N
\end{equation}
where $\Pi^u$ is as in Footnote \ref{footPSSARP1}. Note that for all large N such that $\alpha_N<\underline{\sigma}/2$ (with $\underline{\sigma}$ given in Assumption \ref{assSSARP1}) and for $\xi\in {\cal X}_N$, we have 
\[
\|D_N(\xi)\lambda\|_1=\|\Pi^u(D_N(\xi)\lambda)\|_1\geq \underline{\sigma}/2 \|\Pi^u(\lambda)\| \quad \quad \forall \lambda \in \mathbb{R}^p,
\]
which yields\footnote{The same is true on the event $E_N(Q)$, when ${\cal D}_N(\xi)$ is replaced by $\hat{\cal D}$.}
\begin{equation}
\label{eqnPSSARP4}
\sup_{ \lambda \in {\cal D}_N(\xi)} \|\Pi^u(\lambda)\|_1 \leq 2/\underline{\sigma}.
\end{equation}
Focusing on the component of $\lambda$ that corresponds to the estimated part of $b$, and  arguing as in the proof of Theorem \ref{thmSSAS1}, we have $\forall \lambda \in \mathbb{R}^p$
\begin{equation}
\label{eqnPSSARP40}
(1-\alpha_N/\underline{\sigma})\|\Pi^u(D \lambda)\|_1\leq \|\Pi^u(D_N(\xi)\lambda)\|_1\leq (1+\alpha_N/\underline{\sigma})\|\Pi^u(D \lambda)\|_1.
\end{equation}
As a consequence, since the sets ${\cal D}$ and ${\cal D}_N(\xi)$ are star-shaped w.r.t. the origin, for each $\lambda \in {\cal D}_N(\xi)$, we have $(1-\alpha_N/\underline{\sigma})\lambda \in {\cal D}$. Similarly, since $\|\hat{D}-D\|\leq \alpha_N$ on $E_N(Q)$, for all $\lambda \in \mathbb{R}^p$ and N such that $\alpha_N<\underline{\sigma}/2$, we have
\begin{equation}
\label{eqnPSSARP41}
(1-2\alpha_N/\underline{\sigma})\|\Pi^u(\hat{D} \lambda)\|_1\leq \|\Pi^u(D\lambda)\|_1\leq (1+2\alpha_N/\underline{\sigma})\|\Pi^u(\hat{D} \lambda)\|_1.
\end{equation}
Hence, for each $\lambda \in {\cal D}$, we have $(1-2\alpha_N/\underline{\sigma})\lambda \in \hat{{\cal D}}$. Combining the latter two observations implies that for all $\lambda \in {\cal D}_N(\xi)$, we can set $\Gamma(\lambda)=(1-\alpha_N/\underline{\sigma})(1-2\alpha_N/\underline{\sigma})\lambda \in \hat{{\cal D}}$, and we get
\[
\|\Pi^u(\Gamma(\lambda)) - \Pi^u(\lambda)\| \leq C \alpha_N \|\Pi^u(\lambda)\| \leq C \alpha_N,
\]
where we have used equation \ref{eqnPSSARP4}.
This proves equation \ref{eqnPSSARP2}.

Returning to the proof of equation \ref{eqnPSSARP1}, for $\xi\in {\cal X}_N$ and on the event $E_N(Q)$, we have
\begin{equation*}
\begin{aligned}
\sup_{\lambda \in \Delta_{0,N}(\xi)} \xi_b^\top \lambda &\leq \sup_{\lambda \in \Delta_{0,N}(\xi)} \xi_b^\top\bigl( \Pi^u(\lambda-\Gamma(\lambda))\bigr)+\sup_{\lambda \in \Delta_{0,N}(\xi)} \xi_b^\top\Gamma( \lambda)\\
&\leq CM_N\alpha_N+\sup_{\lambda \in \Delta_{0,N}(\xi)} \xi_b^\top\Gamma( \lambda),
\end{aligned}
\end{equation*}
where we have used equation \ref{eqnPSSARP2} and the fact that the part of $\xi_b$ that corresponds to the deterministic component of $b$ is equal to zero. Inequality \ref{eqnPSSARP1} then follows, with $\beta_N=CM_N\alpha_N$, if we show that for all $Q\in {\cal Q}_0$, $\xi \in {\cal X}_N$, and sufficiently large N, we have
\begin{equation}
\label{eqnPSSARP3}
\{\Gamma(\lambda)\mid \lambda \in \Delta_{0,N}(\xi)\}\subseteq \hat{\Delta}
\end{equation}
on the event $E_N(Q)$. We now proceed to prove \ref{eqnPSSARP3}. For $\lambda\in \hat{{\cal D}}$, for $Q\in {\cal Q}_0$ and on the event $E_N(Q)$, we have
\[
\langle \hat{b},\lambda\rangle=\langle \hat{b}-b,\Pi^u(\lambda)\rangle+\langle b,\lambda\rangle\leq CM_N/\sqrt{N},
\]
where we have used \ref{eqnPSSARP4} and the fact that for $Q\in {\cal Q}_0$, $b^\top \lambda\leq 0$ for all $\lambda \in {\cal D}$ (and thus in $\hat{{\cal D}}$). This yields
\begin{equation}
\label{eqnPSSARP04}
0\leq \hat{v}\leq CM_N/\sqrt{N}.
\end{equation}
Also, for $\xi \in {\cal X}_N$, $\lambda \in \Delta_{0,N}(\xi)$, and on the event $E_N(Q)$, we have
\begin{equation*}
\begin{aligned}
\langle \hat{b}, \Gamma(\lambda) \rangle&=\langle \hat{b}-b, \Pi^u(\Gamma(\lambda)) \rangle+\langle b-b_N(\xi), \Pi^u(\Gamma(\lambda))+\langle b_N(\xi), \Gamma(\lambda) \rangle \rangle\\
&\geq -CM_N/\sqrt{N}, 
\end{aligned}
\end{equation*}
where we have used the fact that $b_N(\xi)^\top \Gamma(\lambda)\geq 0$ for all $\lambda\in \Delta_{0,N}(\xi)$, which holds since $b_N(\xi)^\top\lambda \geq 0$ for all $\lambda\in \Delta_{0,N}(\xi)$ (the origin is always feasible), and $\Gamma(\lambda)$ is a positive scalar multiple of $\lambda$. By our choice of $M_N$, we have $M_N=o(\kappa_N)$, and this combined with the preceding inequalities yields that for all sufficiently large N, for $\xi \in {\cal X}_N$ and $Q\in {\cal Q}_0$, we have
\[
\langle \hat{b}, \Gamma(\lambda) \rangle\geq \hat{v}-\kappa_N/\sqrt{N}
\]
for all $\lambda \in \Delta_{0,N}(\xi)$, which yields equation \ref{eqnPSSARP3}, and concludes the proof of equation \ref{eqnPSSARP1}.

\medskip

\underline{Step 2} \quad In this step, we use equation~\eqref{eqnPSSARP1} and a coupling argument to upper bound the test statistic by another statistic whose distribution can be uniformly estimated for all $Q \in \mathcal{Q}_0$. The proof closely parallels Step 2 in the proof of Theorem~\ref{thmSSAS1}. Let $\hat{\xi}^*=(\sqrt{N}(\hat{b}^*-b(Q)),\sqrt{N}(\hat{D}^*-D(Q)))$ be an independent and identically distributed version of the root $\hat{\xi}(Q)=(\sqrt{N}(\hat{b}-b(Q)),\sqrt{N}(\hat{D}-D(Q)))$, computed from a sample $\mathbb{W}_N^*$, such that $\mathbb{W}_N^*$ and $\mathbb{W}_N$ are independent and identically distributed. For $Q\in {\cal Q}$, let the event $F^*_N=F^*_N(Q)$ be defined by 
\[
F_N^*(Q) := \left\{ \mathbb{W}^* \;\middle|\; \|\hat{\xi}^*_b\| > M_N \;\text{or}\; \|\hat{\xi}^*_D\| > \sqrt{N} \alpha_N \right\}.
\]
By our choice of $M_N$ and $\alpha_N$, we have 
\[
\delta_N:=\sup_{Q\in {\cal Q}} Q\bigl(F^*_N(Q)\bigr) \quad \text{satisfies}\quad \lim_{N\to \infty} \delta_N=0
\]
Equations \ref{eqnPSSARP0} and \ref{eqnPSSARP1} then imply that on the event $E_N(Q)$, $Q\in {\cal Q}_0$, we have

\begin{equation}
\label{eqnPSSARP5}
\sqrt{N}\phi(\mu_N(\hat{\xi}^*))\leq \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b, \lambda \rangle +\beta_N+\infty\cdot \mathbbm{1}_{\{F_N^*\}}.
\end{equation}
Let \( J_N(\cdot; Q) \) denote the CDF of \( \sqrt{N} \hat{T}_N \). Define
\[
\hat{G}_N(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b, \lambda \rangle + \beta_N + \infty \cdot \mathbbm{1}_{\{F_N^*\}} \,\middle|\, \mathbb{W}_N \right)
\]
as the conditional (on \( \mathbb{W}_N \)) CDF of the right-hand side of inequality \eqref{eqnPSSARP5}, viewed as a random element taking values in \( \mathbb{R} \cup \{\infty\} \).  
Similarly, define
\[
\hat{G}_\infty(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\]
where \( \zeta \sim N(0, \Sigma(Q)) \). And let $\hat{H}_N(;Q)$ be defined as in Theorem \ref{thmSSARP1}
\[
\hat{H}_N(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta^*_N, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\]
where $\zeta^*$ is the bootstrap estimate of of $\zeta$ that is given in Assumption \ref{assSSAS3}.

By Strassen's theorem and our choice of $\alpha_N$, we have on the event $E_N(Q)$
\begin{equation}
\label{eqnPSSARP6}
\begin{aligned}
d_{\text{Pr}}\Big( \hat{G}_N, \hat{G}_{\infty} \Big) 
&\leq d_{\text{Pr}}\Bigg( \hat{G}_N, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg) \\
&\quad + d_{\text{Pr}}\Bigg( \hat{G}_{\infty}, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg)\\
&\leq \beta_N+Q(F_N^*)+C \alpha_N.
\end{aligned}
\end{equation}
Here, we have in part used the fact that, equation \ref{eqnPSSARP4}, the inequality \( d_{\text{Pr}}(\hat{\xi}_b^*, \zeta) \leq \alpha_N \) on $E_N(Q)$, and Strassen's theorem, imply that
\[
 d_{\text{Pr}}\Bigg( \hat{G}_{\infty}, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg)=d_{\text{Pr}}\left( \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta, \Pi^u(\lambda) \rangle \,\middle|\, \mathbb{W}_N \right), \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}_b^*, \Pi^u(\lambda) \rangle \,\middle|\, \mathbb{W}_N \right) \right) \leq C \alpha_N.
\]
Similarly, as
\[
d_{\text{Pr}}\bigl( \mathcal{L}(\zeta^* \mid \mathbb{W}), \mathcal{N}(0, \Sigma(Q)) \bigr) \leq \alpha_N
\]
holds on the event \( E_N(Q) \) (by the definition of \( E_N(Q) \)), it follows from Strassen's theorem that
\[
d_{\text{Pr}}\left( \hat{G}_{\infty}, \hat{H}_N \right) \leq C \alpha_N
\]
on \( E_N(Q) \), for all sufficiently large \( N \). 


\medskip
In conclusion, there exists $\gamma_N=o(1)$ such that for all sufficiently large N and all $Q \in {\cal Q}_0$, on the event $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSARP7}
d_{\text{Pr}}\bigl(\hat{G}_N,\hat{G}_{\infty}\bigr)\vee d_{\text{Pr}}\bigl(\hat{H}_N,\hat{G}_{\infty}\bigr)\leq \gamma_N.
\end{equation}
Let the significance level \( \alpha \) and the critical value \( \hat{c}_N(1-\alpha) \) be as in Theorem~\ref{thmSSARP1}.
For now, assume that there exists a constant \( C \) such that for all sufficiently large \( N \), for all \( Q \in \mathcal{Q}_0 \), and for all sample realizations \( \mathbb{W}_N \) on the event \( E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), we have the anti-concentration condition
\begin{equation}
\label{eqnPSSARP8}
\hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) + \gamma_N \big) - \hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) - \gamma_N \big) \leq C \gamma_N.
\end{equation}
We prove in the next step that inequality~\eqref{eqnPSSARP8} indeed holds. For \( \mathbb{W}_N \in E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), and $Q\in {\cal Q}_0$, arguing as in \ref{eqnPSSAS13}, we have
\begin{equation}
\label{eqnPSSARP9}
J_N\big( \hat{c}_N(1-\alpha) \big) \geq 1-\alpha-C\gamma_N.
\end{equation}
 Let $q_{N}(\cdot)$ denote the quantiles of $J_N(\cdot)$. Inequality \ref{eqnPSSARP9} then implies that on the event \(E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), with $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSARP10}
q_N(1-\alpha-C\gamma_N)\leq \hat{c}_N(1-\alpha).
\end{equation}
 Arguing as in equation \ref{eqnPSSAS14}, we have
\begin{equation}
\label{eqnPSSARP11}
\sup_{Q\in {\cal Q}_0}Q\Bigl(\{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \Bigr)\leq \alpha+C\gamma_N+\delta_N.
\end{equation}
which yields equation \ref{eqnSSARP5} from Theorem \ref{thmSSARP1}, as $\gamma_N=o(1)$ and $\delta_N=o(1)$.

\medskip 

\underline{Step 3} In this step, we establish the anti-concentration condition \ref{eqnPSSARP8}. We first recall that as $0\in \hat{{\cal D}}$ and $\lambda\geq 0$ for all $\lambda \in \hat{{\cal D}}$, $0$ is an extreme point of $\hat{{\cal D}}$, and $\operatorname{extr}(\hat{{\cal D}})\neq \emptyset$. It then follows that any face of $\hat{{\cal D}}$ contains at least one extreme point of $\hat{{\cal D}}$ (see Section 8.5 of \cite{ALS}). On the event of a rejection, we necessarily have $\hat{v}>0$, in which case $\hat{\Delta}$ contains an element of $\operatorname{extr}(\hat{{\cal D}})\backslash \{0\}$. Indeed, as the set $\hat{\Delta}_0=\arg\max\{\hat{b}^\top \lambda \mid \lambda \in \hat{{\cal D}}\}=\{\lambda \in \hat{{\cal D}}\mid \hat{b}^\top \lambda =\hat{v}\}$ is a face of $\hat{{\cal D}}$, it must contain an element $\lambda$ of $\operatorname{extr}(\hat{{\cal D}})$, and it must be the case that $\lambda\neq 0$, as $\hat{v}>0$. Since $\hat{\Delta}_0\subseteq \hat{\Delta}$, we conclude that $\hat{\Delta}\cap [\operatorname{extr}(\hat{{\cal D}})\backslash \{0\}]\neq \emptyset$. 

\medskip

We first consider the case where $Q\in {\cal Q}_0$ is such that $\Delta_0(Q)=\{0\}$. Suppose that the following event occurs
\[
 E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \}
\]
and let $\hat{\lambda}\in \hat{\Delta}\cap [\operatorname{extr}(\hat{{\cal D}})\backslash \{0\}]$. Then Lemma \ref{lemEPC} implies that there exists $\lambda \in \operatorname{extr}({\cal D}(Q))\backslash \{0\} $ such that 
\begin{equation}
\label{eqnPSSARP12}
\|\Pi^u(\hat{\lambda})-\Pi^u(\lambda)\|\leq C\|\Pi^u(\hat{\lambda})\| \|\hat{D}-D\|\leq C\alpha_N
\end{equation}
where we have used equation \ref{eqnPSSARP4} and the fact that $\|\hat{D}-D\|\leq \alpha_N$ on $E_N(Q)$. The latter inequality implies that 
\begin{equation}
\label{eqnPSSARP013}
\begin{aligned}
\hat{\lambda}^\top \Sigma(Q)\hat{\lambda}&=\Pi^u(\hat{\lambda})^\top \Sigma(Q)\Pi^u(\hat{\lambda})=\|\Sigma(Q)^{1/2}\Pi^u(\hat{\lambda})\|^2\\
&\geq (1/2)\|\Sigma(Q)^{1/2}\Pi^u(\lambda)\|^2-\|\Sigma(Q)^{1/2}(\Pi^u(\hat{\lambda})-\Pi^u(\lambda))\|^2\\
&=(1/2)\lambda^\top \Sigma(Q)\lambda-\|\Sigma(Q)^{1/2}(\Pi^u(\hat{\lambda})-\Pi^u(\lambda))\|^2\\
&\geq (1/2)\lambda^\top \Sigma(Q)\lambda-C\alpha_N^2
\end{aligned}
\end{equation}
where we have used equation \ref{eqnPSSARP12} and part $i)$ of Assumption \ref{assSSARP1}. Hence, using part $ii)$ of Assumption \ref{assSSARP2}, for all sufficiently large $N$ and for $Q\in {\cal Q}_0$ such that $\Delta_0(Q)=\{0\}$, there exists $\hat{\lambda}\in \hat{\Delta}$ such that 
\begin{equation}
\label{eqnPSSARP13}
\hat{\lambda}^\top \Sigma(Q)\hat{\lambda}\geq \rho/4
\end{equation}
on the event $ E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \}$.

\medskip 

We now establish the analogue of equation \ref{eqnPSSARP13} for $Q\in {\cal Q}_0$ such that $\Delta_0(Q)\neq \{0\}$. By part i) of Assumption \ref{assSSARP2}, there exists $\lambda_Q\in \Delta_0(Q)$ such that 
\begin{equation}
\label{eqnPSSARP14}
\lambda_Q^\top \Sigma(Q)\lambda_Q\geq \rho.
\end{equation}
Equation \ref{eqnPSSARP2} (with $\xi=0$) implies that for all sufficiently large N, and on the event $E_N(Q)$, there exist $\hat{\lambda}\in \hat{{\cal D}}(Q)$ such that
\begin{equation}
\label{eqnPSSARP15}
\|\Pi^u(\hat{\lambda})-\Pi^u(\lambda_Q)\|\leq C\|\Pi^u(\lambda_Q)\| \|\hat{D}-D\|\leq C\alpha_N.
\end{equation}
Moreover, since equation \ref{eqnPSSARP2} gives $\hat{\lambda}$ as a positive scalar multiple of $\lambda_Q$ and $\lambda_Q\in \Delta_0(Q)$, for sufficiently large $N$ and on the event $E_N(Q)$, we have 
\[
|\hat{b}^\top \hat{\lambda}|=|(\hat{b}-b)^\top \hat{\lambda}+b^\top \hat{\lambda}|=|(\hat{b}-b)^\top \Pi^u(\hat{\lambda})|\leq CM_N/\sqrt{N}
\]
where we have used homogeneity and the fact that $\lambda_Q\in \Delta_0(Q)$ implies that $b^\top \lambda_Q=0$, as well as equation \ref{eqnPSSARP4}. The latter inequality, equation \ref{eqnPSSARP04}, and the fact that $M_N=o(\kappa_N)$, then imply that for sufficiently large $N$ and on the event $E_N(Q)$, we have 
\begin{equation}
\label{eqnPSSARP16}
\Bigl[\hat{b}^\top \hat{\lambda}\geq \hat{v}-\kappa_N/\sqrt{N}\Bigr] \quad \quad \text{which implies that} \quad \quad \Bigl[\hat{\lambda}\in \hat{\Delta}\Bigr].
\end{equation}
Reasoning as in equation \ref{eqnPSSARP013}, equation \ref{eqnPSSARP15} and the part $i)$ of Assumption \ref{assSSARP1}, then yield
\[
\hat{\lambda}^\top \Sigma(Q)\hat{\lambda}\geq (1/2)\lambda_Q^\top \Sigma(Q)\lambda_Q-C\alpha_N^2.
\]
For all sufficiently large $N$, the latter inequality and equation \ref{eqnPSSARP14} then give
\[
\hat{\lambda}^\top \Sigma(Q)\hat{\lambda}\geq \rho/4.
\]
In conclusion, for all sufficiently large $N$ and for $Q\in {\cal Q}_0$ such that $\Delta_0(Q)\neq \{0\}$, on the event $E_N(Q)$, there exists a $\hat{\lambda}\in  \hat{\Delta}$ such that
\begin{equation}
\label{eqnPSSARP17}
\hat{\lambda}^\top \Sigma(Q)\hat{\lambda}\geq \rho/4.
\end{equation}

\medskip
Combining equations \ref{eqnPSSARP13} and \ref{eqnPSSARP17}, we conclude that for all sufficiently large $N$ and for all $Q\in {\cal Q}_0$, on the event $ E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \}$, there exists a $\lambda \in \hat{\Delta}$ such that
\[
\Pi^u(\hat{\lambda})^\top \Sigma(Q)\Pi^u(\hat{\lambda})=\hat{\lambda}^\top \Sigma(Q)\hat{\lambda}\geq \rho/4,
\]
and the anti-concentration condition \ref{eqnPSSARP8} then follows from Proposition \ref{prop1}, using the fact that the sets $\Pi^u(\hat{\Delta})$ are eventually uniformly bounded on the events $E_N(Q)$, and
\[
\sup_{\lambda \in \hat{\Delta}} \langle \zeta, \lambda \rangle=\sup_{\lambda \in \hat{\Delta}} \langle \Pi^u(\zeta), \Pi^u(\lambda) \rangle.
\]


\underline{Step 4} We now prove inequality \ref{eqnSSARP6}.
 Fix $Q \in \mathcal{Q}_0$. Under Assumptions~\ref{assSSAS1}, \ref{assSSARP0} and \ref{assSSARP1}, Lemma \ref{lemAD} implies that the asymptotic distribution of $\sqrt{N} \hat{T}_N$ is given by
\begin{equation}
\label{eqnPSSARP18}
\max \left\{ \zeta^\top \lambda \;\middle|\; \lambda \in \Delta_0(Q) \right\}=\max \left\{ \zeta^\top \Pi^u(\lambda) \;\middle|\; \lambda \in \Delta_0(Q) \right\},
\end{equation}
where $\Delta_0(Q) := \arg\max \{ b(Q)^\top \lambda \mid \lambda \in \mathbb{R}^p_+, A^\top \lambda=0, \ \|D(Q)\lambda\|_1 \leq 1 \}$ and $\zeta \sim \mathcal{N}(0, \Sigma(Q))$. Let $G_\infty(\cdot)$ denote the CDF of the value of the program in equation \ref{eqnPSSARP18}. 
Then $d_{\mathrm{Pr}}(\mathcal{L}(\sqrt{N} \hat{T}_N), G_\infty) = o(1)$. To prove~\eqref{eqnSSARP6}, it suffices to show
\begin{equation}
\label{eqnPSSARP19}
d_{\mathrm{Pr}}(\hat{H}_N, G_\infty) = o_p(1),
\end{equation}
where $\hat{H}_N$ is the conditional (given $\mathbb{W}_N$) CDF in~\eqref{eqnSSARP4}. We show below that 
\begin{equation}
\label{eqnPSSARP20}
d_H(\Pi^u(\Delta_0(Q)), \Pi^u(\hat{\Delta})) = o_p(1),
\end{equation}
from which~\eqref{eqnPSSARP19} follows from Assumption \ref{assSSAS3}, via an almost sure representation argument as in Theorem \ref{thm1}.

To establish equation \ref{eqnPSSARP20}, we first show that
\begin{equation}
\label{eqnPSSARP21}
\overset{\rightarrow}{d}_H\bigl(\Pi^u(\Delta_0),\Pi^u(\hat{\Delta})\bigr)=o_p(1),
\end{equation}
and then establish the converse in equation \ref{eqnPSSARP24} below. Arguing as in the proof of equation \ref{eqnPSSARP41}, for all $N$ sufficiently large $N$ that $\alpha_N<\underline{\sigma}/2$, and on the event $E_N(Q)$, we have that
\begin{equation}
\label{eqnPSSARP22}
\forall \lambda \in {\cal D}\quad \hat{\Gamma}(\lambda):=(1-(2/\underline{\sigma})\alpha_N)\lambda\in \hat{{\cal D}} \quad \quad \text{and}\quad \quad \sup_{\lambda \in {\cal D}}\|\Pi^u(\lambda)-\Pi^u(\hat{\Gamma}(\lambda))\|\leq C\alpha_N.
\end{equation}
We now show that, on $E_N(Q)$, $\hat{\Gamma}(\Delta_0)$ is included in $\hat{\Delta}$ for all sufficiently large N. Equation \ref{eqnPSSARP22} would then imply that for all sufficiently large N and on the event $E_N(Q)$, we have
\[
\overset{\rightarrow}{d}_H\bigl(\Pi^u(\Delta_0),\Pi^u(\hat{\Delta})\bigr)\leq \overset{\rightarrow}{d}_H\bigl(\Pi^u(\Delta_0),\Pi^u(\hat{\Gamma}(\Delta_0)))\bigr)+\overset{\rightarrow}{d}_H\bigl(\hat{\Gamma}(\Delta_0),\hat{\Delta})\bigr)=\overset{\rightarrow}{d}_H\bigl(\Pi^u(\Delta_0),\Pi^u(\hat{\Gamma}(\Delta_0)))\bigr)\leq C\alpha_N,
\]
which would yield equation \ref{eqnPSSARP21}. Indeed, on $E_N(Q)$ and for all sufficiently large N, we have
\begin{equation}
\label{eqnPSSARP23}
\begin{aligned}
\inf_{\lambda \in \Delta_0} \langle \hat{b}, \hat{\Gamma}(\lambda) \rangle &= \langle \hat{b}-b, \Pi^u(\hat{\Gamma}(\lambda)) \rangle+\langle b, \hat{\Gamma}(\lambda) \rangle\\
&\geq -\frac{M_N}{\sqrt{N}} \sup_{\lambda \in \hat{{\cal D}}}\|\Pi^u(\lambda)\|\\
&\geq -C\frac{M_N}{\sqrt{N}},
\end{aligned}
\end{equation}
where we have used the fact that $\langle b, \hat{\Gamma}(\lambda)\rangle=0$ since $Q\in {\cal Q}_0$, $\lambda\in \Delta_0$, and $\hat{\Gamma}(\lambda)$ is a positive scalar multiple of $\lambda$; we have also used the analogue of equation \ref{eqnPSSARP4}, for $\hat{{\cal D}}$ on the event $E_N(Q)$. Since by equation \ref{eqnPSSARP04} we have $0\leq \hat{v}\leq C M_N/\sqrt{N}$, equation \ref{eqnPSSARP23} and the fact that $M_N=o(\kappa_N)$ imply that on the event $E_N(Q)$, and for all sufficiently large N, we have
\[
\hat{\Gamma}(\Delta_0)\subseteq \{\lambda \in \hat{{\cal D}}\mid \langle \hat{b},\lambda\rangle\geq \hat{v}-\kappa_N/\sqrt{N} \}.
\]
Hence, $\hat{\Gamma}(\Delta_0)$ is eventually a subset of $\hat{\Delta}$ on the event $E_N(Q)$, and this completes the proof of equation \ref{eqnPSSARP21}.

We now establish the converse of equation \ref{eqnPSSARP21}, and show that 
\begin{equation}
\label{eqnPSSARP24}
\overset{\rightarrow}{d}_H\bigl(\Pi^u(\hat{\Delta}),\Pi^u(\Delta_0)\bigr)=o_p(1).
\end{equation}
As in equation \ref{eqnPSSARP22}, it can be shown that on the event $E_N(Q)$ and for all sufficiently large $N$ such that $\alpha_N<\underline{\sigma}$, we have
\begin{equation}
\label{eqnPSSARP25}
\forall \lambda \in \hat{{\cal D}}\quad \Gamma(\lambda):=(1-(1/\underline{\sigma})\alpha_N)\lambda \in {\cal D} \quad \quad \text{and}\quad \quad \sup_{\lambda \in \hat{{\cal D}}}\|\Pi^u(\lambda)-\Pi^u(\Gamma(\lambda))\|\leq C\alpha_N.
\end{equation}
Moreover, on $E_N(Q)$ and for all sufficiently large $N$, we have
\begin{equation}
\label{eqnPSSARP26}
\begin{aligned}
0\geq \sup_{\lambda \in \hat{\Delta}} \langle b,\Gamma(\lambda)\rangle&\geq \inf_{\lambda \in \hat{\Delta}} \langle b,\Gamma(\lambda)\rangle\\
&=\inf_{\lambda \in \hat{\Delta}} \langle b-\hat{b},\Pi^u(\Gamma(\lambda))\rangle+ \langle \hat{b},\Gamma(\lambda)\rangle\\
&\geq \inf_{\lambda \in \hat{\Delta}} \langle b-\hat{b},\Pi^u(\Gamma(\lambda))\rangle-\kappa_N/\sqrt{N}\\
&\geq \inf_{\lambda \in {\cal D}} \langle b-\hat{b},\Pi^u(\lambda)\rangle-\kappa_N/\sqrt{N}\\
&\geq -\frac{M_N}{\sqrt{N}}\sup_{\lambda \in {\cal D}} \|\Pi^u(\lambda)\|-\kappa_N/\sqrt{N}\\
&\geq -C\kappa_N/\sqrt{N}
\end{aligned}
\end{equation}
where the first inequality follows since $v=0$ (for $Q\in {\cal Q}_0$); the third inequality follows from the fact that $\hat{v}\geq 0$ (we always have $0\in \hat{{\cal D}}$), $\langle \hat{b}, \lambda\rangle \geq \hat{v}-\kappa_N/\sqrt{N}\geq -\kappa_N/\sqrt{N}$ for all $\lambda \in \hat{\Delta}$, and that $\Gamma(\lambda)$ is a scalar multiple of $\lambda$ with scalar factor in $(0,1)$; the fourth inequality follows from the fact that $\Gamma(\hat{\Delta})\subseteq {\cal D}$; and the last inequality follows from the fact that as in equation \ref{eqnPSSARP4} we can show that $\sup_{\lambda \in {\cal D}} \|\Pi^u(\lambda)\|<1/\underline{\sigma}$, and that $M_N=o(\kappa_N)$.
As $\kappa_N=o(\sqrt{N})$, equation \ref{eqnPSSARP26} implies that for any $\epsilon>0$, and for all sufficiently large $N$, we have 
\[
\Gamma(\hat{\Delta})\subseteq \{\lambda \in {\cal D} \mid \langle b,\lambda \rangle \geq -\epsilon\}.
\]
As a consequence, Lemma \ref{lemOSC} then implies that on $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSARP27}
\overset{\rightarrow}{d}_H(\Gamma({\hat{\Delta}}), \Delta_0)=o(1).
\end{equation}
Combining equations \ref{eqnPSSARP25} and \ref{eqnPSSARP27}, we conclude that, on the event $E_N(Q)$ and for all sufficiently large $N$, we have
\begin{equation*}
\begin{aligned}
\overset{\rightarrow}{d}_H(\Pi^u(\hat{\Delta}), \Pi^u(\Delta_0))&\leq  \overset{\rightarrow}{d}_H(\Pi^u(\hat{\Delta}), \Pi^u(\Gamma(\hat{\Delta})))+\overset{\rightarrow}{d}_H(\Gamma(\hat{\Delta}), \Delta_0)\\
&C\alpha_N+o(1)
\end{aligned}
\end{equation*}
which establishes equation \ref{eqnPSSARP24}, and completes the proof of inequality \ref{eqnSSARP6}.

\end{proof}

