\begin{proof}[\bf{Proof of Theorem \ref{thmSSLSUC1}}]
\label{pthmSSLSUC1}
In this section, we provide proofs of equations~\eqref{eqnSSLSUC10} and~\eqref{eqnSSLSUC11}.
The dual to the LP \ref{eqnSSLSUC1} is given by
\begin{equation}
\label{eqnPSSLSUC01}
\min\{t\mid t\Omega(Q) \mathbbm{1}+A(Q)\eta\geq b(Q),\ t\geq 0\}.
\end{equation}
Let the Lagrangian associated with the LP~\ref{eqnSSLSUC1} be given by
\[
L(\lambda,\eta,t)=b^\top \lambda-\eta^\top A^\top \lambda+t\bigl(1-\mathbbm{1}^\top \Omega\lambda\bigr).
\]
where $t\geq 0$ and $\eta$ are the Lagrange multipliers.

Let $\xi=(\xi_A,\xi_b,\xi_{\Omega})$ denote generic pertubations of the input parameters $\mu=(A,b,\Omega)$ of our LPs, where $\xi_A\in \mathbb{R}^{p\times d}$, $\xi_b\in \mathbb{R}^p$, and $\xi_{\Omega}\in \mathbb{R}^{p\times p}$ is a diagonal matrix. Given $\xi$, let the resulting perturbed inputs $\mu_N(\xi)=(A_N(\xi),b_N(\xi),\Omega_N(\xi))$ be defined by
\[
\mu_N(\xi)=\Bigl(A+\frac{\xi_A}{\sqrt{N}}, b+\frac{\xi_b}{\sqrt{N}}, \Omega +\frac{\xi_{\Omega}}{\sqrt{N}}\Bigr).
\]
We assume here that the pertubation matrices $\xi_{\Omega}$, like the matrices $\Omega$, have all their $(i,i)$-th diagonal entries that correspond to indices $i\in K$ equal to zero.\footnote{See the paragraph that precedes Assumption \ref{assSSLSUC0}, for a definition of the set $K$, $U$, and for a definition of the projection operator $\Pi^u$.} Let $\phi_N(\mu)$ denote the value of the LP \ref{eqnSSLSUC1}, for arbitrary inputs $\mu=(A,b,\Omega)$. Let $L_N(\lambda,\eta,t; \xi)$ denote the Lagrangian for the LP \ref{eqnSSLSUC1} when the inputs of the LP are $\mu_N(\xi)$, and given by
\[
L_N(\lambda,\eta,t;\xi)=b_N(\xi)^\top \lambda-\eta^\top A_N(\xi)^\top \lambda+t\bigl(1-\mathbbm{1}^\top \Omega_N(\xi)\lambda\bigr).
\]
Let $\Delta_N(0,N)(\xi)$ and $S_{0,N}(\xi)$ denote respectively the set of optimal solutions for the LP \ref{eqnSSLSUC1} and its dual, when the inputs are given by $\mu_N(\xi)$. Let $\Delta_{0}$ and $S_{0}$ denote the analoguous objects when $\xi=0$. 

For $(\lambda_{\xi}, \eta_{\xi}, t_{\xi}) \in \Delta_{0,N}(\xi) \times S_{0,N}(\xi)$ and $(\lambda_0, \eta_0, t_0) \in \Delta_{0} \times S_{0}$, the saddle point property of the Lagrangian implies that, for all sufficiently small perturbations $\xi$ such that $\phi_N(\mu_N(\xi))$ is finite, we have
\begin{equation*}
\begin{aligned}
\sqrt{N} \bigl(\phi_N(\mu_N(\xi)) - \phi(\mu)\bigr)
&= \sqrt{N} \bigl(L_N(\lambda_{\xi}, \eta_{\xi}, t_{\xi}; \xi) - L(\lambda_0, \eta_0, t_0)\bigr) \\
&\leq \sqrt{N} \bigl(L_N(\lambda_{\xi}, \eta_0, t_0; \xi) - L(\lambda_{\xi}, \eta_0, t_0)\bigr) \\
&= \xi_b^\top \lambda_{\xi} - \eta_0^\top \xi_A^\top \lambda_{\xi} - t_0 \mathbbm{1}^\top \xi_{\Omega} \lambda_{\xi}.
\end{aligned}
\end{equation*}
Now, for any $Q \in \mathcal{Q}_0$, $\phi(\mu)=0$ and the condition $(\eta_0, t_0) \in S_{0}$ implies $t_0 = 0$. In fact, $S_0=\{(t,\eta)\mid t=0, \ b(Q)-A(Q)\eta\leq 0\}$. Therefore, the inequality above yields, for all sufficiently large $N$, for all sufficiently small perturbations $\xi$\footnote{ For small perturbations $\xi$ such that $\Omega_{\xi}$ has strictly positive diagonal entries for all $i \in U$, it follows from the discussion preceding Assumption~\ref{assSSLSUC5} that, for all $Q \in \mathcal{Q}_0$, the function $\phi(\mu_N(\xi))$ remains finite.}, and for $Q \in \mathcal{Q}_0$:
\begin{equation}
\label{eqnPSSLSUC02}
\sqrt{N} \phi_N(\mu_N(\xi)) \leq \xi_b^\top \lambda_{\xi} - \eta_0^\top \xi_A^\top \lambda_{\xi}=\langle \xi_b-\xi_A \eta_0, \lambda_{\xi}\rangle.
\end{equation}

Assumptions \ref{assSSLSUC0} through \ref{assSSLSUC3} imply the existence of $\alpha_N\downarrow 0$, such that
\[
\sup_{Q\in {\cal Q}}d_{\text{Pr}}\Bigl(\sqrt{N}(\hat{d}-d(Q)), \mathcal{N}(0,\Sigma(Q))\Bigr)\leq \alpha_N,
\]
and such that for any $M_N\uparrow \infty$, and for all $Q \in {\cal Q}_0$, the event $E_N(Q)$ defined by\footnote{Since assumption \ref{assSSLSUC0} implies that the number of estimated components of $b$ and $A$ are uniformly bounded w.r.t. $N$, the uniform consistency of the estimator $\hat{D}$ of the standard deviation matrices implies the uniform consistency of the normalizing matrices $\hat{\Omega}$.}
\[
E_N(Q) := \left\{ \mathbb{W} \;\middle|\; 
\begin{array}{l}
\|\hat{\Omega} - \Omega(Q)\| \leq \alpha_N,\quad
d_{\mathrm{Pr}}\bigl(\mathcal{L}(\zeta^* \mid \mathbb{W}), \mathcal{N}(0, \Sigma(Q))\bigr) \leq \alpha_N,\\[0.5em]
\sqrt{N} \|\hat{b} - b(Q)\| \leq M_N,\quad
\sqrt{N} \|\hat{A} - A(Q)\| \leq M_N
\end{array}
\right\}.
\]
 satisfies
\[
\underline{\lim}_{N\to \infty} \inf_{Q\in {\cal Q}} Q(E_N(Q))=1.
\]
We choose $M_N\uparrow \infty$ such that $M_N=o(\kappa_N)$, $M_N \alpha_N=o(1)$, and $M_N^2 \Bigl(\kappa_N/\sqrt{N}\Bigr)=o(1)$.
Such a choice is possible since $\kappa_N=o(\sqrt{N})$, where $\kappa_N$, here and in what follows, denotes either $\kappa_{1N}$, $\kappa_{2N}$, or $\kappa_{3N}$.

Let ${\cal X}_N$ denote the set of pertubation $\xi$ defined by
\[
{\cal X}_N=\Bigl\{\xi \mid \|\xi_b\|\leq M_N, \ \|\xi_A\|\leq M_N, \ \|\xi_{\Omega}\|\leq \sqrt{N}\alpha_N\Bigr\}.
\]
We now proceed to derive inequalities~\eqref{eqnSSLSUC10} and~\eqref{eqnSSLSUC11} from inequality~\eqref{eqnPSSLSUC02}. The proof is structured in four steps, which mirror the steps used in the derivation of the main results in Sections~\ref{sectionSSAS} through~\ref{sectionSSFSST}. In particular, inequality~\eqref{eqnSSLSUC10} is established in Steps~1 through~3, while Step~4 contains the proof of inequality~\eqref{eqnSSLSUC11}. Throughout the argument, we let \( C \) denote a generic constant that is uniform over all data-generating processes \( Q \in \mathcal{Q}_0 \), for sufficiently large \( N \). The constant \( C \) may vary from one equation to another.

\underline{Step 1} \quad In this step, we show that there exists a sequence $\beta_N = o(1)$ such that, for all sufficiently large $N$ and for all $Q \in \mathcal{Q}_0$, the following inequality holds on the event $E_N(Q)$:
\begin{equation}
\label{eqnPSSLSUC03}
\sup_{\xi \in \mathcal{X}_N} \sup_{\lambda \in \Delta_{0,N}(\xi)} 
\left\{ 
\langle \xi_b - \xi_A \eta_0, \lambda \rangle 
- \sup_{\lambda \in \hat{\Delta}} \langle \xi_b - \xi_A \hat{\eta}, \lambda \rangle 
\right\}
\leq \beta_N,
\end{equation}
where $\hat{\Delta}$ is defined in equation~\ref{eqnSSLSUC5}, and $\hat{\eta}$ is as given in equation~\ref{eqnSSLSUC6}.

Let ${\cal D}(Q)$ and $\hat{{\cal D}}$ denote respectively the feasible region of the LPs \ref{eqnSSLSUC1} and \ref{eqnSSLSUC2}. Note that on the event $E_N(Q)$, the condition $\|\hat{D} - D\| \leq \alpha_N$ implies $\|\hat{\Omega} - \Omega\| \leq \alpha_N$. Consequently, for all sufficiently large $N$ such that $\alpha_N \leq \underline{\sigma}/2$, we have $[\hat{\Omega}]_{ii} > \underline{\sigma}/2$ for all $i \in U$. The same reasoning shows that for all such $N$ and for all $\xi \in \mathcal{X}_N$, we also have $[\Omega_N(\xi)]_{ii} \geq \underline{\sigma}/2$ for all $i \in U$. As a consequence, since $\|\Omega_N(\xi) \lambda\|_1 \leq 1$ for all $\lambda \in \Delta_{0,N}(\xi)$, and $\|\hat{\Omega}\lambda\|_1\leq 1$ for all $\lambda\in \hat{\cal D}$, it follows that for all N such that $\alpha_N\leq \underline{\sigma}/2$, we have
\begin{equation}
\label{eqnPSSLSUC04}
\sup_{\xi \in \mathcal{X}_N} \sup_{\lambda \in \Delta_{0,N}(\xi)} \|\Pi^u(\lambda)\|_1 \leq \frac{2}{\underline{\sigma}}, \quad \quad \text{and}\quad \quad \sup_{\lambda \in \hat{{\cal D}}} \|\Pi^u(\lambda)\|_1\leq 2/\underline{\sigma}\quad \text{on the event } E_N(Q).
\end{equation}
In the derivations that follow, we assume that N is sufficiently large that $\alpha_N\leq \underline{\sigma}/2$.

As $\eta_0$ in equation \ref{eqnPSSLSUC02} is any solution to $b(Q)-A(Q)\eta\leq 0$, we can assume that $\eta_0=\eta_Q$, where $\eta_Q$ is as in Assumption \ref{assSSLSUC4}. We first show that on the events $E_N(Q)$, for all sufficiently large N and for $Q\in {\cal Q}_0$, we can replace $\eta_Q$ by $\hat{\eta}$, and we have
\begin{equation}
\label{eqnPSSLSUC05}
\sup_{\xi \in \mathcal{X}_N} \sup_{\lambda \in \Delta_{0,N}(\xi)} 
\left\{ 
\langle \xi_b - \xi_A \eta_Q, \lambda \rangle 
- \langle \xi_b - \xi_A \hat{\eta}, \lambda \rangle 
\right\}
\leq C M_N\Bigl(\kappa_N/\sqrt{N}\Bigr)^{1/2},
\end{equation}
We first show that on the event $E_N(Q)$, for all sufficiently large N and for $Q\in {\cal Q}_0$, $\eta(Q)$ is in the feasible region of the quadratic program \ref{eqnSSLSUC6}, and satisfies
\begin{equation}
\label{eqnPSSLSUC06}
\hat{b}-\hat{A}\eta(Q)\leq \frac{\kappa_N}{\sqrt{N}} \hat{\Omega}\mathbbm{1}.
\end{equation}

Indeed, we have
\begin{equation*}
\begin{aligned}
\hat{b}-\hat{A}\eta_Q&\leq \hat{b}-\hat{A}\eta_Q+A\eta(Q)-b\\
&\leq \Bigl(\|\hat{b}-b\|+\|\hat{A}-A\|\|\eta_Q\|\Bigr)\Pi^u(\mathbbm{1}).
\end{aligned}
\end{equation*}
Since Assumption \ref{assSSLSUC4} implies that $\eta_Q$ is uniformly (in $Q\in {\cal Q}_0$) bounded, we conclude that on the event $E_N(Q)$, we have
\[
\hat{b} - \hat{A} \eta(Q) \leq \frac{C M_N}{\sqrt{N}}\Pi^u(\mathbbm{1}),
\]
which yields equation \ref{eqnPSSLSUC06} for all sufficiently large $N$ as $M_N=o(\kappa_N)$, and $[\hat{\Omega}]_{ii}\geq \underline{\sigma}/2$ for all $i\in U$. In turn, this implies that for all sufficiently large $N$ and all $Q \in \mathcal{Q}_0$, we have
\begin{equation}
\label{eqnPSSLSUC07}
\|\hat{\eta}\| \leq \|\eta_Q\|\leq M
\end{equation}
where $M>0$ is such that $\sup_{Q\in {\cal Q}_0} \|\eta_Q\|\leq M$.

 By Lemma \ref{lemhoff}, if ${\cal C}(Q):=\{\eta\mid b(Q)-A(Q)\eta\leq 0\}$, then inequality \ref{eqnPSSLSUC07}  and Assumption \ref{assSSLSUC4} imply that
\begin{equation}
\label{eqnPSSLSUC08}
d\bigl(\hat{\eta},{\cal C}_Q\bigr)\leq C\|[b(Q)-A(Q)\hat{\eta}]_+\|\leq C\kappa_N/\sqrt{N}.
\end{equation}
Indeed, we have
\begin{equation*}
\begin{aligned}
[b-A\hat{\eta}]_+&\leq \Bigl[b-A\hat{\eta}+\hat{A}\hat{\eta}-\hat{b}+\bigl(\hat{T}_N+\frac{\kappa_N}{\sqrt{N}}\bigr)\hat{\Omega}\mathbbm{1}\Bigr]_+\\
&\leq [b-\hat{b}]_++[(\hat{A}-A)\hat{\eta}]_++C\frac{\kappa_N}{\sqrt{N}}\hat{\Omega}\mathbbm{1}\\
&\leq C\frac{\kappa_N}{\sqrt{N}}\Pi^u(\mathbbm{1}),
\end{aligned}
\end{equation*}
where we have used the fact that $\hat{\eta}$ is in the feasible region of the quadratic program \ref{eqnSSLSUC6}, equation \ref{eqnPSSLSUC07}, the fact that $M_N=o(\kappa_N)$, and the additional fact, which we derive further below, that $T_N=o(\kappa_N/\sqrt{N})$.

Inequalities \ref{eqnPSSLSUC07} and \ref{eqnPSSLSUC08} imply that
\begin{equation}
\label{eqnPSSLSUC09}
\|\hat{\eta}-\eta(Q)\|\leq C \Bigl(\kappa_N/\sqrt{N}\Bigr)^{1/2}.
\end{equation}
 Indeed, if $\Pi_{{\cal C}}(\cdot)$ denotes the (Euclidean) projection operator on ${\cal C}(Q)$, then equations \ref{eqnPSSLSUC07} and \ref{eqnPSSLSUC08} imply that
\[
\langle \eta(Q),\eta\rangle \geq \|\eta(Q)\|^2 \quad \forall \eta\in {\cal C}(Q) \quad \quad{and}\quad \quad \|\Pi_{{\cal C}}(\hat{\eta})\|\leq \|\eta(Q)\|+C\frac{\kappa_N}{\sqrt{N}}.
\]
This gives 
\[
\|\eta(Q)-\Pi_{{\cal C}}(\hat{\eta})\|^2=\|\eta(Q)\|^2+\|\Pi_{{\cal C}}(\hat{\eta})\|^2-2\langle\eta(Q),  \Pi_{{\cal C}}(\hat{\eta})\rangle\leq  C \frac{\kappa_N}{\sqrt{N}},
\]
and equation \ref{eqnPSSLSUC09} then follows from the latter inequality, and equation \ref{eqnPSSLSUC08}, noting that $\|\hat{\eta}-\eta(Q)\|\leq\|\hat{\eta}-\Pi_{{\cal C}}(\hat{\eta})\|+\|\Pi_{{\cal C}}(\hat{\eta})-\eta(Q)\|$.

Equation \ref{eqnPSSLSUC04} implies that $\|\xi_A^\top \lambda \|=\|\xi_A^\top \Pi^u(\lambda)\|\leq C M_N$ for $\xi \in {\cal X}_N$ and $\lambda \in \Delta_{0,N}(\xi)$, and equation \ref{eqnPSSLSUC09} then implies that on the events $E_N(Q)$, for all sufficiently large N and for $Q\in {\cal Q}_0$, we have
\begin{equation*}
\sup_{\xi \in \mathcal{X}_N} \sup_{\lambda \in \Delta_{0,N}(\xi)} 
\big|\left\{ 
\langle \xi_b - \xi_A \eta_0, \lambda \rangle 
- \langle \xi_b - \xi_A \hat{\eta}, \lambda \rangle 
\right\}\big|
\leq C M_N\Bigl(\kappa_N/\sqrt{N}\Bigr)^{1/2}.
\end{equation*}
Note also that, since $M_N$ is chosen such that $M_N^2 (\kappa_N/\sqrt{N}) = o(1)$, the right-hand side of the latter inequality is asymptotically negligible. This yields equation \ref{eqnPSSLSUC05}.


We now show that for all sufficiently large $N$, and for all $Q \in \mathcal{Q}_0$, the following holds on the event $E_N(Q)$:
\begin{equation}
\label{eqnPSSLSUC010}
\sup_{\xi \in {\cal X}_N}\overset{\rightarrow}{d}_H\bigl(\Pi^u(\Delta_{0,N}(\xi)), \Pi^u(\hat{\Delta})\bigr) \leq C \alpha_N.
\end{equation}
Assuming that inequality~\ref{eqnPSSLSUC010} holds, and invoking equation~\ref{eqnPSSLSUC04}, it follows that on the event $E_N(Q)$ we have
\begin{equation}
\label{eqnPSSLSUC011}
\sup_{\xi \in \mathcal{X}_N} \sup_{\lambda \in \Delta_{0,N}(\xi)} 
\left\{ 
\langle \xi_b - \xi_A \hat{\eta}, \lambda \rangle 
- \sup_{\lambda \in \hat{\Delta}} \langle \xi_b - \xi_A \hat{\eta}, \lambda \rangle 
\right\}
\leq C \alpha_N M_N.
\end{equation}
Combining inequalities~\ref{eqnPSSLSUC05} and~\ref{eqnPSSLSUC011} yields inequality~\ref{eqnPSSLSUC03} with
\[
\beta_N = C M_N\left( \frac{\kappa_N}{\sqrt{N}} \right)^{1/2} + C \alpha_N M_N = o(1).
\]
It therefore remains to establish inequality~\ref{eqnPSSLSUC010} in order to complete Step~1.

We first show that on the event $E_N(Q)$, for all sufficiently large $N$ and for $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSLSUC012}
\forall \xi \in {\cal X}_N,\quad \Delta_{0,N}(\xi)\subseteq \Bigl\{\lambda\in \mathbb{R}^p_+\mid -\frac{\kappa_{N}}{\sqrt{N}}\mathbbm{1}\leq \hat{A}^\top \lambda\leq \frac{\kappa_{N}}{\sqrt{N}}\mathbbm{1}\Bigr\}.
\end{equation}
Indeed, on $E_N(Q)$ we have
\[
\sup_{\lambda\in \Delta_{0,N}(\xi)}\|\hat{A}^\top\lambda\|_{\infty}=\sup_{\lambda\in \Delta_{0,N}(\xi)}\|(\hat{A}-A_N(\xi))^\top \Pi^u(\lambda)\|_{\infty}\leq CM_N/\sqrt{N},
\]
where we have use equation \ref{eqnPSSLSUC04}. Equation \ref{eqnPSSLSUC012} then follows since $M_N=o(\kappa_N)$. Arguing as in \ref{eqnPSSARP41}, we easily show that on $E_N(Q)$ and for all $N$ sufficiently large that $\alpha_N< \underline{\sigma}/4$, we have
\[
(1-4\alpha_N/\underline{\sigma})\|\hat{\Omega}\lambda\|_1\leq \|\Omega_N(\xi)\lambda\|_1\leq (1+4\alpha_N/\underline{\sigma})\|\hat{\Omega}\lambda\|_1,
\]
for all $\lambda\in \mathbb{R}^p$. Hence if $\hat{\Gamma}(\lambda):=(1-4\alpha_N/\underline{\sigma})\lambda$, then the latter inequality and equation \ref{eqnPSSLSUC012} imply that on the event $E_N(Q)$, for all sufficiently large $N$ and for $Q\in {\cal Q}_0$, we have
\[
\forall \xi \in {\cal X}_N,\quad \hat{\Gamma}(\Delta_{0,N}(\xi))\subseteq  \Bigl\{\lambda\in \mathbb{R}^p_+\mid -\frac{\kappa_{N}}{\sqrt{N}}\mathbbm{1}\leq \hat{A}^\top \lambda\leq \frac{\kappa_{N}}{\sqrt{N}}\mathbbm{1}, \ \|\hat{\Omega}(\lambda)\|_1\leq 1\Bigr\}.
\]
Moreover, equation \ref{eqnPSSLSUC04} implies that 
\[
\forall \xi \in {\cal X}_N, \quad \sup_{\lambda\in \Delta_{0,N}(\xi)}\|\Pi^u(\lambda-\hat{\Gamma}(\lambda))\|\leq C\alpha_N.
\]


We now show that for all sufficiently large $N$, we have
\[
\inf_{\lambda\in \Delta_{0,N}(\xi)}\hat{b}^\top \hat{\Gamma}(\lambda)\geq \hat{T}_N-\kappa_N/\sqrt{N},
\]
which when combined with the preceding two inequalities yields \ref{eqnPSSLSUC010}, and completes the proof of Step 1.
We first show that $\hat{T}_N=o(\kappa_N/\sqrt{N})$. Indeed, first note that Assumption \ref{assSSLSUC4} implies that there exists a constant $M>0$ such that for all $Q\in {\cal Q}_0$, we have 
\begin{equation}
\label{eqnPSSLSUC013}
b^\top \lambda\leq \langle \lambda, A\eta_Q\rangle=\langle A^\top \lambda, \eta_Q\rangle\leq M\|A^\top \lambda\|, \ \quad \forall \lambda\geq0.
\end{equation}
On the event $E_N(Q)$, for all sufficiently large $N$ and for $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSLSUC014}
\begin{aligned}
0\leq \hat{T}_N=\sup_{\lambda\in \hat{{\cal D}}}\langle \hat{b},\lambda\rangle&\leq \sup_{\lambda\in \hat{{\cal D}}}\langle \hat{b}-b,\lambda\rangle+\sup_{\lambda\in \hat{{\cal D}}}\langle b,\lambda\rangle\\
&\leq \sup_{\lambda\in \hat{{\cal D}}}\langle \hat{b}-b,\Pi^u(\lambda)\rangle+\sup_{\lambda\in \hat{{\cal D}}} M\|A^\top \lambda\|\\
&=\sup_{\lambda\in \hat{{\cal D}}}\langle \hat{b}-b,\Pi^u(\lambda)\rangle+\sup_{\lambda\in \hat{{\cal D}}} M\|(A-\hat{A})^\top \Pi^u(\lambda)\|\\
&\leq CM_N/\sqrt{N}=o\bigl(\kappa_N/\sqrt{N}\bigr),
\end{aligned}
\end{equation}
where we have used equations \ref{eqnPSSLSUC04} and \ref{eqnPSSLSUC013}, and the fact that $M_N=o(\kappa_N)$.

Now on $E_N(Q)$ and for $\xi \in {\cal X}_N$, we have
\begin{equation}
\label{eqnPSSLSUC015}
\begin{aligned}
\inf_{\lambda\in \Delta_{0,N}(\xi)}\hat{b}^\top \hat{\Gamma}(\lambda)&\geq \inf_{\lambda\in \Delta_{0,N}(\xi)} \langle \hat{b}-b_N(\xi), \Pi^u(\hat{\Gamma}(\lambda))\rangle+ \inf_{\lambda\in \Delta_{0,N}(\xi)} \langle b_N(\xi), \hat{\Gamma}(\lambda)\rangle\\
&\geq \inf_{\lambda\in \Delta_{0,N}(\xi)} \langle \hat{b}-b_N(\xi), \Pi^u(\hat{\Gamma}(\lambda))\rangle\\
&\geq -CM_N/\sqrt{N}
\end{aligned}
\end{equation}
where we have used the fact that $\langle b_N(\xi), \hat{\Gamma}(\lambda)\rangle\geq 0$ for all $\lambda \in \Delta_{0,N}(\xi)$, as $\hat{\Gamma}(\lambda)$ is a positive scalar multiple of $\lambda$ and $\inf_{\lambda\in \Delta_{0,N}(\xi)}\langle b_N(\xi),\lambda\rangle\geq 0$ (since 0 is always feasible). Combining equations \ref{eqnPSSLSUC014} and \ref{eqnPSSLSUC015}, and the fact that $M_N=o(\kappa_N)$, implies that on $E_N(Q)$ and for all sufficiently large N we have
\[
\inf_{\lambda\in \Delta_{0,N}(\xi)}\hat{b}^\top \hat{\Gamma}(\lambda)\geq \hat{T}_N-\kappa_N/\sqrt{N},
\]
thus completing the proof of Step 1.




\underline{Step 2} \quad In this step, we use equation~\eqref{eqnPSSLSUC03} and a coupling argument to upper bound the test statistic by another statistic whose distribution can be uniformly estimated for all $Q \in \mathcal{Q}_0$. The proof closely parallels Step 2 in the proof of Theorems~\ref{thmSSAS1} through \ref{thmSSFSST1}. Let $\hat{\xi}^*=(\sqrt{N}(\hat{A}^*-A(Q)),\sqrt{N}(\hat{b}^*-b(Q)),\sqrt{N}(\hat{\Omega}^*-\Omega(Q)))$ be an independent and identically distributed version of the root $\hat{\xi}=(\sqrt{N}(\hat{A}-A(Q)),\sqrt{N}(\hat{b}-b(Q)),\sqrt{N}(\hat{\Omega}-\Omega(Q)))$, computed from a sample $\mathbb{W}_N^*$, such that $\mathbb{W}_N^*$ and $\mathbb{W}_N$ are independent and identically distributed. For $Q\in {\cal Q}$, let the event $F^*_N=F^*_N(Q)$ be defined by 
\[
F_N^*(Q) := \left\{ \mathbb{W}^* \;\middle|\; \|\hat{\xi}^*_A\|>M_N \;\text{or}\; \|\hat{\xi}^*_b\| > M_N \;\text{or}\; \|\hat{\xi}^*_{\Omega}\| > \sqrt{N} \alpha_N \right\}.
\]
By our choice of $M_N$ and $\alpha_N$, we have 
\[
\delta_{1N}:=\sup_{Q\in {\cal Q}} Q\bigl(F^*_N(Q)\bigr) \quad \text{satisfies}\quad \lim_{N\to \infty} \delta_{1N}=0
\]
Equations \ref{eqnPSSLSUC02} and \ref{eqnPSSLSUC03} then imply that for all sufficiently large $N$ and on the event $E_N(Q)$, for $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSLSUC016}
\sqrt{N}\phi(\mu_N(\hat{\xi}^*))\leq \sup_{\lambda \in \hat{\Delta}}\langle \hat{\xi}^*_b - \hat{\xi}^*_A \hat{\eta}, \lambda \rangle+\beta_N+\infty\cdot \mathbbm{1}_{\{F_N^*\}}.
\end{equation}
Let \( J_N(\cdot; Q) \) denote the CDF of \( \sqrt{N} \hat{T}_N \). Define
\[
\hat{G}_N(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b - \hat{\xi}^*_A \hat{\eta}, \lambda \rangle + \beta_N + \infty \cdot \mathbbm{1}_{\{F_N^*\}} \,\middle|\, \mathbb{W}_N \right)
\]
as the conditional (on \( \mathbb{W}_N \)) CDF of the right-hand side of inequality \eqref{eqnPSSLSUC016}, viewed as a random element taking values in \( \mathbb{R} \cup \{\infty\} \).  
Similarly, define
\[
\hat{G}_\infty(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta_b-\zeta_A\eta_Q, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\]
where \( \zeta \sim N(0, \Sigma(Q)) \) (as in Assumption \ref{assSSLSUC1}).\footnote{Here, $\zeta_A$ denotes the matrix formed by extracting the components corresponding to $A$ from the random vector $\zeta$, arranged in a manner compatible with the dimensions of $A$. $\zeta_b$ is defined analogously.} And let $\hat{H}_N(;Q)$ be defined as in Theorem \ref{thmSSLSUC1}
\[
\hat{H}_N(\cdot; Q) := \mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta^*_b - \zeta^*_A \hat{\eta}, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\]
where $\zeta^*$ is the bootstrap estimate of of $\zeta$ that is given in Assumption \ref{assSSLSUC3}.
Note that Assumptions \ref{assSSLSUC0} and \ref{assSSLSUC2} (part~(i)) imply that the random variables $\bigl\{\|\zeta\|\mid \zeta\sim \mathcal{N}(0,\Sigma(Q)),\ Q\in {\cal Q}_0\bigr\}$ are tight. As a consequence, Strassen's coupling, and equations \ref{eqnPSSLSUC04} and \ref{eqnPSSLSUC09}, imply that the sequence
\[
\delta_{2N} = \sup_{Q \in \mathcal{Q}_0} \sup_{\mathbb{W}_N \in E_N(Q)} 
d_{\text{Pr}}\left(
\mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta_b - \zeta_A \eta_Q, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b - \hat{\xi}^*_A \hat{\eta}, \lambda \rangle \,\middle|\, \mathbb{W}_N \right)
\right)
\]
satisfies
\[
\lim_{N\to \infty} \delta_{2N}=0.
\]
The preceding equation, together with Strassen's theorem, implies that on the event \( E_N(Q) \), we have
\begin{equation*}
\begin{aligned}
d_{\text{Pr}}\Big( \hat{G}_N, \hat{G}_{\infty} \Big) 
&\leq d_{\text{Pr}}\Bigg( \hat{G}_N, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b - \hat{\xi}^*_A \hat{\eta}, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg) \\
&\quad + d_{\text{Pr}}\Bigg( \hat{G}_{\infty}, \mathcal{L}\left( \sup_{\lambda \in \hat{\Delta}} \langle \hat{\xi}^*_b - \hat{\xi}^*_A \hat{\eta}, \lambda \rangle \,\middle|\, \mathbb{W}_N \right) \Bigg)\\
&\leq \beta_N+Q(F_N^*)+\delta_{2N}.
\end{aligned}
\end{equation*}
Similarly, by Strassen's theorem and equations~\ref{eqnPSSLSUC04} and~\ref{eqnPSSLSUC09}, it follows that on the event \( E_N(Q) \), we have
\[
\lim_{N\to \infty} \delta_{3N}=0,
\]
where the sequence $\delta_{3N}$ is defined by 
\[
\delta_{3N} = \sup_{Q \in \mathcal{Q}_0} \sup_{\mathbb{W}_N \in E_N(Q)} 
d_{\text{Pr}}\left(
\mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta_b - \zeta_A \eta_Q, \lambda \rangle \,\middle|\, \mathbb{W}_N \right),
\mathcal{L} \left( \sup_{\lambda \in \hat{\Delta}} \langle \zeta^*_b - \zeta^*_A \hat{\eta}, \lambda \rangle \,\middle|\, \mathbb{W}_N \right)
\right).
\]
We have
\[
d_{\text{Pr}}\left( \hat{G}_{\infty}, \hat{H}_N \right) \leq \delta_{3N}
\]
on $E_N(Q)$.

In conclusion, there exists $\gamma_N=o(1)$ such that for all sufficiently large N and all $Q \in {\cal Q}_0$, on the event $E_N(Q)$ we have
\begin{equation}
d_{\text{Pr}}\bigl(\hat{G}_N,\hat{G}_{\infty}\bigr)\vee d_{\text{Pr}}\bigl(\hat{H}_N,\hat{G}_{\infty}\bigr)\leq \gamma_N.
\end{equation}
Let the significance level \( \alpha \) and the critical value \( \hat{c}_N(1-\alpha) \) be as in Theorem~\ref{thmSSLSUC1}.
For now, assume that there exists a constant \( C \) such that for all sufficiently large \( N \), for all \( Q \in \mathcal{Q}_0 \), and for all sample realizations \( \mathbb{W}_N \) on the event \( E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), we have the anti-concentration condition
\begin{equation}
\label{eqnPSSLSUC017}
\hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) + \gamma_N \big) - \hat{G}_{\infty}\big( \hat{c}_N(1-\alpha) - \gamma_N \big) \leq C \gamma_N.
\end{equation}
We prove in the next step that inequality~\eqref{eqnPSSLSUC017} indeed holds. For \( \mathbb{W}_N \in E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), and $Q\in {\cal Q}_0$, arguing as in \ref{eqnPSSAS13}, we have
\begin{equation}
\label{eqnPSSLSUC018}
J_N\big( \hat{c}_N(1-\alpha) \big) \geq 1-\alpha-C\gamma_N.
\end{equation}
 Let $q_{N}(\cdot)$ denote the quantiles of $J_N(\cdot)$. Inequality \ref{eqnPSSLSUC018} then implies that on the event \(E_N(Q) \cap \{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \), with $Q\in {\cal Q}_0$, we have
\begin{equation}
\label{eqnPSSLSUC019}
q_N(1-\alpha-C\gamma_N)\leq \hat{c}_N(1-\alpha).
\end{equation}
 Arguing as in equation \ref{eqnPSSAS14}, we have
\begin{equation}
\label{eqnPSSLSUC020}
\sup_{Q\in {\cal Q}_0}Q\Bigl(\{ \sqrt{N} \hat{T}_N > \hat{c}_N(1-\alpha) \} \Bigr)\leq \alpha+C\gamma_N+\delta_{1N}.
\end{equation}
which yields equation \ref{eqnSSLSUC10} from Theorem \ref{thmSSLSUC1}, as $\gamma_N=o(1)$ and $\delta_{1N}=o(1)$.

\medskip

\underline{Step 3} \quad In this step, we establish inequality~\ref{eqnPSSLSUC017}, which is required in the derivation of equation~\ref{eqnPSSLSUC020}. We begin by noting that for all sufficiently large \( N \) and for all \( Q \in \mathcal{Q}_0 \), equation~\ref{eqnPSSLSUC014} implies that \( 0 \in \hat{\Delta} \), as $\hat{T}_N=o(\sqrt{N}/N)$. Hence for all such sufficiently large $N$, the distributions $\hat{H}(\cdot)$ are supported on $\mathbb{R}_+$, and rejection occurs, i.e. $\{\hat{T}_N>\hat{c}_N(1-\alpha)\}$, only if $\hat{T}_N>0$.

We first consider the case where \( \Delta_0(Q) \neq \{0\} \), with
\[
\Delta_0(Q) := \arg\max \left\{ b(Q)^\top \lambda \ \middle| \ \lambda \geq 0,\ A(Q)^\top \lambda = 0,\ \|\Omega(Q)\lambda\|_1 \leq 1 \right\}.
\]
Equation \ref{eqnPSSLSUC010}, with $\xi=0$, then implies that on the event $E_N(Q)$, we have
\[
\overset{\rightarrow}{d}_H\bigl(\Pi^u(\Delta_{0}(Q)), \Pi^u(\hat{\Delta})\bigr) \leq C \alpha_N.
\]
By Assumption~\ref{assSSLSUC5}, there exists \( \lambda_Q \in \Delta_0(Q) \) such that
\[
\lambda_Q^\top V(Q) \lambda_Q \geq \rho.
\]
This, combined with inequality the preceding inequality, implies that there exists \( \hat{\lambda} \in \hat{\Delta} \) such that
\[
\left\| \Pi^u(\hat{\lambda}) - \Pi^u(\lambda_Q) \right\| \leq C \alpha_N.
\]
Hence, for all sufficiently large \( N \), we have
\begin{equation}
\label{eqnPSSLSUC021}
\sup_{\lambda \in \hat{\Delta}} \lambda^\top V(Q) \lambda=\sup_{\lambda \in \hat{\Delta}} \Pi^u(\lambda)^\top V(Q)\Pi^u( \lambda) \geq  \Pi^u(\hat{\lambda})^\top V(Q)\Pi^u(\hat{ \lambda})\geq \rho / 2.
\end{equation}

We now consider the case where $\Delta_0(Q)= \{0\}$. Since for all sufficiently large N, rejection implies that $\hat{T}_N>0$, with $\hat{T}_N$ finite, there must exist $\hat{\lambda} \in \operatorname{extr}(\hat{D})\setminus\{0\}$ such that $\|\hat{\Omega}\hat{\lambda}\|_1=1$, and  
\[
\hat{\lambda}\in \arg\max \left\{ \hat{b}^\top \lambda \ \middle| \ \lambda \geq 0, \ \hat{A}^\top \lambda=0, \  \|\hat{\Omega}\lambda\|_1 \leq 1 \right\}.
\]
Note that we have $\hat{T}_N= \hat{b}^\top \hat{\lambda}$, and we clearly have that $\hat{\lambda}\in \hat{\Delta}$. By Assumption \ref{assSSLSUC5}, for all $\lambda\geq 0$ such that $\|\Pi^u(\lambda)\|_1\geq 1$ we have
\begin{equation}
\label{eqnPSSLSUC022}
\lambda^\top V(Q) \lambda \geq \rho.
\end{equation}

For all sufficiently large \( N \), we eventually have \( \alpha_N \leq \overline{\sigma} \). Therefore, on the event \( E_N(Q) \), it follows that \( \|\hat{\Omega}\| \leq 2\overline{\sigma} \), which implies
\[
1 = \|\hat{\Omega} \hat{\lambda}\|_1 \leq 2\overline{\sigma} \|\Pi^u(\hat{\lambda})\|_1.
\]
Using equation~\ref{eqnPSSLSUC022}, we then obtain
\begin{equation}
\label{eqnPSSLSUC023}
\hat{\lambda}^\top V(Q) \hat{\lambda} \geq \rho \left( \frac{1}{2\overline{\sigma}} \right)^2.
\end{equation}

In conclusion, equations~\ref{eqnPSSLSUC021} and~\ref{eqnPSSLSUC023} together imply that for all sufficiently large \( N \), and for all \( Q \in \mathcal{Q}_0 \), whenever the event \( E_N(Q) \cap \{\hat{T}_N > \hat{c}_N(1-\alpha)\} \) occurs, there exists some \( \lambda \in \hat{\Delta} \) such that
\[
\lambda^\top V(Q) \lambda \geq \rho \left( \frac{1}{2\overline{\sigma}} \right)^2 \wedge \frac{\rho}{2}.
\]
Inequality~\ref{eqnPSSLSUC017} then follows from Proposition~\ref{prop1}, by applying the above inequality together with the identity
\[
\langle \zeta_b - \zeta_A \eta_Q, \lambda \rangle = \langle \Pi^u(\zeta_b - \zeta_A \eta_Q), \Pi^u(\lambda) \rangle,
\]
and equation~\ref{eqnPSSLSUC04}.

\medskip

\underline{Step 4} \quad In this step, we establish equation ~\eqref{eqnSSLSUC11} from Theorem \ref{thmSSLSUC1}. Fix $Q\in {\cal Q}_0$, and suppose that $\eta_Q$ is the unique solution to the inequality system 
\[
b(Q)-A(Q)\eta\leq 0.
\]
Lemma \ref{lem1AD} implies that
\[
\sqrt{N}\hat{T}_N\overset{d}{\longrightarrow} \max_{\lambda\in \Delta_0} \langle \zeta_b-\zeta_A\eta_Q,\Pi^u(\lambda) \rangle,
\]
where $\Delta_0$ is the set of optimal solutions to the LP given by
\[
\Delta_0:=\bigl\{\lambda\in \mathbb{R}^p \mid \lambda \geq 0, \ \langle b, \lambda \rangle \geq 0, \  A^\top \lambda=0, \mathbbm{1}\Omega\lambda\leq 1 \bigr\}.
\]
Assumption \ref{assSSLSUC3} and equation \ref{eqnPSSLSUC09} imply that
\[
d_{Pr}\Bigl(\mathcal{L}\Bigl(\zeta^*_b-\zeta^*_A\hat{\eta}\mid \mathbb{W}_N\Bigr), \mathcal{L}(\zeta_b-\zeta_A\eta_Q)\Bigr)=o_p(1).
\]
Reasoning using an almost sure representation as in the proof of Theorem \ref{thm1}, equation \ref{eqnSSLSUC11} then follows if we show that 
\[
d_{H}(\Pi^u(\hat{\Delta}),\Pi^u(\Delta_0))=o_p(1).
\] 
Equation \ref{eqnPSSLSUC010}, with $\xi=0$, implies that 
\[
\overset{\rightarrow}{d}_{H}(\Pi^u(\Delta_0),\Pi^u(\hat{\Delta}))=o_p(1).
\]
It thus remains to show that 
\begin{equation}
\label{eqnPSSLSUC024}
\overset{\rightarrow}{d}_{H}(\Pi^u(\hat{\Delta}),\Pi^u(\Delta_0))=o_p(1).
\end{equation}

Using the definition of $\hat{\Delta}$ and equations \ref{eqnPSSLSUC04} and \ref{eqnPSSLSUC014}, on the event $E_N(Q)$, we have
\begin{equation}
\label{eqnPSSLSUC025}
\begin{aligned}
\sup_{\lambda\in \hat{\Delta}}\|A^\top \lambda\| &\leq \sup_{\lambda\in \hat{\Delta}}\|(A-\hat{A})^\top \Pi^u(\lambda)\|+(\kappa_N/\sqrt{N})\|\mathbbm{1}\|\\
&\leq C\kappa_N/\sqrt{N}=o(1),
\end{aligned}
\end{equation}
and 
\begin{equation}
\label{eqnPSSLSUC026}
\begin{aligned}
\sup_{\lambda\in \hat{\Delta}} (\mathbbm{1}^\top \Omega \lambda-1)_+&\leq \sup_{\lambda\in \hat{\Delta}} (\mathbbm{1}^\top (\Omega-\hat{\Omega}) \lambda)_+\\
&\leq C\alpha_N=o(1),
\end{aligned}
\end{equation}
and 
\begin{equation}
\label{eqnPSSLSUC027}
\begin{aligned}
\sup_{\lambda \in \hat{\Delta}} (b^\top \lambda)_- 
&\leq \sup_{\lambda \in \hat{\Delta}} \left[ (b - \hat{b})^\top \Pi^u(\lambda) + \hat{T}_N - \frac{\kappa_N}{\sqrt{N}} \right]_- \\
&\leq \sup_{\lambda \in \hat{\Delta}} \|b - \hat{b}\| \cdot \|\Pi^u(\lambda)\| + |\hat{T}_N| + \frac{\kappa_N}{\sqrt{N}} \\
&\leq C \frac{\kappa_N}{\sqrt{N}} = o(1).
\end{aligned}
\end{equation}
Equations \ref{eqnPSSLSUC025}, \ref{eqnPSSLSUC025}, and \ref{eqnPSSLSUC025}, in combination with Lemma \ref{lemhoff}, then imply that we have 
\[
\overset{\rightarrow}{d}_{H}(\hat{\Delta},\Delta_0)=o_p(1),
\]
which in turn implies equation \ref{eqnPSSLSUC024}. This completes the proof.
\end{proof}
