The following proposition builds on Theorems 1 and 2 of \cite{VST} to derive an anti-concentration result, which is useful for establishing our uniformity results and may be of independent interest.
\begin{proposition}[Anti-concentration]
\label{prop1}
Let $T$ be an arbitrary index set. Let $\{K_t \mid t \in T\}$ be a family of compact subsets of $\mathbb{R}^p$ $(K_t \subseteq \mathbb{R}^p)$, and let $\{Z_t \mid t \in T\}$ be a family of mean-zero Gaussian vectors in $\mathbb{R}^p$, with $Z_t \sim \mathcal{N}(0, \Sigma_t)$. Suppose there exist strictly positive constants $M$ and $\sigma$ such that
\begin{equation}
\label{eqnprop1}
\sup_{t \in T} \|\Sigma_t\| \leq M \quad \text{and} \quad \sup_{t \in T} \max_{\lambda \in K_t} \|\lambda\| \leq M,
\end{equation}
and that for all $t \in T$, there exists $\lambda_t \in K_t$ such that
\begin{equation}
\label{eqnprop2}
\lambda_t^\top \Sigma_t \lambda_t > \sigma^2.
\end{equation}
Define random variables $\{Y_t\}_{t \in T}$ by
\[
Y_t = \max_{\lambda \in K_t} Z_t^\top \lambda.
\]
Then, for any $\delta > 0$, the distributions $\{F_t\}_{t \in T}$ of the random variables $\{Y_t\}_{t \in T}$ are absolutely continuous on the interval $[\delta, +\infty)$ and possess densities $\{f_t\}_{t \in T}$ that are uniformly bounded on $[\delta, +\infty)$; that is,
\begin{equation}
\label{eqnprop3}
\sup_{t \in T} \sup_{x \in [\delta, +\infty)} f_t(x) < \infty.
\end{equation}

As a consequence, if $q_t(\cdot)$ denotes the quantile function of $F_t$, then for any $\overline{\alpha} \in (0, 1/2)$, there exists $\underline{x} > 0$ such that
\begin{equation}
\label{eqnprop4}
\inf_{\alpha \in (0, \overline{\alpha})} \inf_{t \in T} q_t(1-\alpha) > 2\underline{x}, \quad \text{and}\quad \sup_{t\in T}\sup_{x\in [\underline{x},+\infty)}f_t(x)<\infty.
\end{equation}

\end{proposition}

\begin{proof}[\bf{Proof of Proposition \ref{prop1}}]
We proceed in two steps. In the first step, we establish inequality \eqref{eqnprop3} using \eqref{eqnprop1} and Theorem 2 of \cite{VST}. In the second step, we use \eqref{eqnprop2} and \eqref{eqnprop3} to establish inequality \eqref{eqnprop4}.

\medskip
\underline{Step 1: Proof of \eqref{eqnprop3}.}  
Given $\delta > 0$ as in the statement of the proposition, let $C_{\delta}>0$ be a constant satisfying $M C_{\delta} < \delta/2$.
We first show that inequality \eqref{eqnprop2} implies
\begin{equation}
\label{eqnpprop1}
\inf_{t \in T} P(\|Z_t\| < C_{\delta}) > \eta
\end{equation}
for some $\eta > 0$. Indeed, since $Z_t \sim \Sigma_t^{1/2} Z$, where $Z \sim \mathcal{N}(0, \mathbb{I}_p)$ is a standard normal vector in $\mathbb{R}^p$, we have
\[
\inf_{t \in T} P(\|Z_t\| < C_{\delta}) \geq P(\|Z\| < C_{\delta}/\sqrt{M}),
\]
where $M$ is as in \eqref{eqnprop1}, and we have used the fact that $\|\Sigma_t^{1/2}\| = \|\Sigma_t\|^{1/2} \leq M^{1/2}$, as $\Sigma_t$ is symmetric and positive semidefinite. We can thus set $\eta = P(\|Z\| < C_{\delta}/\sqrt{M})$ in \eqref{eqnpprop1}.

Now, by inequality \eqref{eqnpprop1} and the definition of $Y_t$, it follows that
\begin{equation}
\label{eqnpprop2}
F_t(\delta/2) = P(Y_t \leq \delta/2) \geq P(|Y_t|\leq \delta/2)\geq P(\|Z_t\| \leq C_{\delta}) \geq \eta.
\end{equation}
Let $\Phi(\cdot)$ denote the CDF of a standard normal variable, and for each $t \in T$, define $\tau_t$ by
\[
\tau_t = \Phi^{-1}(F_t(\delta/2)).
\]
Assuming without loss of generality that $\eta < 1/2$, inequality \eqref{eqnpprop2} yields
\begin{equation}
\label{eqnpprop3}
(\tau_t)_{-} := \max\{-\tau_t, 0\} \leq -\Phi^{-1}(\eta).
\end{equation}

Applying Theorem 2 of \cite{VST}, for each $t \in T$ and for $x \in [\delta, +\infty)$, we obtain
\[
f_t(x) \leq \bigl( (\tau_t)_- + 2 \bigr)^2 \frac{x}{(x-\delta/2)^2} + \bigl( (\tau_t)_- + 2 \bigr) \frac{1}{x-\delta/2}.
\]
Combining this with \eqref{eqnpprop3}, we deduce that
\[
\sup_{t \in T} \sup_{x \in [\delta, +\infty)} f_t(x) \leq \left( -\Phi^{-1}(\eta) + 2 \right)^2 \frac{4}{\delta} + \left( -\Phi^{-1}(\eta) + 2 \right) \frac{2}{\delta} < \infty,
\]
which establishes \eqref{eqnprop3}.

\medskip
\underline{Step 2: Proof of \eqref{eqnprop4}.}  
We now prove inequality \eqref{eqnprop4}. Observe that by the definition of $Y_t$, it stochastically dominates $\lambda_t^\top Z_t$, where $\lambda_t \in K_t$ is as in the statement of the proposition. Hence, the $1-\alpha$ quantiles of $Y_t$ are at least as large as those of $\lambda_t^\top Z_t$.

Moreover, for each $\alpha \in (0,1/2)$, inequality \eqref{eqnprop2} implies that the $1-\alpha$ quantiles of $\lambda_t^\top Z_t$ are bounded below by those of a $\mathcal{N}(0, \sigma^2)$ distribution, with $\sigma$ as in \eqref{eqnprop2}. Therefore,
\[
\inf_{\alpha \in (0, \overline{\alpha})} \inf_{t \in T} q_t(1-\alpha) \geq \inf_{t \in T} q_t(1-\overline{\alpha})\geq  \sigma \Phi^{-1}(1-\overline{\alpha}) := 2\underline{x}.
\]
The second part of \eqref{eqnprop4} then follows from inequality \eqref{eqnprop3}, with $\delta = \underline{x}$.
\end{proof}
