The following two lemmas are useful in deriving the (pointwise) asymptotic distributions of our test statistics. The first lemma gives the asymptotic distribution of the test statistics in Theorems \ref{thmSSAS1}, \ref{thmSSARP1}, and \ref{thmSSFSST1}, while the second lemma is used to derive the asymptotic distribution of the test statistic in \ref{thmSSLSUC1}.  Foth are variations on the results of \cite{AS}.
\begin{lemma}
\label{lemAD}
Consider the linear program $v = \max\{ b^\top \lambda \mid A^\top \lambda \leq 0,\ \|D\lambda\|_1 \leq 1 \}$. Let $\hat{b}$ and $\hat{D}$ denote estimators of $b$ and $D$, respectively, such that $\sqrt{N}(\hat{b} - b) \Rightarrow \zeta^b$ and $\hat{D} - D = o_p(1)$. Let \( K \) and \( U \) form a partition of \([p]\), where \( p \) denotes the dimension of \( b \). We allow \( K \) to be empty, but require \( U \) to be nonempty. The set \( K \) corresponds to the indices of the deterministic or known components of \( b \), and we assume that
\begin{equation}
\label{eqnlemAD0}
\forall i \in K, \quad \hat{b}_i = b_i \quad \text{and} \quad \hat{D}_{ii} = D_{ii} = 0, 
\qquad \text{and} \qquad \exists\, \underline{\sigma} > 0 \;\; \text{s.t.} \;\; D_{ii} > \underline{\sigma} \quad \forall i \in U.
\end{equation}

 Define $\Delta_0 := \arg\max\{ b^\top \lambda \mid A^\top \lambda \leq 0,\ \|D\lambda\|_1 \leq 1 \}$. If $v = 0$, then
\begin{equation}
\label{eqnlemAD1}
\sqrt{N}(\hat{v} - v)=\sqrt{N}\hat{v} \overset{d}{\longrightarrow} \max_{\lambda \in \Delta_0} \langle \zeta^b, \lambda \rangle.
\end{equation}
Here $\hat{v} = \max\{ \hat{b}^\top \lambda \mid A^\top \lambda \leq 0,\ \|\hat{D}\lambda\|_1 \leq 1 \}$.
\end{lemma}
\begin{proof}[\bf{Proof of Lemma \ref{lemAD}}] 
Let $\hat{\zeta}=(\sqrt{N}(\hat{b}-b),\hat{D}-D)$. The hypothesis of the theorem implies that $\hat{\zeta}\overset{d}{\rightarrow} \zeta:=(\zeta^b,0)$. By the Skorokhod representation theorem, there exists a sufficiently rich probability space, and versions $\xi_N \overset{d}{=}\hat{\zeta}$ and $\xi:=(\xi^b,0)\overset{d}{=}\zeta$ such that $a.s.-\lim_{N\to \infty} \xi_N=\xi$. Using the notation used in the derivation of equation \ref{eqnSSAS6}, let $\mu=(b,D)$ and $\mu_N(\xi_N)=(b_N(\xi_N),D_N(\xi_N))=(b+\frac{\xi_N^b}{\sqrt{N}}, D+\xi_N^D)$. We have $v=\phi(\mu)$ and $\hat{v}\overset{d}{=}\phi(\mu_N(\xi_N))$. For $\lambda\in \mathbb{R}^p$, let $\Pi^u:\mathbb{R}^p\rightarrow \mathbb{R}^p$ be the projection defined by
\[
[\Pi^u(\lambda)]_i=\lambda_i \quad \forall i\in U \quad \quad \text{and} \quad \quad [\Pi^u(\lambda)]_i=0 \quad \forall i \in K,
\]
where $K$ and $U$ are as in equation \ref{eqnlemAD0}. That is, $\Pi^u(\cdot)$ is the projection on the subspace spanned by the cannonical basis vectors with indices in $U$. Condition \ref{eqnlemAD0} then implies that we necessarily have (with prob. 1)
\[
[\xi^b]_i=[\xi_N^b]_i=0 \quad \forall i \in K \quad \quad \text{and}\quad \quad [\xi_N^D]_{ii}=0\quad \forall i\in K.
\]

We show below, using an argument similar to that of Theorem 17 in \cite{YG}, that 
\[
a.s.-\lim_{N\to\infty}\sqrt{N}\phi(\mu_N(\xi_N))=\max_{\lambda\in\Delta_0}\langle \lambda,\xi^b\rangle
\]
from which the conclusion of the lemma follows.

Note that the value of our LP has the following equivalent representations
\begin{equation}
\label{eqnPlemAD0}
\begin{aligned}
v&=\max\{b^\top\lambda \mid A^\top \lambda\leq 0,\ D\lambda =u-v, \ \mathbbm{1}^\top(u+v)\leq 1, \ u,v\geq 0\}\\
&=\min\{x\mid x\geq 0, \ z\geq 0, \ Az-b=Dy, \ \|y\|_{\infty}\leq x\}.
\end{aligned}
\end{equation}
Let $L(\lambda,u,v,x,y,z)$ denote the Lagrangian associated with the unperturbed LP, and given by
\[
L(\lambda,u,v,x,y,z)=\langle \lambda,b\rangle+y^\top(D\lambda-u+v)+x(1-\mathbbm{1}^\top (u+v))-z^\top A^\top \lambda.
\]
Similarly, let $L_N(\lambda,u,v,x,y,z;\xi_N)$ denote the Lagrangian associated with the perturbed LP, and defined by
\[
L_N(\lambda,u,v,x,y,z;\xi_N)=\langle \lambda,b_N(\xi_N)\rangle+y^\top(D_N(\xi_N)\lambda-u+v)+x(1-\mathbbm{1}^\top (u+v))-z^\top A^\top \lambda.
\]
Let $(\lambda_0, u_0, v_0, x_0, y_0, z_0)$ (resp. $(\lambda(\xi_N), u(\xi_N), v(\xi_N), x(\xi_N), y(\xi_N), z(\xi_N))$) denote the optimal primal and dual solutions to the unperturbed (resp. perturbed) linear programs. Then, by the saddle point property of the Lagrangian, and by noting that the condition $v=0$ impilies that $x_0=0$ and $y_0=0$, we have
\begin{equation}
\label{eqnPlemAD1}
\begin{aligned}
\sqrt{N}\phi(\mu_N(\xi_N))&=\sqrt{N}\Bigl(L(\lambda(\xi_N), u(\xi_N), v(\xi_N), x(\xi_N), y(\xi_N), z(\xi_N);\xi_N)-L(\lambda_0, u_0, v_0, x_0, y_0, z_0)\Bigr)\\
&\leq \sqrt{N}\Bigl(L(\lambda(\xi_N), u(\xi_N), v(\xi_N), x_0, y_0, z_0;\xi_N))-L(\lambda(\xi_N), u(\xi_N), v(\xi_N), x_0, y_0, z_0)\Bigr)\\
&=\langle \xi_N^b,\lambda(\xi_N)\rangle=\langle \xi_N^b,\Pi^u(\lambda(\xi_N))\rangle .
\end{aligned}
\end{equation}

We now work toward establishing equation \ref{eqnPlemAD3}. To that end, we want to show that
\begin{equation}
\label{eqnPlemAD20}
\overset{\rightarrow}{d}_H\bigl(\Pi^u(\mathcal{\Delta}_{0,N}(\xi_N)),\Pi^u(\Delta_0)\bigr)\overset{a.s.}{\rightarrow}0,
\end{equation}
where 
\[
\mathcal{\Delta}_{0,N}(\xi_N):=\arg\max\{ b_N(\xi_N)^\top \lambda \mid A^\top \lambda \leq 0,\ \|D_N(\xi_N)\lambda\|_1 \leq 1 \}.
\]
Note that, almost surely, for all sufficiently large $N$ such that $\|\xi_N^D\|\leq \underline{\sigma}/2$, we have 
\[
\|D_N(\xi_N)\lambda\|_1=\|\Pi^u(D_N(\xi_N)\lambda)\|_1\geq (\underline{\sigma}/2)\|\Pi^u(\lambda)\|_1.
\]
with
\[
\mathcal{D}_N(\xi_N):=\bigl\{\lambda \in \mathbb{R}^p \mid A^\top \lambda\leq 0, \ \|D_N(\xi_N)\lambda\|_1\leq 1\bigr\}.
\]
As a consequence, we have
\begin{equation}
\label{eqnPlemAD02}
a.s.-\overline{\lim}_{N\to \infty}  \sup_{\lambda \in {\cal D}_N(\xi_N)} \|\Pi^u(\lambda)\|_1\leq 2/\underline{\sigma}.
\end{equation}
A similar argument gives
\begin{equation}
\label{eqnPlemAD002}
 \sup_{\lambda \in {\cal D}} \|\Pi^u(\lambda)\|_1\leq 1/\underline{\sigma}.
\end{equation}

Since, the smallest nonzero diagonal element of $D$ is bounded away from zero, for all N sufficiently large that $\|\xi_N^D\|< \underline{\sigma}$, we have
\begin{equation}
\label{eqnPlemAD21}
\bigl(1-\|\xi_N^D\|/\underline{\sigma}\bigr)\|D \lambda\|_1\leq \|D_N(\xi_N)\lambda\|_1\leq (1+\|\xi_N^D\|/\underline{\sigma})\|D \lambda\|_1.
\end{equation}
Therefore, as the feasible regions are star-shaped w.r.t the origin, if $\lambda \in \Delta_{0,N}(\xi_N)$, then 
\[
\Gamma_N(\lambda):=(1-\|\xi_N^D\|/\underline{\sigma})\lambda\in {\cal D} \quad \quad \text{and}\quad \quad  \|\Pi^u(\lambda)-\Pi^u(\Gamma_N(\lambda))\|\leq  \|\Pi^u(\lambda)\|\times \|\xi_N^D\|/\underline{\sigma}.
\]
The latter inequality and equation \ref{eqnPlemAD02} then yields
\begin{equation}
\label{eqnPlemAD0021}
\overset{\rightarrow}{d}_H(\Pi^u(\Delta_{0,N}(\xi_N)), \Pi^u(\Gamma_N(\Delta_{0,N}(\xi_N))))\overset{a.s.}{\longrightarrow} 0.
\end{equation}

We have
\begin{equation}
\label{eqnPlemAD22}
\begin{aligned}
0\geq \sup_{\lambda \in \Delta_{0,N}(\xi_N)}\langle b, \Gamma_N(\lambda)\rangle&=\inf_{\lambda \in \Delta_{0,N}(\xi_N)}\langle b, \Gamma_N(\lambda)\rangle\\
&=\inf_{\lambda \in \Delta_{0,N}(\xi_N)}\langle b-b_N(\xi_N), \Gamma_N(\lambda)\rangle+\langle b_N(\xi_N), \Gamma_N(\lambda)\rangle\\
&\geq \inf_{\lambda \in \Delta_{0,N}(\xi_N)}\langle b-b_N(\xi_N), \Gamma_N(\lambda)\rangle=\inf_{\lambda \in \Delta_{0,N}(\xi_N)}\langle \xi_N^b/\sqrt{N}, \Pi^u(\Gamma_N(\lambda))\rangle\\
&\geq \inf_{\lambda \in {\cal D}}\langle \xi_N^b/\sqrt{N}, \Pi^u(\lambda)\rangle\\
&\geq -\sup_{\lambda \in {\cal D}} \|\Pi^u(\lambda)\| \frac{\|\xi_N^b\|}{\sqrt{N}}\overset{a.s.}{\longrightarrow}0
\end{aligned}
\end{equation}
where the first inequality follows from the condition \( v = 0 \); the second inequality follows from the fact that \( \langle b_N(\xi_N), \lambda \rangle \geq 0 \) for all \( \lambda \in \Delta_{0,N}(\xi_N) \), since \( 0 \in \mathcal{D}_N(\xi_N) \) and \( \Gamma_N(\lambda) \) is a positive scalar multiple of \( \lambda \); the third inequality follows from the inclusion \( \Gamma_N(\Delta_{0,N}(\xi_N)) \subseteq \mathcal{D} \); and the almost sure convergence follows from equation~\ref{eqnPlemAD002} and the fact that \( \xi_N^b \overset{a.s.}{\rightarrow} 0 \). By Lemma \ref{lemOSC}, Inequality \ref{eqnPlemAD22} and the fact that $v=0$ then imply
\[
\overset{\rightarrow}{d}_H(\Gamma_N(\Delta_{0,N}(\xi_N)), \Delta_0)\overset{a.s.}{\longrightarrow} 0, 
\]
and we thus have
\begin{equation}
\label{eqnPlemAD0022}
\overset{\rightarrow}{d}_H(\Pi^u(\Gamma_N(\Delta_{0,N}(\xi_N))), \Pi^u(\Delta_0))\overset{a.s.}{\longrightarrow} 0.
\end{equation}
Equation \ref{eqnPlemAD20} then follows from equations \ref{eqnPlemAD0021} and \ref{eqnPlemAD0022}.

We can now take the limit of both sides of equation \ref{eqnPlemAD1}, and using equation \ref{eqnPlemAD20} gives
\begin{equation}
\label{eqnPlemAD3}
\begin{aligned}
a.s.-\overline{\lim}_{N\to \infty}\sqrt{N}\phi(\mu_N(\xi_N))&\leq a.s.-\overline{\lim}_{N\to \infty} \langle \xi_N^b,\Pi^u(\lambda(\xi_N))\rangle \\
&\leq a.s.-\overline{\lim}_{N\to \infty} \sup_{\lambda\in \Delta_0}\langle \xi_N^b,\Pi^u(\lambda)\rangle +\|\xi_N^b\|\overset{\rightarrow}{d}_H(\Pi^u(\Delta_{0,N}(\xi_N)), \Pi^u(\Delta_0))\\
&=\sup_{\lambda\in \Delta_0}\langle \xi^b,\lambda\rangle.
\end{aligned}
\end{equation}
To complete the argument, it remains to establish the converse of inequality \ref{eqnPlemAD3}. To that end, using the saddle point property and adopting the same notation as in the derivation of inequality \ref{eqnPlemAD1}, we have
\begin{equation}
\label{eqnPlemAD4}
\begin{aligned}
\sqrt{N}\phi(\mu_N(\xi_N))&=\sqrt{N}\Bigl(L(\lambda(\xi_N), u(\xi_N), v(\xi_N), x(\xi_N), y(\xi_N), z(\xi_N);\xi_N)-L(\lambda_0, u_0, v_0, x_0, y_0, z_0)\Bigr)\\
&\geq \sqrt{N}\Bigl(L(\lambda_0, u_0, v_0, x(\xi_N), y(\xi_N), z(\xi_N);\xi_N)-L(\lambda_0, u_0, v_0, x(\xi_N), y(\xi_N), z(\xi_N))\Bigr)\\
&=\langle \xi_N^b,\lambda_0\rangle +\sqrt{N}\langle y(\xi_N), \xi_N^D\lambda_0\rangle. 
\end{aligned}
\end{equation}
The dual representation of our LP (equation \ref{eqnPlemAD0}) and inequality \ref{eqnPlemAD3} imply that 
\[
a.s.-\overline{\lim}_{N\to \infty} \sqrt{N}\ \|y(\xi_N)\|_{\infty}= a.s.-\overline{\lim}_{N\to \infty} \sqrt{N}\ x(\xi_N)=a.s.-\overline{\lim}_{N\to \infty}\sqrt{N}\phi(\mu_N(\xi_N))<\infty,
\]
and since $\xi_N^D\overset{a.s.}{\rightarrow}0$, we conclude that 
\[
a.s.-\lim_{N\to \infty}\sqrt{N}\langle y(\xi_N), \xi_N^D\lambda_0\rangle=0.
\]
Equation \ref{eqnPlemAD4} thus gives
\begin{equation}
a.s.-\underline{\lim}\sqrt{N}\phi(\mu_N(\xi_N))\geq \max_{\lambda \in \Delta_0}\langle \xi^b,\lambda \rangle,
\end{equation}
which establishes the converse to \ref{eqnPlemAD3}, and proves the claim.
\end{proof}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

\begin{lemma}
\label{lem1AD}
Consider the linear program $v = \max\{ b^\top \lambda \mid\lambda\geq 0,\ A^\top \lambda = 0,\ \|\Omega\lambda\|_1 \leq 1 \}$ in \ref{eqnSSLSUC1}. And let $\hat{d}$ be an estimator of $d=vec([A\ \ b])$ such that 
\begin{equation}
\sqrt{N}(\hat{d}-d)\overset{d}{\longrightarrow}\mathcal{N}(0,\Sigma) \quad \quad \text{and}\quad \quad \hat{\Omega}-\Omega \overset{p}{\longrightarrow}0
\end{equation}
where $\Omega$ and $\hat{\Omega}$ are as defined in Section \ref{sectionSSLSUC}. Let $U\subset [p]$ denote the set of indices of positive diagonal elements of $\Omega$. Assume that the system
\[
b-A\eta\leq 0
\]
has a unique solution $\eta^*$. For $\hat{T}_N$ as defined in equation \ref{eqnSSLSUC2}, we have
\begin{equation}
\label{eqnlem1AD1}
\sqrt{N}\hat{T}_N\overset{d}{\longrightarrow} \max_{\lambda \in \Delta_0} \langle \zeta_b-\zeta_A\eta^*, \lambda \rangle,
\end{equation}
where $\zeta=vec([\zeta_A \ \ \zeta_b])\sim \mathcal{N}(0,\Sigma)$, and $\Delta_0=\arg\max\{ b^\top \lambda \mid\lambda\geq 0,\ A^\top \lambda = 0,\ \|\Omega\lambda\|_1 \leq 1 \}$.
\end{lemma}


\begin{proof}[\bf{Proof of Lemma \ref{lem1AD}}]
We proceed using an almost sure representation argument as in the preceding lemma. Let $\hat{\zeta}=(\sqrt{N}(\hat{A}-A),\sqrt{N}(\hat{b}-b),\ \hat{\Omega}-\Omega)$. The hypothesis of the theorem implies that $\hat{\zeta}=(\hat{\zeta}_A,\hat{\zeta}_b,\hat{\zeta}_{\Omega})\overset{d}{\rightarrow} \zeta:=(\zeta_A,\zeta_b,0)$ where $vec([\zeta_A\ \ \zeta_b])\sim \mathcal{N}(0,\Sigma)$. By the Skorokhod representation theorem, there exists a sufficiently rich probability space, and versions $\xi_N \overset{d}{=}\hat{\zeta}$ and $\xi:=(\xi_A,\xi_b,0)\overset{d}{=}\zeta$ such that $a.s.-\lim_{N\to \infty} \xi_N=\xi$. Using the notation used the proof of Theorem \ref{thmSSLSUC1} (Section \ref{pthmSSLSUC1}), let $\mu=(A,b,\Omega)$ and $\mu_N(\xi_N)=(A_N(\xi_N),b_N(\xi_N),\Omega_N(\xi_N))=\bigl(A+\frac{\xi_{AN}}{\sqrt{N}}, b+\frac{\xi_{bN}}{\sqrt{N}}, \Omega+\xi_{\Omega N}\bigr)$. We have $v=\phi(\mu)$ and $\hat{v}\overset{d}{=}\phi(\mu_N(\xi_N))$. Let the Lagrangians $L_N(\lambda,\eta,t;\xi)$ and $L(\lambda,\eta,t)$ be as defined in Section \ref{pthmSSLSUC1}.

Reasoning as in the derivation of equation \ref{eqnPSSLSUC02}, we have
\begin{equation}
\label{eqnPlem1AD1}
\sqrt{N} \phi_N(\mu_N(\xi_N)) \leq \langle \xi_{bN}-\xi_{AN} \eta^*, \lambda(\xi_N)\rangle
\end{equation}
where $\lambda(\xi_N)$ is any element in $\Delta_{0,N}(\xi_N)=\arg\max\{b_N(\xi_N)^\top \lambda \mid \lambda\geq 0, \ A_N(\xi_N)^\top \lambda=0, \ \mathbbm{1}^\top \Omega_N(\xi_N)\lambda\leq 1\}$, and $\eta^*$ is as in the statement of the lemma.

We now show that
\begin{equation}
\label{eqnPlem1AD2}
a.s.-\lim_{N\to \infty} \overset{\rightarrow}{d}_H(\Delta_{0,N}(\xi_N),\Delta_0)=0.
\end{equation}
We have
\[
\sup_{\lambda\in \Delta_{0,N}(\xi_N)}\|A^\top\lambda\|=\sup_{\lambda\in \Delta_{0,N}(\xi_N)}\|(A-A_N(\xi_N))^\top\Pi^u(\lambda)\| \leq \|A-A_N(\xi_N)\|\sup_{\lambda\in \Delta_{0,N}(\xi_N)}\|\Pi^u(\lambda)\|\overset{a.s.}{\longrightarrow} 0,
\]
and
\begin{equation*}
\begin{aligned}
\sup_{\lambda\in \Delta_{0,N}(\xi_N)} (\mathbbm{1}^\top \Omega \lambda-1)_+ &\leq \sup_{\lambda\in \Delta_{0,N}(\xi_N)} (\mathbbm{1}^\top \Omega \lambda-1+1-\mathbbm{1}^\top \Omega_N(\xi_N) \lambda)_+\\
&\leq \|\Pi^u(\mathbbm{1})\|\|\Omega-\Omega_N(\xi_N)\|\sup_{\lambda\in \Delta_{0,N}(\xi_N)}\|\Pi^u(\lambda)\|\overset{a.s.}{\longrightarrow} 0,
\end{aligned}
\end{equation*}
where we have used equation \ref{eqnPSSLSUC04}. The latter two inequalities and Lemma \ref{lemhoff} yield equation \ref{eqnPlem1AD2}.

Equations \ref{eqnPlem1AD1} and \ref{eqnPlem1AD2} imply that
\begin{equation}
\label{eqnPlem1AD3}
\begin{aligned}
a.s.-\overline{\lim}_{N\to \infty} \sqrt{N} \phi_N(\mu_N(\xi_N)) &\leq a.s.-\overline{\lim}_{N\to \infty}  \sup_{\lambda\in \Delta_0} \langle \xi_{bN}-\xi_{AN} \eta^*, \lambda\rangle+\\
&\overset{\rightarrow}{d}_H(\Delta_{0,N}(\xi_N),\Delta_0)\|\xi_{bN}-\xi_{AN} \eta^*\| \\
&=\sup_{\lambda\in \Delta_0} \langle \xi_{b}-\xi_{A} \eta^*, \lambda\rangle.
\end{aligned}
\end{equation}

We now derive the converse to equation \ref{eqnPlem1AD3}. Reasoning as in the derivation of equation \ref{eqnPlemAD4}, we have
\begin{equation}
\label{eqnPlem1AD4}
\begin{aligned}
\sqrt{N} \, \phi(\mu_N(\xi_N)) 
&\geq \sqrt{N} \bigl( L_N(\lambda_0, \eta(\xi_N), t(\xi_N); \xi_N) - L(\lambda_0, \eta(\xi_N), t(\xi_N)) \bigr) \\
&= \xi_{bN}^\top \lambda_0 - \eta(\xi_N)^\top \xi_{AN}^\top \lambda_0 - t(\xi_N) \mathbbm{1}^\top \xi_{\Omega N} \lambda_0 ,
\end{aligned}
\end{equation}
where $\lambda_0 \in \Delta_0$ and $(\eta(\xi_N), t(\xi_N)) \in S_{0,N}(\xi_N)$, the set of optimal solutions to the (perturbed) dual LP \ref{eqnPSSLSUC01} with input $\mu_N(\xi_N)$ (see Section~\ref{pthmSSLSUC1}). Note that all elements of the set $S_{0,N}(\xi_N)$ have the same second component, given by the value of the perturbed LP: i.e., $t(\xi_N)=\phi(\mu_N(\xi_N))$. We first show that 
\begin{equation}
\label{eqnPlem1AD5}
a.s.-\overline{\lim}_{N\to \infty} t(\xi_N))=0.
\end{equation}
Indeed, we have
\[
\phi(\mu_N(\xi_N))=\min\{t\mid t\Omega_N(\xi_N) \mathbbm{1}+A_N(\xi_N)\eta\geq b_{N}(\xi_N),\ t\geq 0\}.
\]
Since $b-A\eta^*\leq 0$, we have
\begin{equation*}
\begin{aligned}
b_N(\xi_N)-A_N(\xi_N)\eta^*&\leq \bigl(b_N(\xi_N)-b\bigr)-\bigl(A_N(\xi_N)-A\bigr)\eta^*\\
&\leq \Bigl(\|b-b_N(\xi_N)\|+\|\eta^*\| \|A-A_N(\xi_N)\|\Bigr)\Pi^u(\mathbbm{1}).
\end{aligned}
\end{equation*}
Equation \ref{eqnPlem1AD5} then follows since $\|b-b_N(\xi_N)\|+\|\eta^*\| \|A-A_N(\xi_N)\|\overset{a.s.}{\longrightarrow}0$ and $[\Omega]_{ii}>0$ for all $ i\in U$. 

We now show that 
\begin{equation}
\label{eqnPlem1AD6}
a.s.-\lim \overset{\rightarrow}{d}_H(\Pi_1(S_{0,N}(\xi_N)),\{\eta^*\})=0
\end{equation}
where $\Pi_1(S_{0,N(\xi_N)}):=\bigl\{\eta\mid (\eta,t(\xi_N))\in S_{0,N}(\xi_N)\bigr\}$ is the projection of $S_{0,N}(\xi_N)$ on its first component. Indeed, for every $\eta\in \Pi_1(S_{0,N}(\xi_N))$, we have
\[
b_{N}(\xi_N)-A_N(\xi_N)\eta\leq t(\xi_N)\Omega_N(\xi_N)\mathbbm{1}.
\]
Note that if $(A_N,b_N,t_N)$ is any sequence such that $A_N\rightarrow A$ and $b_N\rightarrow b$, and $t_N\rightarrow 0$, then the set $\mathcal{C}_N=\{\eta \mid b_N-A_N\eta\leq t_N\}$ satisfies
\[
\overline{lim}_{N\to \infty} \sup_{\eta \in {\cal C}_N}\|\eta\|<\infty.
\]
If not, then, after passing to a subsequence, we can assume that there exist $\eta_N\in {\cal C}_N$ such that $\|\eta_N\|\to \infty$.
But then we have
\[
b_N/\|\eta_N\|-A_N(\eta_N/\|\eta_N\|)\leq t_N/\|\eta_N\|.
\]
After passing to a further subsequence, we can assume that $\eta_N/\|\eta_N\|\to \eta_0\neq 0$, and we have
\[
-A\eta_0\leq 0,
\]
which contradicts the assumption of the lemma that the inequality system $b-A\eta\leq 0$ has a unique solution $\eta^*$. Thus, we have
\[
a.s.-\overline{\lim}_{N\to \infty} \sup_{\eta \in \Pi_1(S_{0,N}(\xi_N))}\|\eta\| <\infty,
\]
and
\begin{equation*}
\begin{aligned}
a.s.-\overline{lim} \sup_{\eta\in \Pi_1(S_{0,N}(\xi_N))} \|[b-A\eta]_+\|&\leq a.s.-\overline{lim} \Bigl\{ \|b-b_N(\xi_N)\|+\|A-A_N(\xi_N)\| \sup_{\eta\in \Pi_1(S_{0,N}(\xi_N))}\|\eta\|+\\
&t(\xi_N)\|\Omega_N(\xi_N)\| \|\mathbbm{1}\|\Bigr\}\\
&=0.
\end{aligned}
\end{equation*}
The latter inequality and Lemma \ref{lemhoff} then imply equation \ref{eqnPlem1AD6}.

Combining equations~\ref{eqnPlem1AD4}, ~\ref{eqnPlem1AD5}, and ~\ref{eqnPlem1AD6}, we get 
\begin{equation}
\label{eqnPlem1AD7}
\begin{aligned}
a.s.-\underline{\lim}_{N\to \infty} \sqrt{N}\phi(\mu_N(\xi_N))&\geq a.s.-\underline{\lim}_{N\to \infty}\sup_{\eta\in \Pi_1(S_{0,N}(\xi_N))} \sup_{\lambda \in \Delta_0} \Bigl\{\xi_{bN}^\top \lambda - \eta^\top \xi_{AN}^\top \lambda - t(\xi_N) \mathbbm{1}^\top \xi_{\Omega N} \lambda\Bigr\}\\
&=\sup_{\lambda\in \Delta_0}\langle \xi_b-\xi_A\eta^*,\lambda \rangle.
\end{aligned}
\end{equation}
Combining equations \ref{eqnPlem1AD3} and \ref{eqnPlem1AD7} yield equation \ref{eqnlem1AD1}, and the proof is complete.

\end{proof}



