The following lemma establishes the set of maximizers of a LP is well separated in the sense that values of the objective function at feasible points that are at some fixed distance from the set of optimizers are strictly below the optimal value, even if the feasible region is not compact.

\begin{lemma}
\label{lemOSC}
Consider the LP $v=\max\{b^\top \lambda \mid A \lambda \leq d\}$, where $v$ is finite, and the feasible region ${\cal D}:=\{\lambda\in \mathbb{R}^p\mid A \lambda \leq d \}$ is not necessarily bounded. Let $\Delta_0=\arg\max\{b^\top \lambda \mid A \lambda \leq d\}$ denote the set of optimal solutions, and given $\epsilon>0$, let $\Delta_{\epsilon}$ denote the set of $\epsilon-$optimal solutions defined by
$\Delta_{\epsilon}:=\{\lambda \in {\cal D}\mid b^\top \lambda \geq v-\epsilon\}$.
Then there exists a constant $C$ that depends on the inputs $(A,b,d)$, such that
\begin{equation}
\label{eqnlemOSC1}
\overset{\rightarrow}{d}_H(\Delta_{\epsilon},\Delta_0)\leq C\epsilon.
\end{equation}
\end{lemma}
\begin{proof}[\bf{Proof of Lemma \ref{lemOSC}}]
The dual LP is given by 
\[
\min\{d^\top z\mid z\geq 0,\ A^\top z=b\}.
\]
Let $z^*$ denote an optimal dual solution, and let $J\subseteq [m]$ denote the set of nonzero indices of $z^*$, where $m$ denotes the number of rows of the matrix $A$. If $J=\emptyset$, then $z^*=0$, and since $A^\top z^*=b$, we have $b=0$, from which we deduce that  $\Delta_0={\cal D}$, and the claim trivially holds. So for the remainder of the proof, let us assume that $J\neq \emptyset$.

Let the face $F$ of ${\cal D}$ be given by 
\[
F:=\{\lambda \in \mathbb{R}^p\mid A_J\lambda=d_J \quad \text{and}\quad A_{J^c}\lambda\leq d_{J^c}\}
\]
where $J^c=[m]\backslash J$, and $A_J$ is the matrix obtained from A by deleting the rows not in $J$ (with a similar definition for $d_J$, $A_{J^c}$ and $d_{J^c}$).
We assert that \( F \) is equal to the set of optimal solutions, i.e., \( F = \Delta_0 \). Indeed, if $\lambda\in F$ then 
\[
b^\top \lambda=\langle A^\top z^*, \lambda \rangle=\langle  A^\top z^*, \lambda \rangle=\langle   z_{J}^*, A_J\lambda \rangle=\langle  z_{J}^*, d_J \rangle=\langle  z^*, d \rangle=v,
\]
and we have $F\subseteq \Delta_0$. For the reverse inclusion, note that if $\lambda^*\in \Delta_0$, then 
\[
\langle z^*,d \rangle=v=\langle \lambda^*, b\rangle= \langle \lambda^*, A^\top z^*\rangle \quad \Longrightarrow \quad \langle z^*,A\lambda^*-d\rangle=0\Longleftrightarrow \langle z_J^*,A_J\lambda^*-d_J\rangle=0.
\]
The last equation then implies that $A_J\lambda^*-d_J=0$, since we necessarily have $A_J\lambda^*-d_J\leq 0$, and all entries of $z_J*$ are strictly positive.\footnote{This corresponds to the complementary slackness condition in linear programming.}. As $\lambda^*\in {\cal D}$, we clearly have $A_{J^c}\lambda^*\leq d_{J^c}$. Therefore, $\lambda^*\in \Delta_0$ implies that $A_J\lambda^*-d_J=0$ and $A_{J^c}\lambda^*\leq d_{J^c}$, which gives the second inclusion $\Delta_0\subseteq F$, and we thus conclude that $F=\Delta_0$.

Now for $\lambda\in \Delta_{\epsilon}$ we have 
\[
\big[0\leq v-b^\top \lambda\leq \epsilon\big] \Longleftrightarrow  \big[0\leq \langle z^*,d\rangle- \langle A^\top z^*,\lambda \rangle \leq \epsilon\big] \Longleftrightarrow  \big[0\leq \langle z^*,d-A\lambda \rangle \leq \epsilon\big]
\Longleftrightarrow  \big[0\leq \langle z_J^*,d_J-A_J\lambda \rangle \leq \epsilon\big].
\]
If $\underline{z}:=\min\{z^*_j\mid  j \in J\}$ denotes the smallest value of $z^*$ on its support, then the last inequality implies that
for all $\lambda \in \Delta_{\epsilon}$, we have 
\begin{equation}
\label{eqnPlemOSC1}
\|d_J-A_J\lambda\|_1\leq \epsilon/\underline{z}.
\end{equation}
We recall that Hoffman's Theorem (Lemma \ref{lemhoff}) implies that there exists a constant $C>0$ such that for all $\lambda \in \mathbb{R}^p$ we have
\[
d(\lambda,F)\leq C\Bigl\{\|d_J-A_J\lambda\|+\|(d_{J^c}-A_{J^c}\lambda)_-\| \Bigr\}.
\] 
For $\lambda \in \Delta_{\epsilon}$, we necessarily have $(d_{J^c}-A_{J^c}\lambda)_-=0$, and Hoffman's Theorem and equation \ref{eqnPlemOSC1} then implies that 
\[
\sup_{\lambda \in \Delta_{\epsilon}}d(\lambda,F)\leq C\Bigl\{\|d_J-A_J\lambda\|\Bigr\} \leq (C/\underline{z})\epsilon
\] 
which completes the proof of inequality \ref{eqnlemOSC1}.
\end{proof}





