The following lemma establishes the Hausdorff continuity of the set of extreme points of our feasible regions under perturbations of the normalizing matrix $D$. It extends Lemma 4 in \cite{ARP} to settings in which the points $\lambda$ in the feasible region are not restricted to lie in an orthant of $\mathbb{R}^p$, and where the constraint used for the normalization may correspond to intersecting the feasible region with more than one halfspace. \footnote{When, as in \cite{ARP}, $\lambda \in \mathbb{R}^p_+$ for all $\lambda$ in the feasible region, the normalizing constraint $\|D\lambda\|_1\leq 1$ is equivalent to the inequality $\mathbbm{1}^\top D\lambda\leq 1$. When $\lambda$ is not restricted to lie in a specific orthant, the constraint $\|D\lambda\|_1\leq 1$ is no longer equivalent to one inequality, and may be equivalent with up to $2^p$ inequalities.}

\begin{lemma}
\label{lemEPC}
Given a diagonal matrix $D \in \mathbb{R}^{n \times n}$ and a matrix $B \in \mathbb{R}^{m_B \times n}$, let ${\cal D}(B,D)$ denote a polyhedral set defined by
\[
\mathcal{D}(B, D) := \left\{ \lambda \in \mathbb{R}^n \,\middle|\, B\lambda \leq 0,\ \|D\lambda\|_1 \leq 1 \right\}.
\]
For $D$ a diagonal matrix, let $\operatorname{supp}(D)$ denote the support of $D$, defined as the set of indices corresponding to nonzero diagonal entries of $D$:
\[
\operatorname{supp}(D) := \left\{ i \in [n] \,\middle|\, D_{ii} \neq 0 \right\}.
\]

Let $\operatorname{extr}(\mathcal{D})$ denote the (possibly empty) set of extreme points of $\mathcal{D}$. Let $\underline{\sigma}$ and $\overline{\sigma}$ be two fixed positive constants such that $\underline{\sigma}<\overline{\sigma}$ . Then for all matrices $B$ and diagonal matrices $D$ and $D'$ satisfying
\[
\operatorname{supp}(D) = \operatorname{supp}(D'), \quad 
\|D - D'\| \leq \underline{\sigma}/2, \quad 
\text{and} \quad 
\underline{\sigma} \leq D_{ii} \leq \overline{\sigma}, \quad \forall i \in \operatorname{supp}(D)
\]

 the following hold:

\begin{enumerate}[i)]
\item For all $\lambda \in \operatorname{extr}(\mathcal{D}(B, D))\backslash \{0\}$, we have $\|D'\lambda\|_1>0$, and if we set $\lambda' := \lambda/\|D'\lambda\|_1$, then  $\lambda' \in \operatorname{extr}(\mathcal{D}(B, D'))\backslash \{0\}$, and we have
\begin{equation}
\label{eqnlemEPC1}
   \lambda - \lambda'=\Bigl(1-\frac{1}{\|D'\lambda\|_1}\Bigr)\lambda   \quad \quad \text{and}\quad \quad \bigl|1-\frac{1}{\|D'\lambda\|_1}\bigr| \leq  \frac{2}{\underline{\sigma}} \|D' - D\|.
\end{equation}

\item For all $\lambda' \in \operatorname{extr}(\mathcal{D}(B, D'))\backslash \{0\}$, we have $\|D\lambda'\|_1>0$, and if we set $\lambda := \lambda'/\|D\lambda'\|_1$, then  $\lambda \in \operatorname{extr}(\mathcal{D}(B, D))\backslash \{0\}$, and we have
\begin{equation}
\label{eqnlemEPC2}
   \lambda' - \lambda=\Bigl(1-\frac{1}{\|D\lambda'\|_1}\Bigr)\lambda'   \quad \quad \text{and}\quad \quad \bigl|1-\frac{1}{\|D\lambda'\|_1}\bigr| \leq  \frac{1}{\underline{\sigma}} \|D' - D\|.
\end{equation}


\end{enumerate}
\end{lemma}

\begin{proof}[\bf{Proof of Lemma \ref{lemEPC}}]
We establish \ref{eqnlemEPC1}. The proof of \ref{eqnlemEPC2} is similar. Note that as the sets ${\cal D}(B,D)$ and ${\cal D}(B,D')$ are such that we have $\lambda\in {\cal D}(B,D)$ iff $\exists t>0$ such that $t\lambda \in {\cal D}(B,D')$. Hence $0 \in \operatorname{extr}(\mathcal{D}(B, D))$ iff $0 \in \operatorname{extr}(\mathcal{D}(B, D'))$, and it suffices to consider the nonzero elements of $\operatorname{extr}(\mathcal{D}(B, D))$. To that end, we first note that the inequality $\|\lambda\|_1\leq 1$ can be expressed as a set of $2^n$ inequality constraints, given by $H \lambda\leq 1$, where the rows of $H$ are given by the elements of $\{-1,1\}^n$. Thus the set ${\cal D}(B,D)$ has the equivalent representation
\[
{\cal D}(B,D)=\bigl\{\lambda \in \mathbb{R}^n \mid B\lambda \leq 0, \ HD\lambda\leq \mathbbm{1}_{2^n}\bigr\}
\]
where $\mathbbm{1}_{2^n}$ represent the vector of all ones of dimension $2^n$. For $\lambda \in \mathbb{R}^n$, define the support of $\lambda$ as $\operatorname{supp}(\lambda) = \{i \in [n] \mid \lambda_i \neq 0\}$.
Let $e_{n,j}$, for $j \in [n]$, denote the canonical basis vectors in $\mathbb{R}^n$.


By the characterization of extreme points of a polyhedron, we have $\lambda \in \mathcal{D}(B, D) \setminus \{0\}$ if and only if $\lambda \in \mathcal{D}(B, D)$ and there exist subsets $J_1 \subseteq [m_B]$ and $J_2 \subseteq [2^n]$ such that $J_2\neq \emptyset$ and $n_1+n_2 = n$, where $n_1:=|J_1|$ and  $n_2:= |J_2|$, the matrix
 \( \left( \begin{smallmatrix} B_{J_1} \\ H_{J_2}D \end{smallmatrix} \right) \) is invertible, and $\lambda$ is the unique solution to the equation\footnote{Given a matrix $A \in \mathbb{R}^{m \times n}$ and an index set $J \subseteq [m]$ corresponding to rows of $A$, we let $A_J$ denote the $|J| \times n$ matrix obtained by selecting only the rows of $A$ indexed by $J$.}
\begin{equation}
\label{eqnPlemEPC1}
\begin{pmatrix}
 B_{J_1} \\
 H_{J_2} D
\end{pmatrix} \lambda =
\begin{pmatrix}
 0 \\
 \mathbbm{1}_{n_2} 
\end{pmatrix}.
\end{equation}
For all $i\in [n_2]$, we have 
\[
e_{n_2,i}^\top H_{J_2} D\lambda =\|D\lambda\|_1=1.
\]
As a consequence, when restricted to the columns in the support of $D\lambda$, the rows of $H_{J_2}$ must all be equal, with entries equal to the sign of $D\lambda$; that is, for $i, j \in [n_2]$ and $k \in \operatorname{supp}(D\lambda)$, we have
\begin{equation}
\label{eqnPlemEPC2}
e_{n_2,i}^\top H_{J_2} e_{n,k}=e_{n_2,j}^\top H_{J_2} e_{n,k}, \quad  \text{ and }\quad e_{n_2,i}^\top H_{J_2} e_{n,k}=\operatorname{sign}(e_{n,k}^\top D\lambda).
\end{equation}
Note that as $D'$ is also a positive matrix with same support as $D$, we have $\operatorname{supp}(D'\lambda)=\operatorname{supp}(D\lambda)$, $\operatorname{sign}(D\lambda)=\operatorname{sign}(D'\lambda)$\footnote{Given a vector $x\in \mathbb{R}^n$, let $\operatorname{sign}(x)$ be the vector in $\mathbb{R}^n$ with $i^{th}$ entry equal to $1$ if $x_i>0$, 0 if $x_i=0$, and -1 if $x_i<0$.}, and the second part of equation \ref{eqnPlemEPC2} remains valid when $D$ is replaced with $D'$, which yields
\begin{equation}
\label{eqnPlemEPC3}
H_{J_2}D'\lambda=\|D'\lambda\|_1 \mathbbm{1}_{n_2},\quad \quad \text{with}\quad \quad \|D'\lambda\|_1>0.
\end{equation}
If we set $\lambda'=\frac{\lambda}{\|D'\lambda\|_1}$, then $B\lambda \leq 0$ (by homogeneity) and $\|D'\lambda'\|_1=1$, and thus $\lambda'\in {\cal D}(B,D')$. We now prove that $\lambda'\in \operatorname{extr}({\cal D}(B,D'))$. Suppose that there exist $\alpha\in (0,1)$ and $\lambda_1,\lambda_2\in {\cal D}(B,D')$ such that
\begin{equation}
\label{eqnPlemEPC4}
\lambda'=\alpha \lambda_1+(1-\alpha)\lambda_2.
\end{equation}
For $i\in \{1,2\}$, as $\lambda_i \in {\cal D}(B,D')$, we must have $\|D'\lambda_i\|_1\leq 1$, and since $\|D'\lambda'\|_1=1$, equations \ref{eqnPlemEPC3} and \ref{eqnPlemEPC4} imply that 
\begin{equation}
\label{eqnPlemEPC5}
\|D'\lambda_i\|_1=1,\quad \quad \text{and}\quad \quad H_{J_2}D'\lambda_i=\mathbbm{1}_{n_2}.
\end{equation}
Also, since by homogeneity $B_{J_1}\lambda'=0$, and, for $i\in \{1,2\}$, $B_{J_1}\lambda_i\leq 0$, equation \ref{eqnPlemEPC4} implies that we must have 
\begin{equation}
\label{eqnPlemEPC6}
B_{J_1} \lambda_i=0.
\end{equation}

As in equation~\ref{eqnPlemEPC2}, equation~\ref{eqnPlemEPC5} implies that, for each \( i \in \{1, 2\} \), the entries of the rows of \( H_{J_2} \) coincide when restricted to the indices of columns corresponding to the support of \( D'\lambda_i \), and these entries are equal to the signs of the corresponding elements in \( D'\lambda_i \). That is, for \( i \in \{1, 2\} \), and for any \( j_1, j_2 \in [n_2] \) and \( k \in \operatorname{supp}(D'\lambda_i) \), we have
\begin{equation}
\label{eqnPlemEPC7}
e_{n_2,j_1}^\top H_{J_2} e_{n,k} = e_{n_2,j_2}^\top H_{J_2} e_{n,k}, \quad \text{and} \quad e_{n_2,j_1}^\top H_{J_2} e_{n,k} = \operatorname{sign}(e_{n,k}^\top D'\lambda_i).
\end{equation}
Since $\operatorname{supp}(D\lambda_i)=\operatorname{supp}(D'\lambda_i)$ and $\operatorname{sign}(D\lambda_i)=\operatorname{sign}(D'\lambda_i)$, equation \ref{eqnPlemEPC7} implies that, for $i\in\{1,2\}$, we have
\begin{equation}
\label{eqnPlemEPC8}
H_{J_2}D\lambda_i=\|D\lambda_i\|_1 \mathbbm{1}_{n_2}.
\end{equation}
As the matrix in equation \ref{eqnPlemEPC1} is invertible, equations \ref{eqnPlemEPC6} and \ref{eqnPlemEPC8} imply that $\lambda_i=\|D\lambda_i\|_1\lambda$. thus $\lambda_1,\ \lambda_2$ and $\lambda'$ are all positive scalar multiples of $\lambda$, with $\|D'\lambda_1\|_1=\|D'\lambda_2\|_1=\|D'\lambda'\|_1=1$, which implies that $\lambda'=\lambda_1=\lambda_2$, and $\lambda'\in \operatorname{extr}({\cal D}(B,D'))\backslash\{0\}$.

We have 
\begin{equation*}
\Bigl|1-\frac{1}{\|D'\lambda\|_1}\Bigr|=\Bigl|1-\frac{\|D\lambda\|_1}{\|D'\lambda\|_1}\Bigr|\leq \frac{\|(D'-D)\lambda\|_1}{\|D'\lambda\|_1}\leq (2/\underline{\sigma})\|D-D'\|
\end{equation*}
where we have used the fact that the smallest diagonal entry in the support of $D'$ is bounded below by $2/\underline{\sigma}$ when $\|D-D'\|\leq \underline{\sigma}/2$. This completes the proof of \ref{eqnlemEPC1}.
\end{proof}

\subsection {Appendix B: Auxiliary lemmas}


\begin{lemma}
\label{lem2}


Let  
\[
F, F_n: S\times \Delta \subset \mathbb{R}^d \times \mathbb{R}^p \to \mathbb{R}, \quad n\geq 1,
\]
be a sequence of continuous functions defined on a neighborhood \( S\times \Delta \) of the compact set \( S_0\times \Delta_0 \). Suppose that  
\begin{itemize}
    \item \( F_n \) converges uniformly to \( F \) on \( S \times \Delta \),
    \item \( S_n \times \Delta_n \subset \mathbb{R}^d \times \mathbb{R}^p \) are compact sets satisfying  
    \[
    d_H(S_n, S_0) \to 0, \quad d_H(\Delta_n, \Delta_0) \to 0.
    \]
\end{itemize}  
Then, the minimax values satisfy  
\[
\min_{\theta \in S_n} \max_{\lambda \in \Delta_n} F_n(\theta,\lambda) \to  
\min_{\theta \in S_0} \max_{\lambda \in \Delta_0} F(\theta,\lambda).
\]
\end{lemma}

\begin{proof}[\textbf{Proof of Lemma \ref{lem2}}]
For all sufficiently large n's, as $S$ and $\Delta$ are neighborhoods of $S_0$ and $\Delta_0$, we can assume for simplicity that $S_n\times \Delta_n \subset S\times \Delta$ for all $n\geq 1$, and that $S\times \Delta$ is compact. 
Let $\phi, \phi_n: S \to \mathbb{R}$, for $n\geq 1$, be defined by $\phi_n(\theta)=\max_{\lambda \in \Delta_n}F_n(\theta,\lambda)$ and $\phi(\theta)=\max_{\lambda \in \Delta_0}F(\theta,\lambda)$. Then by the theorem of the maximum, $\phi_ n$ and $\phi$ are continuous. 

\underline{Step 1}We first claim that $\phi_n$ converges uniformly to $\phi$ on $S$. Indeed, as $\phi$ is continuous and $S$ is compact, it suffices to show that \(\lim_{n\to \infty} \phi_n(\theta_n)=\phi(\theta^*)\) whenever $\theta_n \to \theta^*$, $\theta_n,\theta^*\in S$. We establish the latter by showing that every subsequence of $\{\phi_n(\theta_n)\}_{n\geq 1}$ has a further subsequence that converges to $\phi(\theta^*)$. For $\theta \in S$, let $\lambda_n(\theta)$ and $\lambda(\theta)$ be such that by \(\lambda_n(\theta)\in \arg\max_{\lambda \in \Delta_n } F_n(\theta,\lambda) \) and \(\lambda(\theta)\in \arg\max_{\lambda \in \Delta_0 } F(\theta,\lambda) \). Then $\phi_n(\theta_n)=F_n(\theta_n,\lambda_n(\theta_n))$. As $S\times \Delta$ is compact, every subsequence of $\{\phi_n(\theta_n)\}_{n\geq 1}$ has a further subsequence, say $\{\phi_{n_k}(\theta_{n_k})\}_{k\geq 1}$, such that $\lambda_{n_k}(\theta_{n_k}) \to \lambda^*$. By uniform convergence of $F_n$ to $F$ and the continuity of $F$, we have $\phi_{n_k}(\theta_{n_k})= F_{n_k}(\theta_{n_k},\lambda_{n_k}(\theta_{n_k}))\to F(\theta^*,\lambda^*)$. As $d_H(\Delta_n,\Delta_0)\to 0$, we have $\lambda^* \in \Delta_0$. We now show that $F(\theta^*,\lambda^*)=\phi(\theta^*)$. Indeed, for each $\lambda \in \Delta_0$, as $d_H(\Delta_{n_k},\Delta_0)\to 0$ there exists $\lambda_k \in \Delta_{n_k}$ such that $\lambda_k \to \lambda$. Then such $\lambda \in \Delta_0$ we get
\[
F(\theta^*,\lambda)=\lim_{n\to \infty} F_{n_k}(\theta_{n_k},\lambda_k)\leq \lim_{n\to \infty} F_{n_k}(\theta_{n_k},\lambda_{n_k})=F(\theta^*,\lambda^*).
\]
Thus $F(\theta^*,\lambda^*)=\phi(\theta^*)$, and we conclude that $\phi_n(\theta_n)\to \phi(\theta^*)$ and thus $\phi_n$ uniformly converges to $\phi$ on S.

\underline{Step 2} We now show that $\min_{\theta \in S_n} \phi_n(\theta) \to \min_{\theta \in S_0} \phi(\theta)$. Let $\phi_n(\theta_n^*)=\min_{\theta \in S_n} \phi_n(\theta)$, where $\theta_n^* \in S_n$. We establish the claim by showing that every subsequence of $\{\phi_n(\theta_n^*)\}$ has a further subsequence that converges to $\min_{\theta \in S_0} \phi(\theta)$. Indeed, given a subsequence of $\{\phi_n(\theta_n^*)\}$, consider a further subsequence, say $\{\phi_{n_k}(\theta_{n_k}^*)\}_{k\geq 1}$, such  that $\theta_{n_k}^*\to \theta^*$. Then the preceding step implies that $\phi_{n_k}(\theta_{n_k}^*)\to \phi(\theta^*)$. Also, as $d_H(S_n,S_0)\to 0$, we have $\theta^* \in S_0$, and given any $\theta \in S_0$, there exists $\theta_{k}\in S_{n_k}$ such that $\theta_k \to \theta$. Hence for $\theta \in S_0$, we have
\[
\phi(\theta)=\lim_{k\to \infty} \phi_{n_k}(\theta_k)\geq \lim_{k\to \infty} \phi_{n_k}(\theta_{n_k}^*)=\phi(\theta^*).
\]
Thus $\phi(\theta^*)=\min_{\theta \in S_0} \phi(\theta)$ and we conclude that $\phi_n(\theta_n^*) \to \min_{\theta \in S_0} \phi(\theta)$.


\end{proof}


The general form of the following lemma, stated with an implicit constant, is known as Hoffman's Theorem \cite{AH}. Here, we present a proof that includes an explicit constant, as understanding its dependence on the inputs \((A, b, c)\) is crucial for our uniformity results. Our proof modifies the argument in \cite{AH} slightly to obtain an explicit Lipschitz constant. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}[Hoffman's Theorem]
\label{lemhoff}
Consider the polyhedron \(\mathcal{P} = \{z\in \mathbb{R}^n \mid A_E z = b_E, \ A_I z \leq b_I\}\), where \( A_E \in \mathbb{R}^{m_E \times n} \) and \( A_I \in \mathbb{R}^{m_I \times n} \). Then, for all \( x \in \mathbb{R}^n \), we have
\begin{equation}
d(x, \mathcal{P}) \leq C \Bigl(\|A_E x - b_E\| + \|(A_I x - b_I)_+\|\Bigr),
\end{equation}
where the constant \( C \) can be chosen as \( C = \bigl(\Lambda(A)\bigr)^{1/2} \), with \( \Lambda(A) \) defined in Definition \ref{deflambda}.  

Here, \( (x)_{+} \) denotes the positive part of \( x \), obtained by replacing each entry \( x_i \) with \( \max\{x_i, 0\} \), and \( \|\cdot\| \) represents the Euclidean norm in the corresponding space.
\end{lemma}

\begin{proof}[\textbf{Proof of Lemma \ref{lemhoff}}]
Suppose \( x \notin \mathcal{P} \), and let \( y \) be the projection of \( x \) onto \( \mathcal{P} \) with respect to the Euclidean norm. Define \( J \subset I \) as the subset of rows of the matrix \( A_I \) that are active at \( y \). The tangent cone of \( \mathcal{P} \) at \( y \) is given by 
\[
\mathcal{C} = \{z \in \mathbb{R}^n \mid A_E z = 0, \ A_J z \leq 0 \}.
\]
Since \( y \) is the closest point in \( \mathcal{P} \) to \( x \), the first-order optimality condition (FOC) implies that \( \langle x - y, z \rangle \leq 0 \) for all \( z \in \mathcal{C} \). By Farkas' Lemma, there exist vectors \( \lambda_E \) and \( \lambda_J \) with \( \lambda_J \geq 0 \) such that
\[
x - y = A_E^T \lambda_E + A_J^T \lambda_J.
\]

Let \( \tilde{E} \subset E \) be the subset of indices corresponding to nonzero entries of \( \lambda_E \), and define \( \tilde{J} \subset J \) similarly for \( \lambda_J \). By an argument similar to the one used in proving Carath\'eodory’s convex hull theorem, we can choose \( \lambda_E \) and \( \lambda_J \) so that the set of rows of $A_E$ and $A_I$ corresponding to the indices in $F:=\tilde{E}\cup \tilde{J}$, \( \{a_i \mid i \in F\} \), is linearly independent. Set \( \lambda_F = (\lambda_{\tilde{E}}', \lambda_{\tilde{J}}')' \) and \( A_F = (A_{\tilde{E}}', A_{\tilde{J}}')' \). Then, we have
\[
x - y = A_F^T \lambda_F,
\]
where the rows of \( A_F \) are linearly independent.\footnote{Alternatively, we can let $F$ be the support of a \underline{vertex solution} of the dual to the linear program $\max\{\langle x-y,z\rangle \mid A_J z\leq 0, \ A_Ez=0\}$. Note that by assumption, the latter LP has value zero.}

Since \( x \notin \mathcal{P} \), it follows that \( x - y \neq 0 \) and \( x - y \notin \mathcal{C} \) (otherwise, the inequality \( \langle x - y, z \rangle \leq 0 \) for all \( z \in \mathcal{C} \) would imply \( \|x - y\| = 0 \), a contradiction). 

Define the polyhedral cone \( K \) by
\[
K = \{z \in \mathbb{R}^{|F|} \mid z_i = 0 \ \forall i \in \tilde{E}, \ z_j \leq 0 \ \forall j \in \tilde{J} \}.
\]
Setting \( w = x - y \), our goal is to bound \( \|w\| \) in terms of \( d(A_F w, K) \). Let \( \Pi_K \) denote the projection matrix onto \( K \), and define
\[
\delta = A_F w - \eta, \quad \text{where} \quad \eta = \Pi_K(A_F w).
\]
We then obtain
\[
\lambda_F^T \delta = \lambda_F^T A_F w - \lambda_F^T \eta = \lambda_F^T A_F A_F^T \lambda_F - \lambda_F^T \eta.
\]

Since \( \lambda_{\tilde{J}} \geq 0 \) and by the definition of \( K \), we have \( \lambda_F^T \eta \leq 0 \), leading to 
\begin{equation}
\label{2eqn1}
\|A_F^T \lambda_F\|^2 \leq |\lambda_F^T \delta| \Rightarrow (\lambda_{\min}(A_F A_F^T))^{1/2} \|\lambda_F\| \|A_F^T \lambda_F\| \leq \|\lambda_F\| \|\delta\|.
\end{equation}
Using the definition of \( K \), it can be easily verified that \( \eta= (0',- (A_{\tilde{J}} w)'_{-})' \). Consequently, we obtain  
\[
\delta = \bigl((A_{\tilde{E}} w)', (A_{\tilde{J}} w)_{+}'\bigr)',
\]
and \( \|\delta\|^2 = \|A_{\tilde{E}} x - b_{\tilde{E}}\|^2 + \|(A_{\tilde{J}} x - b_{\tilde{J}})_{+}\|^2 \). Since  
\[
\|A_{\tilde{E}} x - b_{\tilde{E}}\|^2 + \|(A_{\tilde{J}} x - b_{\tilde{J}})_{+}\|^2 \leq \|A_E x - b_E\|^2 + \|(A_I x - b_I)_{+}\|^2,
\]  
combining this inequality with the final implication in \eqref{2eqn1}, we conclude that 
\[
d(x, \mathcal{P}) \leq \frac{1}{\sqrt{\lambda_{\min}(A_F A_F^T)}} \Bigl(\|A_E x - b_E\| + \|(A_I x - b_I)_{+}\|\Bigr),
\]
which proves the lemma.
\end{proof}

The following lemma is based on Lemma 2 in \cite{SR2} and establishes that the feasible region ${\cal P}$ is Lipschitz upper hemicontinuous with respect to its inputs if ${\cal P}$ is bounded, and locally Lipschitz upper hemicontinuous otherwise. Throughout this lemma, let $\Lambda(A)$ be as in Definition \ref{deflambda}, and define $b=(b_E',b_I')'$, $A=(A_E',A_I')'$. 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\begin{lemma}[Lipschitz Upper Hemicontinuity]
\label{lemuhc}
Consider the polyhedron  
\[
\mathcal{P} = \{z\in \mathbb{R}^n \mid A_E z = b_E, \ A_I z \leq b_I\},
\]
and let  
\[
\tilde{\mathcal{P}} = \{z\in \mathbb{R}^n \mid \tilde{A}_E z = \tilde{b}_E, \ \tilde{A}_I z \leq \tilde{b}_I\}
\]  
denote a perturbed version of $\mathcal{P}$, obtained by replacing its input parameters $(A, b)$ with $(\tilde{A}, \tilde{b})$.  

If $\tilde{\mathcal{P}}$ is nonempty, then for all $R>0$, we have  \footnote{By convention, the supremum over an empty set is equal to $-\infty$.}
\begin{equation}
\label{eqnuhc1}
\sup_{x \in \tilde{\mathcal{P}},\ \|x\| \leq R}d(x,\mathcal{P})\leq 2(R+1)\Lambda(A)^{-1/2} \Bigl(\|A-\tilde{A}\|+\|b-\tilde{b}\|\Bigr).
\end{equation}
Moreover, if $\mathcal{P}$ is bounded by some $M>0$, i.e.,  
\[
\max_{x\in \mathcal{P}} \|x\| \leq M,
\]  
and the perturbation satisfies  
\[
\|b-\tilde{b}\| \vee \|A-\tilde{A}\| \leq [\Lambda(A)]^{1/2}/4,
\]  
then the set $\tilde{\mathcal{P}}$, if nonempty, remains bounded, with  
\[
\sup_{x\in \tilde{\mathcal{P}}} \|x\| \leq 2M+1,
\]  
and the deviation of points in $\tilde{\mathcal{P}}$ from $\mathcal{P}$ is bounded by  
\begin{equation}
\label{eqnuhc}
\sup_{x\in \tilde{\mathcal{P}}} d(x,\mathcal{P})\leq 2(2M+1)\Lambda(A)^{-1/2} \Bigl(\|A-\tilde{A}\|+\|b-\tilde{b}\|\Bigr).
\end{equation}
\end{lemma}

\begin{proof}[\textbf{Proof of Lemma \ref{lemuhc}}]
Let $x\in \tilde{\mathcal{P}}$. By Lemma \ref{lemhoff}, we have  
\begin{equation}
\label{3eqn1}
d(x,\mathcal{P})\leq (\Lambda(A))^{-1/2}\Bigl(\|A_E x - b_E\| + \|(A_I x - b_I)_+\|\Bigr).
\end{equation}
Since $x\in \tilde{\mathcal{P}}$, it follows that  
\[
A_E x - b_E = (A_E - \tilde{A}_E)x + (\tilde{b}_E - b_E)
\]
and  
\[
A_I x - b_I \leq (A_I - \tilde{A}_I)x + (\tilde{b}_I - b_I).
\]
Substituting these expressions into inequality \eqref{3eqn1}, we obtain  
\begin{equation}
\label{3eqn2}
d(x,\mathcal{P})\leq 2(\Lambda(A))^{-1/2}\Bigl(\|A-\tilde{A}\|\|x\| + \|b-\tilde{b}\|\Bigr)
\end{equation}
which readily yields inequality \ref{eqnuhc1}.
Next, under the assumption that $\sup\{\|x\| \mid x\in {\cal P}\} \leq M$, we have $\|x\|\leq M + d(x,\mathcal{P})$ for any $x$, which combined with inequality \ref{3eqn2} yields   
\[
\|x\|(1 - 2\Lambda(A)^{-1/2} \|A - \tilde{A}\|) \leq 2\Lambda(A)^{-1/2} \|b - \tilde{b}\| + M.
\]
Since the perturbation satisfies  
\[
\|b-\tilde{b}\|\vee \|A-\tilde{A}\|\leq [\Lambda(A)]^{1/2}/4,
\]  
we conclude that $\|x\|\leq2 M+1$. Therefore, $\tilde{\mathcal{P}}$ remains bounded, and we have  
\[
\sup_{x\in \tilde{\mathcal{P}}} \|x\|\leq 2M+1.
\]
Finally, substituting this bound into inequality \eqref{3eqn2} establishes the desired result, completing the proof.
\end{proof}

