The following lemma is a variation on the inequalities in Theorem 1 of \cite{SR1}, adapted to our simpler setting with explicit constants. The explicit dependence of these constants on the inputs is crucial for our uniformity results. 


\begin{lemma}[Lipschitz Lower Hemicontinuity]
\label{lemlhc}
Let \( \mathcal{P} = \{z\in \mathbb{R}^n \mid A_E z = b_E, \ A_I z \leq b_I\} \) be a polyhedron, and assume that \( \|A_I\|\leq M' \) for some \( M' > 0 \). Assume \( A_E \) has full row rank and that there exists \( x_0 \in {\cal P} \) and \( \delta_0 > 0 \) such that \( A_I x_0 + \delta_0 \mathbbm{1} \leq b_I \). Let \( \tilde{{\cal P}} \) be a perturbed version of \( {\cal P} \), and let $M>\|x_0\|$ be a fixed constant. If the perturbation satisfies  
\begin{equation}
\label{condlhc}
\|A-\tilde{A}\|\vee \|b-\tilde{b}\| < \min\Biggl\{ \frac{\lambda_{\min}(A_E A_E^T)^{1/2}}{2}, M', \delta_0 \Bigl[ \frac{1 \wedge \lambda_{\min}(A_E A_E^T)^{1/2} }{3+3M+24(M+1)M'}\Bigr] \Biggr\},
\end{equation}
then  $\tilde{\mathcal{P}}\neq \emptyset$, and we have
\begin{equation}
\label{eqnlhc}
\sup_{x \in {\cal P}, \ \|x\|\leq M} d(x, \tilde{\mathcal{P}}) \leq \Biggl\{ \frac{2M(3+3M+24(M+1)M')}{\delta_0(1 \wedge \lambda_{\min}(A_E A_E^T)^{1/2})} + \frac{2(M+1)}{\sqrt{\lambda_{\min}(A_E A_E^T)}} \Biggr\} \Bigl(\|b - \tilde{b}\| + \|A - \tilde{A}\|\Bigr).
\end{equation}
\end{lemma}

\begin{proof}[\textbf{Proof of Lemma \ref{lemlhc}}]
We proceed in two steps. First, we show that any point in the relative interior of \({\cal P}\) remains close to \(\tilde{\cal P}\) under small perturbations. Second, we extend this result to all points in \({\cal P}\).

\underline{Step 1}: Suppose \( x \in {\cal P} \) is such that $\|x\|\leq M$ and \( \delta\mathbbm{1} + A_Ix \leq b_I \), for some \( \delta_0\geq \delta > 0 \). In addition, assume that condition \ref{condlhc} holds with $\delta_0$ replaced by $\delta$:
\begin{equation}
\label{4eqn3}
\|A-\tilde{A}\|\vee \|b-\tilde{b}\|\leq \min\Bigl\{ \frac{\lambda_{min}(A_EA_E^T)^{1/2}}{2}, M',\delta \bigl[ \frac{1\wedge \lambda_{min}(A_EA_E^T)^{1/2} }{3+3M+24(M+1)M'}\bigr]\Bigr\}.
\end{equation}
Note that such points $x$ exist, as $x_0$ is a candidate.

 By Weyl's inequality,  
\[
\bigl|\lambda_{\min}(A_EA_E^T)^{1/2} - \lambda_{\min}(\tilde{A}_E\tilde{A}_E^T)^{1/2}\bigr| \leq \|A_E - \tilde{A}_E\|.
\]
As condition \ref{4eqn3} ensures \( \|A_E - \tilde{A}_E\| \leq \lambda_{\min}(A_EA_E^T)^{1/2}/2 \), we have \( \lambda_{\min}(\tilde{A}_E\tilde{A}_E^T)^{1/2} \geq \lambda_{\min}(A_EA_E^T)^{1/2}/2 \), implying \( \tilde{A}_E \) has full row rank. The equation \( \tilde{A}_E(x+h) = \tilde{b}_E \), rewritten as  
\[
\tilde{A}_E h = (\tilde{b}_E - b_E) - (\tilde{A}_E - A_E)x,
\]
has a solution \( h \) satisfying  
\[
\|h\| \leq \frac{2}{\sqrt{\lambda_{\min}(A_EA_E^T)}}\bigl(\|b_E - \tilde{b}_E\| + M\|A_E - \tilde{A}_E\|\bigr).
\]
We now show, using condition \ref{4eqn3}, that \( \tilde{A}_I(x+h) \leq \tilde{b}_I \), so \( x+h \in \tilde{\mathcal{P}} \), yielding  
\begin{equation}
\label{4eqn1}
d(x, \tilde{\mathcal{P}}) \leq \|h\|\leq \frac{2(M+1)}{\sqrt{\lambda_{\min}(A_EA_E^T)}}\bigl(\|b_E - \tilde{b}_E\| + \|A_E - \tilde{A}_E\|\bigr).
\end{equation}
Since  
\[
\tilde{A}_I(x+h) \leq \tilde{b}_I+( b_I - \tilde{b}_I) + (\tilde{A}_I - A_I)x + \tilde{A}_Ih -\delta\mathbbm{1},
\]
and condition \ref{4eqn3} ensures  
\[
\|(\tilde{A}_I - A_I)x\| \leq \delta/3, \quad \|\tilde{A}_Ih\| \leq \delta/3, \quad \|\tilde{b}_I - b_I\| \leq \delta/3,
\]
it follows that  
\[
\tilde{A}_I(x+h) \leq  \tilde{b}_I,
\]
thus proving \eqref{4eqn1}.  

\underline{Step 2}: Let \( x \in {\cal P}\cap \{x\mid \|x\|\leq M\} \) be arbitrary. For \( t \in (0,1) \), define  
\[
x_t = tx + (1-t)x_0, \quad \delta_t = (1-t)\delta_0,
\]
where \( x_0 \) and \( \delta_0 \) are as in the statement of the lemma. Then,  
\[
\sup_{x \in {\cal P}, \ \|x\|\leq M}\|x-x_t\|\leq 2M(1-t), \quad A_I x_t + \delta_t \mathbbm{1} \leq b_I.
\]
Thus,  
\begin{align*}
\sup_{x \in {\cal P}, \ \|x\|\leq M} d(x,\tilde{\mathcal{P}}) &\leq \sup_{x \in {\cal P}, \ \|x\|\leq M} d(x, x_t) + \sup_{x \in {\cal P}, \ \|x\|\leq M} d(x_t, \tilde{\mathcal{P}}) \\
&\leq 2M(1-t) + \sup_{x \in {\cal P}, \ \|x\|\leq M} d(x_t, \tilde{\mathcal{P}}).
\end{align*}
If condition \ref{condlhc} holds, there exists \( t^* \in [0,1) \) such that  
\begin{equation}
\label{4eqn4}
\|A - \tilde{A}\| \vee \|b - \tilde{b}\| = \delta_{t^*} \Bigl[ \frac{1 \wedge \lambda_{\min}(A_E A_E^T)^{1/2} }{3+3M + 24(M+1)M'}\Bigr].
\end{equation}
Setting \( \delta = \delta_{t^*} \) in \ref{4eqn3}, inequality \ref{4eqn1} gives  
\begin{equation}
\label{4eqn2}
\sup_{x \in {\cal P}, \ \|x\|\leq M} d(x_t, \tilde{\mathcal{P}}) \leq \frac{2(M+1)}{\sqrt{\lambda_{\min}(A_E A_E^T)}} \bigl(\|b_E - \tilde{b}_E\| + \|A_E - \tilde{A}_E\|\bigr).
\end{equation}
Thus,  
\[
\sup_{x \in {\cal P}, \ \|x\|\leq M} d(x, \tilde{\mathcal{P}}) \leq 2M(1-t^*) + \frac{2(M+1)}{\sqrt{\lambda_{\min}(A_E A_E^T)}} \bigl(\|b_E - \tilde{b}_E\| + \|A_E - \tilde{A}_E\|\bigr).
\]
Substituting \( (1-t^*) \) using \ref{4eqn4} yields  
\[
\sup_{x \in {\cal P}, \ \|x\|\leq M} d(x, \tilde{\mathcal{P}}) \leq \Biggl\{ \frac{2M(3+3M+24(M+1)M')}{\delta_0(1 \wedge \lambda_{\min}(A_E A_E^T)^{1/2})} + \frac{2(M+1)}{\sqrt{\lambda_{\min}(A_E A_E^T)}} \Biggr\} \Bigl(\|b - \tilde{b}\| + \|A - \tilde{A}\|\Bigr),
\]
which completes the proof. 
\end{proof}
