The following lemma is based on parts (a) and (b) of Theorem 1 in \cite{SR2} and provides an alternative characterization of regularity. This alternative characterization will be used in parts to show how to regulararize irregular LPs.
\begin{lemma}[Dual Characterization of Regularity]
\label{lemMFCQ}
Suppose that the primal linear program  \( \min\{c^Tx \mid A_E x = b_E, \ A_I x \leq b_I\} \) is feasible and with finite value. Then, \( \mathcal{P}=\{x\in \mathbb{R}^d \ | \ A_E x = b_E, \ A_I x \leq b_I\} \) satisfies the MFCQ if and only if the set  
\[
\Delta_0 = \arg\max_{\lambda} \Bigl\{ \lambda_E^T b_E + \lambda_I^T b_I \mid \lambda_I \leq 0, \ A_E^T \lambda_E + A_I^T \lambda_I = c \Bigr\}
\]
is bounded.
\end{lemma}
\begin{proof}[\textbf{Proof of Lemma \ref{lemMFCQ}}]

\underline{Necessity}  Suppose, for the sake of contradiction, that $\mathcal{P}$ is regular and $\Delta_0$ is unbounded. Since the MFCQ holds, there exists a point $x_0$ satisfying $A_E x_0 = b_E$ and $A_I x_0 < b_I$. The unboundedness of $\Delta_0$ implies the existence of a nonzero vector $\lambda = (\lambda_E', \lambda_I')' $ such that  

\begin{equation}
\label{5eqn1}
\lambda_I \leq 0, \quad\quad A_E^T \lambda_E + A_I^T \lambda_I = 0, \quad\quad b_I^T \lambda_I + b_E^T \lambda_E = 0.
\end{equation}  

Since the MFCQ ensures that $A_E$ has full row rank, we cannot have $\lambda_I = 0$ in \eqref{5eqn1}. Consequently, the choice of $\lambda$ in \eqref{5eqn1} leads to  

\[
\langle \lambda_E, A_E x_0 \rangle + \langle \lambda_I, A_I x_0 \rangle > \langle \lambda_E, b_E \rangle + \langle \lambda_I, b_I \rangle.
\]  

This results in $0 > 0$, a contradiction.  


\underline{Sufficiency}  Suppose, for the sake of contradiction, that $\Delta_0$ is bounded but the MFCQ does not hold. The failure of MFCQ implies the existence of a sequence of perturbations $b_n \to b$ (where only the $b$-vector is perturbed) such that  

\begin{equation}
\label{5eqn2}
\mathcal{P}_n = \{ x \in \mathbb{R}^d \mid A_E x = b_{n,E}, \ A_I x \leq b_{n,I} \} = \emptyset.
\end{equation}  

By assumption, since the value of the unperturbed program is finite, the set  
\[
\{\lambda \mid \lambda_I \leq 0, \ A_E^T \lambda_E + A_I^T \lambda_I = c \}
\]  
is nonempty. Moreover, \eqref{5eqn2} implies that the corresponding perturbed dual programs are unbounded:  

\[
\max_{\lambda} \Bigl\{ \lambda_E^T b_{n,E} + \lambda_I^T b_{n,I} \mid \lambda_I \leq 0, \ A_E^T \lambda_E + A_I^T \lambda_I = c \Bigr\} = +\infty, \quad \forall n \geq 1.
\]  

This implies the existence of an unbounded sequence $\{\lambda_n\}$ such that  

\[
\lambda_n^T b_n \to +\infty, \quad\quad \lambda_{n,I} \leq 0, \quad\quad A_E^T \lambda_{n,E} + A_I^T \lambda_{n,I} = c.
\]  

Dividing through by $\|\lambda_n\|$ and considering a limit $\lambda^* \neq 0$ of a convergent subsequence of $\{\lambda_n / \|\lambda_n\|\}_{n \geq 1}$, we obtain  

\[
\langle \lambda^*, b \rangle \geq 0, \quad\quad \lambda_I^* \leq 0, \quad\quad A_E^T \lambda_E^* + A_I^T \lambda_I^* = 0.
\]  

However, if $\lambda \in \Delta_0$, then for any $t > 0$, the vector $\lambda + t \lambda^*$ also belongs to $\Delta_0$, contradicting the assumption that $\Delta_0$ is bounded. This contradiction completes the proof.  
\end{proof}

