\section{Definitions, Notation and Background}




\begin{definition} Let $X$ be a compact metric space. We use $d$ or $\rho$ to denote the metric on $X$, unless otherwise specified. We use $\mathbb{N}$ to denote the positive integers; $\mathbb{N}_0$ to denote the nonnegative integers; and $\mathbb{Z}$ to denote the integers.


\end{definition}



\vphantom{}



\begin{definition} A \emph{continuum} is a nonempty compact connected metric space. A continuum is \emph{degenerate} if it consists of exactly one point. Otherwise it is \emph{nondegenerate}. A subspace of a continuum which is itself a continuum is a \emph{subcontinuum}. 

\end{definition}


\vphantom{}

\begin{definition} Let $X$ and $Y$ be metric spaces, and let $f:X \to Y$ be a function. We use $\Gamma(F)= \{(x,y): y=f(x) \}$ to denote the \emph{graph of the function} $f$.

\end{definition}


\vphantom{}

 \begin{definition}
 Let $X$ be a compact metric space and let $G \subset X \times X$ be a relation on $X$. If $G$ is closed in $X \times X$, then $G$ is a \emph{closed relation on} $X$.  
 \end{definition}

\vphantom{}

\begin{definition} Let $X$ be a set and let $G$ be a relation on $X$. Then we define $G^{-1}=\{ (y,x): (x,y) \in G \}$. Also, $G^{-1}$ is the \emph{inverse relation of the relation $G$ on} $X$.

\end{definition}



\vphantom{}


\begin{definition} Let $X$ be a compact metric space and let $G$ be a closed relation on $X$. 

\begin{itemize}
\item  We define the \emph{Mahavier product} $G \star 
G$ as  $\{(x,y,z): (x,y) \in G, (y,z) \in G\}$. If $\mathbf{a}=(x,y) \in G$  and $\mathbf{b}=(y,z) \in G$, then we define $\mathbf{a} \star \mathbf{b}$ to be the point $\mathbf{a} \star \mathbf{b}=(x,y,z) \in G \star G$.

\item If $m$ is a positive integer, we define the $mth$ \emph{Mahavier product} $\star_{i=1}^m G$ to be 
$\star_{i=1}^m G = \{(x_1,x_2, \ldots, x_{m+1}) \in \Pi_{i=1}^{m+1} X: \text{ for each } i \in \{1,2,\ldots,m\} \}, (x_i,x_{i+1}) \in G \}.$ We abbreviate $\star_{i=1}^m G$ by $X_G^m$.
\item We define the  \emph{infinite Mahavier product} $\star_{i=1}^{\infty} G$ to be \newline 
$\star_{i=1}^{\infty} G = \{(x_1,x_2, \ldots) \in \Pi_{i=1}^{\infty} X: \text{ for each positive integer } i, (x_i,x_{i+1}) \in G \}.$ We abbreviate $\star_{i=1}^{\infty} G$ by $X_G^+$.

\item We define the function $$\sigma_G^+: X_G^+ \to X_G^+$$ given by $$\sigma_G^+(x_1,x_2, \ldots) = (x_2,x_3, \ldots)$$ for each 
$(x_1,x_2, \ldots) \in X_G^+$. The map $\sigma_G^+$ is called the \emph{shift map on} $X_G^+$, and it is a continuous function. (To see this, observe that $X_G^+$ is invariant under the shift $\sigma$ on $\Pi_{i=1}^{\infty} X$ defined by $\sigma(x_1,x_2, \dots)=(x_2,x_3, \dots)$ for $(x_1,x_2,\dots) \in \Pi_{i=1}^{\infty} X$. Since $\sigma$ is continuous, so is $\sigma|X_G^+ = \sigma_G^+$.)
\end{itemize}

\end{definition}

\vphantom{}

\begin{definition}(\emph{The standard projection} $\pi_i$.) Suppose $X$ is a space. If $n$ is a positive integer, and $\mathbf{x}=(x_1,x_2, \ldots, x_n) \in X^n$, then $\pi_i(\mathbf{x}) = x_i$ for $i \in \{1,2,\dots,n\}$. If $\mathbf{x}=(x_1,x_2, \ldots) \in X^{\infty}$, then $\pi_i(\mathbf{x}) = x_i$ for $i$ each positive integer $i$. If $m \le n$, $m$ and $n$ are integers, we use $[m,n]$ to denote the set $\{m,m+1,\ldots,n\}$ and refer to $[m,n]$ as an integer interval (if no confusion arises). Also, if $\mathbf{x}=(x_1,x_2,\dots)$, then $\pi_{[m,n]}(\mathbf{x})=(x_m,x_{m+1},\ldots, x_n)$, when $0 <m \le n$, $m,n$ integers.

\end{definition}


\vphantom{}

\begin{definition} If $K \subset X^n$ for some positive integer $n$, then the set $K^{-1}$ is defined to be the set $$K^{-1} = \{(x_n,x_{n-1}, \ldots, x_1): (x_1, x_2, \dots, x_n) \in K \}.$$ We call $K^{-1}$ the \emph{inverse} of the set $K$.

\end{definition}


\vphantom{}


\begin{definition} Suppose $X$ is a compact metric space and $f:X \to X$ is continuous. Then $(X,f)$, or just $f$ when there is no confusion, is a \emph{dynamical system}.

\end{definition}


\vphantom{}

\begin{definition} A dynamical system $(X,f)$ is \emph{turbulent} if there are nonempty closed sets $K$ and $L$ in $X$ such that $K \cap L$ contains at most one point and $K \cup L \subset f(K) \cap f(L)$.

\end{definition}




\vphantom{}


\begin{definition} A dynamical system $(X,f)$ is \emph{separated turbulent} if there are disjoint nonempty closed sets $K$ and $L$ in $X$ such that $K \cup L \subset f(K) \cap f(L)$.

\end{definition}


\vphantom{}

\begin{definition} Suppose $n$ is a positive integer. A dynamical system $(X,f)$ is  \emph{ $n$-turbulent}  if  
$(X,f^n)$ is turbulent.

\end{definition}


\vphantom{}

\begin{definition} A dynamical system $(X,f)$ is  \emph{ separated $n$-turbulent}  if  
$(X,f^n)$ is separated turbulent.
\end{definition}

\vphantom{}


\begin{prop} Suppose $X$ is a space and $f:X \to X$ is a function. Disjoint nonempty closed sets $K_0$ and $K_1$ in $X$ have the property that $K_0 \cup K_1 \subset f(K_0) \cap f(K_1)$ if and only if for each sequence $i_0,i_1, \ldots$ of $0$'s and $1$'s, $K_{i_0} \subset f(K_{i_1}) \subset f^2(K_{i_2}) \subset \cdots$.

\end{prop}

\vphantom{}

\begin{definition} A closed relation $F \subset X \times X$ is \emph{CR-turbulent} if there are $n \in \mathbb{N}$ and two disjoint nonempty closed sets $K$ and $L$ in $X_{F}^{n}$  such that $\pi_1(K) \cup \pi_1(L) \subset \pi_n(K) \cap \pi_n(L)$.
	\end{definition}



\vphantom{}

\begin{definition} A closed relation $F \subset X \times X$ is \emph{reverse CR-turbulent} if there are $n \in \mathbb{N}$ and two disjoint nonempty closed sets $K$ and $L$  in $X_F^{n}$ such that $\pi_n(K) \cup \pi_n(L) \subset \pi_1(K) \cap \pi_1(L)$.


\end{definition}


\vphantom{}

Since fans and topological entropy appear later in the paper, we give a brief, basic discussion of these terms here. More details appear later, as they are needed.


\subsection{Fans} 

At first glance, fans seem deceptively simple. Their structure - arcs radiating from a single point - makes them feel intuitively easy to understand. However, the formal definition of a fan is surprisingly intricate, and this complexity is not accidental. It reflects the need to precisely capture subtle topological properties that arise in these spaces.

\vphantom{}

To illustrate this, consider the following open question:
Is every compact metric space X satisfying the conditions below necessarily a fan?

\begin{enumerate}
\item	$X$ is one-dimensional;
\item	There exists a point $v \in X$ and a family $\mathcal{F}$ of arcs in $X$ such that:

\begin{enumerate}
\item For any distinct $A, B \in \mathcal{F}$, we have $A \cap B = \{v\}$;
\item $X = \bigcup \{ F : F \in \mathcal{F} \}$.

\end{enumerate}

\end{enumerate}

\vphantom{}

Intuitively, such a space looks like a fan - a union of arcs joined only at a common point - but whether it satisfies the formal definition remains an open problem. 

\begin{definition}
Let $X$ be a continuum. 
\begin{enumerate}
\item The continuum $X$ is \emph{unicoherent} if for any subcontinua $A$ and $B$ of $X$ such that $X=A\cup B$,  the compactum $A\cap B$ is connected. 
\item The continuum $X$ is \emph{hereditarily unicoherent } provided that each of its subcontinua is unicoherent.
\item The continuum $X$ is a \emph{dendroid} if it is an arcwise connected, hereditarily unicoherent continuum
\item  Let $X$ be a dendroid.  A point $x\in X$ is called an \emph{end-point of $X$} if for  every arc $A$ in $X$ that contains $x$, $x$ is an end-point of $A$.  The set of all end-points of $X$ is denoted by $E(X)$.  
\item The continuum $X$ is \emph{a simple triod} if it is homeomorphic to $([-1,1]\times \{0\})\cup (\{0\}\times [0,1])$.
\item Let $X$ be a simple triod. A point $x\in X$ is called \emph{the top-point} or, briefly, the \emph{top of $X$} if  there is a homeomorphism $\varphi:([-1,1]\times \{0\})\cup (\{0\}\times [0,1])\rightarrow X$ such that $\varphi(0,0)=x$.
\item Let $X$ be a dendroid.  A point $x\in X$ is called \emph{a ramification-point of $X$}, if there is a simple triod $T$ in $X$ with top $x$.  The set of all ramification-points of $X$ is denoted by $R(X)$. 
\item The continuum $X$ is a \emph{fan} if it is a dendroid with at most one ramification point $v$, which is called the \emph{top} of the fan $X$ (if it exists).
\item  Let $X$ be a fan.  We say that $X$ is \emph{a Cantor fan} if $X$ is homeomorphic to the continuum $\bigcup_{c\in C}A_c$, where $C\subseteq [0,1]$ is the standard Cantor set and for each $c\in C$, $A_c$ is the  {convex} segment in the plane from $(0,0)$ to $(c,1)$.
\item A fan $X$ is a \emph{smooth} fan if it can be embedded in the Cantor fan.
\item A \emph{Lelek fan} is a smooth fan that has a dense set of endpoints. It is known that Lelek fans are unique (see \cite{oversteegen} and \cite{jjc1}), i.e., any two Lelek fans are homeomorphic.
\end{enumerate}	
\end{definition}

\subsection{Topological entropy}

Topological entropy, or simply entropy as used here, is a fundamental but often nonintuitive concept in dynamical systems. For a continuous function from a compact metric space to itself, topological entropy is either a non-negative number or $\infty$. Roughly speaking, it quantifies the rate at which distinct orbits of the function become increasingly distinguishable over time - essentially, how much the function “mixes up” points in the space. Though defined globally, entropy often reflects highly local dynamical complexity, making it a subtle but powerful invariant.

\vphantom{}

Topological entropy has been extensively studied across many areas of mathematics as a rigorous measure of ``chaotic'' behavior. In this paper, we adopt the definition originally introduced by Adler, Konheim, and McAndrew, presented clearly in Chapter 7 of Peter Walters’ book \cite{Walters book}. While several equivalent formulations exist, they all yield the same numerical value for a given system, assuming the same logarithm base is used.

 \begin{definition}
Let $X$ be a set,  let $f:X\rightarrow X$ be a function and let $\mathcal S$ be a family of subsets of $X$. Then we define
$$
f^{-1}(\mathcal S)=\{f^{-1}(S) \ | \ S\in \mathcal S\}.
$$
\end{definition}

\begin{definition}
Let $X$ be a set and let $\mathcal A_1$, $\mathcal A_2$, $\mathcal A_3$, $\ldots$, $\mathcal A_m$ be families of subsets of $X$.  Then we define
$$
\vee_{i=1}^{m}\mathcal A_i=\{A_1\cap A_2\cap A_3\cap \ldots \cap A_m \ | \ \textup{ for each } i\in \{1,2,3,\ldots ,m\}, A_i\in \mathcal A_i\}.
$$
\end{definition}
\begin{definition}
Let $X$ be a compact metric space and let $f:X\rightarrow X$ be a continuous function. For any open cover $\alpha$ for $X$, we define
$$
ent(f,\alpha)=\lim_{m\to\infty}\frac{\log(N(\vee_{i=0}^{m}f^{-i}(\alpha)))}{m}.
$$

\end{definition}

\begin{definition}
Let $X$ be a compact metric space and let $f:X\rightarrow X$ be a continuous function. We define the \emph{topological entropy} $ent(f)$ to be
$$
ent(f) = \mbox{  } \sup_{\alpha} \medspace ent(f,\alpha)
$$
where $\alpha$ ranges over all open covers of $X$.

\end{definition}




