 \section{Turbulence and CR-turbulence}
In this section, we address whether every turbulent dynamical system is also separated  $n$-turbulent for some $n \in \mathbb{N}$, and explore the relationship between a closed relation $F$ on a compact metric space $X$ with CR-turbulence and the various turbulence properties of the shift map $\sigma_F^+$ on the infinite Mahavier product $X_F^+$. We begin the section by giving a result about the relationship of CR-turbulence for a closed relation and separated turbulence for a shift map on the Mahavier product determined by that relation.

\vphantom{}

\begin{theorem}

A closed relation of $F \subset X \times X$ is CR-turbulent if and only if there is an $n \in \mathbb{N}$, $n \ge 2$, such that $(X_F, (\sigma_F^+)^{n-1})$ is separated turbulent.

\end{theorem} 

\begin{proof}  
 %$\sigma^n(\mathbf{x})=(x_n,x_{n+1}, \ldots)$. 


Assume the relation $F\subset X \times X$ is CR-turbulent. Then there is an $n \in \mathbb{N}$ and there are disjoint nonempty closed sets $K_0$ and $K_1$ in $X^n_F \subset X^{n+1}$ such that $\pi_1(K_0) \cup \pi_1(K_1) \subset \pi_n(K_0) \cap \pi_n(K_1)$. For each $i \in \mathbb{N}$, let $r(i)=[(i-1)(n-1)+1,i(n-1)+1]$.

\vphantom{}

We use $\Sigma_2$ to denote the collection of all sequences $\alpha= \alpha_1, \alpha_2, \ldots$ such that $\alpha_n \in \{0,1\}$ for each positive integer $n$. Let $\alpha \in \Sigma_2$ and for each $j \in \mathbb{N}$, define 
$$ M_{j,\alpha} = \{ \mathbf{x} \in X^{\infty}: \text{ for each } 1\le i \le j, \pi_{r(i)}(\mathbf{x}) \in K_{\alpha(i)} \}. $$

We show that for each $j \in \mathbb{N}$ and each $\alpha \in \Sigma_2$, $M_{j,\alpha}$ is a nonempty closed set. The proof is by induction on $j$: If $j=1$, then $M_{1,\alpha}= \{\mathbf{x} \in X^{\infty}:\pi_{[1,n]}(\mathbf{x}) \in K_{\alpha(1)} \}$, which is closed and nonempty whether $\alpha(1) =0$ or $\alpha(1) =1$. Now assume $l \in \mathbb{N}$ and $l >1$, and $M_{l-1,\alpha} \neq \emptyset$ for all $\alpha \in \Sigma_2$. Choose $\alpha \in \Sigma_2$ and let $\alpha ' \in \Sigma_2$ such that $\alpha '(i)=\alpha(i+1)$ for each $i \in \mathbb{N}$. Let $\mathbf{x} \in M_{l-1,\alpha'}$.  Since $\pi_1(\mathbf{x}) \in \pi_1(K_0) \cup \pi_1(K_1) \subset \pi_n(K_0) \cap \pi_n(K_1)$, there is a $\mathbf{y} \in K_{\alpha(1)}$ such that $\pi_n(\mathbf{y})=\pi_1(\mathbf{x})$. It follows that $\mathbf{y} \star \mathbf{x} \in M_{l,\alpha}$. So $M_{j,\alpha} \neq \emptyset$ for each $j \in \mathbb{N}$.



\vphantom{}

Clearly, $M_{j+1,\alpha} \subset M_{j,\alpha}$ for each $j \in \mathbb{N}$. So, since $X^{\infty}$ is compact, $\cap_{j=1}^{\infty} M_{j,\alpha} \neq \emptyset$. Let $M_{\alpha} = \cap_{j=1}^{\infty} M_{j,\alpha}$. Note that $M_{\alpha} \subset X_F^+$ for each $\alpha \in \Sigma_2$. Let $M=\cup_{\alpha \in \Sigma_2} M_{\alpha}$, let $K_0^*=\{\mathbf{x} \in M: \pi_{[1,n]} \in K_0 \}$ and let $K_1^*=\{\mathbf{x} \in M: \pi_{[1,n]} \in K_1 \}$. Then $K_0^*$ and $K_1^*$ are nonempty closed sets in $X_F^+$ such that $(\sigma_F^+)^{n-1}(K_1^*)=(\sigma_F^+)^{n-1}(K_0^*)=M$ and $K_0^* \cup K_1^* \subset M$. So $(\sigma_F^+)^{n-1}$ is separated turbulent.

\vphantom{}

Next assume $n\in \mathbb{N}$, $n>1$, and $(\sigma_F^+)^{n-1}:X_F^+ \to X_F^+$ is separated turbulent. Let $K_0$ and $K_1$ be nonempty disjoint closed subsets of $X_F^+$ such that $K_0 \cup K_1 \subset (\sigma_F^+)^{n-1}(K_0) \cap (\sigma_F^+)^{n-1}(K_1)$. Let $m \in \mathbb{N}$ such that for each $l \ge m$, $\pi_{[1,l]}(K_0) \cap \pi_{[1,l]}(K_1)= \emptyset$.

\vphantom{}

Note that $K_0 \cup K_1 \subset (\sigma_F^+)^{n-1}(K_0) \cap (\sigma_F^+)^{n-1}(K_1)$ implies that $K_0 \cup K_1 \subset (\sigma_F^+)^{n-1}(K_0 \cup K_1)  \subset (\sigma_F^+)^{n-1}(K_0) \cup (\sigma_F^+)^{n-1}(K_1) \subset (\sigma_F^+)^{n-1}((\sigma_F^+)^{n-1})(K_0) \cup (\sigma_F^+)^{n-1}(K_1)) \subset (\sigma_F^+)^{2n-2}(K_0) \cup (\sigma_F^+)^{2n-2}$ and, in general, for each $i \ge 1$ $K_0 \cup K_1 \subset (\sigma_F^+)^{in-i}(K_0)\cup (\sigma_F^+)^{in-i}(K_1)$. So, if $in-i \ge m$, then $\pi_{[1,in-i+1]}(K_0)$ and $\pi_{[0,in-i+1]}(K_1)$ are disjoint nonempty closed subsets of $X_F^{in-i}$. Let $A_0=\pi_{[1,in-i+1]}(K_0)$ and $A_1=\pi_{[1,in-i+1]}(K_1)$. Then $A_0$ and $A_1$ are nonempty disjoint closed sets in $X_F^{in-i}$ and $\pi_1(A_0) \cup \pi_1(A_1) \subset \pi_{in-i+1}(A_0) \cap \pi_{in-i+1}(A_1)$. Thus $F$ is CR-turbulent.

\end{proof}

 \vphantom{}

 It is known that if $X$ is a compact metric space and $f:X \to X$ is a function on $X$ such that $f^n$ is separated turbulent for some $n$, then $ent(f)>0$. See Block and Coppel \cite{BlockCoppel}, p. 128. It is also easy to see that if $F$ is a CR-turbulent relation on $X$, then $\sigma_F^+:X_F^+ \to X_F^+$ is CR-turbulent, so that $ent(\sigma_F^+)>0$, by noting that, from the proof of the previous theorem, we have $M= \cup_{\alpha \in \Sigma_2} M_{\alpha}$, $(\sigma_F^+)^{n-1}(M)=M$ and $M_{\alpha} \cap M_{\beta} =
 \emptyset $ for $\alpha,\beta \in \Sigma_2$ and $\alpha \ne \beta$. If we define $h:M \to \Sigma_2$ by $h(\mathbf{x})=\alpha$ if and only if $\mathbf{x} \in M_{\alpha}$, then $h \circ (\sigma_F^+)^{n-1}|_M=\sigma_{\Sigma_2} \circ h$. Thus, $\sigma_{\Sigma_2}$ is a factor of $(\sigma^+)^{n-1}|_M$. From this it follows that $ent(\sigma_F^+) >0$. Thus, we have the following result:

 \vphantom{}

 \begin{theorem} 
 If $X_F^n$ contains two disjoint continua $K$ and $L$ such that $\pi_1(K) \cup \pi_1(L) \subset \pi_n(K) \cap \pi_n(L)$ (i.e., $F$ is CR-turbulent), then $ent(\sigma_F^+)>0$. 

\end{theorem} 



\vphantom{}





\begin{exam} %Chris' NEW EXAMPLE

We know $f:X \to X$ is turbulent implies $f^n:X \to X$ is turbulent (for $n \in \mathbb{N}$). It is natural to wonder whether there is an example of a continuous $f:X \to X$ such that $f^2$ is turbulent but $f$ is not. 

Let $T:[0,1] \to [0,1]$ be the standard tent map defined by 
\[
T(x)= 
\begin{cases}
2x & \text{if } 0 \le x \le 1/2, \\
2-2x & \text{if } 1/2 \le x \le 1. \\

\end{cases} 
\]

Define $f:\{0,1, \dots,n-1 \} \times [0,1] \to \{0,1, \dots,n-1 \} \times [0,1]$ by

\[
F(k,x)=
\begin{cases}
(1,T(x)) & \text{if } k=0, \\
((k+1)\mod n,x) & \text{if } k \ne 0. \\

\end{cases}
\]
The function $f$ is $n$-turbulent, but not $m$-turbulent for $m < n$. Moreover, if we identify $\{0,1, \dots ,n-1\} \times \{0 \}$, then we get this result on the $n$-od. (See Figures 1 and 2.)





