The following theorem gives an easy-to-check condition for when a closed relation induces separated turbulence for the second iterate of the shift $\sigma^2$.

\vphantom{}

 \begin{theorem}
 If $X$ is a compact metric space and $F \subset X \times X$ is a closed relation such that $F$ contains closed sets $K$ and $L$ with $\pi_1(K)=\pi_1(L)=X$ and $\pi_1(K \cap L) \cap\pi_2(K \cap L) = \emptyset$, then $\sigma^2_{F^{-1}}$ is separated turbulent.
 \end{theorem}  
 \begin{proof}
 If $(x,y,z) \in (K \star K) \cap (L \star L)$, then $y \in \pi_2(K) \cap \pi_2(L)$ and $y \in \pi_1(K) \cap \pi_1(L)$. So $(x,y) \in K \cap L$ and $(y,z) \in K \cap L$, and it follows that $y \in \pi_2(K \cap L) \cap \pi_1(K \cap L),$ which is a contradiction. Then $K \star K$ and $L \star L$ are disjoint closed sets in $X^3_F$. Now $\pi_1(K \star K)=X$, because if $x \in X$, there is $y$ such that $(x,y) \in K$, which implies that $y \in \pi_2(K) \subset X$, and there is some $z$ such that $(y,z) \in K$. Then $(x,y,z) \in K \star K$ and $x \in \pi_1(K \star K)$. Likewise, $X= \pi_1(L \star L)$. Then, since $\pi_3(K \star K) \subset \pi_1(K \star K)=X$ and $\pi_3(L \star L) \subset \pi_1(L \star L)=X$, $F$ is reverse CR-turbulent for $n=3$, so $F^{-1}$ is CR-turbulent for $n=3$, and the result follows. 
 \end{proof}

 \vphantom{}

 If $f:I \to I$ is continuous, then turbulence implies separated 2-turbulence. We don't know if this is true for compact metric spaces, but we do have the following theorem whose proof is similar to that of Theorem 3.5.

 \vphantom{}

 \begin{theorem}
Suppose $X$ is a compact metric space, and $f:X \to X$ is turbulent with $K_0$ and $K_1$ nonempty closed subsets of $X$ such that $K_0 \cap K_1 = \{ x \}$ for some point $x \in X$, and $K_0 \cup K_1 \subset f(K_0) \cap f(K_1)$. Then if $f(x) \neq x$, $f$ is separated 2-turbulent.
\end{theorem}

\begin{proof}
Suppose $f:X \to X$ is a continuous function on a compact metric space $X$, and there are closed sets $K_0,K_1 \subset X$ and $x \in X$ such that $K_0 \cap K_1= \{x \}$ and $K_0 \cup K_1 \subset f(K_0) \cap f(K_1) $ and $f(x) \ne x$. Let $K_0' = K_0 \cap f^{-1}(K_0)$, $K_1' =	K_1 \cap f^{-1}(K_1)$. Note that $K_0'$ and $K_1'$ are closed subsets of $X$. If $K_0' \cap K_1' \ne \emptyset$, then, since $K_0' \subset K_0$ and $K_1' \subset K_1$, $K_0' \cap K_1' =\{x\}$. Thus $x \in f^{-1}(K_0)$ and $x \in f^{-1}(K_1)$, so $f(x) \in K_0 \cap K_1= \{x\}$. But $f(x) \ne x$, so $K_0' \cap K_1' = \emptyset$. If $y \in K_0$, there is $z \in K_0$ such that $f(z)=y$. So $z \in K_0'$ and $f(z)=y$. Thus, $K_0 \subset f(K_0') \subset K_0$ and $f(K_0')=K_0$. Similarly, $f(K_1')=K_1$. It follows that $K_0' \cup K_1' \subset f^2(K_0') \cap f^2(K_1')$. That is, $f$ is $2$-separated turbulent. 
\end{proof}


