 \section{Dynamics on finite closed relations}


We use the following theorem from \cite{van}:

\begin{theorem} (This is Theorem 5.6 in \cite{van}.) Let $X$ be a non-empty compact metric space and let $F$ be a finite subset of $X \times X$. The following statements are equivalent.
\begin{enumerate}
	\item $ent(F) \ne 0$.
	\item There are a set $A \subset X$, a positive integer $k$, and an $\epsilon >0$ such that $F$ has a $(k,\epsilon)$-return on $A$. (We do not use this part of the theorem and so do not define the term $(k,\epsilon)$-return.)
	\item There are \begin{enumerate} 
	\item positive integers $k_x$ and $k_y$, 
	\item points $\mathbf{x} \in X_F^{k_x}$ and $\mathbf{y} \in X_F^{k_y}$ such that $\mathbf{x}(k_x) = \mathbf{x}(0)=\mathbf{y}(0)=\mathbf{y}(k_y),$
	\item a positive integer $j$ such that $0 < j \le \min{k_x,k_y}$ and $\mathbf{x}(j)\ne \mathbf{y}(j)$. \end{enumerate}
	\item $X_F^+$ is uncountable.


\end{enumerate}	
\end{theorem}

\vphantom{}

Now assume $ent(F) >0$. Switching to the notation in this paper, part (3) becomes the following: There are (a) positive integers $n_x$ and $n_y$, (b) points $\mathbf{x} \in X_F^{n_x}$ and $\mathbf{y} \in X_F^{n_y}$ such that $\mathbf{x}_{n_x} =\mathbf{x}_{1}=\mathbf{y}_{1} =\textbf{y}_{n_y}$, and (c) a positive integer $1 <j \le \min{n_x,n_y}$ and $\mathbf{x}_{j} \ne \mathbf{y}_{j}$. Let $A=\{\mathbf{x} \star \mathbf{y} \}$ and let $B=\{ \mathbf{y} \star \mathbf{x} \}$. Then $A$ and $B$ are closed subsets of $X_F^{n_x +n_y -1} $ such that $A \cap B = \emptyset$, and 
$$\pi_1(A)=\pi_2(B) = \{\mathbf{x}_1 \}= \{ \mathbf{y}_1 = \pi_{n_x+n_y -1}(A) = \{\pi_{n_x}(\mathbf{x}) \} = \{ \pi_{n_y}(\mathbf{y}) \} = \pi_{n_x + n_y -1}(B).$$ Thus, $\pi_1(A) \cup \pi_1(B) \subseteq \pi_{n_x+n_y -1}(A) \cap \pi_{n_x+n_y-1}(B)$. It follows that $F$ is CR-turbulent. This proves that part(4) of the theorem below implies part(1). 

\vphantom{}
\begin{theorem}
If $x$ is a compact metric space and $F$ is a finite subset of $X \times X$, 
%such that $p_1(F) \subset p_1(F) $
 then the following are equivalent: \begin{enumerate}
\item $F$ is CR-turbulent.
\item There is some $n \in \mathbb{N}$ such that $(\sigma^+_F)^+$ is separated turbulent.
\item There are some $n \in \mathbb{N}$ and two points $\mathbf{x}$ and $\mathbf{y}$ in $X_F^n$ such that $\mathbf{x} \neq \mathbf{y}$ and $\pi_1(\mathbf{x})=\pi_1(\mathbf{y})=
\pi_n(\mathbf{x})=\pi_n(\mathbf{y})$.

\item $ent(\sigma_F^+) \neq 0$.
\item $X_F^+$ is uncountable. 
\item $(X_F,\sigma_F^+)$ is Li-Yorke chaotic.
\item $(X_F,\sigma_F^+)$ has a DC2-scrambled Cantor set.


\end{enumerate}
\end{theorem}

\begin{proof} That (1) is equivalent to (2) is proved Theorem 3.1. In the theorem from \cite{van} above,  it is shown that (3) - (7) are equivalent (Theorem 5.7 in \cite{van} and Corollary 7 in \cite{van}.) Clearly, (3) implies (1). Hence, all the statements are equivalent.

\end{proof} 


