\section{Closed relations that are neither CR-turbulent nor reverse CR-turbulent but do have positive entropy}

%[Examples to include homeomorphisms and closed relations with positive entropy and closed relations below or above the diagonal. This is how we get an example of $F \subset I^2$ that is not CR-turbulent, $\pi_1(F)=\pi_2(F) =[0,1]$ and $ent(F) >0$.]

Results of M. Misiurewicz, in \cite{Misiurewicz}, imply that a continuous map $f$ on a closed interval has positive topological entropy if and only if $f^n$  separated turbulent for some $n$. This gives rise to the following question.

\vphantom{}

\textbf{Question.} If $F \subset [0,1]^2$ is a closed relation that is the union of the graphs of two continuous functions defined on $[0,1]$, does $ent(F)>0$ imply that $F$ is CR-turbulent or reverse CR-turbulent?

\vphantom{}

Below we give some results to this question and related examples.


\vphantom{}

\begin{lemma} Suppose $X$ is a compact metric space and $G$ is a closed subset of $X \times X$ and $a,b \in X$ such that $a \ne b$ and 
\begin{enumerate}
\item if $(x,a) \in G$, then $x=a$;
\item if $(b,x) \in G$, then $x=b$; and 
\item if $(s,u)\in G$ and $(t,u) \in G$ and $s \ne t$,	then $\{s,t,u\} \cap \{a,b\} \ne \emptyset$.
\end{enumerate} 
 Then $G$ is not CR-turbulent.


\end{lemma}

\begin{proof} Suppose $A$ and $B$ are nonempty disjoint closed sets in $X_G^+$ and $n \in \mathbb{N}$ such that $A \cup B \subset (\sigma^+_G)^n(A) \cap (\sigma^+_G)^n(B)$. Let $\mathbf{z} \in A$. Then there is $\mathbf{x} \in A$ and there is $\mathbf{y} \in B$ such that $(\sigma^+_G)^n(\mathbf{x})=(\sigma^+_G)^n(\mathbf{y})=\mathbf{z}$. But if there is $i \in \mathbb{N}$ such that $z_i=a$, then $x_j=y_j=a$ for each $j \le i$. So $\mathbf{x}=\mathbf{y}$. It follows that for each $\mathbf{w}=(w_1,w_2, \ldots) \in A$ and for each $i \in \mathbb{N}$, $w_i \ne a$. Similarly, for each $\mathbf{w} \in B$ and for each $i \in \mathbb{N}$, $w_i \ne a$. Since $\mathbf{x} \ne \mathbf{y}$ and $(\sigma^+_G)^n(\mathbf{x})=(\sigma^+_G)^n(\mathbf{y})$, there is $i \le n$ such that $x_i \ne y_i$ and $x_{i+1}=y_{i+1}$. By (3), $\{x_i,y_i,x_{i+1}\} \cap \{a,b \} \ne \emptyset$. Thus, $b \in \{x_i,y_i,x_{i+1}\}$, so by (2), $\mathbf{z}=\overline{\mathbf{b}}=(b,b,b,b,\dots)$. Thus, $A = \{ \overline{\mathbf{b}} \}$ and similarly, $B = \{ \overline{\mathbf{b}} \}$, which contradicts $A \cap B = \emptyset$. It follows that $G$ is not CR-turbulent.

\end{proof}

\begin{theorem}
Suppose $X$ is a compact metric space and $f:K_1 \to K_2$ is a homeomorphism from closed set $K_1 \subset X$ to closed set $K_2 \subset X$. Suppose there are $a,b \in X$ such that $a \ne b$ and $(\{(a,x):x \in X \} \cup \{(x,b):b \in X\}) \cap \{(x,f(x)):x \in K_1 \} \subset \{(x,x):x \in X \}$. If $G=\{(a,x):x \in X \} \cup \{(x,b):b \in X \} \cup \{(x,f(x)):x \in K_1\}$, then $\pi_1(G)=\pi_2(G) = X$; $G$ is not CR-turbulent; and $G$ is not reverse CR-turbulent. 	
\end{theorem}

\begin{proof} Assume $X,f,a,b$ are as above. It is easy to verify the following:

\begin{enumerate}
	\item If $(x,a) \in G$, then $x=a$.
	\item If $(b,x) \in G$, then $x=b$.
	\item If $(s,u) \in G$ and $(t,u) \in G$ and $s \ne t$, then $\{s,t,u \} \cap \{a,b\} \ne \emptyset$.
\end{enumerate}
So, by Lemma 5.1, $G$ is not CR-turbulent. The proof that $G^{-1}$ is not CR-turbulent is the same but the roles of $a$ and $b$ are switched.

\end{proof}



\begin{exam} A closed subset $F$ of $[0,1]^2$ such that $\pi_1(F)=\pi_2(F)=[0,1]$, $ent(F)>0$, and $F$ is neither CR-turbulent nor reverse CR-turbulent: Let $f$ be a homeomorphism from the embedding of the Cantor middle-third set in $[0,1]$ onto the same embedding of the middle -third Cantor set in $[0,1]$ with $ent(f) >0$. Choose $a,b \in [0,1]$ such that $a \ne b$ and neither $a$ nor $b$ is in the Cantor middle-third set in $[0,1]$. Let $V_a=\{(a,y)|y \in [0,1] \}$ and $H_b= \{(x,b)|x \in [0,1] \}$. If $F=\Gamma(f) \cup V_a \cup H_b$, then $ent(F)>0$, $\pi_1(F)=\pi_2(F)= [0,1]$, and $F$ is not CR-turbulent and not reverse CR-turbulent. (See Figure 3.)

\end{exam}

