\begin{prop}

Let $\alpha$ be such that $\alpha =f^{-1}\circ g(1)$. Thus $f(\alpha)=g(1)$. Note that $\alpha <a$. Let $f \cup g$ be the closed relation defined by $(f \cup g)(x)= \{f(x),g(x)\}.$ Then $$(f \cup g) ([\alpha,1])=g([\alpha,1]) \cup f([\alpha,a])$$ $$=[g(\alpha),g(1)] \cup [f(\alpha),f(a)]$$ $$=[g(\alpha),g(1)] \cup [g(1),1]$$ $$=[g(\alpha),1]. $$ 
Furthermore, this holds for $0< \beta \le \alpha$, i.e., 
$$(f \cup g) ([\beta,1])=g([\beta,1]) \cup f([\beta,a])$$ $$=[g(\beta),g(1)] \cup [f(\beta),f(a)]$$ $$=[g(\beta),g(1)] \cup [g(1),1]$$ $$=[g(\beta),1], $$
and for each $n$, $$(f \cup g)^n([\alpha, 1])=[g^n(\alpha),1],$$
and  $$(f \cup g)^n([\beta, 1])=[g^n(\beta),1].$$
\end{prop}

\begin{prop} Given $p \in (0,1)$, there are $z=z(p) \in (0,p)$ and $M=M(p)$ such that $(f \cup g)^M([z,p])=[g^M(z),1] \supset [\alpha,1]$. 

\end{prop}


 \begin{proof}
Note that $f^{-1}\circ g(p) \le \alpha$.

\textbf{Case 1: $a \le p$.} Let $z$ be such that $f(z)=g(p)$. Then $z=f^{-1}\circ g(p) \le \alpha$. Let $M=1$. Then $(f \cup g)([z,p]) =f([z,a]) \cup g([z,p]) =[g(p),1] \cup [g(z),g(p)] = [g(z),1] \supseteq [\alpha,1]$. 

\textbf{Case 2: $p <a$.} Let $m \in \mathbb{Z}$ such that $f^{m-2}(p) <a \le f^{m-1}(p)$. Let $z=f^{-m} \circ g^m(p) \le \alpha$. Then $f^{m-1}([z,p]) \supseteq [f^{m-1}(z),a]$, so $f^m([z,p]) \supseteq f([f^{m-1}(z),a])= [f^m(z),f(a)]=[g^m(p),1]$. Now $g^m([z,p])= [g^m(z),g^m(p)] = [g^m(z),f^m(z)]$. Let $M=m$. Then \newline $(f \cup g)^M([z,p]) \supseteq [g^M(z),1] \supseteq [\alpha,1]$. 

\end{proof}

\vphantom{}

\begin{theorem} The closed relation $f \cup g$ defined above is CR-turbulent and reverse CR-turbulent. 
\end{theorem}

\begin{proof}
Let $\alpha= f^{-1}\circ g(1)$ (so $f(\alpha)=g(1)=b$). Let $p \in (0,1)$ and let $M=M(p)$ and $z=z(p)$ be defined as in Proposition 6.2. Let $\beta=g^{-1}(z)$, $\gamma=f^{-1}(\alpha)$. Then notice that $f([\gamma,a])=[\alpha,1]$. Since $g^n(z) \to 0$ and $g^n(\alpha) \to 0$ as $n \to \infty$, there is $N \in \mathbb{N}_0$ such that $g^{M+N}(z) < \min \{ \gamma, \beta \}$ and $g^{M+N}(\alpha) < \min \{\gamma, \beta \}$.


\vphantom{}


Let $A$ and $B$ be subsets of $I_{f \cup g}^{N+M+1}$ defined by 

$$A= \{ (x_1,x_2, \ldots, x_{N+M+1}): x_1 \in [\beta,1] ,g(x_1)=x_2, x_3 \in (f \cup g)  (x_2), \ldots, x_{N+M+1} \in(f \cup g)(x_{N+M}) \},$$ and $$B= \{ (x_1,x_2, \ldots, x_{N+M+1}):x_1 \in [\gamma,\alpha] ,f(x_1)=x_2, x_3 \in (f \cup g)  (x_2), \ldots, x_{N+M+1} \in(f \cup g)(x_{N+M}) \}.$$

Now, if $(x_1,x_2,\ldots,x_{N+M+1}) \in A \cap B$, then $x_1 \in [\beta,1] \cap [\gamma,\alpha]$, and $x_2=g(x_1)=f(x_1)$. But this cannot be since $g(x_1) < f(x_1)$. Then $A \cap B = \emptyset$. Let $$A'= \{ (x_1,x_2, \ldots, x_{N+M+1}): x_1 \in [\beta,1] ,g(x_1)=x_2, x_3 \in g(x_2), \ldots, x_{N+M+1} \in g(x_{N+M}) \},$$ and let $$B'= \{ (x_1,x_2, \ldots, x_{N+M+1}):x_1 \in [\gamma,\alpha] ,f(x_1)=x_2, x_3 \in  g  (x_2), \ldots, x_{N+M+1} \in  g(x_{N+M}) \}.$$ Then $\pi_1(A) =[\beta,1]$,  because $[\beta,1] = \pi_1(A') \subset \pi_1(A)$. Likewise, $[\gamma,\alpha]=\pi_1(B') \subset \pi_1(B)$, so $\pi_1(B)=[\gamma.\alpha]$.

\vphantom{}


Since $g^{M+N}(z) < \beta$ and $z \le \alpha$, it follows from Proposition 6.1 that $$(f \cup g)^n([z, 1])=[g^n(z),1].$$ Since $g^{M+N}(z) < \gamma$, it follows from Proposition 6.2, that $[g^{M+N}(z),1] \supset [g^M(z),1] \supset [\alpha,1]$, so $\pi_{M+N+1}(A)=[g^{M+N}(z),1] \supseteq [\beta,1] \cup [\gamma,a]$. A similar argument yields the result that $\pi_{M+N+1}(B)=[g^{M+N}(\alpha),1] \supseteq [\beta,1] \cup [\gamma, a]$. 

\vphantom{}

Hence, $f \cup g$ is CR-turbulent. By considering the same argument applied to $f^{-1}$ and $g^{-1}$, it follows that $f \cup g$ is also reverse CR-turbulent. 

\end{proof}


