\section{Separated, continuum-wise semi-turbulent homeomorphisms on smooth fans}

\vphantom{}

While homeomorphisms cannot be turbulent, reverse turbulent, or separated turbulent, they can satisfy a related condition called ``separated continuum-wise semi-turbulence'':

\vphantom{}


\begin{definition}

Let $X$ be a compact metric space and $h:X \to X$ be a continuous function. We say that $h$ is \emph{semi-turbulent} if there exist a continuum $Y$, disjoint closed sets $A,B$ in $X$ and continuous functions $\phi:X \to Y$, $f:Y \to Y$, such that 

\begin{enumerate}
	\item $f \circ \phi = \phi \circ h$,
	\item$\phi(A) \cap \phi(B) = \emptyset$, and 

	\item $\phi(A) \cup \phi(B) \subset \phi(h(A)) \cap \phi(h(B))$.

\end{enumerate}

See Figure 5.


\end{definition}

\begin{definition}
Let $X$ be a compact metric space and $h:X \to X$ be a continuous function. We say that $h$ is \emph{separated, continuum-wise semi-turbulent} if there exist a continuum $Y$, disjoint subcontinua $A,B$ in $X$ and continuous functions $\phi:X \to Y$, $f:Y \to Y$, such that 

\begin{enumerate}
\item $f \circ \phi = \phi \circ h$,

\item $\phi(A) \cap \phi(B) = \emptyset$, and 

\item $\phi(A) \cup \phi(B) \subset \phi(h(A)) \cap \phi(h(B))$.
\end{enumerate}

Note that this implies that 
$$f \circ \phi(A) \cap f \circ \phi(B) \supset \phi(A) \cup \phi(B),$$
and hence $f$ is separated, continuum-wise turbulent. 



\end{definition}

