\begin{definition} The following is an equivalent definition of the Cantor fan given in Section 2. It is the definition we need here:
	Let $C$ be a Cantor set and $F_p$ be the quotient of $C\times [0,1]$ formed by identifying $\{(c,0)\}_{c\in C}$ with a point $p$. Any continuum homeomorphic to $F_p$ is called a \emph{Cantor fan} and the point $p$ is called the \emph{top} of the Cantor fan.
\end{definition}


\begin{definition}
	Recall that a continuum $Y$ that can be embedded in $F_p$ is called a \emph{ smooth fan.} We do not discuss non-smooth fans, so we define them as follows: A \emph{non-smooth fan} is one that cannot be embedded in the Cantor fan. (It is possible to give a more direct definition, but it is rather involved, and we do not need it here.)
\end{definition}

{\bf Note:} Arcs are trivial smooth fans and any non-trivial smooth fan that is embedded in $F_p$ must contain the top $p$.\\

\vphantom{}

\textbf{Notation.} If $X \subset Y \times Z$, then $\pi_1: X \to Y$ and we define $\pi_1(y,z)=y$ for $(y,z) \in X$. Thus, for $y \in Y$, $\pi_1^{-1}(y)=\{ (y,z):z \in X \}$. 

\vphantom{}

\begin{definition}

Let $C$ be a Cantor set and $S$ be a closed subset of $C$. Then $B^S$ is a \textit{blade space} if $B^S$ is a compact subset of $S \times [0,1]$ such that $\pi^{-1}_1(c)$ is connected and contains $(c,0)$ for each $c \in S$. Also, for each $c \in S$, there is $\rho(c) \in [0,1]$ such that $B^S \cap (\{c \} \times [0,1])= \{(c,t): t \le \rho(c) \}$. (Note: it is possible that $\rho(c)=0$.)


\end{definition} 

\vphantom{}

Notice that if $B^S\subset S\times [0,1]$ is a blade space, then the identification of $\{(c,0)\}_{c\in S}$ with a point $p$, $B^S_p$ is a smooth fan. Let $\nu_S:B^S\longrightarrow B^S_p$ be the natural map.

\begin{prop}
	If $Y$ is a smooth fan, then there is a blade space $B^S$ such that $Y$ is homeomorphic to $B^S_p$. 
\end{prop}
\begin{proof}
If $Y$ is a arc then $Y$ is homeomorphic to $\{c\}\times [0,1]$ for any $c\in C$, which is a blade space. So assume that $Y$ is a non-trivial smooth fan.
Let $\nu_C:C\times [0,1]\longrightarrow F_p$ be the natural map. Then $\nu_C^{-1}(Y)$ is a blade space since $C\times\{0\}=\nu_C^{-1}(p)$. 
\end{proof}

\begin{definition} Let $Y$ be a continuum and $A,B$ be disjoint closed subsets of $Y$. Let $I$ be an arc and $\varphi:I \to Y$ be a map. An $(A,B)$\emph{-zigzag set for} $\varphi$ is a subset $\{x_i\}_{i=1}^n \subset I$ such that $x_1 < x_2 < \cdots <x_n$ and $\varphi(x_i) \in A$ if $i$ is even, and $\varphi(x_i) \in B$ if $i$ is odd. (Or, similarly, $\varphi(x_i) \in B$ if $i$ is even, and $\varphi(x_i) \in A$ if $i$ is odd.) The $(A,B)$\emph{-zigzag number for} $\varphi$ is the maximum cardinality that an $(A,B)$-zigzag set can have. (A proof that this maximum cardinality exists is given below.) 


\end{definition}



\vphantom{}

\begin{prop} There is $M \in \mathbb{N}$ such that if $\{x_i \}_{i=1}^n$ is an $(A,B)$-zigzag set for $\varphi$, then $n \le M$.
\end{prop}

\begin{proof} Let $\epsilon= \frac{d(A,B)}{2}$. Since $\varphi$ is uniformly continuous, there is $\delta >0$ such that if $x,y \in I$ and $d(x,y)< \delta$, then $d(\varphi(x),\varphi(y)) < \epsilon$. Let $M = \ulcorner \frac{diam (I)}{\delta} \urcorner$. Thus, $M$ is the ``ceiling function'' or the ``round up to the nearest positive integer function''. Then it follows from the pigeon-hole principle that if $\{x_i \}_{i=1}^n$ is an $(A,B)$-zigzag set for $\varphi$, then $n \le M$.

\end{proof}



\begin{lemma} Let $X$ be a blade space, $Y$ be a continuum, $A,B$ be disjoint closed subsets of $Y$, and $\phi:X \to Y$ be continuous (where $X \subset C \times [0,1]$).  For each $c \in C$, let $M(c)$ be the $(A,B)$-zigzag number for $\phi|_{\{c\} \times [0,\rho(c)]}: \{c \} \times [0,\rho(c)] \to Y$. Then $\{ M(c):c \in C \}$ is bounded. 
\end{lemma}

\begin{proof}
Since $X$ is compact, $\phi$ is uniformly continuous. Let $\epsilon = \frac{d(A,B)}{2}$, and let $\delta>0$ such that if $x,y \in X$ and $d(x,y) < \delta$, then $d(\phi(x), \phi(y))< \epsilon$. Since $\pi^{-1}_1(c) \subset \{c \} \times [0,1]$, it follows that $M(c) \le \ulcorner \frac{1}{\delta} \urcorner$, for each $c \in C$.
\end{proof}

\vphantom{}

\textbf{Notation.} In the case that the lemma above holds, let $M_{\phi(A,B)} := \max \{M(c):c \in C \}$ denote the $(A,B)$-zigzag number for $\phi$.


\vphantom{}

Let $\{a_i \}_{i=1}^{2^n} \subset I$ such that $a_i <a_{i+1}$ for each $i$. Let $C_n= \{ (\alpha_1, \dots, \alpha_n): \alpha_i \in \{0,1 \} \}$. Let $\Psi:\{a_i \}_{i=1}^{2^n} \to C_n$ be one-to-one and onto. For each $k \in \{1, \dots,n \}$, let $\{i_j^k\}_{j=1}^{n_k}$ ($n_k \le 2^n$) be a strictly increasing sequence in $\mathbb{N}$ of maximal cardinality such that 
$$ \pi_k \circ \Psi(a_{i_j^k}) \ne \pi_k \circ \Psi(a_{i_j^k+1}).$$ (\textit{Maximal} means that if $i \notin \{i_j^k\}_{j=1}^{n_k}$, then $\pi_k \circ \Psi(a_{i}) = \pi_k \circ \Psi(a_{i+1})$.)  

\begin{lemma}
Given the above, there exists a $k \in \{1, \ldots,n \}$ such that $n_k \ge \frac{2^n-1}{n}$.

\end{lemma} 

\begin{proof}
For each $i \in \{1,2,...,2^n-1\}$ there is $k_i \in \{1,\dots,n\}$ such that $\pi_{k_i} \circ \Psi(a_i) \ne \pi_{k_i} \circ \Psi(a_{i+1})$, since $ \Psi(a_i) \ne \Psi(a_{i+1})$. If $n_k < \frac{2^n-1}{n}$ for each $k \in \{1, \ldots,n \}$, then it follows that there are less than $n(\frac{2^n-1}{n})=2^n-1$ distinct $i$'s such that $ \Psi(a_i) \ne \Psi(a_{i+1})$, so it follows from the pigeon-hole principle that there is at least one $i \in \{1,2,...,2^n-1\}$ such that $ \Psi(a_i) = \Psi(a_{i+1})$, which is a contradiction.


\end{proof}

