\begin{definition}

 Let $Z \subset X \times Y$ such that $\pi_1(Z)=X$. Then the function $g:Z \to Z$ is a \emph{fiber-injection} if there exist a continuous function $\mu:X \to X$ and, for each $x \in X$, a continuous one-to-one function $h_x: \pi_1^{-1}(x) \to \pi_1^{-1}(\mu(x))$ such that $g(x,y) = (\mu(x), h_x(y))$ and $g$ is continuous. 


\end{definition} 

