\item $f \circ \phi = \phi \circ g$,
\item $\phi(A) \cap \phi(B) = \emptyset$, and
\item $\phi(A) \cup \phi(B) \subset \phi \circ g(A) \cap \phi \circ g(B)$.


\end{enumerate}

