$$A_{(p_1,p_2, \dots,p_n,0)}  \cap A_{(p_1,p_2, \dots,p_n,1)}= \emptyset.$$

\vphantom{}

Let $M$ be the $(\phi(A),\phi(B))$-zigzag number for $\phi$ and choose $n$ such that $M<\frac{2^n-1}{n}$. Notice that $A_{(p_1,p_2, \dots,p_n)} \subset \{ \mu^{n-1}(c_A)\} \times \{0,1 \}$ for each $(p_1,p_2, \dots,p_n) \in C_n$. Since $\{A_{(p_1,p_2, \dots,p_n)}\}_{(p_1,p_2, \dots,p_n) \in C_n}$ are all disjoint, we can pick $\{x_i \}_{i=1}^{2^n} \subset \{\mu^{n-1}(c_A)\} \times \{0,1 \}$ such that $x_i <x_{i+1}$ and each $x_i$ is in a distinct element of  $\{A_{(p_1,p_2, \dots,p_n)}\}_{(p_1,p_2, \dots,p_n) \in C_n}$. Let $\Psi:\{x_i \}_{i=1}^{2^n} \to C_n$ be defined by $\Psi(x_i)=(p_1,p_2, \dots,p_n)$ if and only if $x_i \in A_{(p_1,p_2, \dots,p_n)}$. Then by the previous lemma, there is $k$ and a strictly increasing sequence of natural numbers $\{i_j^k\}_{i=1}^{n_k}$ such that $n_k \ge \frac{2^n-1}{n}>M$ such that $\pi_k \circ \Psi(x_{i_j^k}) \neq \pi_k \circ \Psi(x_j^{k+1})$. Then since $g$ is one-to-one and order preserving, $g^{k-n}(x_{i_j^k}) < g^{k-n}(x_{i_{j+1}^k})$, $\phi \circ g^{k-n}(x_{i_j^k}) \in \phi(A) \cup \phi(B)$, and 
$\phi \circ g^{k-n}(x_{i_j^k}) \in \phi(A)$ if and only if $\phi \circ g^{k-n}(x_{i_{j+1}^k}) \in \phi(B)$. Hence, $\{g^{k-n}(x_{i_j^k})\}_{j=1}^{n_k}$ is a $(\phi(A),\phi(B))$-zigzag set for $\phi$ with cardinality $n_k>M$, which is a contradiction. 
\end{proof}



\begin{definition}
Let $Z\subset X\times Y$ be such that $\pi_1(Z)=X$ and let $y\in Y$. Define $Z_q=Z/(X\times\{y\})$ to be the identification of $X\times\{y\}$ with a point $q$. Then we say that $g:Z_q\longrightarrow Z_q$ is a \emph{ $q$-cut fiber injection} if $g|_{Z_q-\{q\}}$ is a fiber injection.



\end{definition}

\begin{theorem} If $g:B^S_p\longrightarrow B^S_p$ is a  $p$-cut fiber injection of a smooth fan $B^S_p$, then $g$ is not separated, continuum-wise semi-turbulent.
\end{theorem}
\begin{proof}
	If $B^S_p$ is a arc, then $B^S_p$ is homeomorphic to the blade space ${c}\times[0,1]$, $g$ is a homeomorphism and hence a fiber injection, so the result follows from Lemma 6.5.

	Suppose $B^S_p$ is not an arc and let $A, B$ be disjoint subcontinua of $B^S_p$. Then $p\not \in A$ or $p \not \in B$. Suppose the former. Then there is a $c_A\in S$ such that  $A \subset \nu_S(\{c_A\}\times(0,1])$ and the proof is the same as Lemma 6.5. 
\end{proof}

\vphantom{}



\begin{corollary}
	Let $h:Y\longrightarrow Y$ be a homeomorphism of a smooth fan $Y$. Then $h$ is not separated, continuum-wise semi-turbulent. Hence, smooth fans do not admit separated continuum-wise turbulent homeomorphisms.	

\end{corollary}

\begin{proof}
	This follows from the fact that homeomorphisms of smooth fans are $p$-cut fiber injections, where $p$ is the top of $Y$.
\end{proof}

We end with some questions:


\vphantom{}

\textbf{Question.} Does there exist a separated continuum-wise semi-turbulent homeomorphism on a non-smooth fan?

\vphantom{}

\textbf{Question.} If $F \subset X \times X$ is a closed relation on a compact metric space $X$ and $ent(F)>0$, is $(X_F^+, \sigma_F^+)$ either turbulent, reverse turbulent, or semi-turbulent?

