\section{Loss of stability and emergence of chaos}

\subsection{Linear stability analysis}
In this section, we study the stability of the fixed point ansatz with a linear stability analysis following \cite{galla2018dynamically}. We add to the DMFT equation a small independent 
%\am{(visto che qui si dice "small" ho sostituito ovunque $\delta \zeta$ con $\zeta$)} 
Gaussian white noise $\zeta(t)$
\begin{multline}
    \dot{x}(t) = x(t)[1-x(t) + \gamma \sigma^2 \int_0^t dt' G(t,t') J(x(t')) \\
    +\mu Q(t) + \eta(t) + \zeta(t)]
\end{multline}
and study the resulting deviations $\delta x(t) = x(t) - x^*$ from the stationary solution. At first order the noise is modified to $\eta(t) = \eta^* +\delta \eta(t)$, with
\begin{align} \label{eq:delta_eta}
    \langle \delta\eta(t) \delta\eta(t')\rangle =\sigma^2 \langle (J'^*)^2 \delta x(t) \delta x(t') \rangle \quad,
\end{align}
where $J'^* \equiv dJ(x)/dx\vert_{x=x^*}$.
The linearized DMFT equation is
\begin{multline} 
    \delta \dot{x} (t) = \delta x(t) [1-x^* +\gamma \sigma ^2 \chi J(x^*) +\mu Q^* +\eta^*] +\\
    + x^* [-\delta x(t) +\gamma \sigma^2 \int dt'[ \delta G(t,t') J(x(t')) +\\
    +G(t,t') \delta J(x(t')]+\mu \delta Q(t) + \delta \eta (t) + \zeta(t)], 
\end{multline}
and it is easy to show that $\delta G(t, t') = 0$ and $\delta Q(t) = 0$, starting from their definition and showing that it can be written as the average of an unperturbed observable multiplied by $\zeta$. Given the independence between the two and the fact that $\langle \zeta \rangle = 0 $, the terms mentioned above are zero.  

The dynamics of small perturbations around $x^* = 0$ thus satisfies
 \begin{equation}
     \delta \dot{x}(t) = \delta x(t) [1 + \mu Q^* + \eta^*]
 \end{equation}
which shows that this fixed point is stable when $\xi = 1 + \mu Q^* + \eta^* < 0$, as anticipated.

The linear dynamics of perturbations around the non-zero fixed point satisfies instead
\begin{multline}
    \delta \dot{x}(t) = x^* [-\delta x(t) + \gamma \sigma ^2 \int dt' G(t, t') \delta J(x(t'))+
    \\+ \delta \eta (t) + \zeta(t)].
\end{multline}
We apply the Fourier transform on both sides, obtaining
\begin{multline}
i \omega \delta \Tilde{x}(\omega) = x^*[-\delta \Tilde{x}(\omega)+ \delta \Tilde{\eta}(\omega) + \Tilde{\zeta}(\omega)+\\
+\gamma \sigma ^2 \Tilde{G}(\omega) \delta \Tilde{x} (\omega) J'^* ],
\end{multline}
and solving for $\delta \Tilde {x}(\omega)$ we get
\begin{equation} \label{eq:perturbation}
    \delta \Tilde {x} (\omega) = A(\omega)^{-1}[\delta \Tilde{\eta}(\omega) + \Tilde{\zeta}(\omega) ],
\end{equation}
with 
\begin{equation}
    A(\omega) = \left[\frac{i\omega}{x^*}+1-\gamma \sigma^2 \Tilde{G}(\omega) J'^*\right].
\end{equation}
Since $\zeta$ is chosen to be a Gaussian white noise, we have
\begin{equation} \label{eq:delta_h}
\langle \Tilde{\zeta}(\omega) \Tilde{\zeta}(\omega') \rangle = \epsilon^2 \delta (\omega +\omega ') 2\pi,
\end{equation}
where $\epsilon$ is the strength of the Gaussian noise. Regarding $\langle \delta x(t) \delta x(t') \rangle$, since we are around the fixed point, it depends only on $t-t'$, and therefore
\begin{equation}\label{eq:delta_x}
    \langle \delta \Tilde{x}(\omega) \delta \Tilde{x}(\omega') \rangle = \epsilon^2 \delta (\omega +\omega ') 2\pi \delta \Tilde{C}(\omega),
\end{equation}
where $\delta \Tilde{C}(\omega)$ can be obtained from equations (\ref{eq:perturbation}), (\ref{eq:delta_h}), (\ref{eq:delta_eta}). Indeed, from eqs.(\ref{eq:delta_eta}) and (\ref{eq:perturbation}) we get
\begin{align}
    &\sigma^{-2}\langle \delta \Tilde{\eta}(\omega) \delta \Tilde{\eta}(\omega') \rangle = \langle (J'^*)^2\delta \Tilde{x}(\omega) \delta \Tilde{x}(\omega') \rangle =\nonumber\\
    &=D(\omega,\omega')\big[ \langle \delta \Tilde{\eta}(\omega) \delta \Tilde{\eta}(\omega') \rangle + \epsilon^2 \delta (\omega +\omega ') 2\pi\big],
    \label{consistency}
\end{align}
where
\begin{equation}
    D(\omega,\omega')\equiv \langle (A(\omega)A(\omega'))^{-1}(J'^*)^2\rangle.
\end{equation}
The last equation allow to determine the $\delta\tilde \eta$ correlation, which used in eq.(\ref{eq:perturbation}) leads to the final result:
\begin{equation}
    \delta \Tilde{C}(\omega) =  \frac{\langle \vert A(\omega)\vert^{-2}\rangle }{1-\sigma^2 D(\omega,-\omega)},
\end{equation}
 where the $\langle \cdot \rangle$ is an average over the distribution of $x^*$, with $x^*>0$. We are in particular interested in the long time response, and we therefore consider $\omega = \omega ' = 0$. In this case we obtain that
\begin{equation}\label{D}
    D(0,0) = \Big\langle \frac{(J'^*)^2}{(1-\gamma \sigma^2 \chi J'^*)^2}\Big\rangle,
\end{equation}
 where we have used that $\tilde G(0)=\chi$. $\delta \Tilde{C}(0)$ diverges if the following critical condition is satisfied
\begin{equation}\label{eq:critical_condition}
    1 = D(0,0) \sigma ^2,
\end{equation}
and the averages need to be computed with the stationary distribution of the surviving species 
\begin{equation}\label{normalization}
    P(x^*) = \frac{1}{1-\phi} P_{\text{surv}}(x^*),
\end{equation}
with $x^*>0$ and the pre-factor $1/(1-\phi)$ guarantees the normalization condition $\int_{x^*>0} dx^* P(x^*) =1$. The critical condition can be thus rewritten as
\begin{equation}\label{eq:stability_condition}
    1 = (1-\phi) \sigma^2 \int_{x^*>0} dx^* P(x^*) (J'^*)^2 \frac{1}{(1-\gamma \sigma^2 \chi J'^*)^2}.
\end{equation}
As expected, in the limit $h\rightarrow 0$ we obtain the same result of Ref. \cite{galla2018dynamically}.
