\section{Dynamical Mean Field Theory}
In this section we carry out the DMFT, or Functional analysis, of model (\ref{eq:glv}). 
The dynamical moment generating functional is defined as 
\begin{equation}
Z\left[\bold{\Psi}\right]=\int_{paths} \mathcal{D}\left[\bold{x}\right] e^{i\sum_i\int dt x_i(t) \Psi_i(t)},    
\end{equation}
where $\bold{\Psi}=(\Psi_1,...,\Psi_N)$ is an external source field and the integral is computed on the measure generated by the GLV dynamics. We can constrain the integral over the possible trajectories using a Dirac delta functional in its Fourier transform representation and obtain
\begin{equation}
Z\left[\bold{\Psi}\right]=\int \mathcal{D}[\bold{x}, \bold{\hat{x}}] \exp{\left(i\sum_i\int dt x_i(t) \Psi_i(t) + \right )}\times \exp{\left(i\sum_i \int dt \hat{x}_i(t)\left(\frac{\dot{x}_i(t)}{x_i(t)} - \left[1-x_i(t)+\sum_{j \neq i} \alpha_{ij}J(x_j(t)) + \zeta(t)\right]\right)\right)} .
\end{equation}
%%\textcolor{magenta}{nella misura $\mathcal{D}[\bold{x}, \bold{\hat{x}}]$apparirebbe anche uno Jacobiano che alla fine, quando si arriva all'equazione effettiva di singola specie si elide. Quindi direi: Included in the measure $\mathcal{D}[\bold{x}, \hat{x}]$ is a Jacobian that guarantees that $Z\left[\bold{\Psi}=0\right]=1$. Its presence will be canceled at the end of the calculation, when we derive the actual stochastic single-species equation. }
 Included in the measure $\mathcal{D}[\bold{x}, \bold{\hat{x}}]$ is a Jacobian that guarantees that $Z\left[\bold{\Psi}=0\right]=1$. Its presence will be canceled at the end of the calculation, when we derive the actual stochastic single-species equation. 
Note that we have set $\lambda = 0$ and introduced a small field $\zeta(t)$ used to compute the response functions that will be set to $0$ at the end of the computation. Now we can perform the average over the quenched disorder due to the parameters $\alpha_{ij}$, that are distributed as
\begin{equation}
\alpha_{ij} = \frac{\mu}{N} + \frac{\sigma}{\sqrt{N}}z_{ij} \hspace{1cm}
\alpha_{ji} = \frac{\mu}{N} + \frac{\sigma}{\sqrt{N}}z_{ji},
\end{equation}
with $\overline{z_{ij}}=0$, $\overline{z_{ij}^2} = 1$ and $\overline{z_{ij}z_{ji}}=\gamma$.
The averaged over disorder functional becomes
\begin{equation}\label{eq:Z_averaged}
    \overline{Z[\bold{\Psi}]} = \int \mathcal{D}[P, Q, L, C, h, \hat{P}, \hat{Q}, \hat{L}, \hat{C}, \hat{K}] \exp{\left(N(\Psi + \Phi +\Omega)\right)},
\end{equation}
where we have introduced the order parameters
\begin{align}
    P(t) &= i \frac{1}{N}\sum_i \hat{x}_i(t)\\
    Q(t) &= \frac{1}{N} \sum_j J(x_j(t))\\
    C(t,t') &= \frac{1}{N} \sum_j J(x_j(t))J(x_j(t'))\\
    L(t,t') &= \frac{1}{N} \sum_i \hat{x}_i(t)\hat{x}_i(t')\\
    K(t,t') &= \frac{1}{N} \sum_i \hat{x}_i(t') J(x_i(t))
\end{align}
using the Dirac delta representation, e.g. for $L(t,t')$
\begin{equation}
    1 = \int \mathcal{D}[L, \hat{L}] \exp{\left(iN\int dt\hspace{0.1cm} dt' \hat{L}(t, t')\left(L(t,t')- \frac{1}{N} \sum_i \hat{x}_i(t)\hat{x}_i(t')\right)\right)}.
\end{equation}
In the argument of the exponential of Eq. (\ref{eq:Z_averaged}) we have pointed out the dependence on $N$ and we have that $\Psi$ comes from the introduction of the order parameters, $\Omega$ depends on the details of the microscopic time evolution and $\Phi$ comes from the average over the disorder:
\begin{equation}
    \Psi = i \int dt \int dt' \left[\hat{L}(t,t')L(t,t') + \hat{K}(t,t') \hat{K}(t,t')+ \hat{C}(t,t')C(t,t') \right] + i\int dt \left[\hat{P}(t)P(t)+\hat{Q}(t) Q(t)\right]
\end{equation}
\begin{multline}
    \Omega = \frac{1}{N}\sum_i \log{\left(\int \mathcal{D}[x_i, \hat{x}_i] p_0^i(x_i(0)) \times \exp{\left(i\int dt J(x_i(t)) \Psi_i(t)\right)}\times \exp{\left(i\int dt \hat{x}_i(t) \left[ \frac{\dot{x}_i(t)}{x_i(t)}-[1-x_i(t)+\zeta(t)]\right]\right)}\right)}\times\\
    \times \exp{\left(-i\int dt \hspace{0.1cm} dt' \left[\hat{L}(t,t') \hat{x}_i(t) \hat{x}_i(t')+ \hat{C}(t,t') J(x_i(t))J(x_i(t')) + \hat{K}(t,t') \hat{x}_i(t') J(x_i(t))\right]\right)}\times \\ \times \exp{\left(-i\int dt \left[\hat{Q}(t) J(x_i(t)) \right]\right)}\times \exp{\left(-i\int dt \left[\hat{P}(t) i \hat{x}_i(t) \right]\right)}
\end{multline}
\begin{equation}
    \Phi = -\frac{1}{2} \sigma^2 \int dt \hspace{0.1cm}dt' \left[L(t,t') C(t,t') +\gamma K(t,t') K(t',t) \right] - \mu \int dt P(t) Q(t),
\end{equation}
where $p_0^i(0)$is the distribution from which the initial values $x_i$ are sampled. Now we are ready to take the $N\rightarrow \infty$ limit and compute $\overline{Z[\bold{\Psi}]}$ with saddle point. From the optimization of the argument of the exponential of Eq. (\ref{eq:Z_averaged}) we obtain the following relations:
\begin{align}   
    \mu Q(t) &= i \hat{P}(t)\\
    i \hat{Q}(t) &= \mu P(t) \\
    \frac{1}{2}\sigma^2 C(t,t') &= i \hat{L}(t,t')\\
    \frac{1}{2} \sigma ^2 L(t,t') &= i \hat{C}(t,t')\\
    i\hat{K}(t,t') &= \frac{1}{2}\gamma \sigma^2 K(t,t')\\
    P(t) &= \lim_{N\to \infty}\frac{1}{N}\sum_i \langle i \hat{x}_i(t) \rangle_\Omega \\
    Q(t) &= \lim_{N\to \infty}\frac{1}{N}\sum_i \langle J(x_i(t)) \rangle_\Omega \\
    L(t, t') &= \lim_{N\to \infty}\frac{1}{N}\sum_i \langle  \hat{x}_i(t) \hat{x}_i(t') \rangle_\Omega \\
    C(t, t') &= \lim_{N\to \infty}\frac{1}{N}\sum_i \langle J(x_i(t))J(x_i(t')) \rangle_\Omega \\
    K(t, t') &= \lim_{N\to \infty}\frac{1}{N}\sum_i \langle i \hat{x}_i(t') J(x_i(t)) \rangle_\Omega.
\end{align}  
From the normalization constraint of the functional $Z$ it is possible to show that $P(t)=0$ $\forall t$ and $L(t,t')=0$ $\forall t,t'$.  Finally, introducing $G(t,t')=-iK(t,t')$ the effective dynamical generating functional is
\begin{multline}
    Z_{eff} = \int D[x, \hat{x}] P_0(x(0)) \exp{i \int dt \hat{x}(t) \left(\frac{\dot{x}(t)}{x(t)}-[1-x(t)+ \zeta(t)+\mu Q(t)]\right)} \times \\
    \times \exp{\left(-\sigma^2 \int dt \hspace{0.1cm} dt' \left[\frac{1}{2}C(t,t') \hat{x}(t) \hat{x}(t') +i\gamma G(t,t') J(x(t)) \hat{x}(t') \right]\right)},
\end{multline}
which is the generating functional of the effective dynamics
\begin{equation}
    \dot{x}(t) = x(t)[1-x(t) +\gamma \sigma ^2 \int dt' G(t,t') J(x(t')) + \mu Q(t) +\eta(t) +\zeta(t)],
\end{equation}
with 
\begin{align}
    C_\eta(t,t') &= \langle \eta(t) \eta(t') \rangle_x =\sigma^2 \left\langle J(x(t))J(x(t')) \right\rangle_x, \\
    G(t, t') &= \left\langle \frac{\delta J(x(t))}{\delta \zeta(t')} \right\rangle_x, \\
    Q(t) &= \left\langle J(x(t)) \right\rangle_x. 
\end{align}.

\section{Stable solution of stationary equation}
Starting from Eq. (\ref{eq:DMFT_stat}) we note that there is a trivial solution $x^*=0$, and possible other solutions can be obtained solving the equation
\begin{equation}
    1-x^* +\gamma \sigma^2 \chi J(x^*) +\mu Q^* + \eta ^* = 0,
\end{equation}
with $J(x^*) = x^*/(1+hx^*)$. Finally we have a second degree polynomial equation in $x^*$. The solutions are 
\begin{equation}\label{eq:second_order_sol}
    x^* = \frac{h\xi-y \pm \sqrt{(h\xi-y)^2+4h\xi}}{2h},
\end{equation}
where we have introduced $\xi = 1 +\mu Q^* +\eta^*$ and $y=1-\gamma \sigma^2 \chi$. The latter can be shown to be always non-negative $y \ge 0$ as confirmed by numerical inspection. Since we want $x^*>=0$ we need $\xi>0$ to have at least one feasible solution. Given that, and the fact that $\sqrt{(h\xi-y)^2+4h\xi}>|h\xi-y|$ we find that the only non-trivial stationary solution is the one with the plus in Eq. (\ref{eq:second_order_sol}). We also want to consider the case in which $h\rightarrow 0$ where Eq. (\ref{eq:second_order_sol}) is ill-defined when we take the plus sign. To regularize it, it is sufficient to multiply numerator and denominator by $h\xi-y-\sqrt{(h\xi-y)^2+4h\xi}$. The final result for the stationary solution is
\begin{equation}
 x^* = \frac{-2\xi}{h\xi-y-\sqrt{(h\xi-y)^2+4h\xi}} H[\xi].
 \end{equation}

