    \includegraphics[width=0.9\linewidth]{alpha2.pdf}
    \caption{Critical capacity $\alpha_c'$ of the volume $V'$, as a function of $\kappa$, $\kappa'$, from Eq.~\eqref{eq:alpha2}.}
    \label{fig:alpha2}
\end{figure}

