\section{ALP effective theory}
\label{sec:coupling_and_REG}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Our starting point is a theory at a UV scale $\Lambda$ above the electroweak scale $\muEW$. 
We consider a pseudoscalar, $a$, with approximately shift-symmetric couplings  to the SM fields. 
The most general EFT up to dimension-5 operators is given by
\begin{align}
\label{eq:UV_Lagrangian}
    \mathcal{L}_a(\Lambda) = &\frac12 (\partial_\mu a)( \partial^\mu a)-\frac12 m_a^2\,a^2+\frac{\partial_\mu a}{f}\sum_F \bar{F}\, {\bm c}_F \,\gamma_\mu F  \nonumber
    \\
    &+c_{GG} \frac{\alpha_s}{4\pi} \frac{a}{f} G_{\mu\nu}^a \tilde{G}^{a,\mu\nu}
    +
    c_{WW} \frac{\alpha_2}{4\pi} \frac{a}{f} W_{\mu\nu}^i \tilde{W}^{i,\mu\nu}
    +
    c_{BB} \frac{\alpha_1}{4\pi} \frac{a}{f} B_{\mu\nu} \tilde{B}^{\mu\nu}\,.
\end{align}
The shift symmetry of $a$ is explicitly broken by its mass term $m_a^2$ and by non-perturbative QCD effects at low energies. 
The quark and lepton couplings run over all SM chiral multiples $F\in\{Q_L,u_R,d_R,L_L,e_R\}$, where ${\bm c}_F$ are hermitian matrices in flavor space. 
The operator $\mathcal{O}_H \equiv (\partial_\mu a)(H^\dagger \overset{\leftrightarrow}{\partial^\mu}H) $ could also be added to the Lagrangian, but is redundant and can be eliminated by a one-parameter family of  field redefinitions~\cite{Bauer:2020jbp}. 
Next, we consider the low-energy theory at a scale $\mu<\muEW$, just above the QCD confinement scale:
\begin{align}
  \mathcal{L}_a(\mu)  = &\frac12 (\partial_\mu a)^2-\frac12 m_a^2\,a^2
+c_{GG} \frac{\alpha_s}{4\pi} \frac{a}{f} G_{\mu\nu}^a \tilde{G}^{a,\mu\nu}+\frac{\partial^\mu a}{f}(\bar{q}_L {\bf k}_Q \gamma_\mu q_L+\bar{q}_R {\bf k}_q \gamma_\mu q_R)  \,,
\label{eq:UV_matching_theory}
\end{align}
where $q=\{u,d,s\}$ denotes the light quark fields, and couplings to leptons have been dropped. 
Without loss of generality, we choose the basis in \Eq{eq:UV_Lagrangian} in which the up-type SM Yukawa matrix is diagonal.
The mass basis for down-type quarks is then obtained by the rotation $d_L \to {\bm V} d_L$, where 
$\bm V$ is the CKM matrix.
We identify
\begin{align}
    {\bm k}_q = \begin{pmatrix}
    [{\bm c}_{u_R}]_{11} & 0 & 0\\
     0& [{\bm c}_{d_R}]_{11} & 
     \kappa_R
     \\
     0& 
          \kappa^\dagger_R
     & [{\bm c}_{d_R}]_{22} 
    \end{pmatrix}\,, \;\;
        {\bm k}_Q = \begin{pmatrix}
    [{{\bm c}}_{Q_L}]_{11} & 0 & 0\\
     0& [\hat{{\bm c}}_{Q_L}]_{11} & 
          \kappa_L
     \\
     0& 
          \kappa^\dagger_L
     & [\hat{{\bm c}}_{Q_L}]_{22} 
    \end{pmatrix}\,,
\end{align}
where $\hat{{\bm c}}_{Q_L} \equiv {\bm V}^{\dagger}{\bm c}_{Q_L}{\bm V}$. 
We now focus on the flavor-violating couplings that mediate $s\to d$ transitions, defining the corresponding vector and axial combinations $\kappa_{V},\kappa_{A}$ as,
\begin{align}
    \mathcal{L}_{\text{\tiny FV}}=& \frac{\partial_\mu a}{f} (\kappa_R \bar{d}_R  \gamma_\mu s_R+ \kappa_L \bar{d}_L  \gamma_\mu s_L + \text{h.c})
\equiv \frac{\partial_\mu a}{2f} (\kappa_V \bar{d}  \gamma_\mu s+ \kappa_A \bar{d}  \gamma_\mu \gamma_5 s + \text{h.c})\,.
\end{align}
At leading order, the off-diagonal coupling $\kappa_{R}$ does not run below the UV scale $\Lambda$~\cite{Bauer:2020jbp} and is given by, 
\begin{align}
    \kappa_R = [{\bm c}_{d_R}(\Lambda)  \big]_{12} \,.
\end{align}
The coupling to the left-handed quarks receives radiative corrections and is given by
 \begin{align}\label{eq:KL}
    \kappa_L &= \big[\hat{{\bm c}}_{Q_L}\big]_{12}+{V}^*_{td}{V}_{ts}\Delta \kappa_L\,,
\end{align}
The first term is a direct consequence of the UV couplings and the transition to the mass basis,
\begin{align}
\label{eq:UV_off_diag_couplings}
     \big[\hat{{\bm c}}_{Q_L}\big]_{12}  &= V^*_{qd}V_{q's}  \big[ \cQL\big]_{q q'} 
     =[\cQL(\Lambda)  \big]_{12} \nonumber
    \\
    & +  {V}^*_{cd}{V}_{cs}\left(\big[  \cQL(\Lambda)  \big]_{22}-\big[  \cQL(\Lambda)  \big]_{11}\right) \nonumber
    \\
    & + {V}^*_{td}{V}_{ts}\left(\big[  \cQL(\Lambda)  \big]_{33}-\big[  \cQL(\Lambda)  \big]_{11}\right) +...\,,
\end{align}
where we omitted terms suppressed by smaller CKM matrix elements.
The radiative correction is given by~\cite{Bauer:2020jbp}
\begin{align}
\label{eq:rad_correction}
\Delta \kappa_L = n_{t}c_{tt}(\Lambda)+n_{G}\tilde{c}_{GG}(\Lambda)+n_{W}\tilde{c}_{WW}(\Lambda)+n_{B}\tilde{c}_{BB}(\Lambda)\,,
\end{align}
where we denote
\begin{align}
\label{eq:nt_def_1}
    n_t(\muEW,\Lambda) &\equiv   \frac{1}{2} \frac{ \alpha_t( \muEW) }{ \alpha_s(\muEW )}\left(1-\left[{\frac{\alpha_s(\Lambda )}{\alpha_s(\muEW )}}\right]^{1/7}\right)\,,
    \\
    n_{G}(\Lambda) &\equiv \frac{2}{\pi^2}\int_\Lambda^{\muEW}\frac{d\mu}{\mu}
    n_t(\muEW,\mu)
     \alpha_s^2(\mu)\,,
     \\
\label{eq:nt_def_2}
    n_{W}(\Lambda) &\equiv \frac{9}{16\pi^2}\int_\Lambda^{\muEW}\frac{d\mu}{\mu}
    n_t(\muEW,\mu)
     \alpha_2^2(\mu)- \frac{3\alpha_t(\muEW)}{8\pi^2} \frac{\alpha_2}{ s_w^2}\,
    \frac{1-x_t+x_t\ln x_t}{\left(1-x_t\right)^2}\,,
                   \\
    n_{B}(\Lambda) &\equiv \frac{17}{48\pi^2}\int_\Lambda^{\muEW}\frac{d\mu}{\mu}
    n_t(\muEW,\mu)
     \alpha_1^2(\mu)\,,
     \label{eq:nt_def_4}
\end{align}
with $\alpha_t \equiv y_t^2/4\pi$ and $x_t \equiv m_t^2/m_W^2$.
Since the off-diagonal coupling $\kappa_{L}$ does not run below the electroweak scale $\muEW$, the expressions in \EqRange{eq:nt_def_1}{eq:nt_def_4} do not depend on the value of $\mu$.
The UV couplings appearing in \Eq{eq:rad_correction} are defined in terms of the couplings in \Eq{eq:UV_Lagrangian} as follows,
\begin{align}
\label{eq:coef_def_1}
    c_{tt}(\Lambda) &\equiv \big[{\bm c}_{u_R}\big]_{33}-\big[\cQL\big]_{33}\,,
    \\
    \tilde{c}_{GG}(\Lambda) &\equiv c_{GG}+\frac12 \text{Tr}\big[{\bm c}_{u_R}+{\bm c}_{d_R}-2 \cQL\big] \,,
        \\
    \tilde{c}_{WW}(\Lambda) &\equiv c_{WW}-\frac12 \text{Tr}\big[3\cQL+{\bm c}_{L_L}\big]\, 
           \\
           \label{eq:coef_def_4}
    \tilde{c}_{BB}(\Lambda) &\equiv c_{BB}+ \text{Tr}\left[\frac43 {\bm c}_{u_R}+\frac13 {\bm c}_{d_R}-\frac16\cQL-\frac12{\bm c}_{L_L}+{\bm c}_{e_R}\right]\,,
\end{align}
where all the couplings on the RHS are evaluated at the UV scale $\Lambda$.
The coupling combinations appearing in \Eq{eq:UV_off_diag_couplings} and \EqRange{eq:coef_def_1}{eq:coef_def_4} are the physical combinations of couplings which are independent of the arbitrary field redefinition used to remove $\mathcal{O}_H$~\cite{Bauer:2020jbp,Bauer:2021mvw}.
In the following section, we shall also encounter the flavor-preserving couplings, e.g.
\begin{align}
    \mathcal{L}_a(\mu) \supset& \frac{\partial_\mu a}{f} (\big[\cdR\big]_{11} \bar{d}_R  \gamma_\mu d_R+ (\big[\hat{{\bm c}}_{Q_L}\big]_{11}\bar{d}_L  \gamma_\mu d_L )+...
\end{align}
and similarly for the up and strange quarks.
These couplings will lead to flavor-changing meson decays mediated by the SM weak interaction.
As opposed to the off-diagonal couplings, the diagonal couplings also run below the weak scale.
However, since these couplings already appear with additional suppression for flavor-violating processes mediated by the SM, we neglect the small RGE effects and CKM-suppressed terms, 
\begin{align}
   &\big[\hat{{\bm c}}_{F}(\mu)\big]_{ii} \approx \big[{\bm c}_{F}(\mu)\big]_{ii} \approx  \big[{\bm c}_{F}(\Lambda)\big]_{ii} \;\;\;\; \text{for $F=\{u_R,d_R,Q_L\}$}\,.
\end{align}
