\section{Chiral perturbation theory}
\label{app:chi_PT}
In this appendix we provide additional details on the calculation of the kaon decay amplitudes in chiral perturbation theory.
Following the approach of Ref.~\cite{Bauer:2021wjo},
before matching the theory to the low-energy chiral Lagrangian, it is convenient to perform a generic field redefinition, as specified in Sec. \ref{Sec:chipT}
\begin{align}
q(x) \to \text{exp}\left[-i(\boldsymbol{\delta}_q + \boldsymbol{\kappa}_q \gamma_5 )c_{GG} \frac{a(x)}{f} \right]q(x)\,,
\end{align}
where $\boldsymbol{\delta}_q$ and $\boldsymbol{\kappa}_q$ are diagonal matrices in flavor space.
This field redefinition removes the gluon coupling if $\text{Tr}[\boldsymbol{\kappa}_q] =1$. 
Importantly, any physical observable must not depend on the base-dependent parameters, $\boldsymbol{\delta}_q$ and $\boldsymbol{\kappa}_q$.
The field redefinition shifts and rotates the ALP coupling to quarks, 
\begin{align}
&{\bf k}_Q \to \hat{\bf k}_Q(a) = U_-({\bf k}_Q+\phi_q^-)U^\dagger_-\,,
\\
&{\bf k}_q \to \hat{\bf k}_q(a) = U_+({\bf k}_q+\phi_q^+)U^\dagger_+\,,
\end{align}
where $\phi_q^\pm \equiv c_{GG} (\boldsymbol{\delta}_q \pm \boldsymbol{\kappa}_q )$ and $U_\pm(a) \equiv e^{i \phi_q^\pm a/f}$. The field redefinition also leads to the axion-dressed quark mass
\begin{align}
{\bf m}_q \to \hat{\bf{m}}_q =  \text{exp}\left[-2i \boldsymbol{\kappa}_q c_{GG} \frac{a(x)}{f} \right]{\bf m}_q\,,
\end{align}
where ${\bf m}_q = \text{Diag}(m_u,m_d,m_s)$.
The UV theory is matched to the chiral Lagrangian,
\begin{align}
\mathcal{L}_{\chi} = \mathcal{L}_{\text{\tiny kin}}+\mathcal{L}_{ m}+\mathcal{L}_{\text{\tiny weak}}\,,
\end{align}
with
\begin{align}
\mathcal{L}_{\text{\tiny kin}} &=  \frac12 (\partial_\mu a)^2+\frac{f_\pi^2}{8}\text{Tr}[D^\mu \Sigma (D_\mu \Sigma)^\dagger]\,,
\\
\mathcal{L}_{ m} &= \frac{f_\pi^2}{4} B_0 \text{Tr} [\hat{\bf m}_q \Sigma^\dagger+\text{h.c}]-\frac12 m_a^2 a^2\,,
\\
\mathcal{L}_{\text{\tiny weak}} &= \frac{4 N_8}{f_\pi^2}[L_\mu L^\mu]^{32}+\text{h.c}\,,
\end{align}
with $B_0=m_\pi^2/(m_u+m_d)$  and where we defined
\begin{align}
 D_\mu \Sigma &\equiv \partial_\mu \Sigma-i \frac{\partial_\mu a}{f} (\hat{\bf k}_Q\Sigma-\Sigma \hat{\bf k}_q)\,,
 \\
 L_\mu^{ji} &\equiv -\frac{i f^2_\pi} {4}e^{i(\phi_{q_i}^--\phi_{q_j}^-)a(x)/f}[\Sigma (D_\mu \Sigma)^\dagger]^{ji}
 \\
 N_8 &\equiv -\frac{G_F}{\sqrt{2}} V_{us}V^*_{ud}g_8 f_\pi^2\,, \;\;\; |N_8| \approx 1.53\times10^{-7}\,,
 \end{align}
with $G_F$ the Fermi constant, $G_F=1.1663787\times 10^{-5}$ GeV$^{-2}$ and $|g_8|\sim 5$.
 The field $\Sigma$ is given by $\Sigma=e^{2i \Pi/f_\pi}$ with
\begin{align}
\Pi = 
\begin{pmatrix}
\dfrac{\eta}{\sqrt{6}} + \dfrac{\pi^{0}}{\sqrt{2}} & \pi^{+} & K^{+} \\[8pt]
\pi^{-} & \dfrac{\eta}{\sqrt{6}} - \dfrac{\pi^{0}}{\sqrt{2}} & K^{0} \\[8pt]
K^{-} & \bar{K}^{0} & -\sqrt{\dfrac{2}{3}}\,\eta
\end{pmatrix}\,.
\end{align}

\section{Phase space integrals and ratios}
\label{app:PSI_and_ratios}
As we discussed in Secs. \ref{Sec:Kpi0pi0} and \ref{Sec:Kpi+pi-}, the amplitude of the three-body decays can be written as a function of the two kinematical variables, $s_\pi $ and 
$\tilde{s}$. The phase space ratios defined in Eqs. (\ref{eq:ratio_schematic}), (\ref{Eq:I}) can be written as
\begin{align}
    I_{\pm}(m_a,\{a_1,a_2,a_3\}) &\equiv \frac{\frac12\int \mathrm{d}\Pi_3\left|        a_1+a_2\frac{s_\pi}{m_K^2}+ a_3\frac{\tilde{s}}{m_K^2}\right|^2}{(|a_1|^2+|a_2|^2+|a_3|^2)(1-m_\pi^2/m_K^2)^{2} f_\pi^2\int \mathrm{d}\Pi_2}\,,
    \\
    I_{0}(m_a,\{a_1,a_2\}) &\equiv \frac12 I_{\pm}(m_a,\{a_1,a_2,a_3=0\}),
\end{align}
where $a_1,a_2$ and $a_3$ are coefficients which depend on the amplitude of the decay mode under consideration and the $f_\pi^2$ normalization is used to make the $I_{0,\pm}$ dimensionless.

The two-body phase space integral is instead a simple function of $m_a$,
\begin{align}
    \int \mathrm{d}\Pi_2 = \frac{\sqrt{1-(m_a+m_\pi)^2/m_K^2} \sqrt{1-(m_a-m_\pi)^2/m_K^2}}{8 \pi}\,.
\end{align}
The three-body phase space depends on the kinematic variables $s_\pi$ and $s_{\pi a}\equiv (p_a+p_{\pi_1})^2$ (where $\tilde{s} = 2 s_{\pi a}+s_{\pi}-m_{a}^2-m_K^2-2 m_\pi^2$) and
\begin{align}
  \mathrm{d}\Pi_3 = \frac{ \mathrm{d}s_\pi \mathrm{d}s_{\pi a}}{ 128 \pi^3 m_K^2}\,.
\end{align}
The integral can be solved numerically, using the $s_\pi$-dependent integration range for $s_{\pi a}$
\begin{align}
    &({s}_{\pi a})_\pm
    &= \frac{1}{2} \left(m_a^2+m_K^2+2 m_\pi^2-s_\pi\pm\sqrt{s_\pi-4 m_\pi^2} \sqrt{\frac{\left(m_a^2-m_K^2\right)^2}{s_\pi}-2 \left(m_a^2+m_K^2\right)+s_\pi}\right)\,,
\end{align}
and for $s_\pi$,
\begin{align}
  (2 m_\pi)^2  <s_\pi< (m_K-m_a)^2\,.
\end{align}

\section{Maximal flavor violation}
\label{sec:non_MFV}
In maximally flavor violating models, the flavor symmetry breaking parameter in the UV theory is much larger than the SM flavor symmetry breaking sources,
\begin{align}
    \kappa^{\text{\tiny FV}} \gg \text{Max}[\kappa_L^{\text{\tiny MFV}},N_8\, \mathcal{C}_i]\,.
\end{align}
For clarity, we introduce the flavor-blind parameters, $\mathcal{C}_i$, which were mentioned in the main text and whose explicit forms are reported in App. \ref{app:Ci}. 
As a consequence, the three-body decay is dominated by this coupling projected in the $CP$ conserving direction, while
the two-body decay is dominated by this coupling projected in the $CP$-breaking direction.
Thus, the ratio of rates strongly depends on the phase of the coupling, which we denote as $\theta_\kappa \equiv \text{arg}\,\kappa^{\text{FV}}$. 
In this section, we will explain the scaling in Eqs. (\ref{eq:maximallyR0}), (\ref{eq:maximallyRpm}).


\subsection{\texorpdfstring{$\tan \theta_\kappa \sim \mathcal{O}(1)$}{tan theta ~ O(1)}}
\label{sec:Non_MFV_case_I}
In this case, the UV coupling maximally violates not only the flavor but also the $CP$ symmetry. 
We can neglect all the contribution proportional to $N_8$ and $\varepsilon$, to find the ratios defined in Eq. (\ref{eq:ratio_defs})
\begin{align}
\label{eq:rates_neutral}
    R_{0}(m_a) &= (c_{\theta_{\kappa}}/s_{\theta_{\kappa}})^2\left(1 + \frac{1}{(1-x_a)^2}\right){I}_0\left(m_a,\left\{-1,\frac{1}{1-x_a}\right\}\right)\,,
    \\
    \label{eq:rates_charged}
    R_{\pm}(m_a) &= (1/s_{\theta_{\kappa}})^2 \left(c_{\theta_{\kappa}}^2 + \frac{1}{(1-x_a)^2}\right){I}_\pm\left(m_a,\left\{-c_{\theta_{\kappa}},\frac{c_{\theta_{\kappa}}}{1-x_a},\frac{-i\, s_{\theta_{\kappa}}}{1-x_a}\right\}\right)\,,
\end{align}
where $x_a \equiv m_{a}^2/m_K^2$, $c_\alpha \equiv \cos\alpha$, and $s_\alpha \equiv \sin\alpha$.
The ratios of phase space integrals $I_0,I_{\pm}$ are defined in \App{app:PSI_and_ratios}.
These functions can be calculated numerically.
For $\theta_\kappa \sim \mathcal{O}(1)$, the ratios are determined by the phase space ratio, since the prefactor is of $\mathcal O(1)$. These monotonically decreasing functions are bounded from above
\begin{align}
 &{I}_0 \leq {I}_0\left(0,\left\{-1,1\right\}\right)\approx 4\times 10^{-4}\,,
 \label{eq:ratios_maximum_CP_violation_neutral}
    \\
   &{I}_\pm \leq {I}_\pm\left(0,\left\{-1,1,0\right\}\right) \approx 8\times 10^{-4},  \label{eq:ratios_maximum_CP_violation_charged}
\end{align}
and vanish as $m_a \to m_K-2m_\pi$.
This is the typical phase space suppression encountered when comparing two-body and three-body decays.
Note that for the charged decay, the phase space integral depends weakly on $\theta_\kappa$, e.g. for $m_a=0$ the functions is minimized for $\theta_\kappa = \pi/2$, where $I_\pm \approx 2\times 10^{-4}$.
\subsection{\texorpdfstring{$\tan \theta_\kappa \ll |\varepsilon|$}{tan theta << eps}}
In this case, $\kappa^{\text{\tiny FV}}$ is a weaker source for $CP$ violation compared to the SM $\varepsilon$ parameter, and the latter is the dominant contribution to the two-body decay.  
Here, we have a similar expressions as in the previous subsection, but with a larger coupling hierarchy,
\begin{align}
    R_{0}(m_a)  &= \frac{1}{|\varepsilon|^2}\left(1 + \frac{1}{(1-x_a)^2}\right){I}_0\left(m_a,\left\{-1,\frac{1}{1-x_a}\right\}\right)\,,
    \\
    R_{\pm}(m_a) &= \frac{1}{|\varepsilon|^2}\left(1 + \frac{1+|\varepsilon|^2}{(1-x_a)^2}\right){I}_{\pm}\left(m_a,\left\{-c_{\theta_{\kappa}},\frac{c_{\theta_{\kappa}}}{1-x_a},\frac{-\varepsilon c_{\theta_{\kappa}}}{1-x_a}\right\}\right)\approx 2R_0(m_a)\,.
\end{align}
This $\varepsilon^2$ suppression in the two-body decay rates leads to,
\begin{align}
    R_0,R_{\pm} \gtrsim 10^2\,,
\end{align}
which mirrors the same scaling as in the SM,
\begin{align}
    \frac{\text{Br}[K_L \to 3\pi^0 ]}{\text{Br}[K_L \to 2\pi^0] } \approx 200 \sim \frac{10^{-3}}{|\varepsilon|^2}\,.
\end{align}
\subsection{\texorpdfstring{$\cot \theta_\kappa \ll |\varepsilon|$}{cot theta << eps}}
\label{sec:max_FV_case_III}
We also entertain the possibility that the flavor violation in the UV is completely aligned  with $CP$ violation and the main source is coming from the SM $\varepsilon$ parameter. 
In this case the ratios are given by,
\begin{align}
    R_0(m_a) &= |\varepsilon|^2 \left(1 + \frac{1}{(1-x_a)^2}\right){I}_0\left(m_a,\left\{-1,\frac{1}{1-x_a}\right\}\right)\,,
    \\
    R_{\pm}(m_a) &=  \left(|\varepsilon|^2+\frac{1+|\varepsilon|^2}{(1-x_a)^2} \right){I}_{\pm}\left(m_a,\left\{\varepsilon\,s_{\theta_{\kappa}},\frac{-\varepsilon\,s_{\theta_{\kappa}}}{1-x_a},\frac{ s_{\theta_{\kappa}}}{1-x_a}\right\}\right).
\end{align}
The leading $CP$-conserving contribution to the neutral three-body decay rate comes from the product $\text{Im}\,\kappa^{\text{\tiny FV}} \varepsilon$, greatly suppressing the $K_L\to\pi^0 \pi^0 a$ decay rate.
For the charged decay, since the initial and final states are not  $CP$ eigenstates, the amplitude itself contains the $CP$-odd kinematic variable $\tilde{s}$ (see Eq. (\ref{Eq:kinvariables}) and discussion below).
Thus, the leading $CP$-conserving contribution to charged decay is $\text{Im}\,\kappa^{\text{\tiny FV}} \tilde{s}$ and the charged decay rate is only phase-space suppressed,
\begin{align}
    R_0(m_a=0) &= 2|\varepsilon|^2I_0(0,\{-1,1\}) \sim 10^{-9}\, ,
    \\
    R_\pm(m_a=0) &= 2I_{\pm}(0,\{0,0,1\}) \sim 10^{-4}\,.
\end{align}
\section{Minimal flavor violation}
\label{app:MFV_details}
In minimal flavor violating models, the flavor symmetry breaking in the UV theory is predominantly due to the SM Yukawas,
\begin{align}
    \text{Min}[\kappa_L^{\text{\tiny MFV}},N_8\, \mathcal{C}_i] \gg \kappa^{\text{\tiny FV}}  \,,
\end{align}
in accordance with the MFV hypothesis.
In the following we consider all the possible coupling hierarchies and their realizations from the UV perspective. In this section, we will explain the scaling found in \Sec{sec::MFV}.
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{\texorpdfstring{$  \kappa_L^{\text{\tiny MFV}} \gg N_8\, \mathcal{C}_i $}{kappaMFV >> N8,Ci} }
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this case both two-body and three-body decays are dominated by $\kappa_L^{\text{\tiny MFV}} \equiv c^{\text{\tiny MFV}}V_{td}^*V_{ts}$. 
This scenario can be realized by having,
\begin{enumerate}
    \item $c^{\text{\tiny NP}}_L \neq0$, which can be realized if we allow a non-trivial ${\bm c}_{Q_L} \propto \hat{{\bm Y}}_u \hat{{\bm Y}}^\dagger_u$, consistent with MFV (see Eq. (\ref{eq:cQMFV})).
    \item $c_{tt}(\Lambda)\neq0$ .
    \item Decoupling the axion from the strong sector all together $c_{GG} = c_{Q_L} = c_{u_R}= c_{d_R}=0$, leading to $\mathcal{C}_i=0$. 
\end{enumerate}
We find identical expression for the rates as in \EqRange{eq:rates_neutral}{eq:rates_charged}, with the replacement,
\begin{align}  \theta_\kappa \to -\theta_{\text{\tiny CKM}}\,,
\end{align}
where $\theta_{\text{\tiny CKM}} \equiv \text{Arg}\,V_{td}\approx 3.5$. 
The coefficient $c^{\text{\tiny MFV}}$ is real at leading order in the MFV expansion, see the discussion in \Sec{sec:FV_couplings}. 
We thus find a sharp prediction,
\begin{align}
    R_0(m_a=0) &= 2\cot^2 \theta_{\text{\tiny CKM}}{I}_0\left(0,\left\{-1,1\right\}\right) \approx 5\times10^{-3}\,,
    \label{eq:MFV_caseI_neutral}
    \\
    R_{\pm}(m_a=0) &= \sin^{-2} \theta_{\text{\tiny CKM}}\left(1+c_{\theta_{\text{\tiny CKM}}}^2 \right){I}_\pm\left(0,\left\{-c_{\theta_{\text{\tiny CKM}}},c_{\theta_{\text{\tiny CKM}}},i\, s_{\theta_{\text{\tiny CKM}}}\right\}\right)\approx 10^{-2}\,.
\end{align}
These ratios are larger by about an order of magnitude compared to the maximally $CP$-violating case in \EqRange{eq:ratios_maximum_CP_violation_neutral}{eq:ratios_maximum_CP_violation_charged} due to a small hierarchy between the real and imaginary components of the CKM element $|\text{Re}\,V_{td}/\text{Im}\,V_{td}|\sim 2.5$. 
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsection{\texorpdfstring{$N_8\,\mathcal{C}_i \gg  \kappa_L^{\text{\tiny MFV}} \gg \varepsilon\,N_8\,\mathcal{C}_i$}{N8,Ci >> kappaMFV >> eps N8}}
\label{AppendixD2}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In this case, the three-body decays are indirectly-mediated by the weak interaction, while the two-body decays are still dominated by $\kappa_L^{\text{\tiny MFV}}$.
The ratios are then given by,
\begin{align}
    R_{0} &= \left(\frac{|N_8|}{\text{Im}\,\kappa_L^{\text{\tiny MFV}}}\right)^2 (\mathcal{C}_2^2+\mathcal{C}_3^2)I_0\left(m_a,\left\{ \mathcal{C}_2,\mathcal{C}_3\right\}\right)\,,
\\
       R_{\pm} &= \left(\frac{|N_8|}{\text{Im}\,\kappa_L^{\text{\tiny MFV}}}\right)^2 (\mathcal{C}_4^2+\mathcal{C}_5^2+|\varepsilon|^2\mathcal{C}_6^2)I_{\pm}(m_a,\{\mathcal{C}_4,\mathcal{C}_5,\varepsilon\mathcal{C}_6\})\,.
\end{align}
For concreteness, let us assume for the remainder of this section that all the fermions couplings are flavor-blind i.e. ${\bm c}_F = c_{F}1_{3\times 3}$ for $F\in\{Q_L,u_R,d_R,L_L,e_R\}$. 
Under this assumption, $c^{\text{\tiny NP}}_L=0$.
The values of $\{c_F\}$, along with $c_{GG},c_{WW}$ and $c_{BB}$, determine the values of the couplings $\{c_{tt},\tilde{c}_{GG},\tilde{c}_{WW},\tilde{c}_{BB}\}$ as well as the combination of flavor-diagonal couplings, $\{\mathcal{C}_i\}$, appearing in the two- and three-body decay rates.

One way to realize this coupling hierarchy is by having $c_{tt}(\Lambda)=0$ and a non-vanishing $\tilde{c}_{GG}(\Lambda)$.
This can be realized by setting $c_{Q_L} = c_{u_R}$ and turning on either $c_{GG}$ or $c_{d_R}$.
In this case, the ratio of couplings varies depending on the UV scale, and, according to Eq. (\ref{eq:MFVcGG})
\begin{align}
        \left|\frac{|N_8|}{\text{Im}\,n_G V^*_{td}V_{ts}}\right|  \approx \begin{cases}
            24 \;\;\;\;\;\;\;\; &\Lambda = 10^4\,\text{GeV}
            \\
            4 & \Lambda = 10^{10}\,\text{GeV}
        \end{cases}\,.
\end{align}
All the other realizations for the hierarchy $N_8\,\mathcal{C}_i \gg  \kappa_L^{\text{\tiny MFV}} \gg \varepsilon\,N_8\,\mathcal{C}_i$ would require non-trivial cancellations to suppress the contribution from $\tilde{c}_{GG}(\Lambda)$, while still allowing for non-vanishing couplings to the strong sector such that the indirectly-mediated decay is still allowed. 
For example, by requiring that $c_{d_R} = c_{Q_L}-2c_{GG}/3$ (in addition to  $c_{Q_L}=c_{u_R}$), we set $\tilde{c}_{GG}=0$ while $\mathcal{C}_i \propto c_{GG}$.
Thus, as long as $c_{GG}\neq 0$, the indirectly-mediated processes are still accessible. 

Another possibility is realized by having $c_{Q_L}\neq0$ or $c_{L_L}\neq0$ or
$c_{WW}\neq0$. In this case, the flavor-changing coupling is dominated by the coupling to $W$ bosons with $\tilde{c}_{WW} = c_{WW}-\frac32(c_{L_L}+3c_{Q_L})$, and we find the coupling hierarchy (see Eq. (\ref{eq:MFVcWW}))
 \begin{align}
     \left|\frac{|N_8|}{\text{Im}\,n_W V^*_{td}V_{ts}}\right| \approx 40\,.
 \end{align}

Finally, if we set $c_{Q_L}=c_{L_L}=c_{WW}=0$, the flavor-changing coupling is dominated by the coupling to $B$ hypercharge gauge bosons with $\tilde{c}_{BB} = c_{BB}+3c_{e_R}-\frac23 c_{GG}$, and we find the coupling hierarchy (see Eq. (\ref{eq::BB_ratio}))
\begin{align}
   \left|\frac{|N_8|}{\text{Im}\,n_B V^*_{td}V_{ts}}\right|_{\Lambda = 10^{10}\,\text{GeV}}  \approx  400\,.  
\end{align}
We summarize the constraints required to realize $N_8\,\mathcal{C}_i \gg  \kappa_L^{\text{\tiny MFV}} \gg \varepsilon\,N_8\,\mathcal{C}_i$ in \Tab{tab:UV_realizations_summary}.
