\section{\texorpdfstring{Full expressions for  $\{\mathcal{C}_i\}$}{Full expressions for Ci}}
\label{app:Ci}
%%%%%%%%%%%%%%%%%%%%%%%%
%%%%%%%%%%%%%%%%%%%%%%%%
In this appendix we provide the full expressions for the $\{\mathcal{C}_i\}$ coefficients appearing in the main text. 
We express them in terms of the low-energy couplings,
\begin{align}
    {\bm k}_q = \begin{pmatrix}
    k_u & 0 & 0\\
     0& k_d & 
     \kappa_R
     \\
     0& 
          \kappa^\dagger_R
     & k_s 
    \end{pmatrix}\,, \;\;
        {\bm k}_Q = \begin{pmatrix}
    k_U & 0 & 0\\
     0& k_D & 
          \kappa_L
     \\
     0& 
          \kappa^\dagger_L
     & k_S 
    \end{pmatrix}\,.
\end{align}
The $\mathcal{C}_i$'s depend on $c_{GG}$ and the axial combination of couplings, which we denote by 
\begin{align}
        c_{q} &\equiv k_{q}-k_{Q}\,.
\end{align}
In the absence of the weak interactions ($N_8\to0$) and off-diagonal ALP coupling to quarks ($\kappa_L=\kappa_R=0$), the vector couplings are non-physical and can be removed from the theory using the field redefinition of \Eq{eq:generic_basis}.
Otherwise, one linear combination of vector couplings cannot be rotated away and is therefore physical~\cite{Bauer:2021wjo}, 
\begin{align}
    \Delta k_{V}^{d-s}&\equiv k_{d}+k_{D}-(k_{s}+k_{S})\,.
\end{align}
The coefficients are given by,
\begin{align}
    \mathcal{C}_1 = &-\frac{ m_a^2 (c_d-2 c_s+c_u)}{3 m_a^2-4 m_K^2+m_{\pi}^2}+\frac{ m_a^2 (c_s-c_d)}{2 (m^2_K-m^2_{\pi})}+\frac{ m^2_a (c_d-c_u)}{m^2_a-m^2_{\pi}}-\frac32 c_d-\frac12  c_s
    \\
    &+\frac{8 (m^2_K-m^2_a) }{3 m_a^2-4 m_K^2+m_\pi^2}c_{GG}
    -\frac{m_K^2+m_\pi^2-m_a^2}{2 \left(m_K^2-m_\pi^2\right)}\Delta k_{V}^{d-s} \nonumber\,.
\end{align}
\begin{align}\label{eq:DC1}
    \Delta \mathcal{C}_1 = \frac{m_\pi^2 (c_d-c_u)}{(m^2_\pi-m_a^2) }\,.
\end{align}
\begin{align}
    \mathcal{C}_2 =& -\frac{m_a^2 (c_d-2 c_s+c_u)}{3 m_a^2-4 m_K^2+m_\pi^2}+\frac{m_a^2 (c_s-c_d)}{2 m_K^2}+\frac{m_K^2 (c_d-c_s)}{m_K^2-m_\pi^2}+\frac{m_a^2 (c_d-c_u)}{m_a^2-m_\pi^2}-\frac{5 c_d}{2}+\frac12 c_s
    \\
    &+\frac{8 (m^2_K-m^2_a) }{3 m_a^2-4 m_K^2+m_\pi^2}c_{GG} +
  \frac{m_a^2-m_K^2+4 m_\pi^2}{2 m_K^2}\Delta k_{V}^{d-s}\nonumber\,.
\end{align}
\begin{align}
    \mathcal{C}_3 =& \frac{m_\pi^2 \left(3 m_a^2 (c_d-c_s)+m_K^2 (c_s-5 c_d)\right)+3 m_a^2 m_K^2 (c_s-c_d)+m_K^4 (3 c_d+c_s)}{2  \left(m_K^2-m_a^2\right) (m_K^2-m^2_\pi) }-\frac32\Delta k_{V}^{d-s}\,.
\end{align}
\begin{align}
  \mathcal{C}_4 =&  -\frac{ m_a^2 (c_d-2 c_s+c_u)}{3 m_a^2-4 m_K^2+m_\pi^2}+\frac{m_a^2 (c_d+c_s-2 c_u)}{2m_K^2}+\frac{m^2_K (c_d-c_s)}{m^2_K-m^2_\pi}+\frac{m_a^4 (c_u-c_d)}{m_K^2 (m^2_a-m^2_\pi)}\nonumber
  \\
  & -\frac32 c_d+\frac12 c_s- c_u
  +\frac{8 (m^2_K-m^2_a) }{3 m_a^2-4 m_K^2+m_{\pi}^2}c_{GG}
  +
  \frac{m_a^2-m_K^2+4 m_\pi^2}{2 m_K^2}\Delta k_{V}^{d-s}\,.
\end{align}
\begin{align}
    \mathcal{C}_5 =& \frac{m_\pi^2}{m_\pi^2-m_a^2} c_u 
    -\frac{3 m_a^2 (m_K^2-m^2_\pi) +m_K^2 \left(m_K^2+m_\pi^2\right)}{2 (m^2_a-m^2_K) (m^2_K-m^2_\pi)}c_s
    \nonumber
    \\
    &+
    \frac{3 m_a^4 (m_K^2-m^2_\pi)+m_a^2 \left(-3 m_K^4+4 m_K^2 m_\pi^2+m_\pi^4\right)+m_K^2 m_\pi^2 \left(m_K^2-3 m_\pi^2\right)}{2 (m^2_a-m^2_K) (m_a^2-m^2_\pi)  (m_K^2-m^2_\pi) } c_d\,.
\end{align}
\begin{align}
    \mathcal{C}_6 = &  -\frac{3 m_a^2 (c_d-2 c_s+c_u)}{3 m_a^2-4 m_K^2+m_\pi^2}+\frac{m_a^2 (c_d-3 c_s+2 c_u)+m_K^2 (-3 c_d+c_s-2 c_u)}{2(m^2_a-m^2_K) }
    \\
     & + \frac{m_K^4 (c_d-c_s)}{(m^2_a-m^2_K)  (m^2_K-m^2_\pi)}-\frac{8 (m^2_K-m^2_\pi) }{3 m_a^2-4 m_K^2+m_\pi^2}c_{GG}+\frac12 \Delta k_{V}^{d-s}\nonumber\,.
\end{align}
For light ALP masses $m^2_a \ll m^2_\pi \ll m^2_K$,
\begin{align}
    \mathcal{C}_1 \to &\frac{1}{2} (-4 c_{GG}-3 c_d-c_s-\Delta k_{V}^{d-s})\,,
    \\
      \mathcal{C}_2 \to &\frac{1}{2} (-4 c_{GG}-3 c_d-c_s-\Delta k_{V}^{d-s})\,,
          \\
      \mathcal{C}_3 \to &\frac{1}{2} (3 c_d+c_s-3 \Delta k_{V}^{d-s})\,,
          \\
      \mathcal{C}_4 \to &\frac{1}{2} (-4 c_{GG}-c_d-c_s-2 c_u-\Delta k_{V}^{d-s})\,,
          \\
      \mathcal{C}_5 \to &\frac{1}{2} (c_d+c_s+2 c_u-3 \Delta k_{V}^{d-s})\,,
          \\
      \mathcal{C}_6 \to &\frac{1}{2} (4 c_{GG}+c_d+c_s+2 c_u+\Delta k_{V}^{d-s})\,.
\end{align}
All the expressions above are given in terms of the low-energy couplings, which in principle could differ from the UV coupling due to the running. In the main text we report the expression for the $ \mathcal{C}_i$'s in the $m_K \gg m_\pi \gg m_a$ approximation in the limit where the RGE running can be neglected, expressed in term of the UV couplings.

\section{Experimental recasts}
In this appendix we provide some details about the recasts of the experimental results used for  \Fig{fig:K_bounds}. 
The recasts were needed in cases where the experimental results were given for a stable ALP i.e. in the limit of infinite lifetime. For each experiment, we estimate the experimental efficiency as a function the finite lifetime of the ALP.
The ALP lifetime in the model we consider in \Sec{section:prompt_ALP} is effectivity $\tau_a \approx \Gamma^{-1}(a\to \gamma \gamma)$. 
We use the expression for the effective ALP coupling to photons and the corresponding decay width from Ref.~\cite{Bauer:2020jbp}. 
\label{app:exp_recasts}
\subsection{\texorpdfstring{KOTO $K_L \to \pi^0 X$}{KOTO KL to pi0 X}}
We estimate the signal efficiency for the KOTO search $K_L \to \pi^0 X$~\cite{KOTO:2024zbl} by
\begin{align}
\label{eq:KOTO_Eff}
   \epsilon_{\text{\tiny KOTO}}(c\tau_a,m_a) =  \int_0^{L_{\text{\tiny KOTO}}} \frac{\mathrm{d}z_{K_L}}{L_{\text{\tiny KOTO}}} \int_{-1}^{+1}\frac{\mathrm{d}\cos \theta_a }{2}\int_0^{\infty} \frac{\mathrm{d}\ell_a}{\bar\ell_a}e^{-\ell_a/\bar{\ell}_a}\mathcal{A}(\ell_a,\theta^{\text{\tiny lab}}_a,z_{K_L})
\end{align}
where 
\begin{align}
\label{eq::KOTO_defs}
    \bar\ell_a(\theta_a,c\tau,m_a) &\equiv\frac{c\tau }{m_a}|\vec{p}_a(p_K,\theta_a)|\,,
    \\
    \label{eq:pa_lab}
    \vec{p}_a(p_K,\theta_a) &= \left(p_{\text{\tiny cm}}\sin\theta_a,0,\sqrt{1+\frac{p_K}{m_K}}p_{\text{\tiny cm}}\cos \theta_a+ \frac{p_K}{m_K}p_{\text{\tiny cm}}\right)\,,
    \\\label{eq:pcm}
    p_{\text{\tiny cm}} &= \frac{\sqrt{(m_K^2-(m_\pi-m_a)^2)(m_K^2-(m_\pi+m_a)^2)}}{2m_K},
    \\
    \label{eq:KOTO_acc}
    \mathcal{A}(\ell_a,\theta^{\text{\tiny lab}}_a,z_{K_L}) &= \begin{cases}
        0 \;\;\;\;\;& z_{K_L}+\ell_a \cos \theta^{\text{\tiny lab}}_a < L_{\text{\tiny KOTO}} \;\;\;\;\text{and}\;\;\;\; \ell_a \sin \theta^{\text{\tiny lab}}_a <R_{\text{\tiny KOTO}}
        \\
        1 & \text{otherwise}\,,
    \end{cases}
\end{align}
where $\theta_a^{\text{\tiny lab}}$ is the ALP angle in the lab frame implied by \Eq{eq:pa_lab}, not to be confused with $\theta_a$ defined in the rest frame of the decaying particle.
We approximate the KOTO detector as a cylinder of radius $ R_{\text{\tiny KOTO}}=1\,\text{m}$ and length $L_{\text{\tiny KOTO}}=4.148\,\text{m}$, 
with \Eq{eq:KOTO_acc} requiring the ALP decays outside that cylinder.
We further assume the kaon beam to be approximately monochromatic with $p_K = p_{\text{\tiny KOTO}} = 1.5\,\text{GeV}$, which corresponds to the average momentum of kaons in the beam. 
Due to its large decay length in the lab frame ($\approx 10\,\text{m}$), we assume that the kaon decay vertex is distributed uniformly inside the cylinder.
The resulting efficiency depends strongly only on the combinations $c\tau_a/m_a$, with mass dependence becoming important only close to the threshold $m_a \approx m_K-m_\pi$. 
We plot the efficiency in \Fig{plot::koto_eff}.
\begin{figure}[t]
  %
  \centering   \includegraphics[width=0.5\textwidth]{plots/KOTO_eff.pdf}  
      \caption{Estimated signal efficiency for $K_L \to \pi^0 X$ in KOTO as a function of the combination  $c\tau_a/m_a$, see \Eq{eq:KOTO_Eff}. }     \label{plot::koto_eff}
\end{figure}
\subsection{\texorpdfstring{E949 $K^+ \to \pi^+ \gamma \gamma$}{E949 K+ to pi+ gamma gamma}}
We estimate the signal efficiency for the E949 $K^+\to \pi^+ \gamma \gamma$ search~\cite{E949:2005qiy} by,
\begin{align}
    \epsilon_{\text{\tiny E939}}(c\tau_a,m_a)= \int_0^{R_{\text{E949}}}\frac{\mathrm{d} \ell_a}{\bar\ell_{a,0}} e^{-\ell_a/\bar\ell_{a,0}} = 1-e^{-R_{\text{\tiny E949}}/\bar\ell_{a,0}}\,,
\end{align}
where in this case since the kaons decay effectivity at rest,
\begin{align}
   \bar \ell_{a,0}\equiv\bar\ell_a(p_K=0,\theta_a,c\tau,m_a) = \frac{c \tau_a p_{\text{\tiny cm}}}{m_a},
\end{align}
and $p_{\text{\tiny cm}}$ is defined in \Eq{eq:pcm} and we used $R_{\text{\tiny E949}} = 1.45\,$m.
\subsection{\texorpdfstring{NA48 $K_L \to \pi^0 \gamma \gamma$}{NA48 KL to pi0 gamma gamma}}
In order to estimate the signal efficiency for the NA48 $K_L \to \pi^0 \gamma \gamma$ search, we simulated $10^6$ $K_L$ decay events for 5 ALP masses $m_a =\{0.01,0.1,0.21,0.29,0.35\}\,$GeV and 41 $c\tau_a$ values, logarithmically distributed in the range $[10^{-4}\,\text{m},10^{4}\,\text{m}]\,$. 
In each simulation point we decay a $K_L$ to $\pi^0 a$ in an arbitrary position inside the decay volume, $z_{K_L}\in[Z_{\text{\tiny cal,start}},Z_{\text{\tiny cal,end}}] = [126\,\text{m},156\,\text{m}]$.
The kaon carries a momentum $p_K$ which is drawn according to the $K_L$ momentum distribution in NA48, see Fig. (24) in Ref.~\cite{NA48:2001bct}.
We propagate the ALP a distance $\ell_a$ drawn from the appropriate exponential distribution. 
The propagation distance depends on the ALP momentum, which is drawn with an arbitrary angle $\theta_a$ in the COM frame and then boosted to the lab frame according to $p_K$.
If the ALP propagates beyond the position of the calorimeter (ECAL), namely if
\begin{align}\label{eq:geomacc}
    z_{K_L}+\ell_a \cos \theta_a^{\text{\tiny COM}} > Z_{\text{\tiny ECAL}} = 241\,\text{m}  \;\;\;\; (\text{geometric})\,,
\end{align}
we assign efficiency $0$. 
This geometrical acceptance criterion provides the strongest dependence on the ALP lifetime and the main source for efficiency loss.
Other selection criteria were used in this search in order to reduce backgrounds. We find that the only selection criterion which had non-negligible effect on the signal efficiency for a finite-lifetime ALP is the requirement that the $K_L$ originates from the decay volume. The $K_L$ decay vertex is deduced from the reconstructed decay vertex,
\begin{align}
    z_{K_L}^{\text{\tiny recon.}} \equiv Z_{\text{\tiny ECAL}}- \frac{\sum_{i>j} E_{\gamma, i}E_{\gamma,j}d^2_{ij}}{m_K}\,,
\end{align}
where $E_{\gamma,i}$ is the $i$-th photon energy and $d_{ij}$ is the transverse distance between the $i$-th and $j$-th photons on the ECAL plane.
The sum runs for all non-identical photon pairs without repetitions with $i,j=\{1,..,4\}$.
The selection criteria is defined as,
\begin{align}
    z_{K_L}^{\text{\tiny recon.}} \in[Z_{\text{\tiny cal,start}},Z_{\text{\tiny cal,end}}] = [126\,\text{m},156\,\text{m}] \;\;\;\; (\text{selection 1})\,.
\end{align}
In the limit where all the photons originate from the same vertex, this formula is reliable for small angles, which is a very good approximation due to the large kaon boost. 
However, when the ALP is significantly displaced, the reconstructed $K_L$ vertex position gets biased towards larger values, leading to a reduction in signal efficiency when $z_{K_L}^{\text{\tiny recon.}}$ is pushed outside the decay volume.

In addition, we require that the two photons originating from the ALP do not merge and can be reconstructed, since otherwise the events would only register 3 photons in the final state and would not be recorded. 
We enforce this criterion by requiring that
\begin{align}
    d_{34} > \sigma_{\text{\tiny ECAL}}\;\;\;\;(\text{selection 2})\,,
\end{align}
where we used $\sigma_{\text{\tiny ECAL}}= 1.3\times 10^{-3}\,\text{m}$~\cite{NA48:2001bct} and $d_{34}$ is the transverse distance between the two photons originating from the ALP.
\begin{figure}[t]
  %
  \centering   \includegraphics[width=0.7\textwidth]{plots/NA48_eff.pdf}  
      \caption{Estimate of the signal efficiency for the NA48 $K_L \to \pi^0 \gamma \gamma$ search as a function of $c\tau_a$ for $m_a=0.01,0.1$ and $0.29\,\text{GeV}$ in red, blue and purple, respectively. The solid lines represent the full efficiency, while the dashed lines are the efficiency if only the geometric acceptance in Eq. (\ref{eq:geomacc}) is taken into account.}     \label{plot::NA48_eff}
\end{figure}
We plot the resulting efficiencies in \Fig{plot::NA48_eff} for three selected masses as a function of $c\tau_a$. 
The solid lines represent the full efficiencies, and the dashed lines show the efficiencies using only the geometric acceptance criterion in Eq. (\ref{eq:geomacc}). 
At lower masses, the selection criteria have a negligible effect and the full efficiency is only due to geometrical acceptance and is essentially a function of $c\tau_a/m_a$, as expected.
At higher masses, the selection criteria lead to an $\mathcal{O}(1-10)$ reduction in efficiency.
Lastly, we take advantage of the fact that the bounds in Ref.~\cite{NA48:2001bct} are given in bins of $m_{34} \equiv \sqrt{(p_{\gamma_3}+p_{\gamma_4})^2}$, which in our case would just be the ALP mass $m_a$, namely for a given ALP mass the signal would contribute to a single bin.  
For a given ALP mass, we then use the upper limit of the branching fraction for the relevant bin, weighted with the appropriate   
efficiency factor (interpolated if needed) to set the limits shown in \Fig{fig:K_bounds}. 
\subsection{\texorpdfstring{E391a $K_L \to \pi^0 \pi^0 X$}{E391a KL to pi0 pi0 X}}
We estimate the signal efficiency in the E391a $K_L\to \pi^0\pi^0X$ search~\cite{E949:2005qiy} for an invisible particle $X$, by,
\begin{align}
    \epsilon_{\text{\tiny E391a}}(c\tau_a,m_a)= \int_{R_{\text{E391a}}}^{\infty}\frac{\mathrm{d} \ell_a}{\bar\ell^{\text{\tiny E391a}}_{a}} e^{-\ell_a/\bar\ell^{\text{\tiny E391a}}_{a}} = e^{-R_{\text{\tiny E391a}}/\bar\ell^{\text{\tiny E391a}}_{a}}\,,
\end{align}
where
\begin{align}
    \bar\ell^{\text{\tiny E391a}}_{a}(c\tau_a,m_a) \equiv \frac{c \tau_a p_a^{\text{\tiny E391a}}}{m_a}\,.
\end{align}
The typical kaon momentum in E391a was $p^{\text{\tiny E391a}}_{K_L}\approx 1.5\,$GeV, thus we estimate that the typical ALP   produced via the three-body decay has momentum $p_a^{\text{\tiny E391a}}\approx p^{\text{\tiny E391a}}_{K_L}/3 \approx 0.5\,$GeV, and we used $R_{\text{\tiny E391a}} = 2\,$m.
\subsection{\texorpdfstring{BABAR $\Upsilon(1S)\to \gamma X$}{BaBaR Upsilon(1S)-> gamma X}}
The Babar search in~\cite{BaBar:2010eww} targeted the decay
\begin{align}
    \Upsilon(1S) \to \gamma\, X\,,
\end{align} 
with $X$ escaping detection. The $\Upsilon(1S)$ particles were produced from the decay 
$\Upsilon(2S) \to \Upsilon(1S) \pi^+ \pi^-$. 
On the $\Upsilon(2S)$ pole the Babar beam energies were set to be $E_{e^-}= 8.05\,$GeV and $E_{e^+}=3.12\,$GeV, producing a slightly boosted $\Upsilon(2S)$.
We simulate the produced ALP spectrum by first decaying the $\Upsilon(2S)$ assuming a uniform distribution in the three-body Dalitz plane, followed by the two-body decay $\Upsilon(1S) \to \gamma\, a$.
We conservatively require the ALP to decay outside the box-shaped region containing the electromagnetic calorimeter, where $\Delta y = 1.375\,$m, $\Delta z_F=2.295\,$m and $\Delta z_B=1.555\,$m~\cite{BaBar:2001yhh}  are the distances between the interaction point to the top, front and back of the box, respectively.
We calculate the efficiency numerically for various values of $c\tau_a/m_a$.
The resulting efficiency is  well-approximated by,
\begin{align}
    \epsilon_{\text{\tiny BABAR}} (c\tau_a/m_a) =e^{ -{R_{\text{\tiny BABAR}}}/{  \bar{\ell}_a^{\text{\tiny BABAR}}}}\,,
\end{align}
where our fit value $R_{\text{\tiny BABAR}} = 1.8\,$m is consistent with the average distance the ALP needs to propagate to escape detection, and
\begin{align}    \bar{\ell}_a^{\text{\tiny BABAR}} \equiv p_a^{\text{\tiny BABAR}}c\tau_a/m_a\,.
\end{align}
Our fitted value $ p_a^{\text{\tiny BABAR}}=5.27\,$GeV is consistent with the average momentum of the ALP.






